function renderListStatus(){
  const el = document.getElementById('listStatus');
  if(statusList.length===0){ el.innerHTML = `<div class="empty">Nenhum status cadastrado.</div>`; return; }
  el.innerHTML = statusList.map((s,i)=>`
    <div class="cad-item">
      <div class="info" style="display:flex;align-items:center;gap:10px;">
        <div style="display:flex;flex-direction:column;gap:2px;">
          <button class="ghost" style="padding:2px 8px;" ${i===0?'disabled':''} onclick="moverStatus('${s.id}',-1)">▲</button>
          <button class="ghost" style="padding:2px 8px;" ${i===statusList.length-1?'disabled':''} onclick="moverStatus('${s.id}',1)">▼</button>
        </div>
        <b>${escaparHtml(s.nome)}</b>
      </div>
      <div class="acts"><button class="danger" onclick="pedirConfirmacao('Remover status?','Remove das opções futuras de lançamento.', ()=>removerStatus('${s.id}'))">Remover</button></div>
    </div>`).join('');
}
async function moverStatus(id, direcao){
  const i = statusList.findIndex(s=>String(s.id)===String(id));
  const j = i + direcao;
  if(i<0 || j<0 || j>=statusList.length) return;
  const novaOrdem = statusList.slice();
  [novaOrdem[i], novaOrdem[j]] = [novaOrdem[j], novaOrdem[i]];
  statusList = novaOrdem;
  renderListStatus(); // resposta visual imediata, antes mesmo do servidor confirmar
  const conta = contaAtual();
  const r = await api('reordenarStatus', { contaId: conta.id, ids: novaOrdem.map(s=>s.id) });
  if(!r.ok){ toast(r.erro || 'Não foi possível reordenar.'); await carregarTudo(); renderListStatus(); return; }
  await carregarTudo({ comAtendimentos: false });
  renderCadastrosTudo();
  renderFiltrosStatus();
}
async function removerStatus(id){
  const r = await api('removerStatus', { contaId: contaAtual().id, id });
  if(!r.ok){ toast(r.erro || 'Não foi possível remover.'); return; }
  await carregarTudo({ comAtendimentos: false }); renderCadastrosTudo(); popularSelects();
  toast('Status removido');
}

let filtroValoresAtendenteId = 'TODOS';
let filtroGanttCliente = new Set();
let filtroGanttTipo = new Set();
let filtroGanttStatus = new Set();

/* ---------- projetos (gerenciamento de projetos: tarefas em árvore sem
   limite de profundidade, Kanban e Cronograma próprios, vínculo com
   cliente e atendimentos) — módulo independente, carregado sob demanda
   igual Atividades/Orçamentos ---------- */
const PROJ_STATUS = [
  { v:'PLANEJAMENTO', label:'Planejamento' },
  { v:'EM ANDAMENTO', label:'Em Andamento' },
  { v:'CONCLUÍDO', label:'Concluído' },
  { v:'CANCELADO', label:'Cancelado' },
];
const PROJ_TAREFA_STATUS = ['Não Iniciado', 'Agendado', 'Em Andamento', 'Parado', 'Concluída'];
const PROJ_TAREFA_STATUS_COR = {
  'Não Iniciado': 'var(--muted)', 'Agendado': 'var(--purple)', 'Em Andamento': 'var(--warn)',
  'Parado': 'var(--bad)', 'Concluída': 'var(--ok)',
};

// indicador visual de % concluída estilo bateria de celular — vermelho
// <34%, amarelo <67%, verde a partir daí
function projBateriaHtml(pct){
  const p = Math.max(0, Math.min(100, Number(pct)||0));
  const cor = p < 34 ? 'var(--bad)' : (p < 67 ? 'var(--warn)' : 'var(--ok)');
  return `<span class="proj-bateria" title="${p}% concluído"><span class="proj-bateria-fill" style="width:${p}%;background:${cor};"></span></span>`;
}

// selects em cascata de Segmento/Módulo/Rotina — versão genérica (recebe o
// id do elemento) da mesma lógica usada no formulário de atendimento
// (popularSelectSegmento/popularSelectModuloPorSegmento/popularSelectRotinaPorModulo)
function opcoesSegmento(valorAtual){
  let opcoes = `<option value="">(selecione)</option>` + segmentos.map(s=>`<option value="${escaparHtml(s.nome)}" ${s.nome===valorAtual?'selected':''}>${escaparHtml(s.nome)}</option>`).join('');
  if(valorAtual && !segmentos.some(s=>s.nome===valorAtual)) opcoes += `<option value="${escaparHtml(valorAtual)}" selected>${escaparHtml(valorAtual)}</option>`;
  return opcoes;
}
function opcoesModuloPorSegmentoGenerico(segmentoNome, valorAtual){
  const segmento = segmentos.find(s=>s.nome===segmentoNome);
  const lista = segmento ? modulos.filter(m=>m.segmentoId===segmento.id) : [];
  let opcoes = `<option value="">(selecione)</option>` + lista.map(m=>`<option value="${escaparHtml(m.nome)}" ${m.nome===valorAtual?'selected':''}>${escaparHtml(m.nome)}</option>`).join('');
  if(valorAtual && !lista.some(m=>m.nome===valorAtual)) opcoes += `<option value="${escaparHtml(valorAtual)}" selected>${escaparHtml(valorAtual)}</option>`;
  return opcoes;
}
function opcoesRotinaPorModuloGenerico(moduloNome, valorAtual){
  const modulo = modulos.find(m=>m.nome===moduloNome);
  const lista = modulo ? submodulos.filter(s=>s.moduloId===modulo.id) : [];
  let opcoes = `<option value="">(selecione)</option>` + lista.map(s=>`<option value="${escaparHtml(s.nome)}" ${s.nome===valorAtual?'selected':''}>${escaparHtml(s.nome)}</option>`).join('');
  if(valorAtual && !lista.some(s=>s.nome===valorAtual)) opcoes += `<option value="${escaparHtml(valorAtual)}" selected>${escaparHtml(valorAtual)}</option>`;
  return opcoes;
}
function projPitPopularSegmentoModuloRotina(segmentoAtual, moduloAtual, submoduloAtual){
  document.getElementById('pit_segmento').innerHTML = opcoesSegmento(segmentoAtual);
  document.getElementById('pit_modulo').innerHTML = opcoesModuloPorSegmentoGenerico(segmentoAtual, moduloAtual);
  document.getElementById('pit_submodulo').innerHTML = opcoesRotinaPorModuloGenerico(moduloAtual, submoduloAtual);
}

let projetos = [];
let projEditandoId = null;
let projetoAtualId = null;
let projetoAtual = null;
let projetoTarefas = [];
let projetoAtendimentoIds = [];
let projRecursosCadastro = [];
// quando um atendimento é criado a partir de um recurso vinculado a um
// atendente (aba Recursos da tela de informações da tarefa), guarda o
// projeto de origem pra vincular o novo atendimento a ele após salvar
let projVincularAposSalvarAtendimento = null;
let projTarefaColapsadas = new Set();
let projSubAba = 'tarefas';

function popularSelectsProjeto(){
  const conta = contaAtual();
  const selCliente = document.getElementById('proj_cliente');
  const clienteAtual = selCliente.value;
  selCliente.innerHTML = `<option value="">(nenhum)</option>` + clientesParaSelecao().map(c=>`<option value="${escaparHtml(c.nome)}">${escaparHtml(c.nome)}</option>`).join('');
  if([...selCliente.options].some(o=>o.value===clienteAtual)) selCliente.value = clienteAtual;

  const atendentesNomes = contas.filter(c=>c.perfil==='ATENDENTE').map(c=>c.nome);
  const selResp = document.getElementById('proj_responsavel');
  const respAtual = selResp.value;
  selResp.innerHTML = atendentesNomes.map(n=>`<option value="${escaparHtml(n)}">${escaparHtml(n)}</option>`).join('');
  if(atendentesNomes.includes(respAtual)) selResp.value = respAtual;
  else if(conta) selResp.value = conta.nome;

  document.getElementById('proj_status').innerHTML = PROJ_STATUS.map(s=>`<option value="${s.v}">${s.label}</option>`).join('');
}

async function carregarProjetos(){
  const conta = contaAtual();
  const r = await api('listarProjetos', { contaId: conta.id, empresaId: empresaAtual ? empresaAtual.id : '' });
  if(!r.ok) return;
  projetos = r.projetos || [];
  renderListaProjetos();
}

// dias da semana em que se trabalha pra um projeto (0=domingo...6=sábado,
// igual Date.getUTCDay() — mesma convenção do backend); padrão seg-sex
const PROJ_DIAS_TRABALHO_PADRAO = [1,2,3,4,5];
function projDefinirDiasTrabalhoForm(dias){
  const marcados = new Set((dias && dias.length ? dias : PROJ_DIAS_TRABALHO_PADRAO).map(String));
  document.querySelectorAll('#proj_dias_trabalho input[type=checkbox]').forEach(cb=>{ cb.checked = marcados.has(cb.value); });
}
function projLerDiasTrabalhoForm(){
  return [...document.querySelectorAll('#proj_dias_trabalho input[type=checkbox]:checked')].map(cb=>parseInt(cb.value,10));
}
function limparFormProjeto(){
  projEditandoId = null;
  document.getElementById('projFormTitulo').textContent = 'Novo projeto';
  document.getElementById('proj_nome').value = '';
  document.getElementById('proj_descricao').value = '';
  document.getElementById('proj_cliente').value = '';
  document.getElementById('proj_status').value = 'PLANEJAMENTO';
  document.getElementById('proj_data_inicio').value = '';
  document.getElementById('proj_data_prevista_fim').value = '';
  projDefinirDiasTrabalhoForm(PROJ_DIAS_TRABALHO_PADRAO);
  document.getElementById('proj_publico').checked = false;
  document.getElementById('btnSalvarProjeto').textContent = 'Salvar projeto';
  document.getElementById('btnCancelarEdicaoProjeto').style.display = 'none';
  const conta = contaAtual();
  const selResp = document.getElementById('proj_responsavel');
  if(conta && [...selResp.options].some(o=>o.value===conta.nome)) selResp.value = conta.nome;
}

function editarProjetoUi(id){
  const p = projetos.find(x=>String(x.id)===String(id));
  if(!p) return;
  fecharProjetoDetalhe();
  projEditandoId = id;
  document.getElementById('projFormTitulo').textContent = 'Editar projeto';
  document.getElementById('proj_nome').value = p.nome;
  document.getElementById('proj_descricao').value = p.descricao || '';
  document.getElementById('proj_cliente').value = p.cliente || '';
  document.getElementById('proj_responsavel').value = p.responsavel || '';
  document.getElementById('proj_status').value = p.status;
  document.getElementById('proj_data_inicio').value = p.dataInicio || '';
  document.getElementById('proj_data_prevista_fim').value = p.dataPrevistaFim || '';
  projDefinirDiasTrabalhoForm(p.diasTrabalho);
  document.getElementById('proj_publico').checked = !!p.publico;
  document.getElementById('btnSalvarProjeto').textContent = 'Salvar alterações';
  document.getElementById('btnCancelarEdicaoProjeto').style.display = '';
  document.getElementById('cardFormProjeto').scrollIntoView({ behavior:'smooth', block:'start' });
}

async function salvarProjeto(){
  const nome = document.getElementById('proj_nome').value.trim();
  if(!nome){ toast('Informe o nome do projeto'); return; }
  const diasTrabalho = projLerDiasTrabalhoForm();
  if(diasTrabalho.length===0){ toast('Marque ao menos um dia da semana em que se trabalha.'); return; }
  const conta = contaAtual();
  const payload = {
    contaId: conta.id, id: projEditandoId,
    nome, descricao: document.getElementById('proj_descricao').value,
    cliente: document.getElementById('proj_cliente').value,
    responsavel: document.getElementById('proj_responsavel').value,
    status: document.getElementById('proj_status').value,
    dataInicio: document.getElementById('proj_data_inicio').value,
    dataPrevistaFim: document.getElementById('proj_data_prevista_fim').value,
    diasTrabalho,
    publico: document.getElementById('proj_publico').checked,
    empresaId: empresaAtual ? empresaAtual.id : '',
  };
  const btn = document.getElementById('btnSalvarProjeto');
  btn.disabled = true;
  try{
    const r = await api(projEditandoId ? 'atualizarProjeto' : 'criarProjeto', payload);
    if(!r.ok) return;
    toast(projEditandoId ? 'Projeto atualizado' : 'Projeto criado');
    limparFormProjeto();
    await carregarProjetos();
  } finally { btn.disabled = false; }
}

function removerProjetoUi(id){
  pedirConfirmacao('Remover projeto?', 'Remove o projeto e todas as suas tarefas — não dá pra desfazer.', async ()=>{
    const conta = contaAtual();
    const r = await api('removerProjeto', { id, contaId: conta.id });
    if(!r.ok){ toast(r.erro || 'Não foi possível remover.'); return; }
    if(String(projetoAtualId)===String(id)) fecharProjetoDetalhe();
    await carregarProjetos();
    toast('Projeto removido');
  }, 'Remover');
}

function renderListaProjetos(){
  const cont = document.getElementById('listaProjetos');
  if(projetos.length===0){ cont.innerHTML = `<div class="empty"><div class="big">📁</div>Nenhum projeto cadastrado.</div>`; return; }
  cont.innerHTML = projetos.map(p=>{
    const pct = p.tarefasTotal > 0 ? Math.round((p.tarefasConcluidas / p.tarefasTotal) * 100) : 0;
    return `
    <div class="proj-card" onclick="abrirProjetoDetalhe('${p.id}')">
      <div class="proj-card-topo">
        <div>
          <div class="proj-card-nome">${escaparHtml(p.nome)}</div>
          <div class="proj-card-sub">${p.cliente ? escaparHtml(p.cliente)+' · ' : ''}${escaparHtml(p.responsavel || 'A definir')}</div>
        </div>
        <div class="proj-card-acoes" onclick="event.stopPropagation();">
          <span class="tag status-${statusSlug(p.status)}">${escaparHtml(p.status)}</span>
          <span class="tag" style="${p.publico?'color:var(--ok);':'color:var(--muted);'}" title="${p.publico?'Todos os usuários do cliente veem esse projeto':'Só o administrador do cliente vê completo; os demais só veem as próprias tarefas'}">${p.publico?'🌐 Público':'🔒 Não público'}</span>
          <button class="ghost" onclick="editarProjetoUi('${p.id}')">Editar</button>
          <button class="danger" onclick="removerProjetoUi('${p.id}')">Remover</button>
        </div>
      </div>
      <div class="proj-progresso">
        <div class="proj-progresso-barra"><div class="proj-progresso-fill" style="width:${pct}%;"></div></div>
        <div class="proj-progresso-texto">${p.tarefasConcluidas}/${p.tarefasTotal} tarefas concluídas${p.dataPrevistaFim ? ' · previsão '+String(p.dataPrevistaFim).split('-').reverse().join('/') : ''}</div>
      </div>
    </div>`;
  }).join('');
}

async function abrirProjetoDetalhe(id){
  const conta = contaAtual();
  const r = await api('obterProjeto', { id, contaId: conta.id });
  if(!r.ok){ toast(r.erro || 'Não foi possível abrir o projeto.'); return; }
  projetoAtualId = id;
  projetoAtual = r.projeto;
  projetoTarefas = r.tarefas || [];
  projetoAtendimentoIds = r.atendimentoIds || [];
  projRecursosCadastro = r.recursosCadastro || [];
  projTarefaColapsadas = new Set();

  document.getElementById('cardFormProjeto').style.display = 'none';
  document.getElementById('listaProjetos').style.display = 'none';
  document.getElementById('projetoDetalhe').style.display = '';
  document.getElementById('projDetalheNome').textContent = projetoAtual.nome;
  const info = [
    projetoAtual.cliente ? `Cliente: ${projetoAtual.cliente}` : '',
    `Responsável: ${projetoAtual.responsavel || 'A definir'}`,
    `Status: ${projetoAtual.status}`,
    projetoAtual.dataInicio ? `Início: ${String(projetoAtual.dataInicio).split('-').reverse().join('/')}` : '',
    projetoAtual.dataPrevistaFim ? `Previsão: ${String(projetoAtual.dataPrevistaFim).split('-').reverse().join('/')}` : '',
  ].filter(Boolean).join(' · ');
  document.getElementById('projDetalheInfo').textContent = info;

  goProjSub('dashboard');
}

function fecharProjetoDetalhe(){
  const tinhaProjetoAberto = !!projetoAtualId;
  projetoAtualId = null;
  projetoAtual = null;
  projetoTarefas = [];
  projetoAtendimentoIds = [];
  projRecursosCadastro = [];
  document.getElementById('projetoDetalhe').style.display = 'none';
  // criar projeto é coisa de quem gerencia (ADMIN/ATENDENTE) — igual o
  // backend já exige em podeGerenciarProjeto; administrador do cliente só
  // acompanha os projetos do próprio cliente, não cria novos
  const conta = contaAtual();
  const podeCriarProjeto = conta && (conta.perfil === 'ADMIN' || conta.perfil === 'ATENDENTE');
  document.getElementById('cardFormProjeto').style.display = podeCriarProjeto ? '' : 'none';
  document.getElementById('listaProjetos').style.display = '';
  // progresso (tarefasTotal/tarefasConcluidas) pode ter mudado enquanto o
  // projeto estava aberto — recarrega a lista pra refletir na volta
  if(tinhaProjetoAberto) carregarProjetos();
}

function goProjSub(sub){
  projSubAba = sub;
  document.querySelectorAll('#projSubtabs .subtab').forEach(t=>t.classList.toggle('active', t.dataset.projsub===sub));
  document.querySelectorAll('.proj-sub-view').forEach(v=>{ v.style.display = (v.id === 'proj-sub-'+sub) ? '' : 'none'; });
  if(sub==='dashboard') renderDashboardProjeto();
  else if(sub==='tarefas') renderTabelaTarefas();
  else if(sub==='quadro') renderQuadroProjeto();
  else if(sub==='kanban') renderKanbanProjeto();
  else if(sub==='gantt'){
    if(!document.getElementById('proj_gantt_de').value){
      const hoje = new Date();
      document.getElementById('proj_gantt_de').value = new Date(hoje.getFullYear(), hoje.getMonth(), 1).toISOString().slice(0,10);
      document.getElementById('proj_gantt_ate').value = new Date(hoje.getFullYear(), hoje.getMonth()+1, 0).toISOString().slice(0,10);
    }
    renderGanttProjeto();
  }
  else if(sub==='mapa') renderMapaMentalProjeto();
  else if(sub==='recursos') renderRecursosCadastroProjeto();
  else if(sub==='atendimentos') renderAtendimentosVinculadosProjeto();
  else if(sub==='anexos') carregarAnexosProjeto(projetoAtualId);
}

/* ---------- cadastro de recursos do projeto (nome + custo padrão) —
   alimenta a aba Recursos da tela de informações da tarefa, pra selecionar
   em vez de digitar toda vez ---------- */
function nomesAtendentesSistema(){
  return contas.filter(c=>c.perfil==='ATENDENTE');
}
// usuários (contas USUARIO) vinculados ao MESMO cliente do projeto aberto —
// é quem pode ser marcado como "É um usuário do cliente" num recurso, pra
// restringir quais tarefas ele vê quando o projeto não é público
function nomesUsuariosDoCliente(){
  if(!projetoAtual || !projetoAtual.cliente) return [];
  const cliente = clientes.find(cl=>cl.nome===projetoAtual.cliente);
  if(!cliente) return [];
  return contas.filter(c=>c.perfil==='USUARIO' && String(c.clienteId||'')===String(cliente.id));
}
function renderRecursosCadastroProjeto(){
  const corpo = document.getElementById('projRecursosCadastroCorpo');
  const atendentes = nomesAtendentesSistema();
  const usuarios = nomesUsuariosDoCliente();
  const podeVerCustos = projPodeVerCustos();
  document.getElementById('projrec_th_custo').style.display = podeVerCustos ? '' : 'none';
  document.getElementById('projrec_custo_campo').style.display = podeVerCustos ? '' : 'none';
  const colspanVazio = podeVerCustos ? 5 : 4;
  if(projRecursosCadastro.length===0){ corpo.innerHTML = `<tr><td colspan="${colspanVazio}" style="text-align:center;color:var(--muted);padding:10px;">Nenhum recurso cadastrado.</td></tr>`; return; }
  corpo.innerHTML = projRecursosCadastro.map(r=>`
    <tr>
      <td><input type="text" value="${escaparHtml(r.nome)}" onblur="projRecursoCadastroSalvarCampo('${r.id}','nome',this.value)"></td>
      ${podeVerCustos ? `<td class="num"><input type="number" min="0" step="0.01" value="${r.custo||0}" onchange="projRecursoCadastroSalvarCampo('${r.id}','custo',this.value)"></td>` : ''}
      <td>
        <select onchange="projRecursoCadastroSalvarCampo('${r.id}','atendenteId',this.value)">
          <option value="">(não é atendente)</option>
          ${atendentes.map(c=>`<option value="${c.id}" ${String(c.id)===String(r.atendenteId||'')?'selected':''}>${escaparHtml(c.nome)}</option>`).join('')}
        </select>
      </td>
      <td>
        <select onchange="projRecursoCadastroSalvarCampo('${r.id}','usuarioId',this.value)">
          <option value="">(não é usuário)</option>
          ${usuarios.map(c=>`<option value="${c.id}" ${String(c.id)===String(r.usuarioId||'')?'selected':''}>${escaparHtml(c.nome)}</option>`).join('')}
        </select>
      </td>
      <td><button class="danger" onclick="projRecursoCadastroRemover('${r.id}')">🗑</button></td>
    </tr>`).join('');
}
async function projRecursoCadastroAdicionar(){
  const nome = document.getElementById('projrec_nome').value.trim();
  const custo = document.getElementById('projrec_custo').value;
  const ehAtendente = document.getElementById('projrec_eh_atendente').checked;
  const atendenteId = ehAtendente ? document.getElementById('projrec_atendente').value : '';
  const ehUsuario = document.getElementById('projrec_eh_usuario').checked;
  const usuarioId = ehUsuario ? document.getElementById('projrec_usuario').value : '';
  if(!nome){ toast('Informe o nome do recurso'); return; }
  if(ehAtendente && !atendenteId){ toast('Selecione o atendente vinculado'); return; }
  if(ehUsuario && !usuarioId){ toast('Selecione o usuário vinculado'); return; }
  const conta = contaAtual();
  const r = await api('criarRecursoProjeto', { projetoId: projetoAtualId, nome, custo, atendenteId, usuarioId, contaId: conta.id });
  if(!r.ok){ toast(r.erro || 'Não foi possível adicionar.'); return; }
  projRecursosCadastro.push({ id: r.id, projetoId: projetoAtualId, nome, custo: parseFloat(custo)||0, atendenteId: atendenteId || '', usuarioId: usuarioId || '' });
  document.getElementById('projrec_nome').value = '';
  document.getElementById('projrec_custo').value = '';
  document.getElementById('projrec_eh_atendente').checked = false;
  document.getElementById('projrec_atendente').style.display = 'none';
  document.getElementById('projrec_eh_usuario').checked = false;
  document.getElementById('projrec_usuario').style.display = 'none';
  renderRecursosCadastroProjeto();
}
async function projRecursoCadastroSalvarCampo(id, campo, valor){
  const conta = contaAtual();
  const r = await api('atualizarRecursoProjeto', { id, [campo]: valor, contaId: conta.id });
  if(!r.ok){ toast(r.erro || 'Não foi possível salvar.'); renderRecursosCadastroProjeto(); return; }
  const rc = projRecursosCadastro.find(x=>String(x.id)===String(id));
  if(rc) rc[campo] = campo==='custo' ? (parseFloat(valor)||0) : valor;
  renderRecursosCadastroProjeto();
}
function projRecursoCadastroRemover(id){
  pedirConfirmacao('Remover recurso?', 'Não afeta recursos já atribuídos em tarefas — só some da lista de seleção.', async ()=>{
    const conta = contaAtual();
    const r = await api('removerRecursoProjeto', { id, contaId: conta.id });
    if(!r.ok){ toast(r.erro || 'Não foi possível remover.'); return; }
    projRecursosCadastro = projRecursosCadastro.filter(x=>String(x.id)!==String(id));
    renderRecursosCadastroProjeto();
    toast('Recurso removido');
  }, 'Remover');
}

/* ---------- tabela de tarefas/subtarefas — estilo MS Project (Modo, Nome,
   Duração, Início, Término, Anotações, % concluída, Recursos, Predecessoras).
   Hierarquia sem limite de profundidade (diferente do item/subitem do
   orçamento, que só tem um nível). Predecessoras recalcula datas
   automaticamente no backend (acaoAtualizarTarefa/recalcularEPersistirProjeto)
   — o front sempre substitui projetoTarefas inteiro pela resposta da API,
   já que editar uma tarefa pode mudar as datas de outras. ---------- */
function projFilhosDe(tarefaPaiId){
  return projetoTarefas
    .filter(t=>String(t.tarefaPaiId||'')===String(tarefaPaiId||''))
    .sort((a,b)=>String(a.criadoEm).localeCompare(String(b.criadoEm)));
}
function projProfundidade(tarefa){
  let nivel = 0, atual = tarefa;
  while(atual && atual.tarefaPaiId){
    atual = projetoTarefas.find(x=>String(x.id)===String(atual.tarefaPaiId));
    nivel++;
    if(nivel > 30) break; // proteção, não deveria acontecer
  }
  return nivel;
}

// numeração sequencial (estilo MS Project) e EDT/WBS hierárquico (1, 1.1,
// 1.2, 2...) recalculados a cada render — a numeração simples alimenta a
// edição de Predecessoras (vínculo de verdade usa o id real); o EDT é só
// exibição (posição na árvore), não é gravado no banco
let projTarefaNumeros = new Map();
let projTarefaPorNumero = [];
let projTarefaEdt = new Map();
function projNumerarTarefas(){
  projTarefaNumeros = new Map();
  projTarefaPorNumero = [];
  projTarefaEdt = new Map();
  let contador = 0;
  (function visitar(paiId, prefixoEdt){
    projFilhosDe(paiId).forEach((t,i)=>{
      contador++;
      projTarefaNumeros.set(String(t.id), contador);
      projTarefaPorNumero[contador] = t.id;
      const edt = prefixoEdt ? `${prefixoEdt}.${i+1}` : `${i+1}`;
      projTarefaEdt.set(String(t.id), edt);
      visitar(t.id, edt);
    });
  })(null, '');
}

// colunas da tabela de tarefas — as "fixa" sempre aparecem; as demais só
// quando marcadas no painel "⚙ Colunas" (preferência salva por navegador).
// A largura de cada uma também é ajustável (arrastando a borda do
// cabeçalho) e persiste do mesmo jeito.
// só toggle/numero/nome/ações ficam sempre fixos (são a identidade mínima
// da linha + os controles da interface) — todo o resto é um campo de
// verdade da tarefa e pode ser ligado/desligado no painel "⚙ Colunas"
const PROJ_COLUNAS_TAREFAS = [
  { key:'toggle', label:'', largura:22, fixa:true, semExportar:true, semResize:true },
  { key:'numero', label:'Nº', largura:36, fixa:true },
  { key:'edt', label:'EDT', largura:70 },
  { key:'nome', label:'Nome da tarefa', largura:220, fixa:true },
  { key:'status', label:'Status', largura:110, filtravel:true },
  { key:'inativa', label:'Inativa', largura:70, filtravel:true },
  { key:'segmento', label:'Segmento', largura:130, filtravel:true },
  { key:'modulo', label:'Módulo', largura:130, filtravel:true },
  { key:'submodulo', label:'Rotina', largura:130, filtravel:true },
  { key:'prioridade', label:'Prioridade', largura:90, num:true },
  { key:'modo', label:'Modo', largura:100, filtravel:true },
  { key:'duracao', label:'Duração', largura:80, num:true },
  { key:'duracaoEstimada', label:'Duração Estimada', largura:70, filtravel:true },
  { key:'inicio', label:'Início', largura:110 },
  { key:'termino', label:'Término', largura:110 },
  { key:'concluidoEm', label:'Data de Conclusão', largura:120 },
  { key:'anotacoes', label:'Anotações', largura:160 },
  { key:'percentual', label:'% concluída', largura:110, num:true },
  { key:'recursos', label:'Nomes dos recursos', largura:150 },
  { key:'atendimentos', label:'Atendimentos', largura:90, num:true },
  { key:'predecessoras', label:'Predecessoras', largura:110 },
  { key:'acoes', label:'', largura:90, fixa:true, semExportar:true, semResize:true },
];
// colunas que já apareciam sempre antes desta mudança — continuam visíveis
// por padrão pra quem já usava a tabela, mesmo agora que viraram opcionais
const PROJ_COLUNAS_VISIVEIS_PADRAO = ['status','duracao','inicio','termino','anotacoes','percentual','recursos','predecessoras'];
let projColunasOpcionaisVisiveis = new Set();
let projColunaLarguras = {};
(function projCarregarPrefsColunasTarefas(){
  try{
    const salvoV2 = localStorage.getItem('projColunasOpcionais_v2');
    if(salvoV2 !== null){
      projColunasOpcionaisVisiveis = new Set(JSON.parse(salvoV2));
    } else {
      // migração: antes só os "extras" (EDT/Segmento/Módulo/Rotina/
      // Prioridade/Modo) eram opcionais — junta com o que já estava
      // marcado e com as colunas que eram fixas, pra não sumir nada da
      // tela de quem já vinha usando
      let extrasAntigos = [];
      try{ extrasAntigos = JSON.parse(localStorage.getItem('projColunasOpcionais_v1')||'[]'); }catch(e){}
      projColunasOpcionaisVisiveis = new Set([...PROJ_COLUNAS_VISIVEIS_PADRAO, ...extrasAntigos]);
      localStorage.setItem('projColunasOpcionais_v2', JSON.stringify([...projColunasOpcionaisVisiveis]));
    }
  }catch(e){ projColunasOpcionaisVisiveis = new Set(PROJ_COLUNAS_VISIVEIS_PADRAO); }
  try{ projColunaLarguras = JSON.parse(localStorage.getItem('projColunaLarguras_v1')||'{}'); }catch(e){ projColunaLarguras = {}; }
})();
// ordem das colunas — o usuário arrasta o cabeçalho (mesmo mecanismo de
// arrastar-pra-reordenar já usado na Lista de atendimentos) pra colocar do
// jeito que preferir; fica salva por navegador. null = ainda não mexeu,
// usa a ordem padrão de PROJ_COLUNAS_TAREFAS
let projTarefaColunasOrdem = null;
(function projCarregarOrdemColunasTarefas(){
  try{
    const salvo = JSON.parse(localStorage.getItem('projColunasOrdem_v1')||'null');
    if(Array.isArray(salvo)) projTarefaColunasOrdem = salvo;
  }catch(e){ projTarefaColunasOrdem = null; }
})();
function colunasOrdenadasBase(){
  if(!projTarefaColunasOrdem) return PROJ_COLUNAS_TAREFAS;
  const porKey = new Map(PROJ_COLUNAS_TAREFAS.map(c=>[c.key,c]));
  const ordenadas = projTarefaColunasOrdem.map(k=>porKey.get(k)).filter(Boolean);
  // uma coluna nova, adicionada depois da última vez que o usuário
  // reordenou, entra no fim (na ordem padrão), pra nunca sumir
  PROJ_COLUNAS_TAREFAS.forEach(c=>{ if(!ordenadas.includes(c)) ordenadas.push(c); });
  return ordenadas;
}
function colunasVisiveisTarefas(){
  return colunasOrdenadasBase().filter(c=>c.fixa || projColunasOpcionaisVisiveis.has(c.key));
}
function reordenarColunaTarefas(campoArrastado, campoAlvo){
  if(!campoArrastado || !campoAlvo || campoArrastado === campoAlvo) return;
  const atual = colunasOrdenadasBase().map(c=>c.key);
  const semArrastado = atual.filter(k=>k!==campoArrastado);
  const idxAlvo = semArrastado.indexOf(campoAlvo);
  if(idxAlvo===-1) return;
  semArrastado.splice(idxAlvo, 0, campoArrastado);
  projTarefaColunasOrdem = semArrastado;
  try{ localStorage.setItem('projColunasOrdem_v1', JSON.stringify(projTarefaColunasOrdem)); }catch(e){}
  renderTabelaTarefas();
}
// arrastar o cabeçalho pra reordenar — Pointer Events, mesmo mecanismo do
// drag de coluna da Lista de atendimentos (iniciarPossivelDragColunaLista)
function projIniciarDragColunaTarefas(e, thEl){
  const campo = thEl.dataset.col;
  const labelEl = thEl.querySelector('span');
  const label = labelEl ? labelEl.textContent : campo;
  const startX = e.clientX, startY = e.clientY;
  const rect = thEl.getBoundingClientRect();
  const offsetX = e.clientX - rect.left, offsetY = e.clientY - rect.top;
  let arrastando = false;
  let ghost = null;
  let thAlvoReordenar = null;

  thEl.setPointerCapture(e.pointerId);

  function limparAlvo(){
    if(thAlvoReordenar) thAlvoReordenar.classList.remove('lista-th-drop-alvo');
    thAlvoReordenar = null;
  }
  function mover(ev){
    if(!arrastando){
      if(Math.hypot(ev.clientX-startX, ev.clientY-startY) < 6) return;
      arrastando = true;
      ghost = document.createElement('div');
      ghost.className = 'lista-coluna-ghost';
      ghost.textContent = label;
      document.body.appendChild(ghost);
    }
    ghost.style.left = (ev.clientX-offsetX)+'px';
    ghost.style.top = (ev.clientY-offsetY)+'px';
    ghost.style.display = 'none';
    const alvo = document.elementFromPoint(ev.clientX, ev.clientY);
    ghost.style.display = '';
    limparAlvo();
    const thHover = alvo && alvo.closest('#projTarefasTabelaCabecalho th[data-col]');
    if(thHover && thHover !== thEl){
      const colHover = PROJ_COLUNAS_TAREFAS.find(c=>c.key===thHover.dataset.col);
      if(colHover && !colHover.semResize){
        thAlvoReordenar = thHover;
        thAlvoReordenar.classList.add('lista-th-drop-alvo');
      }
    }
  }
  function soltar(){
    thEl.removeEventListener('pointermove', mover);
    if(arrastando){
      const alvo = thAlvoReordenar ? thAlvoReordenar.dataset.col : null;
      limparAlvo();
      ghost.remove();
      if(alvo) reordenarColunaTarefas(campo, alvo);
    }
  }
  function cancelar(){
    thEl.removeEventListener('pointermove', mover);
    limparAlvo();
    if(ghost) ghost.remove();
  }
  thEl.addEventListener('pointermove', mover);
  thEl.addEventListener('pointerup', soltar, { once:true });
  thEl.addEventListener('pointercancel', cancelar, { once:true });
}
function projLarguraColuna(col){
  return projColunaLarguras[col.key] || col.largura;
}
function renderPainelColunasTarefas(){
  const painel = document.getElementById('projColunasPainel');
  const opcionais = PROJ_COLUNAS_TAREFAS.filter(c=>!c.fixa);
  painel.innerHTML = opcionais.map(c=>`
    <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;padding:4px 0;cursor:pointer;white-space:nowrap;">
      <input type="checkbox" style="width:auto;" ${projColunasOpcionaisVisiveis.has(c.key)?'checked':''} onchange="projAlternarColunaOpcional('${c.key}', this.checked)">
      ${escaparHtml(c.label)}
    </label>`).join('');
}
function projAlternarColunaOpcional(key, visivel){
  if(visivel) projColunasOpcionaisVisiveis.add(key);
  else projColunasOpcionaisVisiveis.delete(key);
  try{ localStorage.setItem('projColunasOpcionais_v2', JSON.stringify([...projColunasOpcionaisVisiveis])); }catch(e){}
  renderTabelaTarefas();
}
let projResizeEstado = null;
function projIniciarResizeColuna(e, key){
  e.preventDefault();
  e.stopPropagation();
  const col = PROJ_COLUNAS_TAREFAS.find(c=>c.key===key);
  const idx = colunasVisiveisTarefas().findIndex(c=>c.key===key);
  projResizeEstado = { key, xInicial: e.clientX, larguraInicial: projLarguraColuna(col), idx };
  document.addEventListener('mousemove', projMoverResizeColuna);
  document.addEventListener('mouseup', projFinalizarResizeColuna, { once:true });
}
function projMoverResizeColuna(e){
  if(!projResizeEstado) return;
  const delta = e.clientX - projResizeEstado.xInicial;
  const nova = Math.max(40, projResizeEstado.larguraInicial + delta);
  const colEl = document.querySelectorAll('#projTarefasTabelaColgroup col')[projResizeEstado.idx];
  if(colEl) colEl.style.width = nova + 'px';
}
function projFinalizarResizeColuna(e){
  document.removeEventListener('mousemove', projMoverResizeColuna);
  if(!projResizeEstado) return;
  const delta = e.clientX - projResizeEstado.xInicial;
  const nova = Math.max(40, projResizeEstado.larguraInicial + delta);
  projColunaLarguras[projResizeEstado.key] = nova;
  try{ localStorage.setItem('projColunaLarguras_v1', JSON.stringify(projColunaLarguras)); }catch(e){}
  projResizeEstado = null;
}

// filtro de coluna estilo Excel (mesmo padrão visual/mecânico da Lista de
// atendimentos — dropdown com valores distintos, marcáveis — mas com seu
// próprio portal/estado, já que a Lista e a tabela de tarefas nunca
// aparecem juntas na tela); só nas colunas com um conjunto de valores
// enxuto (status, segmento/módulo/rotina, modo, booleanas). Quando algum
// filtro está ativo, a tabela vira uma lista achatada (sem recolher/
// expandir) com só as tarefas que passam em todos os filtros marcados.
let projFiltrosColuna = {};
let projFiltroColunaAberta = null;
function projFiltrosColunaAtivos(){
  return Object.values(projFiltrosColuna).some(s=>s && s.size>0);
}
function projTarefaPassaFiltrosColuna(t){
  return Object.entries(projFiltrosColuna).every(([campo,set])=>{
    if(!set || set.size===0) return true;
    return set.has(projValorColunaTexto(t, campo, 0));
  });
}
function projDistintosColuna(campo){
  const valores = new Set();
  projetoTarefas.forEach(t=>{
    const v = projValorColunaTexto(t, campo, 0);
    if(v) valores.add(v);
  });
  return [...valores].sort((a,b)=>a.localeCompare(b,'pt-BR'));
}
function projFecharFiltroColuna(){
  projFiltroColunaAberta = null;
  const portal = document.getElementById('projFiltroColunaPortal');
  if(portal){ portal.classList.remove('show'); portal.innerHTML = ''; }
}
function projToggleFiltroColuna(campo, spanEl){
  const jaAbertoParaEsse = projFiltroColunaAberta === campo;
  projFecharFiltroColuna();
  if(jaAbertoParaEsse) return;
  projFiltroColunaAberta = campo;
  const portal = document.getElementById('projFiltroColunaPortal');
  if(!portal || !spanEl) return;
  const set = projFiltrosColuna[campo] || (projFiltrosColuna[campo] = new Set());
  const valores = projDistintosColuna(campo);
  const itensDropdown = valores.map(v=>
    `<div class="lista-filtro-coluna-item" data-campo="${campo}" data-valor="${escaparHtml(v)}">${set.has(v) ? '✓ ' : ''}${escaparHtml(v)}</div>`
  ).join('');
  portal.innerHTML = `
    <div class="lista-filtro-coluna-item" data-campo="${campo}" data-valor="" style="font-weight:700;border-bottom:1px solid var(--line);">Selecionar todos</div>
    ${itensDropdown}
  `;
  const r = spanEl.getBoundingClientRect();
  portal.style.left = `${r.left}px`;
  portal.style.top = `${r.bottom + 4}px`;
  portal.classList.add('show');
}
function projCelulaFiltroColuna(c){
  const set = projFiltrosColuna[c.key];
  const ativo = set && set.size>0;
  return `<span class="lista-th-filtro-wrap" style="position:relative;display:inline-block;margin-left:6px;">
    <span onclick="projToggleFiltroColuna('${c.key}', this)" style="cursor:pointer;${ativo ? 'color:var(--accent);' : ''}" title="Filtrar ${escaparHtml(c.label)}">▾</span>
  </span>`;
}

function renderCabecalhoTarefas(colunas){
  document.getElementById('projTarefasTabelaColgroup').innerHTML = colunas.map(c=>`<col style="width:${projLarguraColuna(c)}px;">`).join('');
  document.getElementById('projTarefasTabelaCabecalho').innerHTML = `<tr>${colunas.map(c=>`
    <th class="${c.num?'num':''} ${c.semResize?'':'lista-th-arrastavel'}" data-col="${c.key}" title="${c.semResize?'':'Arraste pra reordenar'}">
      <span>${escaparHtml(c.label)}</span>
      ${c.filtravel ? projCelulaFiltroColuna(c) : ''}
      ${c.semResize ? '' : `<span class="proj-col-resizer" onmousedown="projIniciarResizeColuna(event,'${c.key}')"></span>`}
    </th>`).join('')}</tr>`;
}

function renderTabelaTarefas(){
  const colunas = colunasVisiveisTarefas();
  renderCabecalhoTarefas(colunas);
  const corpo = document.getElementById('projTarefasTabelaCorpo');
  projNumerarTarefas();
  if(projFiltrosColunaAtivos()){
    const linhas = projTarefasListaLinear().filter(({t})=>projTarefaPassaFiltrosColuna(t));
    if(linhas.length===0){ corpo.innerHTML = `<tr><td colspan="${colunas.length}" style="text-align:center;padding:16px;color:var(--muted);">Nenhuma tarefa encontrada com esses filtros.</td></tr>`; return; }
    corpo.innerHTML = linhas.map(({t,nivel})=>projTarefaLinhaUnicaHtml(t, nivel, colunas, true)).join('');
    return;
  }
  const raiz = projFilhosDe(null);
  if(raiz.length===0){ corpo.innerHTML = `<tr><td colspan="${colunas.length}" style="text-align:center;padding:16px;color:var(--muted);">Nenhuma tarefa ainda.</td></tr>`; return; }
  corpo.innerHTML = raiz.map(t=>projTarefaLinhaHtml(t, 0, colunas)).join('');
}
function projTarefaCelulaHtml(t, nivel, filhos, colapsada, numero, predTexto, key, semToggle){
  switch(key){
    case 'toggle':
      return `<td>${(!semToggle && filhos.length > 0) ? `<button type="button" class="orc-toggle" onclick="projAlternarColapso('${t.id}')">${colapsada ? '+' : '−'}</button>` : ''}</td>`;
    case 'numero':
      return `<td style="text-align:center;color:var(--muted);">${numero}</td>`;
    case 'edt':
      return `<td style="text-align:center;color:var(--muted);">${escaparHtml(projTarefaEdt.get(String(t.id))||'')}</td>`;
    case 'nome':
      return `<td>
        <div class="proj-tarefa-nome-linha" style="padding-left:${nivel*16}px;">
          <input type="text" class="proj-tarefa-titulo" value="${escaparHtml(t.titulo)}" onblur="projSalvarCampoTarefa('${t.id}','titulo',this.value)">
        </div>
      </td>`;
    case 'status':
      return `<td>
        <select class="proj-status-select" onchange="projSalvarCampoTarefa('${t.id}','status',this.value)">
          ${PROJ_TAREFA_STATUS.map(s=>`<option value="${s}" ${s===t.status?'selected':''}>${s}</option>`).join('')}
        </select>
      </td>`;
    case 'inativa':
      return `<td style="text-align:center;"><input type="checkbox" style="width:auto;" ${t.inativa?'checked':''} onchange="projSalvarCampoTarefa('${t.id}','inativa',this.checked)"></td>`;
    case 'segmento':
      return `<td><select onchange="projTabelaAlterarSegmento('${t.id}',this.value)">${opcoesSegmento(t.segmento||'')}</select></td>`;
    case 'modulo':
      return `<td><select onchange="projTabelaAlterarModulo('${t.id}',this.value)">${opcoesModuloPorSegmentoGenerico(t.segmento||'', t.modulo||'')}</select></td>`;
    case 'submodulo':
      return `<td><select onchange="projSalvarCampoTarefa('${t.id}','submodulo',this.value)">${opcoesRotinaPorModuloGenerico(t.modulo||'', t.submodulo||'')}</select></td>`;
    case 'prioridade':
      return `<td class="num"><input type="number" min="0" max="1000" step="10" value="${t.prioridade ?? 500}" onchange="projSalvarCampoTarefa('${t.id}','prioridade',this.value)"></td>`;
    case 'modo':
      return `<td>
        <select onchange="projSalvarCampoTarefa('${t.id}','modo',this.value)">
          <option value="AUTOMÁTICO" ${t.modo!=='MANUAL'?'selected':''}>Automático</option>
          <option value="MANUAL" ${t.modo==='MANUAL'?'selected':''}>Manual</option>
        </select>
      </td>`;
    case 'duracao':
      if(filhos.length > 0){
        return `<td class="num" style="color:var(--muted);" title="Calculado automaticamente a partir das subtarefas">${t.duracaoDias||1} d</td>`;
      }
      return `<td class="num"><input type="number" min="1" step="1" value="${t.duracaoDias||1}" onchange="projSalvarCampoTarefa('${t.id}','duracaoDias',this.value)"></td>`;
    case 'duracaoEstimada':
      return `<td style="text-align:center;"><input type="checkbox" style="width:auto;" ${t.duracaoEstimada?'checked':''} onchange="projSalvarCampoTarefa('${t.id}','duracaoEstimada',this.checked)"></td>`;
    case 'inicio':
      if(filhos.length > 0){
        return `<td style="color:var(--muted);" title="Calculado automaticamente a partir das subtarefas">${t.dataInicio ? String(t.dataInicio).split('-').reverse().join('/') : ''}</td>`;
      }
      return `<td><input type="date" value="${t.dataInicio||''}" onchange="projSalvarCampoTarefa('${t.id}','dataInicio',this.value)"></td>`;
    case 'termino':
      if(filhos.length > 0){
        return `<td style="color:var(--muted);" title="Calculado automaticamente a partir das subtarefas">${t.dataFim ? String(t.dataFim).split('-').reverse().join('/') : ''}</td>`;
      }
      return `<td><input type="date" value="${t.dataFim||''}" onchange="projSalvarCampoTarefa('${t.id}','dataFim',this.value)"></td>`;
    case 'concluidoEm':
      return `<td style="color:var(--muted);">${t.concluidoEm ? escaparHtml(new Date(t.concluidoEm).toLocaleDateString('pt-BR')) : '—'}</td>`;
    case 'anotacoes':
      return `<td class="anotacoes-col"><input type="text" value="${escaparHtml(t.descricao||'')}" placeholder="Anotações" onblur="projSalvarCampoTarefa('${t.id}','descricao',this.value)"></td>`;
    case 'percentual':
      if(filhos.length > 0){
        return `<td class="num">
          <div class="proj-bateria-wrap" title="Calculado automaticamente a partir das subtarefas">
            ${projBateriaHtml(t.percentualConcluido||0)}
            <span style="color:var(--muted);">${t.percentualConcluido||0}%</span>
          </div>
        </td>`;
      }
      return `<td class="num">
        <div class="proj-bateria-wrap">
          ${projBateriaHtml(t.percentualConcluido||0)}
          <input type="number" min="0" max="100" step="1" value="${t.percentualConcluido||0}" onchange="projSalvarCampoTarefa('${t.id}','percentualConcluido',this.value)">
        </div>
      </td>`;
    case 'recursos':
      // mesma célula (bolinhas coloridas + "+" abrindo a listinha marcável
      // dos recursos cadastrados no projeto) usada no Quadro — só uma
      // implementação pra editar "quem é responsável" nas duas telas
      return projQuadroCelulaRecursos(t);
    case 'atendimentos':
      return `<td class="num" style="color:var(--muted);">${(t.atendimentoIds||[]).length || '—'}</td>`;
    case 'predecessoras':
      return `<td><input type="text" value="${escaparHtml(predTexto)}" placeholder="ex: 2,3" title="Números das tarefas predecessoras" onblur="projSalvarPredecessoras('${t.id}',this.value)"></td>`;
    case 'acoes':
      // mesmo botão único (⋮) com o menu de ações usado no Quadro, em vez
      // dos 3 ícones lado a lado
      return projQuadroCelulaAcoes(t);
    default:
      return '<td></td>';
  }
}
// linha única (sem recursão nos filhos) — usada tanto pela árvore normal
// (projTarefaLinhaHtml) quanto pela lista achatada por filtro de coluna
// (renderTabelaTarefas), que já resolveu a ordem/nível pela EDT e não
// precisa (nem quer, já que não vai mostrar os filhos logo abaixo) do
// botão de recolher/expandir
function projTarefaLinhaUnicaHtml(t, nivel, colunas, semToggle){
  const filhos = projFilhosDe(t.id);
  const colapsada = projTarefaColapsadas.has(t.id);
  const numero = projTarefaNumeros.get(String(t.id)) || '';
  const predTexto = (t.predecessorasIds||[])
    .map(pid=>projTarefaNumeros.get(String(pid)))
    .filter(n=>n!==undefined)
    .sort((a,b)=>a-b)
    .join(',');
  const celulas = colunas.map(c=>projTarefaCelulaHtml(t, nivel, filhos, colapsada, numero, predTexto, c.key, semToggle)).join('');
  return `<tr class="status-${statusSlug(t.status)}${filhos.length>0?' proj-tarefa-mae':''}" data-id="${t.id}">${celulas}</tr>`;
}
function projTarefaLinhaHtml(t, nivel, colunas){
  const filhos = projFilhosDe(t.id);
  const colapsada = projTarefaColapsadas.has(t.id);
  const linha = projTarefaLinhaUnicaHtml(t, nivel, colunas);
  const filhosHtml = (!colapsada && filhos.length > 0) ? filhos.map(f=>projTarefaLinhaHtml(f, nivel+1, colunas)).join('') : '';
  return linha + filhosHtml;
}
// editar Segmento na tabela limpa Módulo/Rotina (mesmo comportamento do
// formulário de atendimento — módulo/rotina antigos deixam de fazer sentido)
async function projTabelaAlterarSegmento(id, valor){
  const conta = contaAtual();
  const r = await api('atualizarTarefa', { id, contaId: conta.id, segmento: valor, modulo: '', submodulo: '' });
  if(!r.ok){ toast(r.erro || 'Não foi possível salvar.'); renderTabelaTarefas(); return; }
  projetoTarefas = r.tarefas || projetoTarefas;
  renderTabelaTarefas();
  if(projSubAba==='kanban') renderKanbanProjeto();
  else if(projSubAba==='gantt') renderGanttProjeto();
  else if(projSubAba==='quadro') renderQuadroProjeto();
}
async function projTabelaAlterarModulo(id, valor){
  const conta = contaAtual();
  const r = await api('atualizarTarefa', { id, contaId: conta.id, modulo: valor, submodulo: '' });
  if(!r.ok){ toast(r.erro || 'Não foi possível salvar.'); renderTabelaTarefas(); return; }
  projetoTarefas = r.tarefas || projetoTarefas;
  renderTabelaTarefas();
  if(projSubAba==='kanban') renderKanbanProjeto();
  else if(projSubAba==='gantt') renderGanttProjeto();
  else if(projSubAba==='quadro') renderQuadroProjeto();
}

/* ---------- exportar tarefas em PDF/Excel — exporta exatamente as colunas
   visíveis na tela (respeitando o painel "⚙ Colunas"), sempre a árvore
   inteira (ignora tarefas recolhidas — é um relatório, não um print da
   tela) ---------- */
function projTarefasListaLinear(){
  const lista = [];
  (function visitar(paiId, nivel){
    projFilhosDe(paiId).forEach(t=>{
      lista.push({ t, nivel });
      visitar(t.id, nivel+1);
    });
  })(null, 0);
  return lista;
}
function projValorColunaTexto(t, key, nivel){
  const numero = projTarefaNumeros.get(String(t.id)) || '';
  switch(key){
    case 'numero': return String(numero);
    case 'edt': return projTarefaEdt.get(String(t.id)) || '';
    case 'nome': return '  '.repeat(nivel) + t.titulo;
    case 'status': return t.status;
    case 'inativa': return t.inativa ? 'Sim' : 'Não';
    case 'segmento': return t.segmento || '';
    case 'modulo': return t.modulo || '';
    case 'submodulo': return t.submodulo || '';
    case 'prioridade': return String(t.prioridade ?? 500);
    case 'modo': return t.modo === 'MANUAL' ? 'Manual' : 'Automático';
    case 'duracao': return `${t.duracaoDias||1} d`;
    case 'duracaoEstimada': return t.duracaoEstimada ? 'Sim' : 'Não';
    case 'inicio': return t.dataInicio ? String(t.dataInicio).split('-').reverse().join('/') : '';
    case 'termino': return t.dataFim ? String(t.dataFim).split('-').reverse().join('/') : '';
    case 'concluidoEm': return t.concluidoEm ? new Date(t.concluidoEm).toLocaleDateString('pt-BR') : '';
    case 'anotacoes': return t.descricao || '';
    case 'percentual': return `${t.percentualConcluido||0}%`;
    case 'recursos': return t.responsavel || '';
    case 'atendimentos': return String((t.atendimentoIds||[]).length || 0);
    case 'predecessoras': return (t.predecessorasIds||[]).map(pid=>projTarefaNumeros.get(String(pid))).filter(n=>n!==undefined).sort((a,b)=>a-b).join(',');
    default: return '';
  }
}
function gerarPdfTarefasProjeto(){
  if(!projetoAtual) return;
  projNumerarTarefas();
  const colunas = colunasVisiveisTarefas().filter(c=>!c.semExportar);
  const linhas = projTarefasListaLinear();
  const corpoHtml = linhas.map(({t,nivel})=>`<tr>${colunas.map(c=>`<td class="${c.num?'num':''}">${escaparHtml(projValorColunaTexto(t, c.key, c.key==='nome'?nivel:0))}</td>`).join('')}</tr>`).join('');
  document.getElementById('printProjetoTarefas').innerHTML = `
    <table class="proj-print-tabela">
      <thead><tr>${colunas.map(c=>`<th class="${c.num?'num':''}">${escaparHtml(c.label)}</th>`).join('')}</tr></thead>
      <tbody>${corpoHtml || `<tr><td colspan="${colunas.length}">Nenhuma tarefa.</td></tr>`}</tbody>
    </table>`;
  document.body.classList.add('print-modo-projeto-tarefas');
  window.addEventListener('afterprint', ()=>{ document.body.classList.remove('print-modo-projeto-tarefas'); }, { once:true });
  prepararImpressao(`Tarefas — ${projetoAtual.nome}`, '', 'printArea');
}
// cores de status igual ao "bom/neutro" clássico do próprio Excel — mesma
// leitura visual da bateria colorida da tela (verde concluída, amarelo em
// andamento), só que como preenchimento de célula em vez de barra
function projCorExcelPorStatus(status){
  if(status==='Concluída') return { fill:'C6EFCE', texto:'006100' };
  if(status==='Em Andamento') return { fill:'FFEB9C', texto:'9C6500' };
  if(status==='Agendado') return { fill:'E4DFEC', texto:'5F497A' };
  if(status==='Parado') return { fill:'FFC7CE', texto:'9C0006' };
  return null;
}
async function gerarExcelTarefasProjeto(){
  if(typeof XLSX === 'undefined'){ toast('Não foi possível carregar o gerador de Excel. Confira sua internet.'); return; }
  if(!projetoAtual) return;
  projNumerarTarefas();
  const colunas = colunasVisiveisTarefas().filter(c=>!c.semExportar);
  const linhasTarefas = projTarefasListaLinear();

  const aoa = [colunas.map(c=>c.label)];
  linhasTarefas.forEach(({t,nivel})=>{
    aoa.push(colunas.map(c=>projValorColunaTexto(t, c.key, c.key==='nome'?nivel:0)));
  });
  const planilha = XLSX.utils.aoa_to_sheet(aoa);

  // cabeçalho: negrito branco sobre fundo escuro, igual um relatório de
  // verdade (a tela usa cinza claro, mas aqui destaca mais o topo fixo)
  colunas.forEach((c, idx)=>{
    const cel = planilha[XLSX.utils.encode_cell({ r:0, c:idx })];
    if(cel) cel.s = { font:{ bold:true, color:{ rgb:'FFFFFF' } }, fill:{ fgColor:{ rgb:'305496' } }, alignment:{ vertical:'center' } };
  });

  // linhas: tarefa-mãe em negrito + fundo cinza (igual a tabela na tela) e
  // a célula de Status colorida por status (igual a bateria/tag da tela)
  linhasTarefas.forEach(({t}, i)=>{
    const linha = i + 1; // +1 porque a linha 0 é o cabeçalho
    const ehMae = projFilhosDe(t.id).length > 0;
    const corStatus = projCorExcelPorStatus(t.status);
    colunas.forEach((c, idx)=>{
      const cel = planilha[XLSX.utils.encode_cell({ r:linha, c:idx })];
      if(!cel) return;
      const estilo = {};
      if(ehMae) estilo.fill = { fgColor:{ rgb:'F2F2F2' } };
      if(ehMae) estilo.font = { bold:true };
      if(c.key==='status' && corStatus){
        estilo.fill = { fgColor:{ rgb: corStatus.fill } };
        estilo.font = { ...(estilo.font||{}), color:{ rgb: corStatus.texto } };
      }
      if(Object.keys(estilo).length>0) cel.s = estilo;
    });
  });

  // largura de coluna proporcional à largura em pixels usada na tela
  planilha['!cols'] = colunas.map(c=>({ wch: Math.max(6, Math.round((c.largura||100)/7)) }));

  const livro = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(livro, planilha, 'Tarefas');
  const nomeArquivo = ('tarefas-' + projetoAtual.nome)
    .toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'') + '.xlsx';
  await salvarWorkbook(livro, nomeArquivo);
}

/* ---------- importar tarefas de uma planilha Excel — espelha exatamente o
   "Gerar Excel" acima: mesmos rótulos de coluna (PROJ_COLUNAS_TAREFAS),
   hierarquia pela indentação de "Nome da tarefa" (2 espaços por nível,
   igual projValorColunaTexto escreve) e Predecessoras por número (igual a
   coluna exportada). Cada linha vira uma tarefa NOVA — não atualiza nem
   casa com tarefas já existentes no projeto. ---------- */
function projNormalizarCabecalhoImportacao(s){
  return String(s||'').trim().toLowerCase().replace(/\s+/g,' ');
}
function projParseDataBrParaIso(txt){
  const m = String(txt||'').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if(!m) return '';
  const [,d,mo,y] = m;
  return `${y}-${mo.padStart(2,'0')}-${d.padStart(2,'0')}`;
}
async function importarExcelTarefasProjeto(arquivo){
  if(typeof XLSX === 'undefined'){ toast('Não foi possível carregar o leitor de Excel. Confira sua internet.'); return; }
  if(!projetoAtual) return;

  let linhas;
  try{
    const wb = XLSX.read(await arquivo.arrayBuffer(), { type:'array' });
    const sheet = wb.Sheets[wb.SheetNames[0]];
    linhas = XLSX.utils.sheet_to_json(sheet, { header:1, defval:'' });
  }catch(e){
    toast('Não foi possível ler o arquivo. Confira se é um .xlsx válido.');
    return;
  }
  if(linhas.length < 2){ toast('Planilha vazia ou sem dados.'); return; }

  const colunasPorLabel = new Map(PROJ_COLUNAS_TAREFAS.filter(c=>c.label).map(c=>[projNormalizarCabecalhoImportacao(c.label), c.key]));
  const chavesColuna = linhas[0].map(h=>colunasPorLabel.get(projNormalizarCabecalhoImportacao(h)) || null);
  const idxNome = chavesColuna.indexOf('nome');
  if(idxNome < 0){ toast('A planilha precisa ter a coluna "Nome da tarefa" (mesmo cabeçalho gerado pelo "Gerar Excel").'); return; }

  pedirConfirmacao('Importar tarefas do Excel?', 'Cada linha da planilha vira uma tarefa nova — não atualiza nem substitui as tarefas que já existem nesse projeto.', async ()=>{
    const conta = contaAtual();
    const paiPorNivel = {};
    const numeroParaId = {};
    const predecessorasPendentes = [];
    let criadas = 0, falharam = 0;

    for(let i=1;i<linhas.length;i++){
      const linha = linhas[i];
      const brutoNome = String(linha[idxNome] ?? '');
      if(!brutoNome.trim()) continue;

      const nivel = Math.floor((brutoNome.match(/^ */)[0].length)/2);
      const titulo = brutoNome.trim();
      const campos = {};
      chavesColuna.forEach((chave, idx)=>{
        if(!chave || chave==='nome') return;
        campos[chave] = String(linha[idx] ?? '').trim();
      });

      const payload = {
        projetoId: projetoAtualId, contaId: conta.id, titulo,
        tarefaPaiId: nivel>0 ? (paiPorNivel[nivel-1]||'') : '',
        // MANUAL por padrão: preserva as datas literais da planilha; só vira
        // AUTOMÁTICO se a própria linha tiver "Automático" na coluna Modo
        modo: 'MANUAL',
      };
      if(campos.status !== undefined) payload.status = PROJ_TAREFA_STATUS.includes(campos.status) ? campos.status : 'Não Iniciado';
      if(campos.inativa !== undefined) payload.inativa = campos.inativa.toLowerCase()==='sim';
      if(campos.segmento !== undefined) payload.segmento = campos.segmento;
      if(campos.modulo !== undefined) payload.modulo = campos.modulo;
      if(campos.submodulo !== undefined) payload.submodulo = campos.submodulo;
      if(campos.prioridade !== undefined) payload.prioridade = parseInt(campos.prioridade,10) || 500;
      if(campos.modo !== undefined) payload.modo = campos.modo.toLowerCase()==='manual' ? 'MANUAL' : 'AUTOMÁTICO';
      if(campos.duracao !== undefined) payload.duracaoDias = parseInt(campos.duracao,10) || 1;
      if(campos.duracaoEstimada !== undefined) payload.duracaoEstimada = campos.duracaoEstimada.toLowerCase()==='sim';
      if(campos.inicio !== undefined) payload.dataInicio = projParseDataBrParaIso(campos.inicio);
      if(campos.termino !== undefined) payload.dataFim = projParseDataBrParaIso(campos.termino);
      if(campos.anotacoes !== undefined) payload.descricao = campos.anotacoes;
      if(campos.percentual !== undefined) payload.percentualConcluido = parseInt(campos.percentual,10) || 0;
      if(campos.recursos !== undefined) payload.responsavel = campos.recursos;

      const r = await api('criarTarefa', payload);
      if(!r.ok){ falharam++; continue; }
      criadas++;
      paiPorNivel[nivel] = r.id;
      Object.keys(paiPorNivel).forEach(n=>{ if(Number(n) > nivel) delete paiPorNivel[n]; });

      const numeroPlanilha = campos.numero !== undefined ? parseInt(campos.numero,10) : i;
      if(Number.isFinite(numeroPlanilha)) numeroParaId[numeroPlanilha] = r.id;
      if(campos.predecessoras) predecessorasPendentes.push({ id: r.id, texto: campos.predecessoras });
    }

    // predecessoras num segundo passo — precisam de todas as tarefas já
    // criadas pra resolver "número da planilha" -> id novo de verdade
    for(const { id, texto } of predecessorasPendentes){
      const ids = [...new Set(texto.split(',').map(s=>s.trim()).filter(Boolean).map(s=>parseInt(s,10)).filter(Number.isFinite).map(n=>numeroParaId[n]).filter(Boolean))];
      if(ids.length===0) continue;
      await api('atualizarTarefa', { id, contaId: conta.id, predecessorasIds: ids });
    }

    const rFinal = await api('obterProjeto', { id: projetoAtualId, contaId: conta.id });
    if(rFinal.ok) projetoTarefas = rFinal.tarefas || [];
    toast(falharam>0 ? `${criadas} tarefa(s) importada(s), ${falharam} falharam.` : `${criadas} tarefa(s) importada(s) com sucesso.`);
    renderTabelaTarefas();
    if(projSubAba==='kanban') renderKanbanProjeto();
    else if(projSubAba==='gantt') renderGanttProjeto();
    else if(projSubAba==='mapa') renderMapaMentalProjeto();
    else if(projSubAba==='dashboard') renderDashboardProjeto();
    else if(projSubAba==='quadro') renderQuadroProjeto();
  }, 'Importar');
}

function projAlternarColapso(id){
  if(projTarefaColapsadas.has(id)) projTarefaColapsadas.delete(id);
  else projTarefaColapsadas.add(id);
  renderTabelaTarefas();
}
async function projAdicionarTarefaUi(tarefaPaiId){
  const conta = contaAtual();
  const r = await api('criarTarefa', { projetoId: projetoAtualId, tarefaPaiId: tarefaPaiId || '', titulo: 'Nova tarefa', contaId: conta.id });
  if(!r.ok){ toast(r.erro || 'Não foi possível criar a tarefa.'); return; }
  projetoTarefas = r.tarefas || projetoTarefas;
  if(tarefaPaiId) projTarefaColapsadas.delete(tarefaPaiId);
  renderTabelaTarefas();
  if(projSubAba==='kanban') renderKanbanProjeto();
  else if(projSubAba==='gantt') renderGanttProjeto();
  else if(projSubAba==='quadro') renderQuadroProjeto();
  const inputs = document.querySelectorAll('#projTarefasTabelaCorpo .proj-tarefa-titulo');
  const ultimo = inputs[inputs.length-1];
  if(ultimo){ ultimo.focus(); ultimo.select(); }
}
async function projSalvarCampoTarefa(id, campo, valor){
  const conta = contaAtual();
  const r = await api('atualizarTarefa', { id, contaId: conta.id, [campo]: valor });
  if(!r.ok){ toast(r.erro || 'Não foi possível salvar.'); renderTabelaTarefas(); return; }
  projetoTarefas = r.tarefas || projetoTarefas;
  renderTabelaTarefas();
  if(projSubAba==='kanban') renderKanbanProjeto();
  else if(projSubAba==='gantt') renderGanttProjeto();
  else if(projSubAba==='quadro') renderQuadroProjeto();
}
async function projSalvarPredecessoras(id, texto){
  const numeros = texto.split(',').map(s=>s.trim()).filter(Boolean).map(s=>parseInt(s,10)).filter(n=>Number.isFinite(n));
  const ids = [...new Set(numeros.map(n=>projTarefaPorNumero[n]).filter(Boolean).filter(pid=>String(pid)!==String(id)))];
  const conta = contaAtual();
  const r = await api('atualizarTarefa', { id, predecessorasIds: ids, contaId: conta.id });
  if(!r.ok){ toast(r.erro || 'Não foi possível salvar as predecessoras.'); renderTabelaTarefas(); return; }
  projetoTarefas = r.tarefas || projetoTarefas;
  renderTabelaTarefas();
  if(projSubAba==='gantt') renderGanttProjeto();
  else if(projSubAba==='quadro') renderQuadroProjeto();
}
function projDescendentesDe(id){
  const diretos = projFilhosDe(id);
  return diretos.concat(diretos.flatMap(f=>projDescendentesDe(f.id)));
}
function projRemoverTarefaUi(id){
  const temFilhos = projFilhosDe(id).length > 0;
  pedirConfirmacao(
    'Remover tarefa?',
    temFilhos ? 'Remove essa tarefa e todas as subtarefas dela — não dá pra desfazer.' : 'Não dá pra desfazer.',
    async ()=>{
      const conta = contaAtual();
      const r = await api('removerTarefa', { id, contaId: conta.id });
      if(!r.ok){ toast(r.erro || 'Não foi possível remover.'); return; }
      const idsRemovidos = new Set([id, ...projDescendentesDe(id).map(t=>t.id)]);
      projetoTarefas = r.tarefas || projetoTarefas.filter(t=>!idsRemovidos.has(t.id));
      renderTabelaTarefas();
      if(projSubAba==='kanban') renderKanbanProjeto();
      else if(projSubAba==='quadro') renderQuadroProjeto();
      toast('Tarefa removida');
    },
    'Remover'
  );
}

/* ---------- Quadro — mesmas tarefas da aba Tarefas, agrupadas por Segmento
   num formato tipo board (uma linha por tarefa raiz, com as subtarefas
   escondidas numa mini-tabela por baixo). É só outra visualização dos
   mesmos dados — as colunas (menos "Tarefa", que é fixa) podem ser
   escondidas em "⚙ Colunas" (preferência salva por navegador, mesmo
   esquema da tabela Tarefas) e os campos editáveis lá também são editáveis
   aqui, reaproveitando as mesmas células/onchange/onblur. Reaproveita
   .tag.status-*, .avatar e projBateriaHtml já usados no resto do app. ---------- */
// as colunas do Quadro são as MESMAS de PROJ_COLUNAS_TAREFAS (assim toda
// coluna que existe em Tarefas também pode ser escolhida/editada aqui),
// menos "toggle" (o Quadro tem seu próprio botão de recolher embutido no
// nome) — e com "Cronograma" (faixa Início–Término, só leitura) adicionada
// como coluna extra exclusiva do Quadro. Tarefa raiz e subtarefa têm cada
// uma sua própria visibilidade/ordem de colunas (independentes).
const PROJ_QUADRO_COLUNAS = PROJ_COLUNAS_TAREFAS
  .filter(c=>c.key!=='toggle')
  .map(c=>({...c}))
  .concat([{ key:'cronograma', label:'Cronograma', largura:120 }]);
// no Quadro a coluna Ações só tem o botão "⋮" (bem mais estreita do que
// na tabela Tarefas, que mostra os 3 ícones lado a lado)
PROJ_QUADRO_COLUNAS.find(c=>c.key==='acoes').largura = 46;
const PROJ_QUADRO_PADRAO_VISIVEIS = ['recursos','status','percentual','duracao','cronograma','inicio','termino'];
const PROJ_QUADRO_SUB_PADRAO_VISIVEIS = ['recursos','status','cronograma','anotacoes','predecessoras'];
// ordem inicial "arrumada" (só até acomodar as colunas visíveis por
// padrão + as fixas — o resto, que começa escondido, vem depois na ordem
// natural de PROJ_COLUNAS_TAREFAS) pra não nascer bagunçado antes do
// usuário arrastar pela primeira vez; uma vez que ele arrasta, o que fica
// salvo no navegador manda
const PROJ_QUADRO_ORDEM_PADRAO = ['numero','nome','status','percentual','duracao','cronograma','inicio','termino','recursos','acoes'];
const PROJ_QUADRO_SUB_ORDEM_PADRAO = ['numero','nome','recursos','status','cronograma','anotacoes','predecessoras','acoes'];
// "conjunto de colunas" — mesma mecânica (ordem arrastável + visibilidade
// opcional, cada uma persistida por navegador) usada duas vezes (tarefa
// raiz e subtarefa), por isso virou uma fábrica em vez de duplicar tudo
function projQuadroCriarConjuntoColunas(chaveOrdem, chaveVisiveis, chaveLarguras, padraoVisiveis, ordemPadrao){
  let ordem = ordemPadrao || null;
  let visiveis = new Set(padraoVisiveis);
  let larguras = {};
  try{
    const salvoOrdem = JSON.parse(localStorage.getItem(chaveOrdem)||'null');
    if(Array.isArray(salvoOrdem)) ordem = salvoOrdem;
  }catch(e){ /* mantém null (ordem padrão) */ }
  try{
    const salvoVis = JSON.parse(localStorage.getItem(chaveVisiveis)||'null');
    if(Array.isArray(salvoVis)) visiveis = new Set(salvoVis);
  }catch(e){ /* mantém o padrão */ }
  try{
    const salvoLarguras = JSON.parse(localStorage.getItem(chaveLarguras)||'null');
    if(salvoLarguras && typeof salvoLarguras==='object') larguras = salvoLarguras;
  }catch(e){ /* mantém o padrão */ }
  function ordenadasBase(){
    if(!ordem) return PROJ_QUADRO_COLUNAS;
    const porKey = new Map(PROJ_QUADRO_COLUNAS.map(c=>[c.key,c]));
    const out = ordem.map(k=>porKey.get(k)).filter(Boolean);
    PROJ_QUADRO_COLUNAS.forEach(c=>{ if(!out.includes(c)) out.push(c); });
    return out;
  }
  return {
    visiveisSet: visiveis,
    ordenadasBase,
    visiveisOrdenadas(){ return ordenadasBase().filter(c=>c.fixa || visiveis.has(c.key)); },
    reordenar(campoArrastado, campoAlvo){
      if(!campoArrastado || !campoAlvo || campoArrastado===campoAlvo) return;
      const atual = ordenadasBase().map(c=>c.key);
      const semArrastado = atual.filter(k=>k!==campoArrastado);
      const idxAlvo = semArrastado.indexOf(campoAlvo);
      if(idxAlvo===-1) return;
      semArrastado.splice(idxAlvo, 0, campoArrastado);
      ordem = semArrastado;
      try{ localStorage.setItem(chaveOrdem, JSON.stringify(ordem)); }catch(e){}
    },
    alternarVisivel(key, visivel){
      if(visivel) visiveis.add(key);
      else visiveis.delete(key);
      try{ localStorage.setItem(chaveVisiveis, JSON.stringify([...visiveis])); }catch(e){}
    },
    largura(col){ return larguras[col.key] || col.largura || 100; },
    definirLargura(key, px){
      larguras[key] = px;
      try{ localStorage.setItem(chaveLarguras, JSON.stringify(larguras)); }catch(e){}
    },
  };
}
const projQuadroColunas = projQuadroCriarConjuntoColunas('projQuadroColunasOrdem_v1', 'projQuadroColunasVisiveis_v2', 'projQuadroColunasLarguras_v1', PROJ_QUADRO_PADRAO_VISIVEIS, PROJ_QUADRO_ORDEM_PADRAO);
const projQuadroSubColunas = projQuadroCriarConjuntoColunas('projQuadroSubColunasOrdem_v1', 'projQuadroSubColunasVisiveis_v2', 'projQuadroSubColunasLarguras_v1', PROJ_QUADRO_SUB_PADRAO_VISIVEIS, PROJ_QUADRO_SUB_ORDEM_PADRAO);
function renderPainelColunasQuadroGenerico(elId, conjunto){
  const painel = document.getElementById(elId);
  const opcionais = PROJ_QUADRO_COLUNAS.filter(c=>!c.fixa);
  painel.innerHTML = opcionais.map(c=>`
    <label style="display:flex;align-items:center;gap:8px;font-size:12.5px;padding:4px 0;cursor:pointer;white-space:nowrap;">
      <input type="checkbox" style="width:auto;" ${conjunto.visiveisSet.has(c.key)?'checked':''} onchange="projQuadroAlternarColunaGenerico(this, '${c.key}')">
      ${escaparHtml(c.label)}
    </label>`).join('');
  painel.dataset.conjunto = elId==='projQuadroColunasPainel' ? 'principal' : 'sub';
}
function renderPainelColunasQuadro(){ renderPainelColunasQuadroGenerico('projQuadroColunasPainel', projQuadroColunas); }
function renderPainelColunasQuadroSub(){ renderPainelColunasQuadroGenerico('projQuadroSubColunasPainel', projQuadroSubColunas); }
function projQuadroAlternarColunaGenerico(checkboxEl, key){
  const painel = checkboxEl.closest('.proj-colunas-painel');
  const conjunto = painel.dataset.conjunto==='sub' ? projQuadroSubColunas : projQuadroColunas;
  conjunto.alternarVisivel(key, checkboxEl.checked);
  renderQuadroProjeto();
}
const PROJ_QUADRO_MESES = ['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
function projQuadroDataCurta(iso){
  if(!iso) return '';
  const [y,m,d] = String(iso).split('-').map(Number);
  if(!y||!m||!d) return '';
  return `${d} ${PROJ_QUADRO_MESES[m-1]}`;
}
function projQuadroDataLonga(iso){
  if(!iso) return '';
  const [y,m,d] = String(iso).split('-').map(Number);
  if(!y||!m||!d) return '';
  return `${d} ${PROJ_QUADRO_MESES[m-1]}, ${y}`;
}
function projQuadroCronogramaTexto(inicio, fim){
  if(!inicio && !fim) return '';
  if(inicio && !fim) return projQuadroDataCurta(inicio);
  if(!inicio && fim) return projQuadroDataCurta(fim);
  if(inicio===fim) return projQuadroDataCurta(inicio);
  const [ya,ma,da] = String(inicio).split('-').map(Number);
  const [yb,mb,db] = String(fim).split('-').map(Number);
  if(ya===yb && ma===mb) return `${da} – ${db} ${PROJ_QUADRO_MESES[mb-1]}`;
  return `${projQuadroDataCurta(inicio)} – ${projQuadroDataCurta(fim)}`;
}
function projQuadroIniciais(primeiroNome){
  const partes = String(primeiroNome||'').trim().split(/\s+/).filter(Boolean);
  if(partes.length===0) return '';
  if(partes.length===1) return partes[0].slice(0,2).toUpperCase();
  return (partes[0][0]+partes[partes.length-1][0]).toUpperCase();
}
// hash simples e determinístico (mesmo nome sempre cai na mesma cor,
// entre sessões/recarregamentos) — usado tanto pra colorir avatar de
// recurso quanto rótulo de grupo
function projQuadroHash(texto){
  let h = 0;
  const s = String(texto||'');
  for(let i=0;i<s.length;i++) h = (h*31 + s.charCodeAt(i)) >>> 0;
  return h;
}
const PROJ_QUADRO_CORES_AVATAR = ['#e6577a','#5b6fd8','#2fa89a','#e08a3c','#8a6bd6','#4fa8d8','#c9574f','#4fae6e','#c77dc9','#a8843c','#4f9dc9','#d65f8e'];
function projQuadroCorAvatar(nome){
  return PROJ_QUADRO_CORES_AVATAR[projQuadroHash(nome) % PROJ_QUADRO_CORES_AVATAR.length];
}
// cores de agrupamento reaproveitam os tokens semânticos já existentes no
// app (mesma paleta usada em status/gráficos), só pra dar uma cor
// diferente e consistente por Segmento — não tem relação com status
const PROJ_QUADRO_CORES_GRUPO = ['--ok','--blue','--bad','--warn','--purple','--yellow','--accent','--muted'];
function projQuadroCorGrupo(nome){
  return `var(${PROJ_QUADRO_CORES_GRUPO[projQuadroHash(nome) % PROJ_QUADRO_CORES_GRUPO.length]})`;
}
function projQuadroAvatarHtml(responsavel){
  const nomes = String(responsavel||'').split(',').map(s=>s.trim()).filter(Boolean);
  if(nomes.length===0) return `<span class="avatar proj-quadro-avatar-vazio" title="Sem recurso definido">?</span>`;
  return nomes.map(n=>`<span class="avatar" style="background:${projQuadroCorAvatar(n)};color:#fff;" title="${escaparHtml(n)}">${escaparHtml(projQuadroIniciais(n))}</span>`).join('');
}
function projQuadroCronogramaHtml(inicio, fim){
  const texto = projQuadroCronogramaTexto(inicio, fim);
  if(!texto) return `<span class="proj-quadro-cron vazio">sem data</span>`;
  return `<span class="proj-quadro-cron">${escaparHtml(texto)}</span>`;
}
// descendentes achatados (todos os níveis abaixo da tarefa raiz), na
// ordem da árvore, cada um com seu nível (1 = filho direto da raiz, 2 =
// neto, ...) e se tem filhos — a sub-tabela do Quadro mostra tudo achatado
// (sem tabela aninhada dentro de tabela aninhada), mas com indentação por
// nível, toggle de recolher pra quem tem filho, e some com os
// descendentes de quem estiver recolhido (mesmo projTarefaColapsadas
// global, então o estado é o mesmo entre Quadro e Tarefas)
function projQuadroDescendentes(paiId, nivel){
  nivel = nivel || 1;
  return projFilhosDe(paiId).flatMap(t=>{
    const filhosDele = projFilhosDe(t.id);
    const item = { t, nivel, temFilhos: filhosDele.length>0 };
    if(filhosDele.length===0 || projTarefaColapsadas.has(t.id)) return [item];
    return [item, ...projQuadroDescendentes(t.id, nivel+1)];
  });
}
let projQuadroGruposColapsados = new Set();
function projQuadroAlternarGrupo(nomeGrupo){
  if(projQuadroGruposColapsados.has(nomeGrupo)) projQuadroGruposColapsados.delete(nomeGrupo);
  else projQuadroGruposColapsados.add(nomeGrupo);
  renderQuadroProjeto();
}
function projQuadroAlternarTarefa(id){
  if(projTarefaColapsadas.has(id)) projTarefaColapsadas.delete(id);
  else projTarefaColapsadas.add(id);
  renderQuadroProjeto();
}
async function projQuadroAdicionarTarefa(segmento){
  const conta = contaAtual();
  const r = await api('criarTarefa', { projetoId: projetoAtualId, tarefaPaiId: '', titulo: 'Nova tarefa', contaId: conta.id, segmento: segmento || '' });
  if(!r.ok){ toast(r.erro || 'Não foi possível criar a tarefa.'); return; }
  projetoTarefas = r.tarefas || projetoTarefas;
  renderQuadroProjeto();
}
// select de status estilizado como as mesmas .tag.status-* usadas no resto
// do app (a cor muda sozinha no próximo render, já que toda edição do
// Quadro recarrega projetoTarefas inteiro e rechama renderQuadroProjeto)
function projQuadroStatusSelectHtml(t){
  return `<select class="tag status-${statusSlug(t.status)}" onchange="projSalvarCampoTarefa('${t.id}','status',this.value)">
    ${PROJ_TAREFA_STATUS.map(s=>`<option value="${s}" ${s===t.status?'selected':''}>${s}</option>`).join('')}
  </select>`;
}
// nome da tarefa RAIZ — igual à célula "nome" de Tarefas, mas com o botão
// de recolher/expandir subtarefas e o contador embutidos (o Quadro não
// tem coluna própria de recolher, é parte do nome)
function projQuadroCelulaTarefaPrincipal(t, filhos){
  return `<td>
    <div class="proj-quadro-nome">
      <button type="button" class="proj-quadro-toggle${filhos.length===0?' oculto':''}" onclick="projQuadroAlternarTarefa('${t.id}')">▾</button>
      <input type="text" class="proj-tarefa-titulo proj-quadro-titulo-input" value="${escaparHtml(t.titulo)}" onblur="projSalvarCampoTarefa('${t.id}','titulo',this.value)">
      ${filhos.length>0?`<span class="proj-quadro-sub-conta">${filhos.length}</span>`:''}
    </div>
  </td>`;
}
// nome de uma linha da sub-tabela (subtarefa) — indentado por nível e,
// quando ela mesma tem filhos, com toggle de recolher (igual "mãe" da
// tabela Tarefas); a linha toda ganha a classe proj-tarefa-mae pra ficar
// cinza, distinguindo de quem é só folha
function projQuadroCelulaSubNome(t, filhos, nivel){
  return `<td>
    <div class="proj-tarefa-nome-linha" style="padding-left:${nivel*16}px;">
      <button type="button" class="proj-quadro-toggle${filhos.length===0?' oculto':''}" onclick="projQuadroAlternarTarefa('${t.id}')">▾</button>
      <input type="text" class="proj-tarefa-titulo" value="${escaparHtml(t.titulo)}" onblur="projSalvarCampoTarefa('${t.id}','titulo',this.value)">
    </div>
  </td>`;
}
function projQuadroCelulaPercentual(t, filhos){
  const pct = t.percentualConcluido||0;
  if(filhos.length>0){
    return `<td><div class="proj-quadro-nome" style="gap:8px;" title="Calculado automaticamente a partir das subtarefas">${projBateriaHtml(pct)}<span style="color:var(--muted);font-size:11.5px;">${pct}%</span></div></td>`;
  }
  return `<td><div class="proj-quadro-nome" style="gap:8px;">${projBateriaHtml(pct)}<input type="number" min="0" max="100" step="1" value="${pct}" style="width:42px;" onchange="projSalvarCampoTarefa('${t.id}','percentualConcluido',this.value)"></div></td>`;
}
// o menu de ações (⋮) e o picker de recursos (bolinhas + "+") nasceram no
// Quadro mas agora são reaproveitados na tabela Tarefas também — como o
// estado é compartilhado entre as duas telas, o toggle/fechar precisa
// redesenhar QUALQUER UMA que estiver ativa no momento, não sempre o Quadro
function projRenderizarAbaTarefasAtual(){
  if(projSubAba==='quadro') renderQuadroProjeto();
  else renderTabelaTarefas();
}
// coluna Recursos — só as bolinhas (uma por pessoa, cor consistente por
// nome); escolher quem é responsável é pelo "+", que abre uma listinha
// marcável com os recursos já cadastrados no projeto (aba Recursos)
let projQuadroRecursoPickerAberto = null;
function projQuadroAlternarPickerRecursos(id){
  projQuadroRecursoPickerAberto = (projQuadroRecursoPickerAberto === id) ? null : id;
  projQuadroMenuAcoesAberto = null;
  projRenderizarAbaTarefasAtual();
}
function projQuadroFecharPickerRecursos(){
  projQuadroRecursoPickerAberto = null;
  projRenderizarAbaTarefasAtual();
}
function projQuadroAlternarRecursoTarefa(id, nomeRecurso, marcado){
  const t = projetoTarefas.find(x=>String(x.id)===String(id));
  if(!t) return;
  const atuais = String(t.responsavel||'').split(',').map(s=>s.trim()).filter(Boolean);
  const novos = marcado ? [...new Set([...atuais, nomeRecurso])] : atuais.filter(n=>n!==nomeRecurso);
  projSalvarCampoTarefa(id, 'responsavel', novos.join(', '));
}
function projQuadroPickerRecursosHtml(t){
  const atuais = new Set(String(t.responsavel||'').split(',').map(s=>s.trim()).filter(Boolean));
  if(projRecursosCadastro.length===0){
    return `<div class="proj-quadro-menu-acoes proj-quadro-picker-recursos"><div style="padding:6px 8px;color:var(--muted);font-size:12px;white-space:normal;max-width:180px;">Nenhum recurso cadastrado no projeto ainda — cadastre na aba Recursos.</div></div>`;
  }
  return `<div class="proj-quadro-menu-acoes proj-quadro-picker-recursos">
    ${projRecursosCadastro.map(r=>`
      <label>
        <input type="checkbox" style="width:auto;" ${atuais.has(r.nome)?'checked':''} onchange="projQuadroAlternarRecursoTarefa('${t.id}', '${escaparHtml(r.nome).replace(/'/g,"\\'")}', this.checked)">
        ${escaparHtml(r.nome)}
      </label>`).join('')}
  </div>`;
}
function projQuadroCelulaRecursos(t){
  const aberto = projQuadroRecursoPickerAberto === t.id;
  return `<td class="proj-td-sem-clip">
    <div class="proj-quadro-recursos-cel">
      <div class="proj-quadro-avatares">${projQuadroAvatarHtml(t.responsavel)}</div>
      <div class="proj-quadro-menu-wrap">
        <button type="button" class="proj-quadro-recurso-add" title="Escolher recursos" onclick="event.stopPropagation();projQuadroAlternarPickerRecursos('${t.id}')">+</button>
        ${aberto ? projQuadroPickerRecursosHtml(t) : ''}
      </div>
    </div>
  </td>`;
}
// menu de ações do Quadro — a coluna "Ações" da tabela Tarefas tem 3
// botões (ℹ/+/🗑) lado a lado, mas no Quadro a coluna é estreita e eles
// quebram linha (empilham verticalmente); aqui vira 1 botão só (⋮) que
// abre um menu com as mesmas 3 opções. Só um menu fica aberto por vez.
let projQuadroMenuAcoesAberto = null;
function projQuadroAlternarMenuAcoes(id){
  projQuadroMenuAcoesAberto = (projQuadroMenuAcoesAberto === id) ? null : id;
  projQuadroRecursoPickerAberto = null;
  projRenderizarAbaTarefasAtual();
}
function projQuadroFecharMenuAcoes(){
  projQuadroMenuAcoesAberto = null;
  projRenderizarAbaTarefasAtual();
}
function projQuadroCelulaAcoes(t){
  const aberto = projQuadroMenuAcoesAberto === t.id;
  return `<td class="proj-quadro-acoes-cel proj-td-sem-clip">
    <div class="proj-quadro-menu-wrap">
      <button type="button" class="ghost proj-quadro-menu-btn" title="Ações" onclick="event.stopPropagation();projQuadroAlternarMenuAcoes('${t.id}')">⋮</button>
      ${aberto ? `<div class="proj-quadro-menu-acoes">
        <button type="button" onclick="projQuadroFecharMenuAcoes();projAbrirInfoTarefa('${t.id}')">ℹ Informações da tarefa</button>
        <button type="button" onclick="projQuadroFecharMenuAcoes();projAdicionarTarefaUi('${t.id}')">+ Nova subtarefa</button>
        <button type="button" class="danger" onclick="projQuadroFecharMenuAcoes();projRemoverTarefaUi('${t.id}')">🗑 Remover</button>
      </div>` : ''}
    </div>
  </td>`;
}
// dispatcher das células — "nome"/"recursos"/"status"/"percentual"/
// "cronograma"/"acoes" têm tratamento visual próprio do Quadro; todas as
// outras colunas (as mesmas de PROJ_COLUNAS_TAREFAS) reaproveitam DIRETO
// a mesma função de célula da tabela Tarefas, garantindo a mesma edição
function projQuadroCelulaHtml(t, filhos, key, ehSub, nivel){
  if(key==='nome') return ehSub ? projQuadroCelulaSubNome(t, filhos, nivel||1) : projQuadroCelulaTarefaPrincipal(t, filhos);
  if(key==='recursos') return projQuadroCelulaRecursos(t);
  if(key==='status') return `<td>${projQuadroStatusSelectHtml(t)}</td>`;
  if(key==='percentual') return projQuadroCelulaPercentual(t, filhos);
  if(key==='cronograma') return `<td>${projQuadroCronogramaHtml(t.dataInicio, t.dataFim)}</td>`;
  if(key==='acoes') return projQuadroCelulaAcoes(t);
  const colapsada = projTarefaColapsadas.has(t.id);
  const numero = projTarefaNumeros.get(String(t.id)) || '';
  const predTexto = (t.predecessorasIds||[])
    .map(pid=>projTarefaNumeros.get(String(pid)))
    .filter(n=>n!==undefined)
    .sort((a,b)=>a-b)
    .join(',');
  return projTarefaCelulaHtml(t, 0, filhos, colapsada, numero, predTexto, key, true);
}
function projQuadroCabecalhoHtml(colunas, tipo){
  return colunas.map(c=>{
    const classes = [c.num?'num':'', c.semResize?'':'lista-th-arrastavel'].filter(Boolean).join(' ');
    const resizer = c.semResize ? '' : `<span class="proj-col-resizer" onmousedown="projQuadroIniciarResizeColuna(event,'${c.key}','${tipo}')"></span>`;
    return `<th${classes?` class="${classes}"`:''} data-col="${c.key}" title="${c.semResize?'':'Arraste pra reordenar'}">${escaparHtml(c.label)}${resizer}</th>`;
  }).join('');
}
function projQuadroColgroupHtml(colunas, conjunto){
  return `<colgroup>${colunas.map(c=>`<col style="width:${conjunto.largura(c)}px;">`).join('')}</colgroup>`;
}
function projQuadroSubtarefaLinhaHtml({t, nivel, temFilhos}, colunasSub){
  const filhos = projFilhosDe(t.id);
  const colapsada = projTarefaColapsadas.has(t.id);
  const celulas = colunasSub.map(c=>projQuadroCelulaHtml(t, filhos, c.key, true, nivel)).join('');
  const classes = [`status-${statusSlug(t.status)}`, temFilhos?'proj-tarefa-mae':'', colapsada?'colapsada':''].filter(Boolean).join(' ');
  return `<tr data-id="${t.id}" class="${classes}">${celulas}</tr>`;
}
function projQuadroTarefaLinhaHtml(t, colunas, colunasSub){
  const filhos = projFilhosDe(t.id);
  const colapsada = projTarefaColapsadas.has(t.id);
  const celulas = colunas.map(c=>projQuadroCelulaHtml(t, filhos, c.key, false)).join('');
  return `<tr class="proj-quadro-tarefa-linha status-${statusSlug(t.status)}${colapsada?' colapsada':''}" data-id="${t.id}">${celulas}</tr>${filhos.length>0?`<tr class="proj-quadro-sub-wrap"${colapsada?' style="display:none;"':''}>
    <td colspan="${colunas.length}">
      <div class="proj-quadro-sub-caixa">
        <div class="proj-quadro-sub-scroll">
          <table class="proj-quadro-sub-tabela">
            ${projQuadroColgroupHtml(colunasSub, projQuadroSubColunas)}
            <thead><tr>${projQuadroCabecalhoHtml(colunasSub, 'sub')}</tr></thead>
            <tbody>${projQuadroDescendentes(t.id).map(item=>projQuadroSubtarefaLinhaHtml(item, colunasSub)).join('')}</tbody>
          </table>
        </div>
        <button type="button" class="proj-quadro-add" onclick="projAdicionarTarefaUi('${t.id}')">+ Adicionar subtarefa</button>
      </div>
    </td>
  </tr>`:''}`;
}
function projQuadroGrupoHtml(nomeGrupo, tarefas, colunas, colunasSub){
  const colapsado = projQuadroGruposColapsados.has(nomeGrupo);
  const cor = projQuadroCorGrupo(nomeGrupo);
  const somaDuracao = tarefas.reduce((s,t)=>s+(Number(t.duracaoDias)||0),0);
  const somaPeso = tarefas.reduce((s,t)=>s+Math.max(1,Number(t.duracaoDias)||1),0);
  const somaPct = tarefas.reduce((s,t)=>s+Math.max(1,Number(t.duracaoDias)||1)*(Number(t.percentualConcluido)||0),0);
  const pctGrupo = somaPeso>0 ? Math.round(somaPct/somaPeso) : 0;
  return `<tbody>
    <tr class="proj-quadro-grupo-linha${colapsado?' colapsado':''}">
      <td colspan="${colunas.length}">
        <div class="proj-quadro-grupo-barra" onclick="projQuadroAlternarGrupo('${escaparHtml(nomeGrupo).replace(/'/g,"\\'")}')">
          <div class="rail" style="background:${cor};"></div>
          <span class="proj-quadro-grupo-chevron" style="color:${cor};">▾</span>
          <span class="proj-quadro-grupo-titulo" style="color:${cor};">${escaparHtml(nomeGrupo)}</span>
          <span class="proj-quadro-grupo-conta">${tarefas.length} tarefa${tarefas.length===1?'':'s'} · ${somaDuracao} d · ${pctGrupo}% concl.</span>
        </div>
      </td>
    </tr>
  </tbody>
  <tbody class="proj-quadro-corpo${colapsado?' colapsado':''}">
    ${tarefas.map(t=>projQuadroTarefaLinhaHtml(t, colunas, colunasSub)).join('')}
    <tr><td colspan="${colunas.length}"><button type="button" class="proj-quadro-add" onclick="projQuadroAdicionarTarefa('${escaparHtml(nomeGrupo==='(sem segmento)'?'':nomeGrupo).replace(/'/g,"\\'")}')">+ Adicionar tarefa</button></td></tr>
  </tbody>`;
}
function projQuadroRodapeCelulaHtml(key, ctx){
  switch(key){
    case 'nome': return `<td><span class="k">Total</span></td>`;
    case 'status': return `<td>${ctx.raiz.length} tarefa${ctx.raiz.length===1?'':'s'}</td>`;
    case 'percentual': return `<td>${ctx.pctGeral}%</td>`;
    case 'duracao': return `<td class="num">${ctx.todasDuracao} d</td>`;
    case 'cronograma': return `<td>${ctx.rangeTexto}</td>`;
    default: return '<td></td>';
  }
}
function renderQuadroProjeto(){
  const wrap = document.getElementById('projQuadroWrap');
  projNumerarTarefas();
  const raiz = projFilhosDe(null);
  if(raiz.length===0){
    wrap.innerHTML = `<div class="proj-quadro-board" style="padding:24px;text-align:center;color:var(--muted);">Nenhuma tarefa ainda.</div>`;
    return;
  }
  const colunas = projQuadroColunas.visiveisOrdenadas();
  const colunasSub = projQuadroSubColunas.visiveisOrdenadas();
  const grupos = new Map();
  raiz.forEach(t=>{
    const nome = t.segmento || '(sem segmento)';
    if(!grupos.has(nome)) grupos.set(nome, []);
    grupos.get(nome).push(t);
  });
  const todasDuracao = raiz.reduce((s,t)=>s+(Number(t.duracaoDias)||0),0);
  const pesoTotal = raiz.reduce((s,t)=>s+Math.max(1,Number(t.duracaoDias)||1),0);
  const pctTotal = raiz.reduce((s,t)=>s+Math.max(1,Number(t.duracaoDias)||1)*(Number(t.percentualConcluido)||0),0);
  const pctGeral = pesoTotal>0 ? Math.round(pctTotal/pesoTotal) : 0;
  const datasInicio = raiz.map(t=>t.dataInicio).filter(Boolean).sort();
  const datasFim = raiz.map(t=>t.dataFim).filter(Boolean).sort();
  const rangeTexto = datasInicio[0]&&datasFim[datasFim.length-1] ? escaparHtml(projQuadroDataCurta(datasInicio[0])+' – '+projQuadroDataCurta(datasFim[datasFim.length-1])) : '—';
  const ctx = { raiz, pctGeral, todasDuracao, rangeTexto };
  wrap.innerHTML = `
    <div class="proj-quadro-board">
      <div class="proj-quadro-scroll">
        <table class="proj-quadro-tabela">
          ${projQuadroColgroupHtml(colunas, projQuadroColunas)}
          <thead>
            <tr>${projQuadroCabecalhoHtml(colunas, 'principal')}</tr>
          </thead>
          ${[...grupos.entries()].map(([nome,tarefas])=>projQuadroGrupoHtml(nome,tarefas,colunas,colunasSub)).join('')}
          <tfoot>
            <tr class="proj-quadro-rodape">
              ${colunas.map(c=>projQuadroRodapeCelulaHtml(c.key, ctx)).join('')}
            </tr>
          </tfoot>
        </table>
      </div>
    </div>`;
}
// arrastar cabeçalho pra reordenar — mesmo mecanismo (Pointer Events +
// ghost) de projIniciarDragColunaTarefas, só que genérico pros dois
// "conjuntos" de colunas do Quadro (tarefa raiz e subtarefa) e sem
// resize (o Quadro não tem largura de coluna ajustável)
function projQuadroIniciarDragColuna(e, thEl, tabelaSeletor, conjunto){
  const campo = thEl.dataset.col;
  if(!campo) return;
  // a sub-tabela de subtarefas fica ANINHADA dentro de uma célula da
  // tabela principal, então um simples ".proj-quadro-tabela thead th"
  // também bateria com cabeçalhos da sub-tabela (ela é descendente da
  // principal); por isso o alvo do "solte aqui" precisa estar no MESMO
  // nível (dentro ou fora de uma .proj-quadro-sub-tabela) que a coluna
  // sendo arrastada
  const arrastandoDaSub = tabelaSeletor === '.proj-quadro-sub-tabela';
  const label = thEl.textContent.trim();
  const startX = e.clientX, startY = e.clientY;
  const rect = thEl.getBoundingClientRect();
  const offsetX = e.clientX-rect.left, offsetY = e.clientY-rect.top;
  let arrastando = false, ghost = null, thAlvo = null;
  thEl.setPointerCapture(e.pointerId);
  function limpar(){ if(thAlvo) thAlvo.classList.remove('lista-th-drop-alvo'); thAlvo = null; }
  function mover(ev){
    if(!arrastando){
      if(Math.hypot(ev.clientX-startX, ev.clientY-startY) < 6) return;
      arrastando = true;
      ghost = document.createElement('div');
      ghost.className = 'lista-coluna-ghost';
      ghost.textContent = label;
      document.body.appendChild(ghost);
    }
    ghost.style.left = (ev.clientX-offsetX)+'px';
    ghost.style.top = (ev.clientY-offsetY)+'px';
    ghost.style.display = 'none';
    const alvoEl = document.elementFromPoint(ev.clientX, ev.clientY);
    ghost.style.display = '';
    limpar();
    const thCandidato = alvoEl && alvoEl.closest('thead th[data-col]');
    const thHover = (thCandidato && !!thCandidato.closest('.proj-quadro-sub-tabela') === arrastandoDaSub) ? thCandidato : null;
    if(thHover && thHover !== thEl){
      thAlvo = thHover;
      thAlvo.classList.add('lista-th-drop-alvo');
    }
  }
  function soltar(){
    thEl.removeEventListener('pointermove', mover);
    if(arrastando){
      const alvo = thAlvo ? thAlvo.dataset.col : null;
      limpar();
      ghost.remove();
      if(alvo){ conjunto.reordenar(campo, alvo); renderQuadroProjeto(); }
    }
  }
  function cancelar(){
    thEl.removeEventListener('pointermove', mover);
    limpar();
    if(ghost) ghost.remove();
  }
  thEl.addEventListener('pointermove', mover);
  thEl.addEventListener('pointerup', soltar, { once:true });
  thEl.addEventListener('pointercancel', cancelar, { once:true });
}
// redimensionar coluna — mesmo mecanismo de projIniciarResizeColuna
// (mousedown na alcinha, arrasta, solta), só que aplica a largura em
// TODAS as tabelas daquele "tipo" ao mesmo tempo (uma tarefa raiz aberta
// mexe só na principal; como pode ter várias sub-tabelas abertas ao
// mesmo tempo — uma por tarefa expandida — elas todas usam a MESMA
// configuração de colunas da subtarefa, então redimensionar uma redimensiona
// todas, pra ficarem sempre consistentes entre si)
let projQuadroResizeEstado = null;
function projQuadroIniciarResizeColuna(e, key, tipo){
  e.preventDefault();
  e.stopPropagation();
  const conjunto = tipo==='sub' ? projQuadroSubColunas : projQuadroColunas;
  const col = PROJ_QUADRO_COLUNAS.find(c=>c.key===key);
  if(!col) return;
  const idx = conjunto.visiveisOrdenadas().findIndex(c=>c.key===key);
  if(idx===-1) return;
  projQuadroResizeEstado = { conjunto, key, tipo, idx, xInicial: e.clientX, larguraInicial: conjunto.largura(col) };
  document.addEventListener('mousemove', projQuadroMoverResizeColuna);
  document.addEventListener('mouseup', projQuadroFinalizarResizeColuna, { once:true });
}
function projQuadroTabelasDoTipo(tipo){
  return tipo==='sub'
    ? document.querySelectorAll('.proj-quadro-sub-tabela')
    : document.querySelectorAll('table.proj-quadro-tabela');
}
function projQuadroMoverResizeColuna(e){
  if(!projQuadroResizeEstado) return;
  const { idx, tipo, xInicial, larguraInicial } = projQuadroResizeEstado;
  const nova = Math.max(40, larguraInicial + (e.clientX - xInicial));
  projQuadroTabelasDoTipo(tipo).forEach(tabela=>{
    const colEl = tabela.querySelectorAll(':scope > colgroup > col')[idx];
    if(colEl) colEl.style.width = nova+'px';
  });
}
function projQuadroFinalizarResizeColuna(e){
  document.removeEventListener('mousemove', projQuadroMoverResizeColuna);
  if(!projQuadroResizeEstado) return;
  const { conjunto, key, xInicial, larguraInicial } = projQuadroResizeEstado;
  const nova = Math.max(40, larguraInicial + (e.clientX - xInicial));
  conjunto.definirLargura(key, nova);
  projQuadroResizeEstado = null;
}

/* ---------- Excel do Quadro — mesmo mecanismo/estilo de gerarExcelTarefasProjeto
   (xlsx-js-style: cabeçalho escuro em negrito, mãe cinza+negrito, Status
   colorido), só que reproduzindo o agrupamento por Segmento da tela: uma
   linha mesclada e colorida por grupo (mesma cor do rail na tela), seguida
   das tarefas raiz daquele grupo com toda a hierarquia de subtarefas
   indentada — exporta as colunas visíveis/na ordem atual do Quadro. ---------- */
const PROJ_QUADRO_CORES_GRUPO_HEX = ['70AD47','4472C4','C00000','ED7D31','7030A0','BF8F00','1F8A70','808080'];
function projQuadroCorHexGrupo(nome){
  return PROJ_QUADRO_CORES_GRUPO_HEX[projQuadroHash(nome) % PROJ_QUADRO_CORES_GRUPO_HEX.length];
}
function projValorColunaTextoQuadro(t, key, nivel){
  if(key==='cronograma') return projQuadroCronogramaTexto(t.dataInicio, t.dataFim) || 'sem data';
  return projValorColunaTexto(t, key, nivel);
}
async function gerarExcelQuadroProjeto(){
  if(typeof XLSX === 'undefined'){ toast('Não foi possível carregar o gerador de Excel. Confira sua internet.'); return; }
  if(!projetoAtual) return;
  projNumerarTarefas();
  const colunas = projQuadroColunas.visiveisOrdenadas().filter(c=>!c.semExportar);
  const raiz = projFilhosDe(null);
  const grupos = new Map();
  raiz.forEach(t=>{
    const nome = t.segmento || '(sem segmento)';
    if(!grupos.has(nome)) grupos.set(nome, []);
    grupos.get(nome).push(t);
  });

  const aoa = [colunas.map(c=>c.label)];
  const infoLinhas = [null]; // paralelo a aoa; null = linha de cabeçalho

  function empilharComDescendentes(t, nivel){
    aoa.push(colunas.map(c=>projValorColunaTextoQuadro(t, c.key, c.key==='nome'?nivel:0)));
    infoLinhas.push({ tarefa:t });
    projFilhosDe(t.id).forEach(filho=>empilharComDescendentes(filho, nivel+1));
  }
  grupos.forEach((tarefas, nomeGrupo)=>{
    const somaDuracao = tarefas.reduce((s,t)=>s+(Number(t.duracaoDias)||0),0);
    const linhaGrupo = new Array(colunas.length).fill('');
    linhaGrupo[0] = `${nomeGrupo} — ${tarefas.length} tarefa${tarefas.length===1?'':'s'} · ${somaDuracao} d`;
    aoa.push(linhaGrupo);
    infoLinhas.push({ grupo: nomeGrupo });
    tarefas.forEach(t=>empilharComDescendentes(t, 0));
  });

  const planilha = XLSX.utils.aoa_to_sheet(aoa);

  colunas.forEach((c, idx)=>{
    const cel = planilha[XLSX.utils.encode_cell({ r:0, c:idx })];
    if(cel) cel.s = { font:{ bold:true, color:{ rgb:'FFFFFF' } }, fill:{ fgColor:{ rgb:'305496' } }, alignment:{ vertical:'center' } };
  });

  const merges = [];
  infoLinhas.forEach((info, r)=>{
    if(!info) return;
    if(info.grupo){
      const corHex = projQuadroCorHexGrupo(info.grupo);
      colunas.forEach((c, idx)=>{
        const endereco = XLSX.utils.encode_cell({ r, c:idx });
        if(!planilha[endereco]) planilha[endereco] = { t:'s', v:'' };
        planilha[endereco].s = { font:{ bold:true, color:{ rgb:'FFFFFF' } }, fill:{ fgColor:{ rgb: corHex } } };
      });
      if(colunas.length>1) merges.push({ s:{ r, c:0 }, e:{ r, c:colunas.length-1 } });
      return;
    }
    const t = info.tarefa;
    const ehMae = projFilhosDe(t.id).length > 0;
    const corStatus = projCorExcelPorStatus(t.status);
    colunas.forEach((c, idx)=>{
      const cel = planilha[XLSX.utils.encode_cell({ r, c:idx })];
      if(!cel) return;
      const estilo = {};
      if(ehMae){ estilo.fill = { fgColor:{ rgb:'F2F2F2' } }; estilo.font = { bold:true }; }
      if(c.key==='status' && corStatus){
        estilo.fill = { fgColor:{ rgb: corStatus.fill } };
        estilo.font = { ...(estilo.font||{}), color:{ rgb: corStatus.texto } };
      }
      if(Object.keys(estilo).length>0) cel.s = estilo;
    });
  });
  if(merges.length) planilha['!merges'] = merges;

  planilha['!cols'] = colunas.map(c=>({ wch: Math.max(6, Math.round((projQuadroColunas.largura(c)||100)/7)) }));

  const livro = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(livro, planilha, 'Quadro');
  const nomeArquivo = ('quadro-' + projetoAtual.nome)
    .toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'') + '.xlsx';
  await salvarWorkbook(livro, nomeArquivo);
}

/* ---------- tela "Informações sobre a tarefa" (estilo MS Project) — Geral/
   Predecessoras/Recursos/Anotações. Início/Término/Duração salvam na hora
   (um campo por vez, reaproveitando a mesma sincronia de 3 vias e o
   recálculo automático em cadeia que já valida a edição rápida da tabela);
   os demais campos (inclusive Predecessoras com Tipo/Latência e Recursos
   com Unidades/Custo) só vão pro servidor quando clicar em Salvar. ---------- */
let pitTarefaId = null;
let pitPredecessoras = [];
let pitRecursos = [];

function projAbrirInfoTarefa(id){
  const t = projetoTarefas.find(x=>String(x.id)===String(id));
  if(!t) return;
  pitTarefaId = id;
  pitPredecessoras = (t.predecessoras||[]).map(p=>({...p}));
  pitRecursos = (t.recursos||[]).map(r=>({...r}));

  const numero = projTarefaNumeros.get(String(id)) || '';
  document.getElementById('projInfoTarefaTitulo').textContent = `Informações sobre a tarefa — Nº ${numero}`;
  document.getElementById('pit_nome').value = t.titulo || '';
  document.getElementById('pit_duracao').value = t.duracaoDias || 1;
  document.getElementById('pit_duracao_estimada').checked = !!t.duracaoEstimada;
  document.getElementById('pit_percentual').value = t.percentualConcluido || 0;
  const temFilhosInfo = projFilhosDe(id).length > 0;
  document.getElementById('pit_percentual').disabled = temFilhosInfo;
  document.getElementById('pit_percentual').title = temFilhosInfo ? 'Calculado automaticamente a partir das subtarefas' : '';
  document.getElementById('pit_duracao').disabled = temFilhosInfo;
  document.getElementById('pit_duracao').title = temFilhosInfo ? 'Calculado automaticamente a partir das subtarefas' : '';
  document.getElementById('pit_prioridade').value = t.prioridade ?? 500;
  document.getElementById('pit_inativa').checked = !!t.inativa;
  const radioModo = document.querySelector(`input[name="pit_modo"][value="${t.modo==='MANUAL'?'MANUAL':'AUTOMÁTICO'}"]`);
  if(radioModo) radioModo.checked = true;
  document.getElementById('pit_inicio').value = t.dataInicio || '';
  document.getElementById('pit_fim').value = t.dataFim || '';
  document.getElementById('pit_inicio').disabled = temFilhosInfo;
  document.getElementById('pit_inicio').title = temFilhosInfo ? 'Calculado automaticamente a partir das subtarefas' : '';
  document.getElementById('pit_fim').disabled = temFilhosInfo;
  document.getElementById('pit_fim').title = temFilhosInfo ? 'Calculado automaticamente a partir das subtarefas' : '';
  document.getElementById('pit_anotacoes').value = t.descricao || '';
  projPitPopularSegmentoModuloRotina(t.segmento || '', t.modulo || '', t.submodulo || '');

  projPitGoTab('geral');
  projPitRenderPredecessoras();
  projPitRenderRecursos();
  projPitRenderAtendimentos();
  carregarAnexosTarefa(id);
  carregarAtualizacoesTarefa(id);
  document.getElementById('pit_atualizacao_texto').innerHTML = '';
  document.getElementById('projInfoTarefaModal').classList.add('show');
}
function projPitFechar(){
  document.getElementById('projInfoTarefaModal').classList.remove('show');
  pitTarefaId = null;
}
function projPitGoTab(tab){
  document.querySelectorAll('#projInfoTarefaTabs .subtab').forEach(el=>el.classList.toggle('active', el.dataset.infotab===tab));
  document.querySelectorAll('.proj-info-tab').forEach(el=>{ el.style.display = (el.id === 'projInfoTab-'+tab) ? '' : 'none'; });
}
// Início/Término/Duração salvam individualmente assim que mudam (mesmo
// caminho da edição rápida na tabela) — evita reimplementar a sincronia de
// 3 vias e o recálculo de predecessoras em cadeia em duas versões diferentes
async function projPitAtualizarCampoData(campo, valor){
  if(!pitTarefaId) return;
  const conta = contaAtual();
  const r = await api('atualizarTarefa', { id: pitTarefaId, contaId: conta.id, [campo]: valor });
  if(!r.ok){ toast(r.erro || 'Não foi possível salvar.'); return; }
  projetoTarefas = r.tarefas || projetoTarefas;
  const t = projetoTarefas.find(x=>String(x.id)===String(pitTarefaId));
  if(t){
    document.getElementById('pit_duracao').value = t.duracaoDias || 1;
    document.getElementById('pit_inicio').value = t.dataInicio || '';
    document.getElementById('pit_fim').value = t.dataFim || '';
  }
  renderTabelaTarefas();
  if(projSubAba==='kanban') renderKanbanProjeto();
  else if(projSubAba==='gantt') renderGanttProjeto();
  else if(projSubAba==='quadro') renderQuadroProjeto();
}
function projPitRenderPredecessoras(){
  const corpo = document.getElementById('pitPredecessorasCorpo');
  if(pitPredecessoras.length===0){ corpo.innerHTML = `<tr><td colspan="5" style="text-align:center;color:var(--muted);padding:10px;">Nenhuma predecessora.</td></tr>`; return; }
  corpo.innerHTML = pitPredecessoras.map((p,i)=>{
    const numero = projTarefaNumeros.get(String(p.predecessoraId)) || '';
    const outra = projetoTarefas.find(x=>String(x.id)===String(p.predecessoraId));
    return `<tr>
      <td><input type="number" min="1" value="${numero}" onchange="projPitAlterarPredecessoraNumero(${i},this.value)" style="width:56px;"></td>
      <td>${escaparHtml(outra ? outra.titulo : '(tarefa não encontrada)')}</td>
      <td><select onchange="projPitAlterarPredecessoraCampo(${i},'tipo',this.value)">
        <option value="FS" ${p.tipo==='FS'?'selected':''}>FS</option>
        <option value="SS" ${p.tipo==='SS'?'selected':''}>SS</option>
        <option value="FF" ${p.tipo==='FF'?'selected':''}>FF</option>
        <option value="SF" ${p.tipo==='SF'?'selected':''}>SF</option>
      </select></td>
      <td><input type="number" value="${p.latenciaDias||0}" onchange="projPitAlterarPredecessoraCampo(${i},'latenciaDias',parseInt(this.value,10)||0)" style="width:64px;"></td>
      <td><button type="button" class="danger" onclick="projPitRemoverPredecessora(${i})">🗑</button></td>
    </tr>`;
  }).join('');
}
function projPitAlterarPredecessoraNumero(i, valor){
  const numero = parseInt(valor, 10);
  const id = projTarefaPorNumero[numero];
  if(!id || String(id)===String(pitTarefaId)){ toast('Número de tarefa inválido.'); projPitRenderPredecessoras(); return; }
  pitPredecessoras[i].predecessoraId = id;
  projPitRenderPredecessoras();
}
function projPitAlterarPredecessoraCampo(i, campo, valor){
  pitPredecessoras[i][campo] = valor;
}
function projPitAdicionarPredecessora(){
  const candidata = projetoTarefas.find(t=>String(t.id)!==String(pitTarefaId) && !pitPredecessoras.some(p=>String(p.predecessoraId)===String(t.id)));
  if(!candidata){ toast('Não há outra tarefa disponível pra ser predecessora.'); return; }
  pitPredecessoras.push({ predecessoraId: candidata.id, tipo: 'FS', latenciaDias: 0 });
  projPitRenderPredecessoras();
}
function projPitRemoverPredecessora(i){
  pitPredecessoras.splice(i, 1);
  projPitRenderPredecessoras();
}
function projPitRenderRecursos(){
  const corpo = document.getElementById('pitRecursosCorpo');
  const podeVerCustos = projPodeVerCustos();
  document.getElementById('pit_th_custo').style.display = podeVerCustos ? '' : 'none';
  if(pitRecursos.length===0){ corpo.innerHTML = `<tr><td colspan="${podeVerCustos?4:3}" style="text-align:center;color:var(--muted);padding:10px;">Nenhum recurso.</td></tr>`; return; }
  corpo.innerHTML = pitRecursos.map((r,i)=>{
    const cad = projRecursosCadastro.find(rc=>rc.nome===r.nome);
    const atendenteConta = cad && cad.atendenteId ? contas.find(c=>String(c.id)===String(cad.atendenteId)) : null;
    return `
    <tr>
      <td>
        <select onchange="projPitSelecionarRecursoCadastro(${i},this.value)">
          <option value="">Selecione...</option>
          ${projRecursosCadastro.map(rc=>`<option value="${escaparHtml(rc.nome)}" ${rc.nome===r.nome?'selected':''}>${escaparHtml(rc.nome)}</option>`).join('')}
        </select>
      </td>
      <td><input type="number" min="0" max="100" value="${r.unidades??100}" onchange="projPitAlterarRecursoCampo(${i},'unidades',parseInt(this.value,10)||0)" style="width:64px;"></td>
      ${podeVerCustos ? `<td>R$ <input type="number" min="0" step="0.01" value="${r.custo||0}" onchange="projPitAlterarRecursoCampo(${i},'custo',parseFloat(this.value)||0)" style="width:80px;"></td>` : ''}
      <td>
        ${atendenteConta ? `<button type="button" class="ghost" title="Criar atendimento pra ${escaparHtml(atendenteConta.nome)}" onclick="projCriarAtendimentoParaRecurso('${escaparHtml(atendenteConta.nome)}')">📋</button>` : ''}
        <button type="button" class="danger" onclick="projPitRemoverRecurso(${i})">🗑</button>
      </td>
    </tr>`;
  }).join('');
}
function projPitSelecionarRecursoCadastro(i, nome){
  const rc = projRecursosCadastro.find(x=>x.nome===nome);
  pitRecursos[i].nome = nome;
  if(rc) pitRecursos[i].custo = rc.custo;
  projPitRenderRecursos();
}
function projPitAlterarRecursoCampo(i, campo, valor){
  pitRecursos[i][campo] = valor;
}
function projPitAdicionarRecurso(){
  if(projRecursosCadastro.length===0){ toast('Cadastre um recurso na aba Recursos do projeto primeiro.'); return; }
  pitRecursos.push({ nome: '', unidades: 100, custo: 0 });
  projPitRenderRecursos();
}
function projPitRemoverRecurso(i){
  pitRecursos.splice(i, 1);
  projPitRenderRecursos();
}
async function projPitSalvar(){
  if(!pitTarefaId) return;
  const modoEl = document.querySelector('input[name="pit_modo"]:checked');
  const payload = {
    id: pitTarefaId, contaId: contaAtual().id,
    titulo: document.getElementById('pit_nome').value,
    percentualConcluido: document.getElementById('pit_percentual').value,
    prioridade: document.getElementById('pit_prioridade').value,
    duracaoEstimada: document.getElementById('pit_duracao_estimada').checked,
    inativa: document.getElementById('pit_inativa').checked,
    modo: modoEl ? modoEl.value : 'AUTOMÁTICO',
    descricao: document.getElementById('pit_anotacoes').value,
    segmento: document.getElementById('pit_segmento').value,
    modulo: document.getElementById('pit_modulo').value,
    submodulo: document.getElementById('pit_submodulo').value,
    predecessoras: pitPredecessoras.filter(p=>p.predecessoraId),
    recursos: pitRecursos.filter(r=>r.nome && r.nome.trim()),
  };
  const r = await api('atualizarTarefa', payload);
  if(!r.ok){ toast(r.erro || 'Não foi possível salvar.'); return; }
  projetoTarefas = r.tarefas || projetoTarefas;
  projPitFechar();
  renderTabelaTarefas();
  if(projSubAba==='kanban') renderKanbanProjeto();
  else if(projSubAba==='gantt') renderGanttProjeto();
  else if(projSubAba==='quadro') renderQuadroProjeto();
  toast('Tarefa atualizada');
}

// abre "Novo atendimento" já com o atendente preenchido (e o cliente do
// projeto, se bater com um cadastrado) — ao salvar, o atendimento novo
// volta a ser vinculado a este projeto automaticamente (ver salvarRegistro)
function projCriarAtendimentoParaRecurso(nomeAtendente){
  if(!projetoAtualId || !pitTarefaId) return;
  const tarefa = projetoTarefas.find(x=>String(x.id)===String(pitTarefaId));
  projVincularAposSalvarAtendimento = { projetoId: projetoAtualId, tarefaId: pitTarefaId };
  projPitFechar();
  goView('novo');
  resetForm();
  setLookupSingleValor('f_atendente', nomeAtendente);
  if(tarefa){
    document.getElementById('f_assunto').value = tarefa.titulo || '';
    if(tarefa.segmento){
      popularSelectSegmento(tarefa.segmento);
      popularSelectModuloPorSegmento(tarefa.segmento, tarefa.modulo || '');
      popularSelectRotinaPorModulo(tarefa.modulo || '', tarefa.submodulo || '');
    }
  }
  if(projetoAtual && projetoAtual.cliente){
    const cli = clientes.find(c=>c.nome===projetoAtual.cliente);
    if(cli){
      document.getElementById('f_cliente').value = cli.id;
      popularUsuariosSolicitantes();
    }
  }
  toast('Preencha os dados e salve — o atendimento será vinculado a este projeto e a esta tarefa automaticamente.');
}

function projPitRenderAtendimentos(){
  const cont = document.getElementById('pitAtendimentosLista');
  const t = projetoTarefas.find(x=>String(x.id)===String(pitTarefaId));
  const ids = t ? (t.atendimentoIds || []) : [];
  if(ids.length===0){ cont.innerHTML = `<span style="color:var(--muted);font-size:12px;">Nenhum atendimento vinculado ainda.</span>`; return; }
  cont.innerHTML = ids.map(id=>{
    const at = atendimentos.find(x=>String(x.id)===String(id));
    const texto = at ? `#${escaparHtml(String(at.id))} — ${escaparHtml(at.cliente)} · ${escaparHtml(at.usuario)}` : `#${escaparHtml(String(id))}`;
    return `<span class="lookup-tag" style="cursor:pointer;" onclick="abrirDetalhe('${id}')">${texto}<button type="button" onclick="event.stopPropagation();projPitDesvincularAtendimento('${id}')">×</button></span>`;
  }).join('');
}
async function projPitDesvincularAtendimento(atendimentoId){
  if(!pitTarefaId) return;
  const conta = contaAtual();
  const r = await api('desvincularAtendimentoTarefa', { tarefaId: pitTarefaId, atendimentoId, contaId: conta.id });
  if(!r.ok){ toast(r.erro || 'Não foi possível remover o vínculo.'); return; }
  const t = projetoTarefas.find(x=>String(x.id)===String(pitTarefaId));
  if(t) t.atendimentoIds = (t.atendimentoIds||[]).filter(x=>String(x)!==String(atendimentoId));
  projPitRenderAtendimentos();
}

/* ---------- anexos da tarefa — tabela própria (projeto_tarefa_anexos),
   mesmo padrão de anexos de orçamento/atividade ---------- */
async function carregarAnexosTarefa(tarefaId){
  const cont = document.getElementById('pitAnexosLista');
  cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Carregando…</div>`;
  try{
    const r = await api('listarAnexosTarefa', { tarefaId });
    if(!r.ok){ cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">${r.erro || 'Não foi possível carregar.'}</div>`; return; }
    renderAnexosTarefaLista(r.anexos, tarefaId);
  }catch(e){
    cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Não foi possível carregar os anexos.</div>`;
  }
}
function renderAnexosTarefaLista(lista, tarefaId){
  const cont = document.getElementById('pitAnexosLista');
  if(!lista || lista.length === 0){ cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Nenhum anexo ainda.</div>`; return; }
  cont.innerHTML = lista.map(a=>`
    <div class="anexo-item">
      <a href="${a.url}" target="_blank">📎 ${escaparHtml(a.nome||'anexo')}</a>
      <a href="${urlDownloadAnexo(a.url, a.nome)}" title="Baixar arquivo original">⬇ Baixar</a>
      <button type="button" onclick="removerAnexoTarefaUi('${a.id}','${tarefaId}')">remover</button>
    </div>`).join('');
}
async function adicionarAnexoTarefaUi(tarefaId, arquivo){
  if(arquivo.size > 8 * 1024 * 1024){ toast('Anexo muito grande (máx. 8MB)'); return; }
  toast('Enviando anexo…');
  try{
    const base64 = await lerArquivoBase64(arquivo);
    const r = await api('adicionarAnexoTarefa', { tarefaId, base64, tipo: arquivo.type, nome: arquivo.name });
    if(!r.ok){ toast(r.erro || 'Não foi possível enviar o anexo.'); return; }
    await carregarAnexosTarefa(tarefaId);
    toast('Anexo adicionado');
  }catch(e){
    toast(e && e.message ? e.message : 'Não foi possível enviar o anexo.');
  }
}
async function removerAnexoTarefaUi(id, tarefaId){
  const r = await api('removerAnexoTarefa', { id });
  if(!r.ok){ toast(r.erro || 'Não foi possível remover.'); return; }
  await carregarAnexosTarefa(tarefaId);
  toast('Anexo removido');
}

/* ---------- Atualizações da tarefa — duas origens misturadas na mesma
   lista: "automatica" (o próprio servidor gera ao gravar atualizarTarefa,
   comparando o antes/depois de Status/datas/% concluída/Recursos/
   Prioridade/Segmento-Módulo-Rotina/Nome) e "manual" (comentário digitado
   aqui, com texto rico — mesmo editor .rt-toolbar/.rt-editor já usado nas
   Movimentações de atendimento e na Solução). ---------- */
let pitAtualizacoesCache = [];
async function carregarAtualizacoesTarefa(tarefaId){
  const cont = document.getElementById('pitAtualizacoesLista');
  cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Carregando…</div>`;
  try{
    const r = await api('listarAtualizacoesTarefa', { tarefaId });
    if(!r.ok){ cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">${r.erro || 'Não foi possível carregar.'}</div>`; return; }
    pitAtualizacoesCache = r.atualizacoes || [];
    renderAtualizacoesTarefaLista();
  }catch(e){
    cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Não foi possível carregar as atualizações.</div>`;
  }
}
function renderAtualizacoesTarefaLista(){
  const cont = document.getElementById('pitAtualizacoesLista');
  if(pitAtualizacoesCache.length === 0){ cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Nenhuma atualização ainda.</div>`; return; }
  cont.innerHTML = pitAtualizacoesCache.map(a=>{
    if(a.tipo === 'automatica'){
      return `<div class="mov-item pit-atualizacao-auto">
        <div class="mov-topo">
          <div class="mov-autor"><span style="font-size:13px;">🔄</span><span class="mov-nome">${escaparHtml(a.autorNome)}</span></div>
          <div class="mov-data">${movFmtDataHora(a.criadoEm)}</div>
        </div>
        <div class="mov-conteudo rt-content">${sanitizarHtml(a.texto)}</div>
      </div>`;
    }
    return `<div class="mov-item">
      <div class="mov-topo">
        <div class="mov-autor"><div class="mov-avatar">${movIniciais(a.autorNome)}</div><span class="mov-nome">${escaparHtml(a.autorNome)}</span></div>
        <div class="mov-data">${movFmtDataHora(a.criadoEm)}</div>
      </div>
      <div class="mov-conteudo rt-content">${sanitizarHtml(a.texto)}</div>
    </div>`;
  }).join('');
}
async function enviarAtualizacaoTarefaUi(){
  if(!pitTarefaId) return;
  const editor = document.getElementById('pit_atualizacao_texto');
  const texto = sanitizarHtml(editor.innerHTML.trim());
  if(!stripHtml(texto)){ toast('Escreva algo antes de adicionar.'); return; }
  const conta = contaAtual();
  const r = await api('criarAtualizacaoTarefa', { tarefaId: pitTarefaId, texto, contaId: conta.id });
  if(!r.ok){ toast(r.erro || 'Não foi possível adicionar a atualização.'); return; }
  editor.innerHTML = '';
  pitAtualizacoesCache.push(r.atualizacao);
  renderAtualizacoesTarefaLista();
  toast('Atualização adicionada');
}

/* ---------- Kanban de tarefas (uma coluna por status de PROJ_TAREFA_STATUS
   — status de tarefa não é um cadastro, ao contrário do status de
   atendimento) ---------- */
function renderKanbanProjeto(){
  const board = document.getElementById('projKanbanBoard');
  const porStatus = {};
  projetoTarefas.forEach(t=>{ (porStatus[t.status] = porStatus[t.status] || []).push(t); });
  board.innerHTML = PROJ_TAREFA_STATUS.map(nome=>{
    const lista = porStatus[nome] || [];
    const cards = lista.map(t=>projKanbanCardHtml(t)).join('');
    return `
    <div class="kanban-col">
      <div class="kanban-col-header status-${statusSlug(nome)}">
        <div class="titulo"><span class="kanban-col-dot" style="background:${corStatusDot(nome)};"></span><span>${escaparHtml(nome)}</span></div>
        <span class="kanban-col-count">${lista.length}</span>
      </div>
      <div class="kanban-col-body" data-status="${escaparHtml(nome)}">
        ${cards || `<div class="kanban-col-empty">Nenhuma tarefa</div>`}
      </div>
    </div>`;
  }).join('');
}
function projKanbanCardHtml(t){
  const pai = t.tarefaPaiId ? projetoTarefas.find(x=>String(x.id)===String(t.tarefaPaiId)) : null;
  return `
    <div class="kanban-card" data-id="${t.id}" data-status="${escaparHtml(t.status)}">
      <div class="kanban-card-handle">⠿</div>
      <div class="kanban-card-body">
        <div class="cliente">${escaparHtml(t.titulo)}</div>
        ${pai ? `<div class="data">↳ ${escaparHtml(pai.titulo)}</div>` : ''}
        <div class="meta">
          ${t.responsavel ? `<span class="tag">${escaparHtml(t.responsavel)}</span>` : ''}
          ${t.dataFim ? `<span class="tag">${String(t.dataFim).split('-').reverse().join('/')}</span>` : ''}
        </div>
      </div>
    </div>`;
}

let kanbanDragTarefa = null;
let kanbanTarefaAcabouDeArrastar = false;
function iniciarDragKanbanTarefa(e, handleEl){
  const cardEl = handleEl.closest('.kanban-card');
  if(!cardEl) return;
  e.preventDefault();
  const rect = cardEl.getBoundingClientRect();
  const ghost = cardEl.cloneNode(true);
  ghost.classList.add('kanban-card-ghost');
  ghost.style.left = rect.left + 'px';
  ghost.style.top = rect.top + 'px';
  ghost.style.width = rect.width + 'px';
  document.body.appendChild(ghost);
  cardEl.classList.add('dragging');
  kanbanDragTarefa = {
    id: cardEl.dataset.id, statusOrigem: cardEl.dataset.status, cardEl, ghost,
    offsetX: e.clientX - rect.left, offsetY: e.clientY - rect.top, colunaAtual: null,
  };
  handleEl.setPointerCapture(e.pointerId);
  handleEl.addEventListener('pointermove', moverDragKanbanTarefa);
  handleEl.addEventListener('pointerup', soltarDragKanbanTarefa, { once:true });
  handleEl.addEventListener('pointercancel', cancelarDragKanbanTarefa, { once:true });
}
function moverDragKanbanTarefa(e){
  if(!kanbanDragTarefa) return;
  const { ghost, offsetX, offsetY } = kanbanDragTarefa;
  ghost.style.left = (e.clientX - offsetX) + 'px';
  ghost.style.top = (e.clientY - offsetY) + 'px';
  ghost.style.display = 'none';
  const elAlvo = document.elementFromPoint(e.clientX, e.clientY);
  ghost.style.display = '';
  const colunaBody = elAlvo ? elAlvo.closest('.kanban-col-body') : null;
  if(kanbanDragTarefa.colunaAtual && kanbanDragTarefa.colunaAtual !== colunaBody) kanbanDragTarefa.colunaAtual.classList.remove('drag-over');
  if(colunaBody) colunaBody.classList.add('drag-over');
  kanbanDragTarefa.colunaAtual = colunaBody;
}
async function soltarDragKanbanTarefa(e){
  const handleEl = e.currentTarget;
  handleEl.removeEventListener('pointermove', moverDragKanbanTarefa);
  if(!kanbanDragTarefa) return;
  const { id, statusOrigem, cardEl, ghost, colunaAtual } = kanbanDragTarefa;
  document.querySelectorAll('.kanban-col-body.drag-over').forEach(el=>el.classList.remove('drag-over'));
  cardEl.classList.remove('dragging');
  ghost.remove();
  kanbanDragTarefa = null;
  kanbanTarefaAcabouDeArrastar = true;
  setTimeout(()=>{ kanbanTarefaAcabouDeArrastar = false; }, 50);

  const novoStatus = colunaAtual ? colunaAtual.dataset.status : null;
  if(!novoStatus || novoStatus === statusOrigem) return;
  const conta = contaAtual();
  try{
    const r = await api('atualizarTarefa', { id, status: novoStatus, contaId: conta.id });
    if(!r.ok){ toast(r.erro || 'Não foi possível mudar o status.'); renderKanbanProjeto(); return; }
    const t = projetoTarefas.find(x=>String(x.id)===String(id));
    if(t){ t.status = novoStatus; t.concluidoEm = novoStatus==='Concluída' ? new Date().toISOString() : ''; }
    renderKanbanProjeto();
    toast(`Status alterado para ${novoStatus}`);
  }catch(err){
    toast('Não foi possível mudar o status.');
  }
}
function cancelarDragKanbanTarefa(e){
  const handleEl = e.currentTarget;
  handleEl.removeEventListener('pointermove', moverDragKanbanTarefa);
  if(!kanbanDragTarefa) return;
  document.querySelectorAll('.kanban-col-body.drag-over').forEach(el=>el.classList.remove('drag-over'));
  kanbanDragTarefa.cardEl.classList.remove('dragging');
  kanbanDragTarefa.ghost.remove();
  kanbanDragTarefa = null;
}

/* ---------- Cronograma (Gantt) das tarefas — mesma matemática de
   posicionamento do Gantt de Atendimentos, fonte de dados diferente ---------- */
function calcularItensGanttProjeto(){
  let de = document.getElementById('proj_gantt_de').value;
  let ate = document.getElementById('proj_gantt_ate').value;
  if(!de || !ate){
    const hoje = new Date();
    de = new Date(hoje.getFullYear(), hoje.getMonth(), 1).toISOString().slice(0,10);
    ate = new Date(hoje.getFullYear(), hoje.getMonth()+1, 0).toISOString().slice(0,10);
    document.getElementById('proj_gantt_de').value = de;
    document.getElementById('proj_gantt_ate').value = ate;
  }
  const dataInicio = new Date(de+'T00:00:00');
  const dataFim = new Date(ate+'T00:00:00');
  if(dataFim < dataInicio) return { itens: [], dataInicio, dataFim, invalido: true };

  let itens = projetoTarefas.filter(t=>t.dataInicio);
  itens = itens.filter(t=>{
    const ini = new Date(t.dataInicio+'T00:00:00');
    const fim = new Date((t.dataFim || t.dataInicio)+'T00:00:00');
    return fim >= dataInicio && ini <= dataFim;
  });
  itens.sort((a,b)=> String(a.dataInicio).localeCompare(String(b.dataInicio)));
  return { itens, dataInicio, dataFim, invalido: false };
}
function renderGanttProjeto(){
  const { itens, dataInicio, dataFim, invalido } = calcularItensGanttProjeto();
  const cont = document.getElementById('projGanttChart');
  if(invalido){ cont.innerHTML = `<div class="empty">O período "Até" precisa ser depois do "De".</div>`; return; }
  const totalDias = Math.max(1, Math.round((dataFim - dataInicio) / 86400000) + 1);
  if(itens.length === 0){ cont.innerHTML = `<div class="empty"><div class="big">📊</div>Nenhuma tarefa com data no período selecionado.</div>`; return; }

  const larguraDia = 100 / totalDias;
  let headerDias = '';
  for(let i=0;i<totalDias;i++){
    const d = new Date(dataInicio); d.setDate(d.getDate()+i);
    const mostrarNumero = totalDias <= 45 || d.getDate() === 1 || i === 0;
    headerDias += `<div class="gantt-day" style="width:${larguraDia}%;">${mostrarNumero ? d.getDate()+'/'+(d.getMonth()+1) : ''}</div>`;
  }

  const linhas = itens.map(t=>{
    const ini = new Date(t.dataInicio+'T00:00:00');
    const semFim = !t.dataFim;
    const fim = new Date((t.dataFim || t.dataInicio)+'T00:00:00');
    const iniClamp = ini < dataInicio ? dataInicio : ini;
    const fimClamp = fim > dataFim ? dataFim : fim;
    const offsetDias = Math.round((iniClamp - dataInicio) / 86400000);
    const duracaoDias = Math.max(1, Math.round((fimClamp - iniClamp) / 86400000) + 1);
    const left = offsetDias * larguraDia;
    const width = duracaoDias * larguraDia;
    const nivel = projProfundidade(t);
    const label = '　'.repeat(nivel) + t.titulo;
    const [y,m,d] = String(t.dataInicio).split('-');
    const tituloBarra = `${t.titulo} — início ${d}/${m}${t.dataFim ? ' · fim '+String(t.dataFim).split('-').reverse().slice(0,2).join('/') : ' · sem data de fim'} — ${t.status}`;
    return `<div class="gantt-row">
      <div class="gantt-label" title="${escaparHtml(t.titulo)}">${escaparHtml(label)}</div>
      <div class="gantt-track">
        <div class="gantt-bar status-${statusSlug(t.status)} ${semFim?'gantt-bar-sem-previsao':''}" style="left:${left}%;width:${width}%;" title="${escaparHtml(tituloBarra)}"></div>
      </div>
    </div>`;
  }).join('');

  cont.innerHTML = `
    <div class="gantt-header"><div class="gantt-label-col"></div><div class="gantt-days">${headerDias}</div></div>
    ${linhas}
  `;
}

/* ---------- Dashboard do projeto — panorama de status, cronograma, custo
   de recursos e financeiro real (a partir dos atendimentos vinculados),
   tudo calculado em cima do que já está carregado (sem chamada extra) ---------- */
// dados de custo (planejado, faturado ao cliente, custo interno) só pra
// quem gerencia o projeto ou é administrador do cliente — usuário comum
// (mesmo com acesso a tarefas suas) não vê valores em dinheiro
function projPodeVerCustos(){
  const conta = contaAtual();
  return ehAdminEfetivo(conta) || (conta && conta.perfil==='USUARIO' && conta.adminCliente);
}
function renderDashboardProjeto(){
  const cont = document.getElementById('projDashboardConteudo');
  const p = projetoAtual;
  if(!p){ cont.innerHTML = ''; return; }
  const podeVerCustos = projPodeVerCustos();
  const tarefas = projetoTarefas;
  const totalTarefas = tarefas.length;
  const concluidas = tarefas.filter(t=>t.status==='Concluída').length;
  const pctGeral = totalTarefas>0 ? Math.round((concluidas/totalTarefas)*100) : 0;

  const hojeIso = new Date().toISOString().slice(0,10);
  const atrasadas = tarefas.filter(t=>t.dataFim && t.dataFim < hojeIso && t.status!=='Concluída');

  let prazoLabel = 'Prazo', prazoTexto = '—', prazoSub = 'sem previsão definida';
  if(p.dataPrevistaFim){
    const diff = Math.round((new Date(p.dataPrevistaFim+'T00:00:00') - new Date(hojeIso+'T00:00:00')) / 86400000);
    if(diff >= 0){ prazoTexto = diff; prazoSub = 'dias até o previsto'; }
    else { prazoLabel = 'Atraso'; prazoTexto = Math.abs(diff); prazoSub = 'dias além do previsto'; }
  }

  // custo planejado: soma de custo x % de unidades de cada recurso atribuído em cada tarefa
  let custoPlanejado = 0;
  const custoPorRecurso = {};
  tarefas.forEach(t=>(t.recursos||[]).forEach(r=>{
    const valor = (Number(r.custo)||0) * ((Number(r.unidades)||100)/100);
    custoPlanejado += valor;
    const chave = r.nome || '(sem nome)';
    custoPorRecurso[chave] = (custoPorRecurso[chave]||0) + valor;
  }));
  const topRecursos = Object.entries(custoPorRecurso).sort((a,b)=>b[1]-a[1]).slice(0,6);
  const maiorCustoRecurso = topRecursos.length ? topRecursos[0][1] : 0;

  // financeiro real: soma dos atendimentos já vinculados ao projeto
  const atendsVinculados = projetoAtendimentoIds.map(id=>atendimentos.find(a=>String(a.id)===String(id))).filter(Boolean);
  const totalReal = atendsVinculados.reduce((s,a)=>s+Number(a.totalReal||0),0);
  const totalAnanda = atendsVinculados.reduce((s,a)=>s+Number(a.totalAnanda||0),0);
  const horasApuradas = atendsVinculados.reduce((s,a)=>s+Number(a.qtd||0),0);

  // saúde do projeto: compara % concluído com % do prazo já decorrido
  let saudeTexto = 'Sem dados suficientes pra avaliar', saudeCor = 'var(--muted)', saudeIcone = '❔';
  if(p.dataInicio && p.dataPrevistaFim){
    const ini = new Date(p.dataInicio+'T00:00:00'), fim = new Date(p.dataPrevistaFim+'T00:00:00'), hoje = new Date(hojeIso+'T00:00:00');
    const totalDias = Math.max(1, Math.round((fim-ini)/86400000));
    const decorridos = Math.max(0, Math.min(totalDias, Math.round((hoje-ini)/86400000)));
    const pctEsperado = Math.round((decorridos/totalDias)*100);
    const gap = pctGeral - pctEsperado;
    if(atrasadas.length===0 && gap >= -5){ saudeTexto = 'No prazo'; saudeCor = 'var(--ok)'; saudeIcone = '✓'; }
    else if(gap >= -20){ saudeTexto = 'Atenção — ligeiramente atrás do cronograma'; saudeCor = 'var(--warn)'; saudeIcone = '⚠'; }
    else { saudeTexto = 'Crítico — bem atrás do cronograma'; saudeCor = 'var(--bad)'; saudeIcone = '⛔'; }
  } else if(atrasadas.length > 0){
    saudeTexto = `${atrasadas.length} tarefa(s) em atraso`; saudeCor = 'var(--warn)'; saudeIcone = '⚠';
  } else if(totalTarefas > 0){
    saudeTexto = 'Sem atrasos registrados'; saudeCor = 'var(--ok)'; saudeIcone = '✓';
  }

  const proximasTarefas = tarefas.filter(t=>t.dataFim && t.status!=='Concluída').sort((a,b)=>String(a.dataFim).localeCompare(String(b.dataFim))).slice(0,5);

  // tarefas agrupadas por Segmento/Módulo/Rotina — mesmo formato de barras
  // já usado em "Tarefas por status", limitado aos 8 mais frequentes cada;
  // cada grupo também traz o % concluída médio (ponderado pela Duração,
  // mesmo critério do quadro "Percentual de conclusão" acima)
  function projContagemPorCampo(campo, semInfo){
    const grupos = {};
    tarefas.forEach(t=>{
      const chave = t[campo] || semInfo;
      const g = grupos[chave] || (grupos[chave] = { qtd:0, somaPeso:0, somaPonderada:0 });
      g.qtd++;
      const peso = t.duracaoDias || 1;
      g.somaPeso += peso;
      g.somaPonderada += peso * (t.percentualConcluido || 0);
    });
    return Object.entries(grupos)
      .map(([nome,g])=>[nome, g.qtd, g.somaPeso>0 ? Math.round(g.somaPonderada/g.somaPeso) : 0])
      .sort((a,b)=>b[1]-a[1])
      .slice(0,8);
  }
  const porSegmento = projContagemPorCampo('segmento', '(sem segmento)');
  const porModulo = projContagemPorCampo('modulo', '(sem módulo)');
  const porRotina = projContagemPorCampo('submodulo', '(sem rotina)');
  function projSecaoContagemHtml(titulo, entradas){
    if(totalTarefas===0 || entradas.length===0) return '';
    return `
    <div class="proj-dash-secao">
      <h3>${escaparHtml(titulo)}</h3>
      ${entradas.map(([nome,qtd,pctConclusao])=>{
        const pct = totalTarefas>0 ? Math.round((qtd/totalTarefas)*100) : 0;
        return `<div class="proj-dash-barra-linha">
          <div class="proj-dash-barra-label">${escaparHtml(nome)}</div>
          <div class="proj-dash-barra-trilha"><div class="proj-dash-barra-fill" style="width:${pct}%;background:var(--accent);"></div></div>
          <div class="proj-dash-barra-valor" style="width:150px;">${qtd} tarefa(s) · ${pctConclusao}% concl.</div>
        </div>`;
      }).join('')}
    </div>`;
  }

  // percentual de conclusão real do projeto: média dos % concluída
  // ponderada pela Duração de cada tarefa-folha (tarefa sem subtarefa —
  // quem tem filha já é um rollup dessas mesmas folhas, então entraria
  // duplicada na conta)
  const folhas = tarefas.filter(t=>projFilhosDe(t.id).length===0);
  let somaPesoPct = 0, somaPonderadaPct = 0;
  folhas.forEach(t=>{ const peso = t.duracaoDias||1; somaPesoPct += peso; somaPonderadaPct += peso*(t.percentualConcluido||0); });
  const pctConclusaoReal = somaPesoPct>0 ? Math.round(somaPonderadaPct/somaPesoPct) : 0;
  const corPctReal = pctConclusaoReal < 34 ? 'var(--bad)' : (pctConclusaoReal < 67 ? 'var(--warn)' : 'var(--ok)');

  cont.innerHTML = `
    <div class="proj-dash-saude" style="background:color-mix(in oklch, ${saudeCor} 15%, transparent);color:${saudeCor};">
      <span style="font-size:20px;">${saudeIcone}</span>
      <span>${escaparHtml(saudeTexto)}</span>
    </div>

    <div class="proj-dash-secao" style="margin-top:14px;">
      <h3>Percentual de conclusão</h3>
      <div class="proj-dash-pct-grande">
        <div class="proj-dash-pct-numero" style="color:${corPctReal};">${pctConclusaoReal}%</div>
        <div class="proj-dash-pct-trilha"><div class="proj-dash-pct-fill" style="width:${pctConclusaoReal}%;background:${corPctReal};"></div></div>
      </div>
      <div class="proj-dash-pct-sub">Média do % concluída das tarefas, ponderada pela duração de cada uma</div>
    </div>

    <div class="proj-dash-grid">
      <div class="proj-dash-tile"><div class="k">Status</div><div class="v" style="font-size:15px;">${escaparHtml(p.status)}</div></div>
      <div class="proj-dash-tile"><div class="k">Progresso geral</div><div class="v">${pctGeral}%</div><div class="sub">${concluidas}/${totalTarefas} tarefas</div></div>
      <div class="proj-dash-tile"><div class="k">${escaparHtml(prazoLabel)}</div><div class="v">${prazoTexto}</div><div class="sub">${prazoSub}</div></div>
      <div class="proj-dash-tile"><div class="k">Tarefas em atraso</div><div class="v" style="color:${atrasadas.length>0?'var(--bad)':'inherit'};">${atrasadas.length}</div></div>
      ${podeVerCustos ? `<div class="proj-dash-tile"><div class="k">Custo planejado (recursos)</div><div class="v" style="font-size:16px;">${fmtMoeda(custoPlanejado)}</div></div>` : ''}
      <div class="proj-dash-tile"><div class="k">Atendimentos vinculados</div><div class="v">${atendsVinculados.length}</div><div class="sub">${horasApuradas.toFixed(1)}h apuradas</div></div>
      ${podeVerCustos ? `<div class="proj-dash-tile"><div class="k">Faturado ao cliente</div><div class="v" style="font-size:16px;">${fmtMoeda(totalReal)}</div></div>` : ''}
      ${podeVerCustos ? `<div class="proj-dash-tile"><div class="k">Custo interno (atendentes)</div><div class="v" style="font-size:16px;">${fmtMoeda(totalAnanda)}</div></div>` : ''}
    </div>

    <div class="proj-dash-secao">
      <h3>Tarefas por status</h3>
      ${totalTarefas===0 ? `<div class="empty" style="padding:6px 0;">Nenhuma tarefa ainda.</div>` : PROJ_TAREFA_STATUS.map(nome=>[nome, tarefas.filter(t=>t.status===nome).length, PROJ_TAREFA_STATUS_COR[nome]]).map(([nome,qtd,cor])=>{
        const pct = totalTarefas>0 ? Math.round((qtd/totalTarefas)*100) : 0;
        return `<div class="proj-dash-barra-linha">
          <div class="proj-dash-barra-label">${escaparHtml(nome)}</div>
          <div class="proj-dash-barra-trilha"><div class="proj-dash-barra-fill" style="width:${pct}%;background:${cor};"></div></div>
          <div class="proj-dash-barra-valor">${qtd} (${pct}%)</div>
        </div>`;
      }).join('')}
    </div>

    ${projSecaoContagemHtml('Tarefas por Segmento', porSegmento)}
    ${projSecaoContagemHtml('Tarefas por Módulo', porModulo)}
    ${projSecaoContagemHtml('Tarefas por Rotina', porRotina)}

    ${(podeVerCustos && topRecursos.length > 0) ? `
    <div class="proj-dash-secao">
      <h3>Custo por recurso</h3>
      ${topRecursos.map(([nome,custo])=>{
        const pct = maiorCustoRecurso>0 ? Math.round((custo/maiorCustoRecurso)*100) : 0;
        return `<div class="proj-dash-barra-linha">
          <div class="proj-dash-barra-label">${escaparHtml(nome)}</div>
          <div class="proj-dash-barra-trilha"><div class="proj-dash-barra-fill" style="width:${pct}%;background:var(--blue);"></div></div>
          <div class="proj-dash-barra-valor">${fmtMoeda(custo)}</div>
        </div>`;
      }).join('')}
    </div>` : ''}

    <div class="proj-dash-secao">
      <h3>Próximas tarefas a vencer</h3>
      ${proximasTarefas.length===0 ? `<div class="empty" style="padding:6px 0;">Nenhuma tarefa pendente com data de término.</div>` : proximasTarefas.map(t=>{
        const atrasada = t.dataFim < hojeIso;
        return `<div class="proj-dash-lista-alerta">
          <span>${escaparHtml(t.titulo)}</span>
          <span style="color:${atrasada?'var(--bad)':'var(--muted)'};font-weight:${atrasada?700:400};">${String(t.dataFim).split('-').reverse().join('/')}${atrasada?' (atrasada)':''}</span>
        </div>`;
      }).join('')}
    </div>
  `;
}

/* ---------- Mapa Mental das tarefas — hierarquia (pai/filho) por posição
   em árvore + linhas de predecessoras desenhadas por cima em SVG. Div-based
   (sem lib externa), mesmo espírito do Gantt já existente. ---------- */
// mapa mental estilo organograma: raízes no topo, filhas centralizadas
// embaixo do pai, ligadas por tronco/galhos (igual organograma de empresa).
// Largura de cada ramo = número de folhas do ramo (bottom-up), depois cada
// nó é centralizado dentro do espaço herdado (top-down) — mesma ideia de
// layout de árvore usada em qualquer organograma.
// cor do card de tarefa no Mapa Mental — status da tarefa de projeto não é
// o mesmo vocabulário do status de atendimento que corStatusDot mapeia,
// por isso usa PROJ_TAREFA_STATUS_COR em vez daquele
function corStatusTarefaProjeto(status){
  return PROJ_TAREFA_STATUS_COR[status] || 'var(--muted)';
}
function renderMapaMentalProjeto(){
  const wrap = document.getElementById('projMapaMentalWrap');
  if(projetoTarefas.length===0){ wrap.innerHTML = `<div class="empty" style="padding:24px;"><div class="big">🧠</div>Nenhuma tarefa ainda.</div>`; return; }
  projNumerarTarefas();

  const LARGURA_NODE = 220, ALTURA_NODE = 68, ESPACO_X = 36, ESPACO_Y = 72;
  const UNIDADE_X = LARGURA_NODE + ESPACO_X;

  // passo 1 (bottom-up): quantas "unidades" de largura cada ramo precisa —
  // uma folha ocupa 1 unidade; um galho ocupa a soma dos filhos dele
  const largurasSubarvore = new Map();
  function calcularLargura(id){
    const filhos = projFilhosDe(id);
    if(filhos.length===0){ largurasSubarvore.set(String(id), UNIDADE_X); return UNIDADE_X; }
    let total = 0;
    filhos.forEach(f=>{ total += calcularLargura(f.id); });
    largurasSubarvore.set(String(id), total);
    return total;
  }
  projFilhosDe(null).forEach(t=>calcularLargura(t.id));

  // passo 2 (top-down): centraliza cada nó dentro do espaço que herdou
  const posicoes = {};
  let maxNivel = 0;
  function posicionar(paiId, nivel, xIni){
    const filhos = projFilhosDe(paiId);
    let cursor = xIni;
    filhos.forEach(t=>{
      maxNivel = Math.max(maxNivel, nivel);
      const largura = largurasSubarvore.get(String(t.id)) || UNIDADE_X;
      const centro = cursor + largura/2;
      posicoes[t.id] = { x: centro - LARGURA_NODE/2, y: nivel*(ALTURA_NODE+ESPACO_Y) + 16 };
      posicionar(t.id, nivel+1, cursor);
      cursor += largura;
    });
  }
  posicionar(null, 0, 16);

  const larguraTotal = projFilhosDe(null).reduce((s,t)=>s+(largurasSubarvore.get(String(t.id))||UNIDADE_X), 0) + 32;
  const alturaTotal = (maxNivel+1) * (ALTURA_NODE+ESPACO_Y) + 16;

  // galhos do organograma: tronco descendo do pai, barra horizontal ligando
  // as filhas, e um traço vertical de cada filha até a barra
  let linhasSvg = '';
  projetoTarefas.forEach(t=>{
    const pos = posicoes[t.id];
    if(!pos) return;
    const filhos = projFilhosDe(t.id);
    if(filhos.length===0) return;
    const xPai = pos.x + LARGURA_NODE/2, yPaiBase = pos.y + ALTURA_NODE;
    const yTronco = yPaiBase + ESPACO_Y/2;
    linhasSvg += `<path d="M${xPai},${yPaiBase} L${xPai},${yTronco}" stroke="var(--line)" stroke-width="2" fill="none"/>`;
    const centrosFilhos = filhos.map(f=>posicoes[f.id]).filter(Boolean).map(p=>p.x + LARGURA_NODE/2);
    if(centrosFilhos.length > 0){
      const xMin = Math.min(...centrosFilhos), xMax = Math.max(...centrosFilhos);
      if(xMax > xMin) linhasSvg += `<path d="M${xMin},${yTronco} L${xMax},${yTronco}" stroke="var(--line)" stroke-width="2" fill="none"/>`;
    }
    filhos.forEach(f=>{
      const posFilho = posicoes[f.id];
      if(!posFilho) return;
      const xFilho = posFilho.x + LARGURA_NODE/2;
      linhasSvg += `<path d="M${xFilho},${yTronco} L${xFilho},${posFilho.y}" stroke="var(--line)" stroke-width="2" fill="none"/>`;
    });
  });

  // linhas de predecessoras (independem da hierarquia) por cima, tracejadas
  projetoTarefas.forEach(t=>{
    const pos = posicoes[t.id];
    if(!pos) return;
    (t.predecessorasIds||[]).forEach(pid=>{
      const pred = posicoes[pid];
      if(!pred) return;
      const x1 = pred.x + LARGURA_NODE, y1 = pred.y + ALTURA_NODE/2;
      const x2 = pos.x, y2 = pos.y + ALTURA_NODE/2;
      linhasSvg += `<path d="M${x1},${y1} C${x1+40},${y1} ${x2-40},${y2} ${x2},${y2}" stroke="var(--accent)" stroke-width="2" stroke-dasharray="4,3" fill="none" marker-end="url(#projMapaSeta)"/>`;
    });
  });

  const nodesHtml = projetoTarefas.map(t=>{
    const pos = posicoes[t.id];
    if(!pos) return '';
    const numero = projTarefaNumeros.get(String(t.id)) || '';
    return `<div class="proj-mapa-node status-${statusSlug(t.status)}" style="left:${pos.x}px;top:${pos.y}px;width:${LARGURA_NODE}px;min-height:${ALTURA_NODE}px;border-top:4px solid ${corStatusTarefaProjeto(t.status)};" title="${escaparHtml(t.titulo)}">
      <div class="titulo">${numero ? `#${numero} ` : ''}${escaparHtml(t.titulo)}</div>
      <div class="meta">${escaparHtml(t.status)}${t.percentualConcluido?' · '+t.percentualConcluido+'%':''}</div>
    </div>`;
  }).join('');

  wrap.innerHTML = `
    <div style="position:relative;width:${larguraTotal}px;height:${alturaTotal}px;">
      <svg class="proj-mapa-svg" width="${larguraTotal}" height="${alturaTotal}" style="position:absolute;left:0;top:0;">
        <defs><marker id="projMapaSeta" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="var(--accent)"/></marker></defs>
        ${linhasSvg}
      </svg>
      ${nodesHtml}
    </div>
  `;
}

// gera o PDF do organograma reaproveitando o HTML já renderizado na tela
// (nós + SVG das linhas) — só pede uma escala antes, já que a árvore pode
// ficar bem mais larga/alta que uma folha impressa
function gerarPdfMapaMentalProjeto(){
  if(!projetoAtual) return;
  const wrap = document.getElementById('projMapaMentalWrap');
  if(!wrap || !wrap.firstElementChild){ toast('Nenhuma tarefa pra gerar o mapa mental.'); return; }
  const escalaTexto = prompt('Escala do mapa mental na impressão (% do tamanho atual):', '100');
  if(escalaTexto === null) return;
  const escala = Math.min(300, Math.max(10, parseInt(escalaTexto, 10) || 100)) / 100;
  document.getElementById('printProjetoMapa').innerHTML = `<div class="proj-print-mapa-wrap" style="transform:scale(${escala});">${wrap.innerHTML}</div>`;
  document.body.classList.add('print-modo-projeto-mapa');
  window.addEventListener('afterprint', ()=>{ document.body.classList.remove('print-modo-projeto-mapa'); }, { once:true });
  prepararImpressao(`Mapa Mental — ${projetoAtual.nome}`, '', 'printArea');
}

/* ---------- vínculo do projeto com atendimentos existentes (muitos-pra-
   muitos, mesmo padrão de vínculo de Atividades) — cada atendimento
   vinculado aparece com a mesma carta/card usado na visão de Atendimentos
   (renderLinhaComVinculos), só com um botão a mais pra desvincular do
   projeto sem excluir o atendimento ---------- */
function renderAtendimentosVinculadosProjeto(){
  const wrap = document.getElementById('projAtendimentosVinculadosLista');
  if(projetoAtendimentoIds.length===0){ wrap.innerHTML = `<div class="empty" style="padding:24px 0;"><div class="big">🗂️</div>Nenhum atendimento vinculado.</div>`; return; }

  const conta = contaAtual();
  const podeEditar = conta && conta.perfil !== 'USUARIO';
  const isUsuario = conta && conta.perfil === 'USUARIO';
  const verValores = podeVerValores();
  const isAdmin = ehAdminEfetivo(conta);
  const permAt = permissaoMenu(conta, 'atendimentos');
  const podeEditarBtn = permAt ? permAt.editar : podeEditar;
  const podeExcluirBtn = permAt ? permAt.excluir : podeEditar;
  const podeInserirBtn = permAt ? permAt.inserir : true;
  permissoesAcoesMenu = { podeEditarBtn, isAdmin, podeExcluirBtn, podeInserirBtn };
  const ctx = { isUsuario, verValores, isAdmin, podeEditarBtn, podeExcluirBtn, podeInserirBtn };

  wrap.innerHTML = projetoAtendimentoIds.map(id=>{
    const r = atendimentos.find(x=>String(x.id)===String(id));
    if(!r) return `<div class="item">#${escaparHtml(String(id))} — atendimento não encontrado</div>`;
    // botão fica ao lado do card (não sobreposto) — o próprio ".item" já
    // vira uma linha flex em telas largas (ver CSS de #listaItens), então
    // um wrapper flex externo alinha os dois sem entrar em conflito com o
    // layout interno do card em nenhuma largura de tela
    return `<div style="display:flex;align-items:flex-start;gap:8px;">
      <button type="button" class="ghost" style="flex:none;width:auto;padding:6px 10px;font-size:11px;margin-top:2px;" title="Desvincular do projeto" onclick="event.stopPropagation();projRemoverVinculoAtendimento('${id}')">✕ Desvincular</button>
      <div style="flex:1;min-width:0;">${renderLinhaComVinculos(r, ctx)}</div>
    </div>`;
  }).join('');
}
async function projRemoverVinculoAtendimento(atendimentoId){
  const conta = contaAtual();
  const r = await api('desvincularAtendimentoProjeto', { projetoId: projetoAtualId, atendimentoId, contaId: conta.id });
  if(!r.ok){ toast(r.erro || 'Não foi possível remover o vínculo.'); return; }
  projetoAtendimentoIds = projetoAtendimentoIds.filter(x=>String(x)!==String(atendimentoId));
  renderAtendimentosVinculadosProjeto();
}
async function projAdicionarVinculoAtendimento(atendimentoId){
  const conta = contaAtual();
  const r = await api('vincularAtendimentoProjeto', { projetoId: projetoAtualId, atendimentoId, contaId: conta.id });
  if(!r.ok){ toast(r.erro || 'Não foi possível vincular.'); return; }
  projetoAtendimentoIds.push(atendimentoId);
  renderAtendimentosVinculadosProjeto();
}

/* ---------- anexos do projeto — tabela própria (projeto_anexos), mesmo
   padrão de anexos de orçamento/atividade/tarefa ---------- */
async function carregarAnexosProjeto(projetoId){
  const cont = document.getElementById('projAnexosLista');
  cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Carregando…</div>`;
  try{
    const r = await api('listarAnexosProjeto', { projetoId });
    if(!r.ok){ cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">${r.erro || 'Não foi possível carregar.'}</div>`; return; }
    renderAnexosProjetoLista(r.anexos, projetoId);
  }catch(e){
    cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Não foi possível carregar os anexos.</div>`;
  }
}
function renderAnexosProjetoLista(lista, projetoId){
  const cont = document.getElementById('projAnexosLista');
  if(!lista || lista.length === 0){ cont.innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Nenhum anexo ainda.</div>`; return; }
  cont.innerHTML = lista.map(a=>`
    <div class="anexo-item">
      <a href="${a.url}" target="_blank">📎 ${escaparHtml(a.nome||'anexo')}</a>
      <a href="${urlDownloadAnexo(a.url, a.nome)}" title="Baixar arquivo original">⬇ Baixar</a>
      <button type="button" onclick="removerAnexoProjetoUi('${a.id}','${projetoId}')">remover</button>
    </div>`).join('');
}
async function adicionarAnexoProjetoUi(projetoId, arquivo){
  if(arquivo.size > 8 * 1024 * 1024){ toast('Anexo muito grande (máx. 8MB)'); return; }
  toast('Enviando anexo…');
  try{
    const base64 = await lerArquivoBase64(arquivo);
    const r = await api('adicionarAnexoProjeto', { projetoId, base64, tipo: arquivo.type, nome: arquivo.name });
    if(!r.ok){ toast(r.erro || 'Não foi possível enviar o anexo.'); return; }
    await carregarAnexosProjeto(projetoId);
    toast('Anexo adicionado');
  }catch(e){
    toast(e && e.message ? e.message : 'Não foi possível enviar o anexo.');
  }
}
async function removerAnexoProjetoUi(id, projetoId){
  const r = await api('removerAnexoProjeto', { id });
  if(!r.ok){ toast(r.erro || 'Não foi possível remover.'); return; }
  await carregarAnexosProjeto(projetoId);
  toast('Anexo removido');
}

/* ---------- Cubo de Atendimentos (tabela cruzada — só admin) ---------- */
const CUBO_DIMENSOES = {
  cliente: r => r.cliente || '(sem cliente)',
  usuario: r => r.usuario || '(sem usuário)',
  atendente: r => r.atendente || '(a definir)',
  tipo: r => labelTipo(r.tipo),
  status: r => r.status,
  segmento: r => r.segmento || '(sem segmento)',
  modulo: r => r.modulo || '(sem módulo)',
  submodulo: r => r.submodulo || '(sem rotina)',
  mes: r => r.mes || '(sem mês)',
};
const CUBO_DIMENSOES_LABEL = { cliente:'Cliente', usuario:'Usuário solicitante', atendente:'Atendente', tipo:'Tipo', status:'Status', segmento:'Segmento', modulo:'Módulo', submodulo:'Rotina', mes:'Mês' };
const CUBO_MEDIDAS = {
  qtd_chamados: { label:'Qtd. de chamados', valor: () => 1, formatar: v => String(v) },
  soma_horas: { label:'Horas', valor: r => Number(r.qtd) || 0, formatar: v => v.toFixed(2).replace('.', ',') + 'h' },
  soma_real: { label:'Valor Real (R$)', valor: r => Number(r.totalReal) || 0, formatar: v => fmtMoeda(v) },
  soma_ananda: { label:'Valor Atendente (R$)', valor: r => Number(r.totalAnanda) || 0, formatar: v => fmtMoeda(v) },
};
const CUBO_MEDIDAS_LABEL = Object.fromEntries(Object.entries(CUBO_MEDIDAS).map(([k,v])=>[k,v.label]));

// ordem de seleção importa pra Linhas/Colunas — vira a ordem dos
// níveis/subníveis (primeiro = nível mais de fora); dá pra reordenar
// depois com as setas ‹ › em cada tag
let cuboLinhasSelecionadas = ['atendente'];
let cuboColunasSelecionadas = ['mes'];
let cuboMedidasSelecionadas = ['qtd_chamados'];
// grupos de linha recolhidos (guarda o "caminho" de valores, tipo
// "Camila|||08/2026" — não o objeto, porque a árvore é recalculada do
// zero a cada render)
let cuboLinhasColapsadas = new Set();

const CUBO_TIPO_INFO = {
  linhas: { tagsId:'cuboLinhasTags', opcoesId:'cuboLinhasOpcoes', labels:CUBO_DIMENSOES_LABEL, lista:()=>cuboLinhasSelecionadas, minimoUm:true },
  colunas: { tagsId:'cuboColunasTags', opcoesId:'cuboColunasOpcoes', labels:CUBO_DIMENSOES_LABEL, lista:()=>cuboColunasSelecionadas, minimoUm:false },
  medidas: { tagsId:'cuboMedidasTags', opcoesId:'cuboMedidasOpcoes', labels:CUBO_MEDIDAS_LABEL, lista:()=>cuboMedidasSelecionadas, minimoUm:true },
};

function renderCuboSeletor(tipo){
  const info = CUBO_TIPO_INFO[tipo];
  const selecionadas = info.lista();
  document.getElementById(info.tagsId).innerHTML = selecionadas.map((chave,i)=>`
    <div class="lookup-tag">
      ${i>0 ? `<button type="button" data-cubo-mover="${tipo}:${i}:-1" title="Mover pra esquerda" style="background:none;border:none;color:inherit;cursor:pointer;padding:0;font-weight:700;">‹</button>` : ''}
      ${escaparHtml(info.labels[chave])}
      ${i<selecionadas.length-1 ? `<button type="button" data-cubo-mover="${tipo}:${i}:1" title="Mover pra direita" style="background:none;border:none;color:inherit;cursor:pointer;padding:0;font-weight:700;">›</button>` : ''}
      <button type="button" data-cubo-remover="${tipo}:${chave}">×</button>
    </div>`
  ).join('');
  const disponiveis = Object.keys(info.labels).filter(chave=>!selecionadas.includes(chave));
  document.getElementById(info.opcoesId).innerHTML = disponiveis.map(chave=>
    `<button type="button" class="chip" data-cubo-adicionar="${tipo}:${chave}">+ ${escaparHtml(info.labels[chave])}</button>`
  ).join('');
}

function renderTodosSeletoresCubo(){
  renderCuboSeletor('linhas'); renderCuboSeletor('colunas'); renderCuboSeletor('medidas');
}

// perfis de visualização do Cubo — guarda linhas/colunas/medidas escolhidas
// com um nome, pra não ter que remontar toda vez; fica salvo só nesse
// navegador (localStorage), não é compartilhado com outras contas/telas
const CUBO_PERFIS_CHAVE = 'teaatend_cubo_perfis';

function cuboPerfisSalvos(){
  try{ return JSON.parse(localStorage.getItem(CUBO_PERFIS_CHAVE) || '[]'); }catch(e){ return []; }
}
function cuboGravarPerfis(perfis){
  try{ localStorage.setItem(CUBO_PERFIS_CHAVE, JSON.stringify(perfis)); }catch(e){ /* localStorage indisponível — perfil simplesmente não persiste */ }
}

function renderCuboPerfilSelect(){
  const perfis = cuboPerfisSalvos();
  const sel = document.getElementById('cuboPerfilSelect');
  sel.innerHTML = `<option value="">Selecione um perfil salvo…</option>` + perfis.map((p,i)=>`<option value="${i}">${escaparHtml(p.nome)}</option>`).join('');
}

function cuboSalvarPerfilAtual(){
  const nome = document.getElementById('cuboNovoPerfilNome').value.trim();
  if(!nome){ toast('Digite um nome pro perfil'); return; }
  const perfis = cuboPerfisSalvos();
  const idxExistente = perfis.findIndex(p=>p.nome.toLowerCase()===nome.toLowerCase());
  const perfil = { nome, linhas: [...cuboLinhasSelecionadas], colunas: [...cuboColunasSelecionadas], medidas: [...cuboMedidasSelecionadas] };
  const idx = idxExistente >= 0 ? idxExistente : perfis.length;
  if(idxExistente >= 0) perfis[idxExistente] = perfil; else perfis.push(perfil);
  cuboGravarPerfis(perfis);
  document.getElementById('cuboNovoPerfilNome').value = '';
  renderCuboPerfilSelect();
  document.getElementById('cuboPerfilSelect').value = String(idx);
  toast(idxExistente >= 0 ? 'Perfil atualizado' : 'Perfil salvo');
}

function cuboCarregarPerfilSelecionado(){
  const idx = document.getElementById('cuboPerfilSelect').value;
  if(idx === '') return;
  const perfil = cuboPerfisSalvos()[Number(idx)];
  if(!perfil) return;
  cuboLinhasSelecionadas = perfil.linhas.length ? [...perfil.linhas] : ['atendente'];
  cuboColunasSelecionadas = [...perfil.colunas];
  cuboMedidasSelecionadas = perfil.medidas.length ? [...perfil.medidas] : ['qtd_chamados'];
  cuboLinhasColapsadas.clear();
  renderTodosSeletoresCubo();
  renderCubo();
}

function cuboRemoverPerfilSelecionado(){
  const sel = document.getElementById('cuboPerfilSelect');
  if(sel.value === ''){ toast('Escolha um perfil pra remover'); return; }
  const perfis = cuboPerfisSalvos();
  perfis.splice(Number(sel.value), 1);
  cuboGravarPerfis(perfis);
  renderCuboPerfilSelect();
  toast('Perfil removido');
}

function itensCuboFiltrados(){
  let itens = atendimentos.slice();
  const de = document.getElementById('cubo_periodo_de').value;
  const ate = document.getElementById('cubo_periodo_ate').value;
  if(de) itens = itens.filter(r=>String(r.data) >= de);
  if(ate) itens = itens.filter(r=>String(r.data) <= ate);
  return itens;
}

// agrupa itens recursivamente por uma sequência de dimensões — cada nível
// vira um nó com os próprios itens (pra calcular o subtotal daquele grupo)
// e os filhos do próximo nível, se sobrar mais alguma dimensão na lista
function cuboAgrupar(itens, chaves, nivel){
  if(chaves.length === 0) return null;
  const extrair = CUBO_DIMENSOES[chaves[0]];
  const grupos = new Map();
  itens.forEach(r=>{
    const v = extrair(r);
    if(!grupos.has(v)) grupos.set(v, []);
    grupos.get(v).push(r);
  });
  const restante = chaves.slice(1);
  return [...grupos.keys()].sort((a,b)=>String(a).localeCompare(String(b))).map(valor=>{
    const itensGrupo = grupos.get(valor);
    return { valor, itens: itensGrupo, filhos: cuboAgrupar(itensGrupo, restante, nivel+1) };
  });
}

// combinações de coluna que realmente ocorrem nos dados (evita coluna
// vazia pra uma combinação de valores que nunca aconteceu junta)
function cuboCombinacoesColuna(itens, chaves){
  if(chaves.length === 0) return [[]];
  const extrair = CUBO_DIMENSOES[chaves[0]];
  const restante = chaves.slice(1);
  const valores = [...new Set(itens.map(extrair))].sort((a,b)=>String(a).localeCompare(String(b)));
  const combos = [];
  valores.forEach(v=>{
    const itensDoValor = itens.filter(r=>extrair(r)===v);
    cuboCombinacoesColuna(itensDoValor, restante).forEach(resto=> combos.push([v, ...resto]));
  });
  return combos;
}

function cuboItensNaColuna(itens, colunaChaves, colunaPath){
  if(colunaChaves.length === 0) return itens;
  return itens.filter(r=> colunaChaves.every((chave,i)=> CUBO_DIMENSOES[chave](r) === colunaPath[i]));
}

// uma linha de cabeçalho por nível de coluna (colspan agrupa combinações
// com o mesmo prefixo) + uma linha extra com o nome da medida quando tem
// mais de uma escolhida (ou "Total" quando não tem dimensão de coluna
// nenhuma e só uma medida)
function cuboLinhasCabecalho(colunaPaths, colunaChaves, medidaChaves){
  const numMedidas = medidaChaves.length;
  const linhas = [];
  colunaChaves.forEach((_,nivel)=>{
    const celulas = [];
    let i = 0;
    while(i < colunaPaths.length){
      const prefixo = colunaPaths[i].slice(0, nivel+1).join('|||');
      let j = i;
      while(j < colunaPaths.length && colunaPaths[j].slice(0, nivel+1).join('|||') === prefixo) j++;
      celulas.push({ texto: colunaPaths[i][nivel], colspan: (j - i) * numMedidas });
      i = j;
    }
    linhas.push(celulas);
  });
  if(numMedidas > 1){
    const celulas = [];
    colunaPaths.forEach(()=> medidaChaves.forEach(mk=> celulas.push({ texto: CUBO_MEDIDAS[mk].label, colspan: 1 })));
    linhas.push(celulas);
  }else if(colunaChaves.length === 0){
    linhas.push([{ texto: 'Total', colspan: 1 }]);
  }
  return linhas;
}

function cuboRenderLinhas(nos, colunaPaths, colunaChaves, medidaChaves, nivel, caminhoPai){
  // com nenhuma dimensão de coluna escolhida, colunaPaths já É a única
  // coluna que existe — repetir uma coluna "Total" ao lado seria mostrar
  // o mesmo número duas vezes; a coluna extra de Total só faz sentido
  // quando tem dimensão de coluna de verdade pra somar através dela
  const mostrarColunaTotal = colunaChaves.length > 0;
  return nos.map(no=>{
    const caminho = caminhoPai ? caminhoPai + '|||' + no.valor : String(no.valor);
    const celulas = colunaPaths.map(path=>{
      const itensColuna = cuboItensNaColuna(no.itens, colunaChaves, path);
      return medidaChaves.map(mk=>{
        const total = itensColuna.reduce((soma,r)=> soma + CUBO_MEDIDAS[mk].valor(r), 0);
        return `<td style="text-align:right;padding:6px 10px;white-space:nowrap;">${total ? CUBO_MEDIDAS[mk].formatar(total) : '—'}</td>`;
      }).join('');
    }).join('');
    const totalLinha = mostrarColunaTotal ? medidaChaves.map(mk=>{
      const total = no.itens.reduce((soma,r)=> soma + CUBO_MEDIDAS[mk].valor(r), 0);
      return `<td style="text-align:right;padding:6px 10px;font-weight:700;white-space:nowrap;">${CUBO_MEDIDAS[mk].formatar(total)}</td>`;
    }).join('') : '';
    const colapsado = cuboLinhasColapsadas.has(caminho);
    const toggle = no.filhos
      ? `<button type="button" data-cubo-toggle-linha="${escaparHtml(caminho)}" title="${colapsado?'Expandir':'Recolher'}" style="background:none;border:none;cursor:pointer;color:inherit;padding:0;font-size:10px;width:14px;">${colapsado?'▸':'▾'}</button>`
      : `<span style="display:inline-block;width:14px;"></span>`;
    const linhaAtual = `<tr><td style="padding:6px 10px;padding-left:${nivel*18}px;font-weight:${no.filhos?700:600};white-space:nowrap;">${toggle}${escaparHtml(String(no.valor))}</td>${celulas}${totalLinha}</tr>`;
    const linhasFilhas = (no.filhos && !colapsado) ? cuboRenderLinhas(no.filhos, colunaPaths, colunaChaves, medidaChaves, nivel+1, caminho) : '';
    return linhaAtual + linhasFilhas;
  }).join('');
}

function renderCubo(){
  const cont = document.getElementById('cuboTabela');
  const itens = itensCuboFiltrados();
  if(itens.length === 0){ cont.innerHTML = `<div class="empty">Nenhum atendimento encontrado nesse período.</div>`; return; }

  const linhaChaves = cuboLinhasSelecionadas;
  const colunaChaves = cuboColunasSelecionadas;
  const medidaChaves = cuboMedidasSelecionadas;

  const arvoreLinhas = cuboAgrupar(itens, linhaChaves, 0);
  const colunaPaths = cuboCombinacoesColuna(itens, colunaChaves);
  const linhasCabecalho = cuboLinhasCabecalho(colunaPaths, colunaChaves, medidaChaves);

  // a coluna extra de "Total" (soma através de todas as combinações de
  // coluna) só faz sentido quando existe alguma dimensão de coluna de
  // verdade — sem isso, colunaPaths já É a única coluna, e repetir um
  // "Total" do lado mostraria o mesmo número de novo
  const mostrarColunaTotal = colunaChaves.length > 0;

  // a linha de rótulos de medida (quando tem mais de uma escolhida) é
  // sempre a última — "Total" só ocupa as linhas de dimensão de coluna
  // acima dela (rowspan), e ganha seus próprios rótulos de medida nessa
  // última linha, igual qualquer outro grupo de coluna
  const temLinhaDeMedida = medidaChaves.length > 1;
  const cabecalhoHtml = linhasCabecalho.map((celulas, i)=>{
    const ehUltimaLinha = i === linhasCabecalho.length - 1;
    const bordaCelulaVazia = i===0 ? `<th rowspan="${linhasCabecalho.length}" style="text-align:left;padding:6px 10px;border-bottom:2px solid var(--line);"></th>` : '';
    const meio = celulas.map(c=>`<th colspan="${c.colspan}" style="text-align:right;padding:6px 10px;border-bottom:2px solid var(--line);white-space:nowrap;">${escaparHtml(String(c.texto))}</th>`).join('');
    let celulaTotal = '';
    if(mostrarColunaTotal){
      if(i === 0 && !(temLinhaDeMedida && ehUltimaLinha)){
        celulaTotal = `<th rowspan="${temLinhaDeMedida ? linhasCabecalho.length-1 : linhasCabecalho.length}" colspan="${medidaChaves.length}" style="text-align:right;padding:6px 10px;border-bottom:2px solid var(--line);">Total</th>`;
      }else if(temLinhaDeMedida && ehUltimaLinha){
        celulaTotal = medidaChaves.map(mk=>`<th style="text-align:right;padding:6px 10px;border-bottom:2px solid var(--line);white-space:nowrap;">${escaparHtml(CUBO_MEDIDAS[mk].label)}</th>`).join('');
      }
    }
    return `<tr>${bordaCelulaVazia}${meio}${celulaTotal}</tr>`;
  }).join('');

  const linhasHtml = cuboRenderLinhas(arvoreLinhas, colunaPaths, colunaChaves, medidaChaves, 0, null);

  const totaisColuna = colunaPaths.map(path=>{
    const itensColuna = cuboItensNaColuna(itens, colunaChaves, path);
    return medidaChaves.map(mk=>{
      const total = itensColuna.reduce((soma,r)=> soma + CUBO_MEDIDAS[mk].valor(r), 0);
      return `<td style="text-align:right;padding:6px 10px;font-weight:700;white-space:nowrap;">${CUBO_MEDIDAS[mk].formatar(total)}</td>`;
    }).join('');
  }).join('');
  const totalGeral = mostrarColunaTotal ? medidaChaves.map(mk=>{
    const total = itens.reduce((soma,r)=> soma + CUBO_MEDIDAS[mk].valor(r), 0);
    return `<td style="text-align:right;padding:6px 10px;font-weight:700;white-space:nowrap;">${CUBO_MEDIDAS[mk].formatar(total)}</td>`;
  }).join('') : '';

  cont.innerHTML = `
    <div style="overflow-x:auto;">
      <table style="width:100%;border-collapse:collapse;font-size:12.5px;">
        <thead>${cabecalhoHtml}</thead>
        <tbody>
          ${linhasHtml}
          <tr class="cubo-total" style="border-top:2px solid var(--line);">
            <td style="padding:6px 10px;font-weight:700;">Total</td>
            ${totaisColuna}
            ${totalGeral}
          </tr>
        </tbody>
      </table>
    </div>`;
}

// junta numa lista só (respeitando o que está recolhido/expandido — só
// exporta o que a pessoa está vendo na tela) pra gerar o Excel/CSV
function cuboColetarLinhasVisiveis(nos, colunaPaths, colunaChaves, medidaChaves, nivel, caminhoPai, saida){
  const mostrarColunaTotal = colunaChaves.length > 0;
  nos.forEach(no=>{
    const caminho = caminhoPai ? caminhoPai + '|||' + no.valor : String(no.valor);
    const valores = [];
    colunaPaths.forEach(path=>{
      const itensColuna = cuboItensNaColuna(no.itens, colunaChaves, path);
      medidaChaves.forEach(mk=> valores.push(itensColuna.reduce((soma,r)=> soma + CUBO_MEDIDAS[mk].valor(r), 0)));
    });
    if(mostrarColunaTotal) medidaChaves.forEach(mk=> valores.push(no.itens.reduce((soma,r)=> soma + CUBO_MEDIDAS[mk].valor(r), 0)));
    saida.push({ label: no.valor, nivel, valores });
    const colapsado = cuboLinhasColapsadas.has(caminho);
    if(no.filhos && !colapsado) cuboColetarLinhasVisiveis(no.filhos, colunaPaths, colunaChaves, medidaChaves, nivel+1, caminho, saida);
  });
}

// mesmo padrão de exportação em Excel de verdade usado no resto do
// sistema (XLSX + salvarWorkbook) — um Blob com <a download> direto não
// funciona dentro do app Android (WebView do Capacitor não salva sozinha)
async function exportarCuboExcel(){
  const itens = itensCuboFiltrados();
  if(itens.length === 0){ toast('Nada para exportar com esse período'); return; }

  const linhaChaves = cuboLinhasSelecionadas, colunaChaves = cuboColunasSelecionadas, medidaChaves = cuboMedidasSelecionadas;
  const mostrarColunaTotal = colunaChaves.length > 0;
  const arvoreLinhas = cuboAgrupar(itens, linhaChaves, 0);
  const colunaPaths = cuboCombinacoesColuna(itens, colunaChaves);

  const cabecalhosColuna = [];
  colunaPaths.forEach(path=> medidaChaves.forEach(mk=> cabecalhosColuna.push([...path, CUBO_MEDIDAS[mk].label].join(' - '))));
  if(mostrarColunaTotal) medidaChaves.forEach(mk=> cabecalhosColuna.push('Total - ' + CUBO_MEDIDAS[mk].label));
  const cabecalho = [linhaChaves.map(k=>CUBO_DIMENSOES_LABEL[k]).join(' / ') || 'Item', ...cabecalhosColuna];

  const linhasVisiveis = [];
  cuboColetarLinhasVisiveis(arvoreLinhas, colunaPaths, colunaChaves, medidaChaves, 0, null, linhasVisiveis);
  const linhas = linhasVisiveis.map(l=> [
    '  '.repeat(l.nivel) + String(l.label),
    ...l.valores.map(v=> Number(v.toFixed(2))),
  ]);

  const totalGeralValores = [];
  colunaPaths.forEach(path=>{
    const itensColuna = cuboItensNaColuna(itens, colunaChaves, path);
    medidaChaves.forEach(mk=> totalGeralValores.push(itensColuna.reduce((soma,r)=> soma + CUBO_MEDIDAS[mk].valor(r), 0)));
  });
  if(mostrarColunaTotal) medidaChaves.forEach(mk=> totalGeralValores.push(itens.reduce((soma,r)=> soma + CUBO_MEDIDAS[mk].valor(r), 0)));
  linhas.push(['Total', ...totalGeralValores.map(v=>Number(v.toFixed(2)))]);

  const livro = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(livro, XLSX.utils.aoa_to_sheet([cabecalho, ...linhas]), 'Cubo');
  await salvarWorkbook(livro, `cubo-atendimentos-${hojeLocalISO()}.xlsx`);
  toast('Excel exportado');
}

/* ---------- construtor de relatório ---------- */
let relFiltroCliente = new Set();
let relFiltroTipo = new Set();
let relFiltroStatus = new Set();
let relFiltroAtendente = new Set();
let relColunas = ['data','cliente','usuario','atendente','tipo','detalhe','horario','qtd','status']; // array — mantém a ordem escolhida
let relAgrupar = 'nenhum';
let relTipoVisualizacao = 'tabela'; // 'tabela' ou 'ficha' (detalhado, com fotos)
let relEditandoId = null; // id do relatório salvo sendo editado (null = novo)
// "incluir movimentações" — na visão em tabela é opcional (uma linha extra
// por movimentação logo abaixo da linha do atendimento dela); no modelo
// "Detalhado" (ficha) as movimentações sempre aparecem, junto com horário e
// valores do atendimento — por isso conta como "precisa buscar" nos dois
// casos. Não tem endpoint em massa pra isso (só existe listarMovimentacoes
// por atendimento, usado no chat), então busca tudo de uma vez só quando o
// relatório é (re)gerado, cacheado por assinatura do conjunto de ids atual
// pra não buscar de novo à toa a cada coluna/ordem mexida
let relIncluirMovimentacoes = false;
let movimentacoesPorAtendimentoRelatorio = {};
let relMovimentacoesAssinatura = '';
async function carregarMovimentacoesRelatorio(itens){
  const precisaBuscar = relIncluirMovimentacoes || relTipoVisualizacao === 'ficha';
  if(!precisaBuscar){
    movimentacoesPorAtendimentoRelatorio = {}; relMovimentacoesAssinatura = '';
    return;
  }
  const ids = itens.map(r=>r.id);
  const assinatura = ids.slice().sort().join(',');
  if(assinatura === relMovimentacoesAssinatura) return;
  relMovimentacoesAssinatura = assinatura;
  if(ids.length === 0){ movimentacoesPorAtendimentoRelatorio = {}; return; }
  const conta = contaAtual();
  const r = await api('listarMovimentacoesEmLote', { contaId: conta ? conta.id : '', atendimentoIds: ids });
  movimentacoesPorAtendimentoRelatorio = (r.ok && r.movimentacoesPorAtendimento) || {};
}
function formatarDataHoraBr(iso){
  const d = iso ? new Date(iso) : null;
  if(!d || isNaN(d.getTime())) return '';
  const dia = String(d.getDate()).padStart(2,'0');
  const mes = String(d.getMonth()+1).padStart(2,'0');
  const hora = String(d.getHours()).padStart(2,'0');
  const min = String(d.getMinutes()).padStart(2,'0');
  return `${dia}/${mes}/${d.getFullYear()} ${hora}:${min}`;
}
// "YYYY-MM-DD" (como data_inicial/data_final são gravadas) -> "DD/MM/AAAA"
function formatarDataSimplesBr(iso){
  if(!iso) return '';
  const [y,m,d] = String(iso).split('-');
  return (y && m && d) ? `${d}/${m}/${y}` : String(iso);
}
// mesma conta de supabase/functions/api/index.ts:calcularQtdMovimentacao —
// duração em horas (decimal) entre início e fim, descontando o intervalo
function calcularHorasMovimentacao(m){
  if(!m.dataInicial || !m.horaInicial || !m.dataFinal || !m.horaFinal) return null;
  const ini = new Date(`${m.dataInicial}T${m.horaInicial}:00`).getTime();
  const fim = new Date(`${m.dataFinal}T${m.horaFinal}:00`).getTime();
  if(isNaN(ini) || isNaN(fim)) return null;
  const totalMin = Math.max(0, (fim - ini) / 60000 - (Number(m.intervaloMin) || 0));
  return totalMin / 60;
}
function textoMovimentacaoRelatorio(m){
  const autor = m.autorNome ? `${m.autorNome}${m.autorPerfil ? ' ('+m.autorPerfil+')' : ''}` : '';
  const texto = stripHtml(m.texto || '');
  // apontamento de horas da movimentação (quando ela registrou trabalho, não
  // só um comentário) — só entra quando tem algo preenchido, senão fica
  // poluindo uma movimentação que é só um comentário de chat
  const apontamento = [];
  if(m.dataInicial) apontamento.push(`DI: ${formatarDataSimplesBr(m.dataInicial)}`);
  if(m.dataFinal) apontamento.push(`DF: ${formatarDataSimplesBr(m.dataFinal)}`);
  if(m.horaInicial) apontamento.push(`HI: ${m.horaInicial}`);
  if(m.horaFinal) apontamento.push(`HF: ${m.horaFinal}`);
  if(m.intervaloMin) apontamento.push(`Inter: ${m.intervaloMin}min`);
  const temApontamento = apontamento.length > 0;
  // com apontamento, as próprias datas/horas já dizem "quando" — não repete
  // o horário do comentário; sem apontamento (só um comentário de chat),
  // mantém o horário do comentário como antes
  const quando = formatarDataHoraBr(m.criadoEm);
  const prefixo = temApontamento ? apontamento.join(' · ') + ' ' : (quando ? quando + ' — ' : '');
  const horas = temApontamento ? calcularHorasMovimentacao(m) : null;
  const totalHoras = horas !== null ? ` · Total Horas: ${horas.toFixed(2).replace('.',',')}h` : '';
  return `${prefixo}${autor ? autor+': ' : ''}${texto}${totalHoras}`;
}
function linhasMovimentacoesHtml(r, numColunas){
  if(!relIncluirMovimentacoes) return '';
  const movs = movimentacoesPorAtendimentoRelatorio[r.id] || [];
  return movs.map(m=>`<tr class="rel-mov-linha"><td colspan="${numColunas}">↳ ${escaparHtml(textoMovimentacaoRelatorio(m))}</td></tr>`).join('');
}
function linhasMovimentacoesExcel(r){
  if(!relIncluirMovimentacoes) return [];
  const movs = movimentacoesPorAtendimentoRelatorio[r.id] || [];
  return movs.map(m=>['', `↳ ${textoMovimentacaoRelatorio(m)}`]);
}

