function renderListRmPaineis(){
  const el = document.getElementById('listRmPaineis');
  if(!el) return;
  renderConsultasPickerPainel(editandoRmPainelId ? (rmPaineis.find(p=>p.id===editandoRmPainelId)||{}).consultas : []);
  renderSetorSelectPainel(editandoRmPainelId ? (rmPaineis.find(p=>p.id===editandoRmPainelId)||{}).setorId : '');
  const conta = contaAtual();
  const souUsuario = conta && conta.perfil === 'USUARIO';
  // cada painel usa um menu diferente pro editar/excluir — o especial
  // (Painel de Recebíveis) é 'painelrecebiveis', os genéricos são 'paineis'
  const permGenerico = permissaoMenu(conta, 'relatoriosgerenciaisrm.paineis');
  const podeInserirGenerico = ehAdminEfetivo(conta) || !permGenerico || permGenerico.inserir;
  const formCard = document.getElementById('pnlCardCadastroForm');
  if(formCard) formCard.style.display = podeInserirGenerico ? '' : 'none';

  let visiveis = rmPaineis.filter(p=>painelAcessivel(conta, p.id));
  if(souUsuario) visiveis = visiveis.filter(p=>painelTemConsultaDoCliente(p, conta.clienteId));

  // guias por Setor — só aparecem quando há pelo menos 1 painel visível com
  // setor definido; "Geral" sempre entra, pros sem setor (ou setor removido)
  const tabsEl = document.getElementById('pnlPaineisSetorTabs');
  const setorIdsEmUso = [...new Set(visiveis.map(p=>p.setorId).filter(Boolean))];
  if(tabsEl){
    if(setorIdsEmUso.length === 0){
      tabsEl.style.display = 'none';
    }else{
      tabsEl.style.display = '';
      const guias = [
        { chave:'geral', label:'Geral' },
        ...setorIdsEmUso.map(id=>{
          const s = setores.find(x=>x.id===id);
          return { chave:id, label: s ? s.nome : '(setor removido)' };
        }),
      ];
      if(!guias.some(g=>g.chave===pnlPaineisGuiaAtual)) pnlPaineisGuiaAtual = 'geral';
      tabsEl.innerHTML = guias.map(g=>`<div class="subtab ${g.chave===pnlPaineisGuiaAtual?'active':''}" data-pnlsetortab="${escaparHtml(g.chave)}">${escaparHtml(g.label)}</div>`).join('');
      visiveis = visiveis.filter(p=> pnlPaineisGuiaAtual==='geral' ? !p.setorId : p.setorId===pnlPaineisGuiaAtual);
    }
  }

  if(visiveis.length===0){ el.innerHTML = `<div class="empty">${souUsuario ? 'Nenhum painel liberado pro seu cliente ainda.' : 'Nenhum painel cadastrado nessa guia.'}</div>`; return; }
  el.innerHTML = visiveis.map(p=>{
    const nomesConsultas = (p.consultas||[]).map(id=>{
      const r = rmRelatoriosGerenciais.find(x=>String(x.id)===String(id));
      return r ? (r.clienteId ? rgrmNomeCliente(r.clienteId) : r.nome) : null;
    }).filter(Boolean);
    const menu = p.tipo==='especial' ? 'relatoriosgerenciaisrm.painelrecebiveis' : 'relatoriosgerenciaisrm.paineis';
    const perm = permissaoMenu(conta, menu);
    const podeEditar = ehAdminEfetivo(conta) || !perm || perm.editar;
    const podeExcluir = ehAdminEfetivo(conta) || !perm || perm.excluir;
    return `
    <div class="cad-item"><div class="info"><b>${escaparHtml(p.nome)}${p.tipo==='especial' ? ' <span class="pill">especial</span>' : ''}</b>
      <span>${nomesConsultas.length ? 'Clientes: '+escaparHtml(nomesConsultas.join(', ')) : 'Nenhuma consulta vinculada ainda'}</span>
    </div>
    <div class="acts">
      <button class="ghost" onclick="abrirRmPainel('${p.id}')">Abrir</button>
      ${podeEditar ? `<button class="ghost" onclick="editarRmPainel('${p.id}')">Editar</button>` : ''}
      ${(p.tipo!=='especial' && podeExcluir) ? `<button class="danger" onclick="pedirConfirmacao('Remover painel?','Isso remove só a configuração do painel (grade de widgets) — as consultas SQL vinculadas continuam cadastradas.', ()=>removerRmPainel('${p.id}'))">Remover</button>` : ''}
    </div></div>`;
  }).join('');
}
function abrirRmPainel(id){
  const p = rmPaineis.find(x=>x.id===id);
  if(!p) return;
  if(p.tipo==='especial'){ goRgrmSub('painelrecebiveis'); return; }
  pnlPainelAtual = p;
  goRgrmSub('painelgenerico');
}
function editarRmPainel(id){
  const p = rmPaineis.find(x=>x.id===id);
  if(!p) return;
  editandoRmPainelId = id;
  document.getElementById('pnl_nome').value = p.nome;
  renderConsultasPickerPainel(p.consultas);
  renderSetorSelectPainel(p.setorId);
  document.getElementById('pnl_tituloForm').textContent = 'Editar painel';
  document.getElementById('btnAddRmPainel').textContent = 'Salvar alterações';
  document.getElementById('btnCancelarEdicaoRmPainel').style.display = '';
  document.getElementById('pnl_nome').scrollIntoView({ behavior:'smooth', block:'center' });
}
function cancelarEdicaoRmPainel(){
  editandoRmPainelId = null;
  document.getElementById('pnl_nome').value = '';
  renderConsultasPickerPainel([]);
  renderSetorSelectPainel('');
  document.getElementById('pnl_tituloForm').textContent = 'Novo painel';
  document.getElementById('btnAddRmPainel').textContent = 'Adicionar painel';
  document.getElementById('btnCancelarEdicaoRmPainel').style.display = 'none';
}
async function removerRmPainel(id){
  const r = await api('removerRmPainel', { contaId: contaAtual().id, id });
  if(!r.ok){ toast(r.erro || 'Não foi possível remover.'); return; }
  await carregarTudo({ comAtendimentos: false });
  renderListRmPaineis();
  toast('Painel removido');
}

/* ---------- Painel de Recebíveis (interno) ---------- */
const RECEB_DAY = 86400000;
let recebClienteId = '';
let recebLinhas = []; // já normalizado (ver recebNormalizar)
let recebInfo = null; // { quando, nomeRelatorio }
let recebCarregando = false;
// filtros configuráveis — recebPainelFiltros é a lista (em edição) de
// campos escolhidos pelo usuário, na ordem em que aparecem; cada campo é
// "mes"/"cliente"/"municipio"/"contrato"/"situacao" (embutidos) ou
// "rm:NOME_DA_COLUNA" pra filtrar por qualquer coluna crua que a consulta
// do RM trouxer (como as colunas variam de cliente pra cliente, a lista
// de campos disponíveis é descoberta a partir dos dados já carregados —
// ver recebCamposFiltroDisponiveis). recebPainelFiltrosSalvos guarda o
// último estado salvo, pra "Cancelar" voltar pra ele — mesmo esquema do
// recebPainelWidgets/recebPainelWidgetsSalvos logo abaixo.
let recebPainelFiltros = [];
let recebPainelFiltrosSalvos = [];
// cada filtro é multi-seleção (um "lookup": busca + chips dos escolhidos +
// lista com checkbox, mesmo padrão já usado no Gerador SQL RM) — Set
// vazio = "todos", igual os filtros do Construtor de Relatório. Chaveado
// pelo próprio nome do campo (recebPainelFiltros).
let recebFiltros = {};
// filtro de situação e última lista copiável de cada widget "tabela de
// notas em aberto" — por id do widget (só costuma existir um, mas o
// motor de widgets não impede mais de um em tese)
let recebSegPorWidget = {};
let recebUltimaListaAbertas = {};
// filtro rápido (chips clicáveis) de cada widget "tabela (colunas à sua
// escolha)" — igual o seletor Todas/Atrasada/Próximos dias/A vencer da
// tabela de notas em aberto, mas pro CAMPO que o admin escolher ao criar o
// widget (widget.filtroRapido) e só vale PRA ESSE widget, nunca mexe no
// filtro geral do painel. 'todas' (ou ausente) = sem filtro. Por id do widget.
let recebFiltroRapidoPorWidget = {};
// colunas marcadas no formulário "Adicionar widget" quando tipo==='tabela'
// (trabalha junto com o seletor de fonte — notas ou agrupado)
let recebFormColunasAtual = [];
// "grade configurável" (widgets): recebPainelWidgets é o array em edição;
// recebPainelWidgetsSalvos guarda o último estado salvo, pra "Cancelar"
// voltar exatamente pra ele. Um widget é {id,tipo,titulo,medida,medida2,
// dimensao,top} — ver RECEB_MEDIDAS/RECEB_DIMENSOES mais abaixo.
let recebPainelWidgets = [];
let recebPainelWidgetsSalvos = [];
// catálogo de medidas (overrides de uma medida de sistema + medidas
// personalizadas) — mesmo esquema de edição/cancelar/salvar dos widgets e
// filtros. Ver RECEB_MEDIDAS/recebReconstruirCatalogoMedidas mais abaixo.
let recebPainelMedidas = [];
let recebPainelMedidasSalvos = [];
let recebEditandoMedidaId = null;
let recebLayoutCarregado = false;
let recebModoEdicao = false;
let recebEditandoWidgetId = null;
let recebUltimoLinhasFiltradas = []; // cache pro re-render leve de busca/segmento de uma tabela, sem remontar a grade toda

function recebHoje(){ const d=new Date(); return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/RECEB_DAY); }
function recebFmtDia(n){ if(n==null) return ''; const d=new Date(n*RECEB_DAY); return String(d.getUTCDate()).padStart(2,'0')+'/'+String(d.getUTCMonth()+1).padStart(2,'0')+'/'+d.getUTCFullYear(); }
function recebYm(n){ if(n==null) return ''; const d=new Date(n*RECEB_DAY); return d.getUTCFullYear()+'-'+String(d.getUTCMonth()+1).padStart(2,'0'); }
const RECEB_MESES=['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
function recebMesLbl(m){ const [y,mm]=m.split('-'); return RECEB_MESES[(+mm)-1]+'/'+y.slice(2); }
function recebTitleCase(s){ return s.toLowerCase().replace(/(^|\s|-|\/)(\S)/g,(a,b,c)=>b+c.toUpperCase()).replace(/\b(De|Do|Da|Dos|Das|E)\b/g,w=>w.toLowerCase()); }
// agrupa os nomes de cliente que vêm crus do RM em rótulos mais legíveis —
// mesma lógica (e mesmos casos especiais) do painel standalone
function recebGrupo(c){
  const u=c.toUpperCase();
  if(u.includes('CAGECE')||u.includes('AGUA E ESGOTO')) return 'CAGECE';
  if(u.includes('OBRAS PUBLICAS')||/\bSOP\b/.test(u)) return 'SOP';
  const m=u.match(/PREFEITURA MUNICIPAL D[EOA]S?\s+(.*)/); if(m) return 'Prefeitura de '+recebTitleCase(m[1].replace(/\s+CE$/,'').trim());
  if(u.includes('UFCA')) return 'UFCA';
  return recebTitleCase(c);
}
function recebCtrLbl(k){ const p=String(k).split(' - ').map(s=>s.trim()).filter(Boolean); return p.length>=3?{n:p[1],d:recebTitleCase(p.slice(2).join(' - '))}:{n:p[0]||k,d:p.slice(1).join(' - ')}; }
function recebSit(o, hoje){
  const s=(o.s||'').toLowerCase();
  if(s.startsWith('cancel')) return 'Cancelada';
  if(o.p||s.startsWith('recebid')) return 'Recebida';
  if(o.v==null) return 'A vencer';
  const dd=o.v-hoje;
  if(dd<0) return 'Atrasada';
  if(dd<=7) return 'Próximos dias';
  return 'A vencer';
}
const recebSaldo = o => Math.max(0, (o.t||0)-(o.r||0));

/* linhas cruas do RM chegam como array de objetos com chaves arbitrárias
   (os nomes das colunas da sentença SQL) — acha cada coluna lógica pelo
   nome normalizado, igual o painel standalone fazia lendo a planilha */
const recebNormH = h => String(h??'').normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase().replace(/_/g,' ').replace(/\s+/g,' ').trim();
function recebCellDia(v){
  if(v==null||v==='') return null;
  if(typeof v==='number'){ if(v<1) return null; return Math.floor(v)-25569; }
  const m=String(v).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/); if(m) return Math.floor(Date.UTC(+m[3],+m[2]-1,+m[1])/RECEB_DAY);
  const i=String(v).match(/(\d{4})-(\d{2})-(\d{2})/); if(i) return Math.floor(Date.UTC(+i[1],+i[2]-1,+i[3])/RECEB_DAY);
  return null;
}
function recebCellNum(v){ if(typeof v==='number') return v; if(v==null||v==='') return 0; const n=parseFloat(String(v).replace(/[R$\s.]/g,'').replace(',','.')); return isNaN(n)?0:n; }
function recebIdLinha(mov, lan, nf){ const m=String(mov??'').trim(), l=String(lan??'').trim(); if(m&&m!=='0') return l&&l!=='0'?m+'-'+l:m; return 'NF'+String(nf??''); }
function recebNormalizar(linhasRm){
  if(!linhasRm || !linhasRm.length) return [];
  // descobre as colunas varrendo TODAS as linhas, não só a primeira — o RM
  // costuma omitir um campo da linha quando ele vem nulo, então se a 1ª
  // linha calhar de ter "DATA RECEBIDO" (ou qualquer outro campo) nulo,
  // usar só ela pra achar as chaves faria a coluna inteira sumir
  const chavesSet = new Set();
  linhasRm.forEach(r=>Object.keys(r).forEach(k=>chavesSet.add(k)));
  const chaves = [...chavesSet];
  const H = chaves.map(recebNormH);
  const ix = (...ks)=>{ for(const k of ks){ const i=H.indexOf(k); if(i>=0) return chaves[i]; } return null; };
  const CH = {
    venc:ix('VENCIMENTO'), mes:ix('MES','COMPETENCIA'), cli:ix('CLIENTE'), emi:ix('EMISSAO'), nf:ix('NOTA FISCAL','NF'),
    ctr:ix('CONTRATO'), mun:ix('PREFEITURA','MUNICIPIO'), rec:ix('VALOR RECEBIDO','RECEBIDO'), dtr:ix('DATA RECEBIDO'), pago:ix('PAGO (S)','PAGO'),
    st:ix('STATUS'), med:ix('VALOR MEDIDO'), inss:ix('INSS'), iss:ix('ISS'), irrf:ix('IRRF'), out:ix('OUTRAS RETENCOES'), tot:ix('TOTAL NF'), parc:ix('VALOR PARCELA'), mov:ix('IDMOV'), lan:ix('IDLAN'),
    nomeAbrev:ix('NOME ABREV'),
  };
  const g = (r,k) => CH[k]==null ? null : r[CH[k]];
  const brutas = [], movs = [];
  linhasRm.forEach(r=>{
    let mes = g(r,'mes'); if(typeof mes==='number') mes = recebYm(recebCellDia(mes)); mes = mes ? String(mes).trim() : '';
    if(/^\d{2}\/\d{4}$/.test(mes)) mes = mes.slice(3)+'-'+mes.slice(0,2);
    if(/^\d{4}-\d{2}-\d{2}/.test(mes)) mes = mes.slice(0,7);
    const pv = String(g(r,'pago')??'').trim().toUpperCase(); const pago = pv==='S'||pv==='1'||pv==='SIM'||pv==='TRUE';
    const emi = recebCellDia(g(r,'emi'));
    brutas.push({
      v: recebCellDia(g(r,'venc')), m: mes || (emi!=null ? recebYm(emi) : ''), c: String(g(r,'cli')??'').trim(),
      e: emi, nf: String(g(r,'nf')??''), k: String(g(r,'ctr')??'').trim(), u: String(g(r,'mun')??'').trim()||'—',
      r: recebCellNum(g(r,'rec')), d: recebCellDia(g(r,'dtr')), p: pago, s: String(g(r,'st')??'').trim(),
      md: recebCellNum(g(r,'med')), inss: recebCellNum(g(r,'inss')), iss: recebCellNum(g(r,'iss')), ot: recebCellNum(g(r,'out'))+recebCellNum(g(r,'irrf')),
      t: recebCellNum(g(r,'tot')), pc: recebCellNum(g(r,'parc')), id: recebIdLinha(g(r,'mov'), g(r,'lan'), g(r,'nf')),
      na: String(g(r,'nomeAbrev')??'').trim(),
      _rm: r, // linha bruta da consulta, sem nenhum tratamento — usada no "Exportar Excel" pra trazer TODAS as colunas que o RM devolveu, não só as que o painel usa
    });
    movs.push(String(g(r,'mov')??'')||null);
  });
  // NF com várias parcelas vem repetida — rateia os valores do movimento
  // pela parcela (não soma em dobro), igual o painel standalone
  const grupos = {};
  brutas.forEach((o,i)=>{ const mv=movs[i]; if(mv && mv!=='0'){ (grupos[mv]=grupos[mv]||[]).push(i); } });
  Object.values(grupos).forEach(ixs=>{
    if(ixs.length<2) return;
    const somaParcela = ixs.reduce((s,i)=>s+(brutas[i].pc||0), 0);
    ixs.forEach(i=>{
      const w = somaParcela>0 ? (brutas[i].pc||0)/somaParcela : 1/ixs.length;
      ['md','inss','iss','ot','t'].forEach(campo=>{ brutas[i][campo] = (brutas[i][campo]||0)*w; });
    });
  });
  // usa o NOME_ABREV vindo direto da consulta do RM quando a sentença já
  // traz essa coluna; sem ela, cai no agrupamento heurístico de sempre
  brutas.forEach(o=>{ o.g = o.na || recebGrupo(o.c); });
  return brutas;
}

// campos embutidos que todo mundo tem (processados/formatados); "rm:X" é
// tratado à parte, direto da linha crua da consulta (ver recebNormalizar)
const RECEB_CAMPOS_FILTRO_BUILTIN = { mes:'Competência', cliente:'Cliente', municipio:'Município', contrato:'Contrato', situacao:'Situação' };
function recebLabelCampoFiltro(campo){
  if(RECEB_CAMPOS_FILTRO_BUILTIN[campo]) return RECEB_CAMPOS_FILTRO_BUILTIN[campo];
  if(campo.startsWith('rm:')) return campo.slice(3);
  return campo;
}
// valor de UM campo filtrável pra uma linha — usado tanto pra montar as
// opções do dropdown quanto pra aplicar o filtro, sempre com a mesma regra
function recebValorFiltro(o, campo){
  switch(campo){
    case 'mes': return o.m;
    case 'cliente': return o.g;
    case 'municipio': return o.u;
    case 'contrato': return o.k;
    case 'situacao': return o.situacao;
    default:
      if(campo.startsWith('rm:')){ const v = o._rm ? o._rm[campo.slice(3)] : undefined; return v==null ? '' : String(v); }
      return '';
  }
}
// todas as colunas que vieram na consulta atual (descobertas nos dados já
// carregados, já que variam de sentença pra sentença) — pra oferecer como
// opção de filtro além dos campos embutidos
function recebColunasRmDisponiveis(){
  const vistas = new Set(), colunas = [];
  recebLinhas.forEach(o=>{ Object.keys(o._rm||{}).forEach(k=>{ if(!vistas.has(k)){ vistas.add(k); colunas.push(k); } }); });
  return colunas;
}
// catálogo pro seletor "Adicionar filtro": embutidos + colunas cruas da
// consulta, menos os campos que já estão configurados como filtro
function recebCamposFiltroDisponiveis(){
  const jaConfigurados = new Set(recebPainelFiltros.map(f=>f.campo));
  const opcoes = Object.keys(RECEB_CAMPOS_FILTRO_BUILTIN).filter(c=>!jaConfigurados.has(c)).map(c=>({ campo:c, label:RECEB_CAMPOS_FILTRO_BUILTIN[c] }));
  recebColunasRmDisponiveis().forEach(col=>{
    const campo = 'rm:'+col;
    if(!jaConfigurados.has(campo)) opcoes.push({ campo, label: col });
  });
  return opcoes;
}
function recebFiltrados(){
  return recebLinhas.filter(o=>
    recebPainelFiltros.every(f=>{
      const set = recebFiltros[f.campo];
      return !set || set.size===0 || set.has(recebValorFiltro(o, f.campo));
    })
  );
}
// linhas restritas por TODOS os outros filtros já marcados, menos o
// próprio campo — usada só pra montar as OPÇÕES do dropdown de um filtro,
// assim cada filtro "se cruza" com os demais (ex: já escolheu Ano=2026, o
// dropdown de Mês só lista os meses que têm nota naquele ano)
function recebLinhasParaOpcoes(campoExcluir){
  return recebLinhas.filter(o=>
    recebPainelFiltros.every(f=>{
      if(f.campo === campoExcluir) return true;
      const set = recebFiltros[f.campo];
      return !set || set.size===0 || set.has(recebValorFiltro(o, f.campo));
    })
  );
}

// só entram clientes cuja Consulta SQL está vinculada ao painel "especial"
// Painel de Recebíveis (Relatórios Gerenciais TOTVS RM → Painéis) — ter só
// a conexão RM no cadastro do cliente não basta, falta vincular a consulta
function recebClientesDisponiveis(){
  return pnlClientesDoPainel(rmPaineis.find(p=>p.slug==='painel-recebiveis'));
}
function recebCarregarLayoutPainel(){
  const layout = rmPainelLayouts.find(p=>p.slug==='painel-recebiveis');
  recebPainelWidgets = layout ? JSON.parse(JSON.stringify(layout.widgets||[])) : [];
  recebPainelWidgetsSalvos = JSON.parse(JSON.stringify(recebPainelWidgets));
  // sem "filtros" salvo (painel antigo, de antes dessa configuração
  // existir) cai nos mesmos 4 filtros de sempre — ninguém perde nada.
  // Cada filtro é {campo, apelido} — "apelido" é opcional (rótulo
  // personalizado); layouts salvos antes do apelido existir guardavam só a
  // string do campo, por isso normaliza string -> {campo} ao carregar
  recebPainelFiltros = layout && Array.isArray(layout.filtros)
    ? layout.filtros.map(f=>typeof f==='string' ? {campo:f} : {campo:f.campo, ...(f.apelido?{apelido:f.apelido}:{})})
    : ['mes','cliente','municipio','contrato'].map(campo=>({campo}));
  recebPainelFiltrosSalvos = JSON.parse(JSON.stringify(recebPainelFiltros));
  recebFiltros = Object.fromEntries(recebPainelFiltros.map(f=>[f.campo, new Set()]));
  recebPainelMedidas = layout && Array.isArray(layout.medidas) ? JSON.parse(JSON.stringify(layout.medidas)) : [];
  recebPainelMedidasSalvos = JSON.parse(JSON.stringify(recebPainelMedidas));
  recebReconstruirCatalogoMedidas();
  recebLayoutCarregado = true;
}
function recebAbrir(){
  if(!recebLayoutCarregado) recebCarregarLayoutPainel();
  const conta = contaAtual();
  // USUARIO só enxerga (e só pode escolher) o próprio cliente — o mesmo
  // isolamento que já existe em Resumo/Dashboard/Financeiro pra quem é
  // da empresa cliente, não da consultoria; ADMIN/ATENDENTE continuam
  // vendo qualquer cliente com o relatório cadastrado
  const souUsuario = conta && conta.perfil === 'USUARIO';
  let disponiveis = recebClientesDisponiveis();
  if(souUsuario) disponiveis = disponiveis.filter(c=>String(c.id)===String(conta.clienteId));
  const sel = document.getElementById('receb_cliente');
  sel.disabled = souUsuario;
  sel.innerHTML = disponiveis.length === 0
    ? `<option value="">${souUsuario ? 'Seu cliente ainda não tem esse relatório cadastrado' : 'Nenhum cliente com relatório cadastrado'}</option>`
    : disponiveis.map(c=>`<option value="${c.id}">${escaparHtml(c.nome)}${c.rmUrl ? '' : ' (falta configurar a conexão RM)'}</option>`).join('');
  if(disponiveis.length === 0) document.getElementById('recebStatus').textContent = souUsuario
    ? 'Peça pro administrador vincular a consulta do seu cliente ao Painel de Recebíveis, em Relatórios Gerenciais TOTVS RM → Painéis.'
    : 'Cadastre uma consulta SQL pra algum cliente e vincule ela ao Painel de Recebíveis em Relatórios Gerenciais TOTVS RM → Painéis.';
  else document.getElementById('recebStatus').textContent = '';
  if(recebClienteId && disponiveis.some(c=>String(c.id)===String(recebClienteId))) sel.value = recebClienteId;
  else recebClienteId = sel.value || '';
  // painel recém-aberto (ou sessão nova) sem nada em memória ainda — tenta
  // usar o último resultado salvo localmente antes de obrigar o usuário a
  // clicar em "Atualizar do RM" só pra ver o que já tinha
  if(recebClienteId && !recebLinhas.length) recebCarregarCache(recebClienteId);
  const perm = permissaoMenu(conta, 'relatoriosgerenciaisrm.painelrecebiveis');
  document.getElementById('btnRecebEditarPainel').style.display = (ehAdminEfetivo(conta) || !perm || perm.editar) ? '' : 'none';
  recebRender();
}
// consultas que precisam de um valor por execução marcam o lugar do valor
// como {nomeDoParametro} dentro do campo "Parâmetros" cadastrado — aqui a
// gente só detecta esses nomes (pra saber se precisa perguntar algo antes
// de disparar o "Atualizar do RM"); a substituição de verdade é feita no
// backend (acaoExecutarRmRelatorioGerencial), que é quem tem o texto real
function rmDetectarParametros(parametros){
  const achados = String(parametros || '').match(/\{([^{}]+)\}/g) || [];
  return [...new Set(achados.map(x=>x.slice(1,-1).trim()).filter(Boolean))];
}
let rmParametrosResolve = null;
// mostra um campo de texto pra cada nome de parâmetro encontrado e devolve
// um Promise com { nome: valor } (ou null se o usuário cancelar) — usado
// tanto pelo painel genérico quanto pelo Painel de Recebíveis antes de
// chamar o RM
function rmPedirValoresParametros(nomes){
  return new Promise(resolve=>{
    rmParametrosResolve = resolve;
    document.getElementById('rmParametrosCampos').innerHTML = nomes.map(n=>`
      <div class="field"><label>${escaparHtml(n)}</label><input type="text" data-paramnome="${escaparHtml(n)}"></div>
    `).join('');
    document.getElementById('rmParametrosModal').classList.add('show');
    const primeiro = document.querySelector('#rmParametrosCampos input');
    if(primeiro) primeiro.focus();
  });
}
function rmFecharModalParametros(valores){
  document.getElementById('rmParametrosModal').classList.remove('show');
  if(rmParametrosResolve){ const resolve = rmParametrosResolve; rmParametrosResolve = null; resolve(valores); }
}
// pede os valores de todos os parâmetros das consultas passadas (unificando
// nomes repetidos entre consultas do mesmo painel) — devolve null se não
// houver nenhum parâmetro pra pedir (segue direto, sem interromper) ou se
// o usuário cancelar o modal
async function rmValoresParametrosDeConsultas(consultas){
  const nomes = [...new Set(consultas.flatMap(c=>rmDetectarParametros(c.parametros)))];
  if(!nomes.length) return {};
  const valores = await rmPedirValoresParametros(nomes);
  return valores;
}
// mesmo cache local do Painel genérico (ver pnlChaveCache/pnlSalvarCache/
// pnlCarregarCache), só que pro Painel de Recebíveis — que é sempre o
// mesmo painel fixo, então a chave é só por cliente
function recebChaveCache(clienteId){ return `recebCache::${clienteId}`; }
function recebSalvarCache(){
  if(!recebClienteId || !recebLinhas.length) return;
  try{
    localStorage.setItem(recebChaveCache(recebClienteId), JSON.stringify({ linhas: recebLinhas, info: recebInfo }));
  }catch(e){ /* quota cheia, modo privado, etc. — sem cache dessa vez, sem travar o resto */ }
}
function recebCarregarCache(clienteId){
  if(!clienteId) return false;
  try{
    const bruto = localStorage.getItem(recebChaveCache(clienteId));
    if(!bruto) return false;
    const cache = JSON.parse(bruto);
    if(!cache || !Array.isArray(cache.linhas) || !cache.info) return false;
    recebLinhas = cache.linhas;
    recebInfo = cache.info;
    recebFiltros = Object.fromEntries(recebPainelFiltros.map(f=>[f.campo, new Set()]));
    return true;
  }catch(e){ return false; }
}
async function recebAtualizarDoRm(){
  if(recebCarregando) return;
  recebClienteId = document.getElementById('receb_cliente').value;
  if(!recebClienteId){ toast('Escolha um cliente com conexão RM cadastrada.'); return; }
  const painelRecebiveis = rmPaineis.find(p=>p.slug==='painel-recebiveis');
  const relatorioId = pnlConsultaIdParaCliente(painelRecebiveis, recebClienteId);
  if(!relatorioId){ document.getElementById('recebStatus').textContent = 'Esse cliente não está vinculado ao Painel de Recebíveis — configure em Relatórios Gerenciais TOTVS RM → Painéis.'; return; }
  const consultaRm = rmRelatoriosGerenciais.find(x=>String(x.id)===String(relatorioId));
  const valoresParametros = await rmValoresParametrosDeConsultas(consultaRm ? [consultaRm] : []);
  if(!valoresParametros) return;
  recebCarregando = true;
  const btn = document.getElementById('btnRecebAtualizar');
  btn.disabled = true; btn.textContent = 'Consultando o RM…';
  document.getElementById('recebStatus').textContent = '';
  try{
    const r = await api('executarRmRelatorioGerencial', { contaId: contaAtual().id, clienteId: recebClienteId, relatorioId, painelId: painelRecebiveis ? painelRecebiveis.id : null, valoresParametros });
    if(!r.ok){ document.getElementById('recebStatus').textContent = r.erro || 'Não foi possível atualizar.'; return; }
    recebLinhas = recebNormalizar(r.linhas || []);
    // calcula situação/saldo já aqui (não só no render) — o filtro por
    // "Situação" e as opções dos outros filtros (que dependem da situação
    // pra "cruzar" com o resto) precisam disso direto em recebLinhas
    const hoje = recebHoje();
    recebLinhas.forEach(o=>{ o.situacao = recebSit(o, hoje); o.saldo = (o.situacao==='Recebida'||o.situacao==='Cancelada') ? 0 : recebSaldo(o); });
    recebInfo = { quando: new Date().toISOString(), nomeRelatorio: r.nomeRelatorio || 'Painel de Recebíveis' };
    recebFiltros = Object.fromEntries(recebPainelFiltros.map(f=>[f.campo, new Set()]));
    toast(`Painel atualizado com ${recebLinhas.length} linha${recebLinhas.length===1?'':'s'} do RM.`);
    recebSalvarCache();
    recebRender();
  } finally {
    recebCarregando = false;
    btn.disabled = false; btn.textContent = 'Atualizar do RM';
  }
}
// "lookup" de multi-seleção (busca + chips dos escolhidos + lista com
// checkbox) — mesmo padrão visual já usado no Gerador SQL RM, só que
// genérico pra qualquer lista de {value,label}, reusado nos 4 filtros
// filtros no mesmo padrão "estilo Excel" já usado nas colunas de
// Atendimentos/Financeiro/Tarefas: um dropdown com "Selecionar todos" +
// uma linha por valor (✓ = marcado), num portal único posicionado embaixo
// do ▾ clicado — Set vazio = "todos" (nenhum filtro aplicado)
let recebFiltroColunaAberta = null; // qual campo está com o dropdown aberto agora
// opções de UM campo filtrável — embutido (processado) ou "rm:X" (direto
// da coluna crua da consulta, sem nenhum tratamento)
// opções de UM campo — cruzadas com os demais filtros já marcados (ver
// recebLinhasParaOpcoes), assim escolher um filtro estreita o que aparece
// nos outros, igual uma tabela dinâmica/slicer
function recebOpcoesPorCampo(campo){
  const linhas = recebLinhasParaOpcoes(campo);
  if(campo==='mes') return [...new Set(linhas.map(o=>o.m).filter(Boolean))].sort().map(m=>({ value:m, label:recebMesLbl(m) }));
  if(campo==='situacao') return [...new Set(linhas.map(o=>o.situacao).filter(Boolean))].map(v=>({ value:v, label:RECEB_PILL_TXT[v]||v }));
  if(campo==='cliente' || campo==='contrato'){
    const m = {}; linhas.forEach(o=>{ const k = campo==='cliente' ? o.g : o.k; m[k] = (m[k]||0) + o.t; });
    return Object.keys(m).sort((a,b)=>m[b]-m[a]).map(v=>campo==='contrato' ? { value:v, label:(c=>c.n+' '+c.d)(recebCtrLbl(v)) } : { value:v, label:v });
  }
  if(campo==='municipio') return [...new Set(linhas.map(o=>o.u))].sort((a,b)=>a.localeCompare(b,'pt')).map(v=>({ value:v, label:v }));
  if(campo.startsWith('rm:')){
    const vistos = new Set();
    linhas.forEach(o=>{ const v = recebValorFiltro(o, campo); if(v!=='') vistos.add(v); });
    return [...vistos].sort((a,b)=>a.localeCompare(b,'pt',{numeric:true})).map(v=>({ value:v, label:v }));
  }
  return [];
}
function recebFecharFiltroColuna(){
  recebFiltroColunaAberta = null;
  const portal = document.getElementById('recebFiltroColunaPortal');
  if(portal){ portal.classList.remove('show'); portal.innerHTML = ''; }
}
function recebToggleFiltroColuna(campo, spanEl){
  const jaAbertoParaEsse = recebFiltroColunaAberta === campo;
  recebFecharFiltroColuna();
  if(jaAbertoParaEsse) return;
  recebFiltroColunaAberta = campo;
  const portal = document.getElementById('recebFiltroColunaPortal');
  if(!portal || !spanEl) return;
  const set = recebFiltros[campo] || new Set();
  const opcoes = recebOpcoesPorCampo(campo);
  const itensDropdown = opcoes.length
    ? opcoes.map(o=>`<div class="lista-filtro-coluna-item" data-chave="${escaparHtml(campo)}" data-valor="${escaparHtml(o.value)}" data-label="${escaparHtml(o.label)}">${set.has(o.value) ? '✓ ' : ''}${escaparHtml(o.label)}</div>`).join('')
    : `<div class="lista-filtro-coluna-item" style="color:var(--muted);cursor:default;">Nenhuma opção disponível</div>`;
  portal.innerHTML = `
    <div style="padding:6px;border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--panel);">
      <input type="text" class="lista-filtro-coluna-busca" placeholder="Buscar…" autocomplete="off" style="width:100%;box-sizing:border-box;border:1px solid var(--line);border-radius:6px;padding:5px 8px;font-size:12.5px;background:var(--bg);color:inherit;">
    </div>
    <div class="lista-filtro-coluna-item" data-chave="${escaparHtml(campo)}" data-valor="" style="font-weight:700;border-bottom:1px solid var(--line);">Selecionar todos</div>
    ${itensDropdown}
  `;
  // busca filtra a lista sem fechar o dropdown — clicar múltiplos itens
  // marca um a um sem precisar reabrir (ver recebRedesenharChecksPortal)
  const busca = portal.querySelector('.lista-filtro-coluna-busca');
  if(busca){
    busca.addEventListener('keydown', e=>e.stopPropagation());
    busca.addEventListener('input', ()=>{
      const t = busca.value.trim().toLowerCase();
      portal.querySelectorAll('.lista-filtro-coluna-item[data-label]').forEach(it=>{
        it.style.display = (!t || it.dataset.label.toLowerCase().includes(t)) ? '' : 'none';
      });
    });
  }
  const r = spanEl.getBoundingClientRect();
  portal.style.left = `${r.left}px`;
  portal.style.top = `${r.bottom + 4}px`;
  portal.classList.add('show');
  if(busca) busca.focus();
}
function recebRedesenharChecksPortal(portal, set){
  portal.querySelectorAll('.lista-filtro-coluna-item[data-label]').forEach(it=>{
    it.textContent = (set.has(it.dataset.valor) ? '✓ ' : '') + it.dataset.label;
  });
}
function recebResumoFiltroConteudoHtml(campo){
  const set = recebFiltros[campo] || new Set();
  if(!set.size) return 'Todos';
  return [...set].map(v=>`<span class="chip on" data-chipfiltro="${escaparHtml(campo)}" data-chipvalor="${escaparHtml(v)}" style="padding:2px 6px 2px 9px;font-size:11px;margin:1px 3px 1px 0;display:inline-flex;align-items:center;gap:4px;">${escaparHtml(recebLabelValorFiltro(campo,v))}<b style="cursor:pointer;font-weight:900;">×</b></span>`).join('');
}
function recebAtualizarResumoFiltro(campo){
  const el = document.querySelector(`#recebGradeFiltros [data-resumo-filtro="${CSS.escape(campo)}"]`);
  if(el) el.innerHTML = recebResumoFiltroConteudoHtml(campo);
  const trig = document.querySelector(`#recebGradeFiltros [data-rfiltro="${CSS.escape(campo)}"]`);
  if(trig) trig.style.color = (recebFiltros[campo]||new Set()).size > 0 ? 'var(--accent)' : '';
}
// recebOpcoesPorCampo já traduz valor->label pros campos especiais (mes,
// situacao, contrato); reaproveita a mesma tradução nos chips, senão o
// chip mostraria o valor cru (ex: "2026-03" em vez de "Março/2026")
function recebLabelValorFiltro(campo, valor){
  const opcao = recebOpcoesPorCampo(campo).find(o=>o.value===valor);
  return opcao ? opcao.label : valor;
}
// recalcula e redesenha só os widgets (sem tocar na grade de filtros,
// que fecharia o dropdown recém-clicado) — mesmo cálculo de linhas do
// recebRender(), só sem o toggle de cards/filtros
function recebAtualizarWidgetsFiltrados(){
  recebRenderEsqueleto();
  const hoje = recebHoje();
  const linhas = recebFiltrados().map(o=>({ ...o, situacao: recebSit(o, hoje) }));
  linhas.forEach(o=>{ o.saldo = (o.situacao==='Recebida'||o.situacao==='Cancelada') ? 0 : recebSaldo(o); });
  recebRenderConteudo(linhas);
}
// monta as LINHAS de filtro (uma por campo configurado) — refeito a cada
// render porque em modo edição cada linha ganha botões de mover/remover e
// um campo de apelido editável
function recebRenderGradeFiltros(){
  const cont = document.getElementById('recebGradeFiltros');
  if(!cont) return;
  cont.innerHTML = recebPainelFiltros.length ? recebPainelFiltros.map((f,i)=>{
    const campo = f.campo;
    const labelPadrao = recebLabelCampoFiltro(campo);
    const label = f.apelido || labelPadrao;
    const botoesEdicao = recebModoEdicao ? `<div style="position:absolute;top:0;right:0;display:flex;gap:2px;">
        <button type="button" data-moverfiltro="up" data-campofiltro="${escaparHtml(campo)}" ${i===0?'disabled':''} title="Mover pra esquerda" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:13px;line-height:1;padding:2px;">↑</button>
        <button type="button" data-moverfiltro="down" data-campofiltro="${escaparHtml(campo)}" ${i===recebPainelFiltros.length-1?'disabled':''} title="Mover pra direita" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:13px;line-height:1;padding:2px;">↓</button>
        <button type="button" data-removerfiltro="${escaparHtml(campo)}" title="Remover filtro" style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:15px;line-height:1;padding:2px;">✕</button>
      </div>` : '';
    const labelHtml = recebModoEdicao
      ? `<input type="text" data-apelidofiltro="${escaparHtml(campo)}" value="${escaparHtml(f.apelido||'')}" placeholder="${escaparHtml(labelPadrao)}" title="Apelido (em branco usa o nome do campo)" style="border:none;background:transparent;padding:0;font:inherit;font-weight:700;color:inherit;width:100%;max-width:110px;">`
      : escaparHtml(label);
    return `<div class="field" style="flex:1;min-width:150px;position:relative;">
      ${botoesEdicao}
      <label for="_">${labelHtml} <span class="lista-th-filtro-wrap" style="position:relative;display:inline-block;"><span data-rfiltro="${escaparHtml(campo)}" style="cursor:pointer;" title="Filtrar ${escaparHtml(label)}">▾</span></span></label>
      <div style="font-size:12.5px;color:var(--muted);" data-resumo-filtro="${escaparHtml(campo)}">${recebResumoFiltroConteudoHtml(campo)}</div>
    </div>`;
  }).join('') : `<div class="empty" style="padding:4px 0;">Nenhum filtro configurado${recebModoEdicao ? ' — escolha um campo abaixo e clique em "+ Adicionar".' : '.'}</div>`;
}
function recebRenderFiltros(){
  if(recebFiltroColunaAberta) recebFecharFiltroColuna();
  recebRenderGradeFiltros();
  document.querySelectorAll('#recebGradeFiltros [data-resumo-filtro]').forEach(el=>{
    el.innerHTML = recebResumoFiltroConteudoHtml(el.dataset.resumoFiltro);
  });
  document.querySelectorAll('#recebGradeFiltros [data-rfiltro]').forEach(el=>{
    const n = (recebFiltros[el.dataset.rfiltro] || new Set()).size;
    el.style.color = n > 0 ? 'var(--accent)' : '';
  });
}
// clique num gráfico/ranking pode filtrar por um campo que ainda não é
// "filtro geral" do painel — nesse caso registra ele na hora (igual
// recebAdicionarFiltro faria manualmente), pra aparecer como chip removível
// na grade de filtros, em vez de simplesmente não fazer nada
function recebToggleFiltro(campo, valor){
  if(!recebPainelFiltros.some(f=>f.campo===campo)){
    recebPainelFiltros.push({campo});
    recebPopularSelectNovoFiltro();
  }
  const set = recebFiltros[campo] = recebFiltros[campo] || new Set();
  if(set.has(valor)) set.delete(valor); else set.add(valor);
  recebRender();
}
// catálogo de campos filtráveis ainda não usados — preenche o seletor
// "Adicionar filtro" (só existe em modo edição)
function recebPopularSelectNovoFiltro(){
  const sel = document.getElementById('recebNovoFiltroCampo');
  if(!sel) return;
  const opcoes = recebCamposFiltroDisponiveis();
  sel.innerHTML = opcoes.length
    ? opcoes.map(o=>`<option value="${escaparHtml(o.campo)}">${escaparHtml(o.label)}</option>`).join('')
    : `<option value="">Nenhum campo disponível</option>`;
}
function recebAdicionarFiltro(campo){
  if(!campo || recebPainelFiltros.some(f=>f.campo===campo)) return;
  recebPainelFiltros.push({campo});
  if(!recebFiltros[campo]) recebFiltros[campo] = new Set();
  recebPopularSelectNovoFiltro();
  recebRender();
}
function recebRemoverFiltro(campo){
  recebPainelFiltros = recebPainelFiltros.filter(f=>f.campo!==campo);
  recebPopularSelectNovoFiltro();
  recebRender();
}
// reordena os filtros gerais (ordem em que aparecem na grade) — mesmo
// padrão do recebWidgetMover, só que no array recebPainelFiltros
function recebMoverFiltro(campo, dir){
  const i = recebPainelFiltros.findIndex(f=>f.campo===campo);
  if(i<0) return;
  const j = dir==='up' ? i-1 : i+1;
  if(j<0 || j>=recebPainelFiltros.length) return;
  [recebPainelFiltros[i], recebPainelFiltros[j]] = [recebPainelFiltros[j], recebPainelFiltros[i]];
  recebRenderFiltros();
}

/* ---------- motor de widgets (medida + dimensão) ----------
   Um widget é {id,tipo,titulo,medida,medida2,dimensao,top}. "medida" é
   o que se mede (faturado, recebido...), "dimensao" é o agrupamento
   (por mês, por cliente...) — qualquer combinação medida×dimensão vira
   um gráfico, sem precisar de código novo pra cada combinação. */
// as 12 medidas "de sistema" (fórmulas de negócio fixas, com a regra de
// cancelada/situação embutida) — nunca removíveis, mas o rótulo e o
// formato de exibição podem ser editados em "Medidas" no modo edição
const RECEB_MEDIDAS_PADRAO = {
  faturado: { label:'Faturado (Total NF)', fmt:'money' },
  recebido: { label:'Recebido', fmt:'money' },
  emAberto: { label:'Em aberto', fmt:'money' },
  retencoes: { label:'Retenções na fonte', fmt:'money' },
  qtdNotas: { label:'Qtd. de notas', fmt:'int', casas:0 },
  qtdCanceladas: { label:'Notas canceladas', fmt:'int', casas:0 },
  canceladas: { label:'Valor cancelado', fmt:'money' },
  vencido: { label:'Vencido', fmt:'money' },
  proximos7: { label:'Vence em 7 dias', fmt:'money' },
  aVencer: { label:'A vencer depois', fmt:'money' },
  prazoMedio: { label:'Prazo médio de recebimento', fmt:'dias', casas:0 },
  pontualidade: { label:'Recebido no prazo', fmt:'pct', casas:1 },
};
// catálogo EFETIVO de medidas — começa igual ao padrão, e é reconstruído
// (recebReconstruirCatalogoMedidas) toda vez que recebPainelMedidas muda,
// aplicando os overrides (label/fmt de uma medida de sistema) e as
// medidas personalizadas (campo+função) por cima. Usado em TODO lugar
// que já lia RECEB_MEDIDAS[x].label/.fmt — nenhum desses lugares precisou
// mudar, só passou a enxergar um catálogo editável.
let RECEB_MEDIDAS = { ...RECEB_MEDIDAS_PADRAO };
function recebReconstruirCatalogoMedidas(){
  RECEB_MEDIDAS = { ...RECEB_MEDIDAS_PADRAO };
  (recebPainelMedidas||[]).forEach(m=>{
    RECEB_MEDIDAS[m.id] = { label:m.label, fmt:m.fmt, campo:m.campo, funcao:m.funcao, casas:m.casas };
  });
}
// campos numéricos que uma medida personalizada pode agregar: os já
// processados (iguais aos da tabela) + qualquer coluna crua da consulta
const RECEB_CAMPOS_MEDIDA_BUILTIN = { totalNf:'Total NF', recebido:'Recebido', saldo:'Saldo', medido:'Valor Medido', inss:'INSS', iss:'ISS', outrasRetencoes:'Outras Retenções' };
function recebCamposMedidaDisponiveis(){
  const opcoes = Object.entries(RECEB_CAMPOS_MEDIDA_BUILTIN).map(([campo,label])=>({campo,label}));
  recebColunasRmDisponiveis().forEach(col=>opcoes.push({ campo:'rm:'+col, label:col }));
  return opcoes;
}
function recebValorCampoMedidaBruto(o, campo){
  switch(campo){
    case 'totalNf': return o.t; case 'recebido': return o.r; case 'saldo': return o.saldo;
    case 'medido': return o.md; case 'inss': return o.inss; case 'iss': return o.iss; case 'outrasRetencoes': return o.ot;
    default: return campo && campo.startsWith('rm:') ? (o._rm ? o._rm[campo.slice(3)] : undefined) : undefined;
  }
}
function recebValorCampoMedidaNum(o, campo){
  const v = recebValorCampoMedidaBruto(o, campo);
  if(typeof v === 'number') return v;
  if(v==null || v==='') return 0;
  const n = parseFloat(String(v).replace(/[^\d,.\-]/g,'').replace(',','.'));
  return isNaN(n) ? 0 : n;
}
// medida personalizada: {campo, funcao[, campoBase]} — "contagem" nem
// olha pro campo (conta linhas), as demais agregam recebValorCampoMedidaNum
function recebCalcularMedidaGenerica(linhas, def){
  if(def.funcao === 'contagem') return linhas.length;
  if(def.funcao === 'contagemDistinta'){
    const vistos = new Set();
    linhas.forEach(o=>{ const v = recebValorCampoMedidaBruto(o, def.campo); if(v!=null && v!=='') vistos.add(String(v)); });
    return vistos.size;
  }
  const vals = linhas.map(o=>recebValorCampoMedidaNum(o, def.campo));
  switch(def.funcao){
    case 'soma': return vals.reduce((s,v)=>s+v,0);
    case 'media': return vals.length ? vals.reduce((s,v)=>s+v,0)/vals.length : 0;
    case 'min': return vals.length ? Math.min(...vals) : 0;
    case 'max': return vals.length ? Math.max(...vals) : 0;
    case 'percentualDoTotal': {
      const totalGeral = recebLinhas.reduce((s,o)=>s+recebValorCampoMedidaNum(o, def.campo),0);
      const soma = vals.reduce((s,v)=>s+v,0);
      return totalGeral ? soma/totalGeral : 0;
    }
    default: return 0;
  }
}
function recebCalcularMedida(linhas, medida){
  const def = RECEB_MEDIDAS[medida];
  if(def && def.campo && def.funcao) return recebCalcularMedidaGenerica(linhas, def);
  const validas = linhas.filter(o=>o.situacao!=='Cancelada');
  const canceladas = linhas.filter(o=>o.situacao==='Cancelada');
  switch(medida){
    case 'faturado': return validas.reduce((s,o)=>s+o.t,0);
    case 'recebido': return linhas.reduce((s,o)=>s+(o.r||0),0);
    case 'emAberto': return validas.reduce((s,o)=>s+o.saldo,0);
    case 'retencoes': return validas.reduce((s,o)=>s+o.inss+o.iss+o.ot,0);
    case 'qtdNotas': return validas.length;
    case 'qtdCanceladas': return canceladas.length;
    case 'canceladas': return canceladas.reduce((s,o)=>s+o.t,0);
    case 'vencido': return linhas.filter(o=>o.situacao==='Atrasada').reduce((s,o)=>s+o.saldo,0);
    case 'proximos7': return linhas.filter(o=>o.situacao==='Próximos dias').reduce((s,o)=>s+o.saldo,0);
    case 'aVencer': return linhas.filter(o=>o.situacao==='A vencer').reduce((s,o)=>s+o.saldo,0);
    case 'prazoMedio': {
      const r = validas.filter(o=>o.situacao==='Recebida' && o.d!=null && o.e!=null);
      const w = r.reduce((s,o)=>s+o.r,0);
      return w ? r.reduce((s,o)=>s+(o.d-o.e)*o.r,0)/w : 0;
    }
    case 'pontualidade': {
      const r = validas.filter(o=>o.situacao==='Recebida' && o.d!=null && o.e!=null && o.v!=null);
      return r.length ? r.filter(o=>o.d<=o.v).length/r.length : 0;
    }
    default: return 0;
  }
}
// "casas" (casas decimais) é configurável pra qualquer formato que não
// seja dinheiro — 0 = número inteiro, >0 = decimal com essa quantidade
// de casas; sem "casas" definido, cai no padrão de cada formato (1 pro
// percentual, 0 pros demais) — mantém o comportamento de sempre pras
// medidas de sistema que nunca tiveram essa configuração
function recebFormatarMedida(valor, medida){
  const def = RECEB_MEDIDAS[medida] || {};
  const fmt = def.fmt;
  if(fmt==='money') return fmtMoeda(valor);
  const casas = Number.isInteger(def.casas) ? def.casas : (fmt==='pct' ? 1 : 0);
  if(fmt==='pct') return (valor*100).toLocaleString('pt-BR',{minimumFractionDigits:casas,maximumFractionDigits:casas})+'%';
  const numFmt = valor.toLocaleString('pt-BR',{minimumFractionDigits:casas,maximumFractionDigits:casas});
  if(fmt==='dias') return numFmt+' dias';
  return numFmt;
}
// subtítulo pequeno sob o valor do KPI — só os casos que valem a pena
function recebSubtituloMedida(linhas, medida){
  const validas = linhas.filter(o=>o.situacao!=='Cancelada');
  const pct = x => x.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%';
  switch(medida){
    case 'faturado': return `${validas.length} notas válidas`;
    case 'recebido': { const fat=recebCalcularMedida(linhas,'faturado'); return fat ? pct(recebCalcularMedida(linhas,'recebido')/fat*100)+' do faturado' : ''; }
    case 'emAberto': return `${validas.filter(o=>o.saldo>0).length} notas`;
    case 'prazoMedio': return 'da emissão ao crédito, ponderado por valor';
    case 'pontualidade': return 'notas pagas até o vencimento';
    case 'retencoes': { const medido=validas.reduce((s,o)=>s+o.md,0); const ret=recebCalcularMedida(linhas,'retencoes'); return medido ? `INSS, ISS e outras: ${pct(ret/medido*100)} do medido` : ''; }
    case 'qtdCanceladas': return fmtMoeda(recebCalcularMedida(linhas,'canceladas'))+' em notas canceladas';
    case 'vencido': { const n=linhas.filter(o=>o.situacao==='Atrasada').length; return `${n} nota${n===1?'':'s'}`; }
    case 'proximos7': { const n=linhas.filter(o=>o.situacao==='Próximos dias').length; return `${n} nota${n===1?'':'s'}`; }
    case 'aVencer': { const n=linhas.filter(o=>o.situacao==='A vencer').length; return `${n} nota${n===1?'':'s'}`; }
    default: return '';
  }
}
// dimensões "normais" (agrupam por um campo da própria linha); a
// "faixaVencimento" é tratada à parte logo abaixo, porque sua faixa
// depende da data de hoje, não de um campo fixo
const RECEB_DIMENSOES = {
  mes: { label:'Competência', chave:o=>o.m, fmtLabel:recebMesLbl, ordenar:'chave' },
  cliente: { label:'Cliente', chave:o=>o.g, fmtLabel:v=>v, ordenar:'valor' },
  municipio: { label:'Município', chave:o=>o.u, fmtLabel:v=>v, ordenar:'valor' },
  contrato: { label:'Contrato', chave:o=>o.k, fmtLabel:k=>{ const c=recebCtrLbl(k); return c.n+' '+c.d; }, ordenar:'valor' },
  situacao: { label:'Situação', chave:o=>o.situacao, fmtLabel:v=>v, ordenar:'valor' },
};
const RECEB_DIMENSOES_TODAS = { ...Object.fromEntries(Object.entries(RECEB_DIMENSOES).map(([k,v])=>[k,v.label])), faixaVencimento:'Faixa de vencimento' };
// faixaVencimento é a única dimensão sem valor "cru" por linha (é um
// bucket calculado por data, ver recebAgruparPorDimensao/RECEB_FAIXAS_VENCIMENTO)
// — recebValorFiltro não sabe recalculá-lo, então é a única que não pode
// virar filtro de clique; todas as outras podem
function recebDimensaoFiltravel(dimensao){ return dimensao !== 'faixaVencimento'; }
const RECEB_FAIXAS_VENCIMENTO = [
  { nome:'Vencido há mais de 30d', teste:(o,hoje)=>o.v!=null && (hoje-o.v)>30 },
  { nome:'Vencido 15–30d', teste:(o,hoje)=>o.v!=null && (hoje-o.v)>=15 && (hoje-o.v)<=30 },
  { nome:'Vencido até 14d', teste:(o,hoje)=>o.v!=null && (hoje-o.v)>=1 && (hoje-o.v)<15 },
  { nome:'Vence em até 7d', teste:(o,hoje)=>o.v!=null && (o.v-hoje)>=0 && (o.v-hoje)<=7 },
  { nome:'Vence em 8–30d', teste:(o,hoje)=>o.v!=null && (o.v-hoje)>7 && (o.v-hoje)<=30 },
  { nome:'Vence depois de 30d', teste:(o,hoje)=>o.v!=null && (o.v-hoje)>30 },
  { nome:'Sem vencimento', teste:(o,hoje)=>o.v==null },
];
function recebAgruparPorDimensao(linhas, dimensaoChave, medida){
  if(dimensaoChave === 'faixaVencimento'){
    const hoje = recebHoje();
    return RECEB_FAIXAS_VENCIMENTO.map(f=>({ chave:f.nome, rotulo:f.nome, valor: recebCalcularMedida(linhas.filter(o=>f.teste(o,hoje)), medida) }));
  }
  const dim = RECEB_DIMENSOES[dimensaoChave];
  if(!dim) return [];
  const grupos = {};
  linhas.forEach(o=>{ const k = dim.chave(o); (grupos[k] = grupos[k] || []).push(o); });
  const arr = Object.entries(grupos).map(([k,itens])=>({ chave:k, rotulo:dim.fmtLabel(k), valor: recebCalcularMedida(itens, medida) }));
  arr.sort(dim.ordenar==='chave' ? (a,b)=>String(a.chave).localeCompare(String(b.chave)) : (a,b)=>b.valor-a.valor);
  return arr;
}
// agrupa por uma dimensão calculando a MESMA quebra por situação que o
// painel standalone já tinha (Recebido/Vencido/A vencer) — usado pelo
// widget "ranking-situacao", ordenado sempre do maior faturado pro menor
function recebAgruparRankingSituacao(linhas, dimensaoChave, top){
  const hoje = recebHoje();
  const grupos = {};
  linhas.forEach(o=>{
    if(o.situacao === 'Cancelada') return;
    const k = recebChaveDimensaoValor(o, dimensaoChave, hoje);
    const g = grupos[k] || (grupos[k] = { chave:k, rotulo: recebRotuloDimensaoValor(k, dimensaoChave), t:0, r:0, v:0, f:0 });
    g.t += o.t;
    g.r += Math.min(o.r||0, o.t); // nunca deixa o "recebido" passar do total (nota paga a mais não estoura a barra)
    if(o.situacao === 'Atrasada') g.v += o.saldo; else g.f += o.saldo;
  });
  let arr = Object.values(grupos).sort((a,b)=>b.t-a.t);
  if(top) arr = arr.slice(0, Number(top));
  return arr;
}
function recebRenderWidgetRankingSituacao(containerId, widget, linhas){
  const cont = document.getElementById(containerId); if(!cont) return;
  const grupos = recebAgruparRankingSituacao(linhas, widget.dimensao, widget.top);
  if(!grupos.length){ cont.innerHTML = '<div class="dash-empty">Sem dados no período.</div>'; return; }
  const max = Math.max(...grupos.map(g=>g.t), 1);
  const w = x => (x/max*100).toFixed(2)+'%';
  const filtravel = recebDimensaoFiltravel(widget.dimensao);
  cont.innerHTML = grupos.map(g=>{
    const outro = Math.max(0, g.t - g.r - g.v - g.f);
    const nome = filtravel
      ? `<button type="button" class="receb-rs-nome" data-rsclique="${escaparHtml(widget.dimensao)}" data-rsvalor="${escaparHtml(g.chave)}" title="Filtrar por ${escaparHtml(g.rotulo)}">${escaparHtml(g.rotulo)}</button>`
      : `<span>${escaparHtml(g.rotulo)}</span>`;
    return `<div class="receb-rs-row">
      <div style="display:flex;justify-content:space-between;align-items:baseline;gap:10px;">${nome}<span class="receb-rs-valor">${fmtMoeda(g.t)}</span></div>
      <div class="receb-rs-track" title="Recebido ${fmtMoeda(g.r)} · Vencido ${fmtMoeda(g.v)} · A vencer ${fmtMoeda(g.f)}">
        <span style="width:${w(g.r)};background:${dashCss('--ok')};"></span><span style="width:${w(g.v)};background:${dashCss('--bad')};"></span><span style="width:${w(g.f)};background:${dashCss('--warn')};"></span><span style="width:${w(outro)};background:${dashCss('--line')};"></span>
      </div>
    </div>`;
  }).join('');
}
// clique na barra filtra o painel por aquele valor — no modo horizontal
// o dashBarChart desenha 2 <rect> por linha (trilho + barra, por isso
// índice ímpar); no vertical é 1 <rect> por barra (índice direto)
function recebLigarCliqueBarras(container, grupos, chaveFiltro, horizontal){
  const rects = container.querySelectorAll('rect');
  grupos.forEach((g,i)=>{
    const bar = horizontal ? rects[i*2+1] : rects[i];
    if(!bar) return;
    bar.style.cursor = 'pointer';
    bar.addEventListener('click', ()=>recebToggleFiltro(chaveFiltro, g.chave));
  });
}
// dashDonut desenha 1 <path> por fatia, na mesma ordem dos dados passados
function recebLigarCliqueDonut(container, grupos, chaveFiltro){
  const paths = container.querySelectorAll('path');
  grupos.forEach((g,i)=>{
    const fatia = paths[i];
    if(!fatia) return;
    fatia.style.cursor = 'pointer';
    fatia.addEventListener('click', ()=>recebToggleFiltro(chaveFiltro, g.chave));
  });
}
// dashLineChart desenha 2 <circle> por ponto (visível + invisível de r:9,
// esse último já usado pra tooltip) — ver pnlLigarCliqueLinha, mesma convenção
function recebLigarCliqueLinha(container, chaves, chaveFiltro, numSeries){
  const circles = container.querySelectorAll('circle');
  const totalPontos = chaves.length * numSeries;
  for(let i=0;i<totalPontos;i++){
    const alvo = circles[i*2+1];
    if(!alvo) continue;
    const chave = chaves[i % chaves.length];
    alvo.style.cursor = 'pointer';
    alvo.addEventListener('click', ()=>recebToggleFiltro(chaveFiltro, chave));
  }
}
const RECEB_PILL_COR = { 'Atrasada':'var(--bad)', 'Próximos dias':'var(--warn)', 'A vencer':'var(--muted)' };
const RECEB_PILL_TXT = { 'Atrasada':'Vencida', 'Próximos dias':'Próx. 7 dias', 'A vencer':'A vencer' };

/* ---------- render de cada tipo de widget ---------- */
function recebRenderWidgetKpi(containerId, widget, linhas){
  const el = document.getElementById(containerId); if(!el) return;
  const valor = recebCalcularMedida(linhas, widget.medida);
  const info = RECEB_MEDIDAS[widget.medida] || {};
  const sub = widget.mostrarSubtitulo === false ? '' : (widget.subtitulo || recebSubtituloMedida(linhas, widget.medida));
  const corDestaque = widget.medida==='vencido' ? ' style="color:var(--bad);"' : '';
  el.innerHTML = `<div class="box"><div class="k">${escaparHtml(widget.titulo || info.label || widget.medida)}</div><div class="v"${corDestaque}>${recebFormatarMedida(valor, widget.medida)}</div>${sub ? `<div class="x" style="font-size:11px;color:var(--muted);margin-top:2px;">${escaparHtml(sub)}</div>` : ''}</div>`;
}
function recebRenderWidgetGrafico(containerId, widget, linhas, tipo){
  const cont = document.getElementById(containerId); if(!cont) return;
  const altura = RECEB_ALTURAS_WIDGET[widget.altura];
  if(tipo==='linha'){
    const dimensao = widget.dimensao || 'mes';
    const medidas = widget.medida2 ? [widget.medida, widget.medida2] : [widget.medida];
    const cores = ['--blue','--ok','--bad','--warn'];
    const porMedida = medidas.map(m=>recebAgruparPorDimensao(linhas, dimensao, m));
    const chaves = [...new Set(porMedida.flatMap(arr=>arr.map(g=>g.chave)))];
    const dim = RECEB_DIMENSOES[dimensao];
    chaves.sort(dim && dim.ordenar==='chave' ? (a,b)=>String(a).localeCompare(String(b)) : (a,b)=>{
      const soma = c => porMedida.reduce((s,arr)=>s+(arr.find(g=>g.chave===c)?.valor||0),0);
      return soma(b)-soma(a);
    });
    const fmtLabel = dimensao==='faixaVencimento' ? (v=>v) : (dim ? dim.fmtLabel : (v=>v));
    const series = medidas.map((m,i)=>{
      const porChave = {}; porMedida[i].forEach(g=>{ porChave[g.chave]=g.valor; });
      return { label:(RECEB_MEDIDAS[m]||{}).label||m, tok:cores[i%cores.length], data: chaves.map(c=>porChave[c]||0) };
    });
    dashLineChart(cont, { labels: chaves.map(fmtLabel), series, mostrarRotulos: !!widget.mostrarRotulos, ...(altura ? {height:altura} : {}) });
    if(recebDimensaoFiltravel(dimensao)) recebLigarCliqueLinha(cont, chaves, dimensao, medidas.length);
    if(widget.mostrarLegenda) cont.insertAdjacentHTML('beforeend', `<div class="dash-legend">${dashLegendHtml(series.map(s=>({label:s.label, cor:dashCss(s.tok)})))}</div>`);
    return;
  }
  let grupos = recebAgruparPorDimensao(linhas, widget.dimensao, widget.medida);
  if(widget.top) grupos = grupos.slice(0, Number(widget.top));
  if(tipo==='donut'){
    const cores = ['--blue','--ok','--bad','--warn','--purple','--yellow'];
    const total = grupos.reduce((s,g)=>s+g.valor,0);
    dashDonut(cont, grupos.map((g,i)=>({ label:g.rotulo, value:g.valor, cor:dashCss(cores[i%cores.length]) })), altura ? {size:altura} : undefined);
    if(recebDimensaoFiltravel(widget.dimensao)) recebLigarCliqueDonut(cont, grupos, widget.dimensao);
    if(widget.mostrarLegenda){
      const itens = grupos.map((g,i)=>({ label: widget.mostrarRotulos && total ? `${g.rotulo} (${Math.round(g.valor/total*100)}%)` : g.rotulo, cor:dashCss(cores[i%cores.length]) }));
      cont.insertAdjacentHTML('beforeend', `<div class="dash-legend">${dashLegendHtml(itens)}</div>`);
    }
    return;
  }
  const unit = (RECEB_MEDIDAS[widget.medida]||{}).fmt === 'pct' ? '' : 'R$';
  const data = grupos.map(g=>({ label:g.rotulo, value:g.valor, tok:'--blue' }));
  const horizontal = tipo==='barra-h';
  dashBarChart(cont, { data, horizontal, rotateLabels: tipo==='barra', unit, mostrarRotulos: !!widget.mostrarRotulos, ...(altura ? {height:altura} : {}) });
  if(recebDimensaoFiltravel(widget.dimensao)) recebLigarCliqueBarras(cont, grupos, widget.dimensao, horizontal);
}
function recebRenderWidgetAbertas(widget, linhas){
  const hoje = recebHoje();
  const buscaEl = document.querySelector(`[data-wbusca][data-wid="${widget.id}"]`);
  const busca = (buscaEl?.value || '').trim().toLowerCase();
  const seg = recebSegPorWidget[widget.id] || 'todas';
  const abertas = linhas.filter(o=>o.saldo>0 && (seg==='todas' || o.situacao===seg)
    && (!busca || [o.nf,o.c,o.k,o.u,o.g].join(' ').toLowerCase().includes(busca)))
    .sort((a,b)=>(a.v??9e9)-(b.v??9e9));
  recebUltimaListaAbertas[widget.id] = abertas;
  const total = abertas.reduce((s,o)=>s+o.saldo,0);
  const linhasHtml = abertas.map(o=>{
    const dias = o.v==null ? '' : o.v-hoje;
    const c = recebCtrLbl(o.k);
    const diasTxt = dias==='' ? '' : (dias<0 ? Math.abs(dias)+' atraso' : dias===0 ? 'hoje' : 'em '+dias);
    return `<tr><td><span class="pill" style="background:${RECEB_PILL_COR[o.situacao]||'var(--muted)'};color:#fff;">${RECEB_PILL_TXT[o.situacao]||o.situacao}</span></td>
      <td>${recebFmtDia(o.v)}</td><td style="color:${dias<0?'var(--bad)':'inherit'};">${escaparHtml(diasTxt)}</td>
      <td${ehNumAlinhavel(o.nf)?' class="num"':''}>${escaparHtml(o.nf)}</td><td>${escaparHtml(o.g)}</td><td>${escaparHtml(o.u)}</td><td title="${escaparHtml(o.k)}">${escaparHtml(c.n)}</td>
      <td class="num">${fmtMoeda(o.t)}</td><td class="num">${o.r?fmtMoeda(o.r):''}</td><td class="num"><b>${fmtMoeda(o.saldo)}</b></td></tr>`;
  }).join('');
  const tab = document.getElementById(`receb-${widget.id}-tabela`);
  if(tab) tab.innerHTML = `<thead><tr><th>STATUS</th><th>VENCIMENTO</th><th>Dias</th><th class="num">NOTA FISCAL</th><th>CLIENTE</th><th>PREFEITURA</th><th>CONTRATO</th><th class="num">TOTAL NF</th><th class="num">RECEBIDO</th><th class="num">Saldo</th></tr></thead>
    <tbody>${linhasHtml || `<tr><td colspan="10" class="empty">${recebLinhas.length ? 'Nenhuma nota em aberto com esses filtros.' : 'Sem dados — atualize do RM primeiro.'}</td></tr>`}</tbody>
    <tfoot><tr><td colspan="9"><b>${abertas.length} notas</b></td><td class="num"><b>${fmtMoeda(total)}</b></td></tr></tfoot>`;
}
function recebRenderWidgetContratos(widget, linhas){
  const m = {};
  linhas.forEach(o=>{
    const g = m[o.k] || (m[o.k] = { k:o.k, g:o.g, n:0, t:0, r:0, a:0, v:0, c:0 });
    if(o.situacao==='Cancelada'){ g.c++; return; }
    g.n++; g.t+=o.t; g.r+=o.r||0; g.a+=o.saldo; if(o.situacao==='Atrasada') g.v+=o.saldo;
  });
  const arr = Object.values(m).filter(g=>g.n||g.c).sort((a,b)=>b.t-a.t);
  const linhasHtml = arr.map(g=>{
    const c = recebCtrLbl(g.k);
    const pct = g.t ? Math.round(Math.min(1,g.r/g.t)*100) : 0;
    return `<tr data-ctr="${escaparHtml(g.k)}" style="cursor:pointer;" title="Clique pra filtrar por esse contrato"><td><b>${escaparHtml(c.n)}</b><br><span style="color:var(--muted);font-size:11px;">${escaparHtml(c.d)}</span></td>
      <td>${escaparHtml(g.g)}</td><td class="num">${g.n}</td><td class="num">${fmtMoeda(g.t)}</td><td class="num">${fmtMoeda(g.r)}</td><td class="num">${pct}%</td>
      <td class="num">${g.a?fmtMoeda(g.a):''}</td><td class="num" style="color:var(--bad);">${g.v?fmtMoeda(g.v):''}</td><td class="num">${g.c||''}</td></tr>`;
  }).join('');
  const tab = document.getElementById(`receb-${widget.id}-tabela`);
  if(tab) tab.innerHTML = `<thead><tr><th>Contrato</th><th>Cliente</th><th class="num">Notas</th><th class="num">Faturado</th><th class="num">Recebido</th><th class="num">% recebido</th><th class="num">Em aberto</th><th class="num">Vencido</th><th class="num">Canceladas</th></tr></thead>
    <tbody>${linhasHtml || `<tr><td colspan="9" class="empty">${recebLinhas.length ? 'Nenhum contrato com esses filtros.' : 'Sem dados — atualize do RM primeiro.'}</td></tr>`}</tbody>`;
}
// catálogo de colunas da "Tabela (colunas à sua escolha)" quando a fonte é
// "notas" (uma linha por nota) — quando a fonte é "agrupado", as colunas
// disponíveis são as próprias RECEB_MEDIDAS (reaproveitadas)
// os rótulos são os nomes EXATOS das colunas como a consulta do RM devolve
// (conferido direto num export da RealizaConsulta) — "Dias" e "Saldo" são
// os únicos sem equivalente lá, por serem calculados aqui no sistema
const RECEB_COLUNAS_NOTAS = {
  situacao:'STATUS', vencimento:'VENCIMENTO', dias:'Dias', emissao:'EMISSÃO', nf:'NOTA FISCAL',
  cliente:'CLIENTE', municipio:'PREFEITURA', contrato:'CONTRATO', competencia:'MÊS',
  totalNf:'TOTAL NF', recebido:'RECEBIDO', dataRecebido:'DATA RECEBIDO', saldo:'Saldo',
  medido:'VALOR MEDIDO', inss:'INSS', iss:'ISS', outrasRetencoes:'OUTRAS RETENÇÕES',
};
const RECEB_COLUNAS_NOTAS_PADRAO = ['situacao','vencimento','nf','cliente','municipio','contrato','totalNf','recebido','saldo'];
// catálogo de colunas disponíveis na tabela "fonte: notas" — os campos
// processados de cima + TODAS as colunas cruas que a consulta do RM
// trouxer (igual o Exportar Excel, pra não faltar nenhuma)
function recebColunasTabelaDisponiveis(){
  const opcoes = { ...RECEB_COLUNAS_NOTAS };
  recebColunasRmDisponiveis().forEach(col=>{ const campo = 'rm:'+col; if(!opcoes[campo]) opcoes[campo] = col; });
  return opcoes;
}
// formata o valor cru de uma coluna da consulta quando ele é numérico —
// mesma regra segura do Exportar Excel (não mexe em código com zero à
// esquerda, tipo NOTA FISCAL/protocolo) + uma heurística: número com
// casas decimais é tratado como dinheiro (todo campo financeiro do RM
// sai com 2 casas), número inteiro só ganha separador de milhar, pra não
// rotular ano/id como "R$"
function recebFormatarCampoRm(v){
  if(v == null || v === '') return '';
  const n = recebCoagirNumeroExcel(v);
  if(typeof n !== 'number') return v;
  return Number.isInteger(n) ? n.toLocaleString('pt-BR') : fmtMoeda(n);
}
function recebValorColunaNota(o, hoje, chave){
  switch(chave){
    case 'situacao': return o.situacao;
    case 'vencimento': return recebFmtDia(o.v);
    case 'dias': { if(o.v==null) return ''; const d=o.v-hoje; return d<0?Math.abs(d)+' atraso':d===0?'hoje':'em '+d; }
    case 'emissao': return recebFmtDia(o.e);
    case 'nf': return o.nf;
    case 'cliente': return o.g;
    case 'municipio': return o.u;
    case 'contrato': { const c=recebCtrLbl(o.k); return `${c.n} ${c.d}`.trim(); }
    case 'competencia': return o.m ? recebMesLbl(o.m) : '';
    case 'totalNf': return fmtMoeda(o.t);
    case 'recebido': return o.r ? fmtMoeda(o.r) : '';
    case 'dataRecebido': return recebFmtDia(o.d);
    case 'saldo': return fmtMoeda(o.saldo);
    case 'medido': return fmtMoeda(o.md);
    case 'inss': return fmtMoeda(o.inss);
    case 'iss': return fmtMoeda(o.iss);
    case 'outrasRetencoes': return fmtMoeda(o.ot);
    default:
      if(chave && chave.startsWith('rm:')) return recebFormatarCampoRm(o._rm ? o._rm[chave.slice(3)] : undefined);
      return '';
  }
}
// valor NUMÉRICO (não formatado) de uma coluna de nota — usado só pra
// somar no rodapé da tabela; colunas que não fazem sentido somar
// (situação, datas, texto) devolvem null e ficam de fora do total
function recebValorColunaNotaNumerico(o, chave){
  switch(chave){
    case 'totalNf': return o.t;
    case 'recebido': return o.r || 0;
    case 'saldo': return o.saldo;
    case 'medido': return o.md;
    case 'inss': return o.inss;
    case 'iss': return o.iss;
    case 'outrasRetencoes': return o.ot;
    default:
      if(chave && chave.startsWith('rm:')){ const n = recebCoagirNumeroExcel(o._rm ? o._rm[chave.slice(3)] : undefined); return typeof n === 'number' ? n : null; }
      return null;
  }
}
const RECEB_COLUNAS_NOTAS_MONETARIAS = new Set(['totalNf','recebido','saldo','medido','inss','iss','outrasRetencoes']);
function recebFormatarTotalColunaNota(chave, soma){
  if(RECEB_COLUNAS_NOTAS_MONETARIAS.has(chave)) return fmtMoeda(soma);
  return Number.isInteger(soma) ? soma.toLocaleString('pt-BR') : fmtMoeda(soma);
}
// decide alinhamento (números à direita) de uma coluna da tabela de notas —
// usa a mesma regra de "dá pra somar" (dinheiro + rm: numéricas) e soma só
// a NOTA FISCAL (nf), que não faz sentido somar mas é numérica
function recebColunaEhNumerica(o, chave){
  if(recebValorColunaNotaNumerico(o, chave) != null) return true;
  return chave === 'nf' && ehNumAlinhavel(o.nf);
}
// valor/rótulo de UM nível de agrupamento — isola o caso especial da
// "faixaVencimento" (não é um campo fixo, depende da data de hoje)
function recebChaveDimensaoValor(o, dimKey, hoje){
  if(dimKey === 'faixaVencimento'){ const f = RECEB_FAIXAS_VENCIMENTO.find(f=>f.teste(o,hoje)); return f ? f.nome : ''; }
  const dim = RECEB_DIMENSOES[dimKey];
  return dim ? dim.chave(o) : '';
}
function recebRotuloDimensaoValor(chave, dimKey){
  if(dimKey === 'faixaVencimento') return chave;
  const dim = RECEB_DIMENSOES[dimKey];
  return dim ? dim.fmtLabel(chave) : chave;
}
// agrupa por 1 a 3 níveis de dimensão de uma vez — "colunas" pode
// misturar medidas (agregadas com recebCalcularMedida) e campos crus (o
// valor da 1ª nota do grupo, já que um campo de nota não tem como ser
// "somado" — útil pra ver, por exemplo, um dado complementar daquele
// grupo junto com as medidas) — usado pela tabela personalizada "agrupado"
function recebAgruparMultiplasDimensoes(linhas, dimensoesChaves, colunas){
  const hoje = recebHoje();
  const grupos = {};
  linhas.forEach(o=>{
    const chaves = dimensoesChaves.map(d=>recebChaveDimensaoValor(o, d, hoje));
    const chaveComposta = chaves.join('␟');
    if(!grupos[chaveComposta]) grupos[chaveComposta] = { chaves, itens:[] };
    grupos[chaveComposta].itens.push(o);
  });
  const resultado = Object.values(grupos).map(g=>({
    chaves: g.chaves,
    rotulos: g.chaves.map((k,i)=>recebRotuloDimensaoValor(k, dimensoesChaves[i])),
    valores: Object.fromEntries(colunas.map(c=>[c, RECEB_MEDIDAS[c] ? recebCalcularMedida(g.itens, c) : recebValorColunaNota(g.itens[0], hoje, c)])),
  }));
  const dim0 = RECEB_DIMENSOES[dimensoesChaves[0]];
  const ordenarPorChave = dimensoesChaves[0]!=='faixaVencimento' && dim0 && dim0.ordenar==='chave';
  const primeiraMedida = colunas.find(c=>RECEB_MEDIDAS[c]);
  resultado.sort((a,b)=>{
    let d = ordenarPorChave ? String(a.chaves[0]).localeCompare(String(b.chaves[0])) : (primeiraMedida ? (b.valores[primeiraMedida]||0)-(a.valores[primeiraMedida]||0) : 0);
    if(d) return d;
    for(let i=1;i<a.chaves.length;i++){ d = String(a.chaves[i]).localeCompare(String(b.chaves[i])); if(d) return d; }
    return 0;
  });
  return resultado;
}
// valores distintos de uma coluna, em cima de TODAS as linhas carregadas
// (recebLinhas, não as já filtradas) — usada pra popular o seletor "Valor"
// do filtro fixo do widget, na hora de configurar o widget
function recebValoresDistintosColuna(campo){
  if(!campo) return [];
  const hoje = recebHoje();
  return [...new Set(recebLinhas.map(o=>recebValorColunaNota(o, hoje, campo)))]
    .filter(v=>v!=='' && v!=null).sort((a,b)=>String(a).localeCompare(String(b),'pt',{numeric:true}));
}
// monta os chips do filtro rápido (um widget Tabela só) em cima das
// linhas-base (antes da busca e do próprio filtro rápido, senão o valor
// escolhido sumiria da lista assim que fosse aplicado)
function recebRenderOpcoesFiltroRapido(widget, itensBase){
  const cont = document.getElementById(`receb-${widget.id}-filtrorapido`);
  if(!cont) return;
  const hoje = recebHoje();
  const valores = [...new Set(itensBase.map(o=>recebValorColunaNota(o, hoje, widget.filtroRapido)))]
    .filter(v=>v!=='' && v!=null).sort((a,b)=>String(a).localeCompare(String(b),'pt',{numeric:true}));
  const atual = recebFiltroRapidoPorWidget[widget.id] || 'todas';
  cont.innerHTML = `<div class="chip ${atual==='todas'?'on':''}" data-wfiltrorapido="todas" data-wid="${widget.id}">Todas</div>` +
    valores.map(v=>`<div class="chip ${atual===v?'on':''}" data-wfiltrorapido="${escaparHtml(v)}" data-wid="${widget.id}">${escaparHtml(v)}</div>`).join('');
}
function recebRenderWidgetTabelaPersonalizada(widget, linhas){
  const tab = document.getElementById(`receb-${widget.id}-tabela`); if(!tab) return;
  const colunas = (widget.colunas && widget.colunas.length) ? widget.colunas : RECEB_COLUNAS_NOTAS_PADRAO;
  // filtro fixo do widget — restrição permanente (ex: só o cliente X),
  // configurada na criação do widget, nunca mexe no filtro geral do
  // painel nem no filtro rápido (chips); vale pras duas fontes (notas e
  // agrupado), por isso aplicado ANTES de qualquer uma das duas
  if(widget.filtroFixoCampo && widget.filtroFixoValor){
    const hojeFixo = recebHoje();
    linhas = linhas.filter(o=>recebValorColunaNota(o, hojeFixo, widget.filtroFixoCampo)===widget.filtroFixoValor);
  }
  if(widget.fonte === 'agrupado'){
    const catalogoCampos = recebColunasTabelaDisponiveis();
    const dimensoes = [widget.dimensao, widget.dimensao2, widget.dimensao3].filter(Boolean);
    const grupos = recebAgruparMultiplasDimensoes(linhas, dimensoes, colunas);
    const cabDim = dimensoes.map(d=>RECEB_DIMENSOES_TODAS[d] || d);
    const cab = [...cabDim, ...colunas.map(c=>(RECEB_MEDIDAS[c]||{}).label || catalogoCampos[c] || c)];
    const corpo = grupos.map(g=>{
      // célula de dimensão clicável filtra só por ELA (campo+valor daquela
      // coluna), não pela linha inteira — evita ambiguidade quando a tabela
      // agrupa por mais de uma dimensão (2º/3º nível); faixaVencimento fica
      // de fora (ver recebDimensaoFiltravel)
      const celulasDimHtml = g.rotulos.map((v,i)=>{
        const campo = dimensoes[i];
        const atributos = recebDimensaoFiltravel(campo) ? ` style="cursor:pointer;" data-tcampo="${escaparHtml(campo)}" data-tvalor="${escaparHtml(g.chaves[i])}" title="Filtrar por ${escaparHtml(String(v))}"` : '';
        return `<td${ehNumAlinhavel(v)?' class="num"':''}${atributos}>${escaparHtml(String(v))}</td>`;
      }).join('');
      const celulasValHtml = colunas.map(c=>{
        const ehMedida = !!RECEB_MEDIDAS[c];
        const html = ehMedida ? recebFormatarMedida(g.valores[c], c) : String(g.valores[c]);
        const numerico = ehMedida ? true : ehNumAlinhavel(g.valores[c]);
        return `<td${numerico?' class="num"':''}>${escaparHtml(html)}</td>`;
      }).join('');
      return `<tr>${celulasDimHtml}${celulasValHtml}</tr>`;
    }).join('');
    tab.innerHTML = `<thead><tr>${cab.map(c=>`<th>${escaparHtml(c)}</th>`).join('')}</tr></thead>
      <tbody>${corpo || `<tr><td colspan="${cab.length}" class="empty">${recebLinhas.length ? 'Nenhum grupo com esses filtros.' : 'Sem dados — atualize do RM primeiro.'}</td></tr>`}</tbody>`;
    tab.querySelectorAll('tbody [data-tcampo]').forEach(td=>{
      td.addEventListener('click', ()=>recebToggleFiltro(td.dataset.tcampo, td.dataset.tvalor));
    });
    return;
  }
  // fonte 'notas' — uma linha por nota, com busca própria do widget
  const hoje = recebHoje();
  const catalogo = recebColunasTabelaDisponiveis();
  const buscaEl = document.querySelector(`[data-wbusca][data-wid="${widget.id}"]`);
  const busca = (buscaEl?.value || '').trim().toLowerCase();
  let itens = widget.apenasAbertas ? linhas.filter(o=>o.saldo>0) : linhas.slice();
  // filtro rápido (chips) — SÓ desse widget, nunca mexe no filtro geral do
  // painel; os chips são montados em cima das linhas de ANTES desse filtro
  // (recebRenderOpcoesFiltroRapido), senão o valor escolhido sumiria da
  // lista de opções assim que fosse aplicado
  if(widget.filtroRapido){
    recebRenderOpcoesFiltroRapido(widget, itens);
    const seg = recebFiltroRapidoPorWidget[widget.id];
    if(seg && seg!=='todas') itens = itens.filter(o=>recebValorColunaNota(o,hoje,widget.filtroRapido)===seg);
  }
  if(busca) itens = itens.filter(o=>[o.nf,o.c,o.k,o.u,o.g].join(' ').toLowerCase().includes(busca));
  itens.sort((a,b)=>(a.v??9e9)-(b.v??9e9));
  recebUltimaListaAbertas[widget.id] = itens;
  const cab = colunas.map(c=>catalogo[c]||c);
  const corpo = itens.map(o=>`<tr>${colunas.map(c=>`<td${recebColunaEhNumerica(o,c)?' class="num"':''}>${escaparHtml(String(recebValorColunaNota(o,hoje,c)))}</td>`).join('')}</tr>`).join('');
  // rodapé com o total de cada coluna numérica (dinheiro ganha fmtMoeda,
  // inteiro só separador de milhar) — a 1ª coluna sempre mostra a
  // quantidade de notas, nunca um total, mesmo que seja numérica
  const totais = colunas.map((c,i)=>{
    if(i===0) return `<td><b>${itens.length} nota${itens.length===1?'':'s'}</b></td>`;
    const vals = itens.map(o=>recebValorColunaNotaNumerico(o,c)).filter(v=>v!=null);
    return vals.length ? `<td class="num"><b>${recebFormatarTotalColunaNota(c, vals.reduce((s,v)=>s+v,0))}</b></td>` : '<td></td>';
  }).join('');
  tab.innerHTML = `<thead><tr>${cab.map(c=>`<th>${escaparHtml(c)}</th>`).join('')}</tr></thead>
    <tbody>${corpo || `<tr><td colspan="${cab.length}" class="empty">${recebLinhas.length ? 'Nenhuma nota com esses filtros.' : 'Sem dados — atualize do RM primeiro.'}</td></tr>`}</tbody>
    ${itens.length ? `<tfoot><tr>${totais}</tr></tfoot>` : ''}`;
}
async function recebCopiarAbertas(widgetId){
  const hoje = recebHoje();
  const lista = recebUltimaListaAbertas[widgetId] || [];
  const linhasTxt = [['STATUS','VENCIMENTO','Dias','NOTA FISCAL','CLIENTE','PREFEITURA','CONTRATO','TOTAL NF','RECEBIDO','Saldo'].join('\t'),
    ...lista.map(o=>[RECEB_PILL_TXT[o.situacao]||o.situacao, recebFmtDia(o.v), o.v==null?'':o.v-hoje, o.nf, o.g, o.u, o.k, o.t.toFixed(2).replace('.',','), (o.r||0).toFixed(2).replace('.',','), o.saldo.toFixed(2).replace('.',',')].join('\t'))];
  try{ await navigator.clipboard.writeText(linhasTxt.join('\n')); toast(`${lista.length} notas copiadas. Cole direto no Excel.`); }
  catch(e){ toast('O navegador bloqueou a cópia. Selecione a tabela e copie manualmente.'); }
}

/* ---------- grade configurável (montagem do esqueleto + edição) ---------- */
function recebWidgetTitulo(w){
  if(w.titulo) return w.titulo;
  if(w.tipo==='tabela-abertas') return 'Notas em aberto';
  if(w.tipo==='tabela-contratos') return 'Contratos';
  if(w.tipo==='tabela') return 'Tabela';
  if(w.tipo==='ranking-situacao') return `${RECEB_DIMENSOES_TODAS[w.dimensao] || 'Ranking'} por situação`;
  return (RECEB_MEDIDAS[w.medida]||{}).label || w.medida || '(sem título)';
}
// opções de coluna do formulário "tabela (colunas à sua escolha)" — notas
// usa só o catálogo de campos; agrupado mescla as MEDIDAS (agregadas por
// grupo) com os mesmos CAMPOS de notas (aí o valor mostrado é o da 1ª
// nota do grupo, já que um campo cru não tem como ser "somado")
// opções (chave->label) da última renderização do picker de colunas —
// cacheado só pra recebMoverColuna conseguir re-render a lista de ordem
// sem precisar recalcular tudo de novo
let recebColunasOrdemOpcoes = {};
function recebRenderColunasOrdem(opcoes){
  recebColunasOrdemOpcoes = opcoes;
  const cont = document.getElementById('recebNovoWidgetColunasOrdem');
  if(!cont) return;
  if(!recebFormColunasAtual.length){ cont.innerHTML = ''; return; }
  cont.innerHTML = `<div style="font-size:11px;color:var(--muted);margin-bottom:4px;">Ordem das colunas (use ↑/↓)</div>` +
    recebFormColunasAtual.map((c,i)=>{
      const v = opcoes[c];
      const label = typeof v === 'string' ? v : (v ? v.label : c);
      return `<div style="display:flex;align-items:center;gap:4px;padding:2px 0;">
        <button type="button" data-movercoluna="up" data-coluna="${escaparHtml(c)}" ${i===0?'disabled':''} style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:13px;line-height:1;padding:2px;">↑</button>
        <button type="button" data-movercoluna="down" data-coluna="${escaparHtml(c)}" ${i===recebFormColunasAtual.length-1?'disabled':''} style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:13px;line-height:1;padding:2px;">↓</button>
        <span style="font-size:13px;">${escaparHtml(label)}</span>
      </div>`;
    }).join('');
}
function recebMoverColuna(campo, dir){
  const i = recebFormColunasAtual.indexOf(campo);
  if(i<0) return;
  const j = dir==='up' ? i-1 : i+1;
  if(j<0 || j>=recebFormColunasAtual.length) return;
  [recebFormColunasAtual[i], recebFormColunasAtual[j]] = [recebFormColunasAtual[j], recebFormColunasAtual[i]];
  recebRenderColunasOrdem(recebColunasOrdemOpcoes);
}
function recebRenderColunasPicker(fonte){
  const marcadas = new Set(recebFormColunasAtual);
  const montaItens = opcoes => Object.entries(opcoes).map(([k,v])=>{
    const label = typeof v === 'string' ? v : v.label;
    return `<label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:normal;">
      <input type="checkbox" data-wcoluna value="${k}" ${marcadas.has(k)?'checked':''} style="width:auto;"> ${escaparHtml(label)}
    </label>`;
  }).join('');
  let opcoesCombinadas;
  if(fonte === 'agrupado'){
    const campos = recebColunasTabelaDisponiveis();
    opcoesCombinadas = { ...RECEB_MEDIDAS, ...campos };
    document.getElementById('recebNovoWidgetLabelColunas').textContent = 'Colunas (medidas e campos)';
    document.getElementById('recebNovoWidgetColunasLista').innerHTML =
      `<div style="font-weight:700;font-size:11px;color:var(--muted);margin:2px 0;">MEDIDAS (somadas/calculadas por grupo)</div>${montaItens(RECEB_MEDIDAS)}` +
      `<div style="font-weight:700;font-size:11px;color:var(--muted);margin:10px 0 2px;">CAMPOS (valor da 1ª nota do grupo)</div>${montaItens(campos)}`;
  }else{
    opcoesCombinadas = recebColunasTabelaDisponiveis();
    document.getElementById('recebNovoWidgetLabelColunas').textContent = 'Colunas';
    document.getElementById('recebNovoWidgetColunasLista').innerHTML = montaItens(opcoesCombinadas);
  }
  recebRenderColunasOrdem(opcoesCombinadas);
}
function recebHtmlToolbar(w, i, total){
  if(!recebModoEdicao) return '';
  return `<div class="recebwidget-toolbar">
    <button type="button" data-wtoolbar="up" data-wid="${w.id}" ${i===0?'disabled':''} title="Mover pra cima">↑</button>
    <button type="button" data-wtoolbar="down" data-wid="${w.id}" ${i===total-1?'disabled':''} title="Mover pra baixo">↓</button>
    <button type="button" data-wtoolbar="editar" data-wid="${w.id}" title="Editar">✎</button>
    <button type="button" data-wtoolbar="remover" data-wid="${w.id}" title="Remover">✕</button>
  </div>`;
}
// altura máxima (com rolagem vertical) pras tabelas e pro ranking por
// situação — os gráficos (barra/linha/donut) não usam isso, porque já
// recebem a altura direto no height/size do dashBarChart/dashLineChart/
// dashDonut (ver recebRenderWidgetGrafico)
function recebEstiloAlturaScroll(w){
  const altura = RECEB_ALTURAS_WIDGET[w.altura];
  return altura ? `max-height:${altura}px;overflow-y:auto;` : '';
}
function recebHtmlWidget(w, i, total){
  const toolbar = recebHtmlToolbar(w, i, total);
  const classeEdit = recebModoEdicao ? ' editando' : '';
  const estiloAltura = recebEstiloAlturaScroll(w);
  if(w.tipo === 'tabela-abertas'){
    return `<div class="card recebwidget${classeEdit}" data-wid="${w.id}">${toolbar}
      <h2>${escaparHtml(recebWidgetTitulo(w))}</h2>
      <div class="dash-sub">tudo o que ainda não foi recebido, do vencimento mais antigo pro mais novo</div>
      <div class="filters">
        <div class="chip ${(recebSegPorWidget[w.id]||'todas')==='todas'?'on':''}" data-wseg="todas" data-wid="${w.id}">Todas</div>
        <div class="chip ${recebSegPorWidget[w.id]==='Atrasada'?'on':''}" data-wseg="Atrasada" data-wid="${w.id}">Vencidas</div>
        <div class="chip ${recebSegPorWidget[w.id]==='Próximos dias'?'on':''}" data-wseg="Próximos dias" data-wid="${w.id}">Próximos 7 dias</div>
        <div class="chip ${recebSegPorWidget[w.id]==='A vencer'?'on':''}" data-wseg="A vencer" data-wid="${w.id}">A vencer</div>
      </div>
      <input type="search" data-wbusca data-wid="${w.id}" placeholder="Buscar nota, cliente, contrato ou município" style="margin-bottom:10px;">
      <div style="overflow-x:auto;${estiloAltura}"><table class="valores-table" id="receb-${w.id}-tabela"></table></div>
      <button class="ghost" data-wcopy data-wid="${w.id}" type="button" style="width:auto;margin-top:10px;padding:8px 14px;">Copiar lista</button>
    </div>`;
  }
  if(w.tipo === 'tabela-contratos'){
    return `<div class="card recebwidget${classeEdit}" data-wid="${w.id}">${toolbar}
      <h2>${escaparHtml(recebWidgetTitulo(w))}</h2>
      <div class="dash-sub">ordenados pelo maior faturado no período</div>
      <div style="overflow-x:auto;${estiloAltura}"><table class="valores-table" id="receb-${w.id}-tabela"></table></div>
    </div>`;
  }
  if(w.tipo === 'tabela'){
    const buscaHtml = w.fonte !== 'agrupado' ? `<input type="search" data-wbusca data-wid="${w.id}" placeholder="Buscar nota, cliente, contrato ou município" style="margin-bottom:10px;">` : '';
    const filtroRapidoHtml = (w.fonte !== 'agrupado' && w.filtroRapido) ? `<div class="filters" id="receb-${w.id}-filtrorapido"></div>` : '';
    return `<div class="card recebwidget${classeEdit}" data-wid="${w.id}">${toolbar}
      <h2>${escaparHtml(recebWidgetTitulo(w))}</h2>
      ${filtroRapidoHtml}
      ${buscaHtml}
      <div style="overflow-x:auto;${estiloAltura}"><table class="valores-table" id="receb-${w.id}-tabela"></table></div>
    </div>`;
  }
  if(w.tipo === 'kpi'){
    return `<div class="recebwidget${classeEdit}" data-wid="${w.id}">${toolbar}<div id="receb-${w.id}-conteudo"></div></div>`;
  }
  if(w.tipo === 'ranking-situacao'){
    return `<div class="card recebwidget${classeEdit}" data-wid="${w.id}">${toolbar}
      <h2>${escaparHtml(recebWidgetTitulo(w))}</h2>
      <div class="dash-legend" style="margin:2px 0 10px;">${dashLegendHtml([{label:'Recebido',cor:dashCss('--ok')},{label:'Vencido',cor:dashCss('--bad')},{label:'A vencer',cor:dashCss('--warn')}])}</div>
      <div id="receb-${w.id}-conteudo" style="${estiloAltura}"></div>
    </div>`;
  }
  // barra-h (ranking) ignora o "height" do dashBarChart — a altura dele
  // sempre nasce do número de linhas, então "Altura" vira um teto com
  // rolagem no lugar de um tamanho fixo (igual a tabela); os outros
  // (barra/linha/donut) já recebem a altura certinha no gráfico, então
  // nem precisam do wrapper
  const estiloAlturaRanking = w.tipo==='barra-h' ? estiloAltura : '';
  return `<div class="card recebwidget${classeEdit}" data-wid="${w.id}"${w.tipo==='linha'?' style="overflow-x:auto;"':''}>${toolbar}
    <h2>${escaparHtml(recebWidgetTitulo(w))}</h2>
    <div id="receb-${w.id}-conteudo" style="margin-top:8px;${estiloAlturaRanking}"></div>
  </div>`;
}
// largura de cada widget (exceto kpi, que sempre fica dentro do .summary
// de sempre) — flex-basis em %; combinado com flex-wrap no
// #recebGradeWidgets, dois widgets "metade" seguidos ficam lado a lado
// a largura precisa descontar o gap (14px) entre widgets da mesma linha,
// senão "50% + 50% + gap" ultrapassa a largura do contêiner e o 2º
// widget quebra pra linha de baixo em vez de ficar do lado do 1º
const RECEB_LARGURAS_WIDGET = {
  completa: '100%',
  metade: 'calc(50% - 7px)',
  terco: 'calc(33.3334% - 9.3334px)',
};
// altura de gráficos (passada direto pro dashBarChart/dashLineChart/
// dashDonut) e, pra tabela, a altura máxima da área com rolagem —
// "padrao" não força nada, cada tipo de gráfico usa o próprio tamanho
// de sempre (180px, ou 140 de "size" no donut)
const RECEB_ALTURAS_WIDGET = { padrao: null, baixa: 140, alta: 320, enorme: 450 };
function recebRenderEsqueleto(){
  const grade = document.getElementById('recebGradeWidgets');
  const ws = recebPainelWidgets;
  let html = '', i = 0;
  while(i < ws.length){
    if(ws[i].tipo === 'kpi'){
      let j = i, grupoHtml = '';
      while(j < ws.length && ws[j].tipo === 'kpi'){ grupoHtml += recebHtmlWidget(ws[j], j, ws.length); j++; }
      html += `<div style="flex:1 1 100%;min-width:0;"><div class="summary">${grupoHtml}</div></div>`;
      i = j;
    }else{
      // flex-grow 0 é de propósito: um widget "metade"/"terço" sozinho
      // na linha (sem outro do lado) precisa manter a largura configurada
      // e deixar o resto da linha vazio, em vez de esticar pra 100% —
      // senão "metade" fica visualmente idêntico a "completa" quando é
      // o único widget daquele tamanho ali
      const largura = RECEB_LARGURAS_WIDGET[ws[i].largura] || RECEB_LARGURAS_WIDGET.completa;
      html += `<div style="flex:0 1 ${largura};min-width:280px;">${recebHtmlWidget(ws[i], i, ws.length)}</div>`;
      i++;
    }
  }
  grade.innerHTML = html || `<div class="empty">Nenhum widget no painel ainda. Clique em "⚙ Configurar painel" pra adicionar.</div>`;
}
function recebRenderConteudo(linhas){
  recebUltimoLinhasFiltradas = linhas;
  recebPainelWidgets.forEach(w=>{
    if(w.tipo==='kpi') recebRenderWidgetKpi(`receb-${w.id}-conteudo`, w, linhas);
    else if(w.tipo==='tabela-abertas') recebRenderWidgetAbertas(w, linhas);
    else if(w.tipo==='tabela-contratos') recebRenderWidgetContratos(w, linhas);
    else if(w.tipo==='tabela') recebRenderWidgetTabelaPersonalizada(w, linhas);
    else if(w.tipo==='ranking-situacao') recebRenderWidgetRankingSituacao(`receb-${w.id}-conteudo`, w, linhas);
    else recebRenderWidgetGrafico(`receb-${w.id}-conteudo`, w, linhas, w.tipo);
  });
}
function recebRender(){
  const temDados = recebLinhas.length > 0;
  document.getElementById('recebCardGradeTopo').style.display = temDados ? '' : 'none';
  document.getElementById('recebCardFiltros').style.display = temDados ? '' : 'none';
  document.getElementById('btnRecebExportarExcel').style.display = temDados ? '' : 'none';
  document.getElementById('btnRecebExportarCsv').style.display = temDados ? '' : 'none';
  document.getElementById('recebBaseInfo').textContent = temDados
    ? `${recebInfo.nomeRelatorio} · ${recebLinhas.length} linha${recebLinhas.length===1?'':'s'}.`
    : 'Nenhum dado ainda. Escolha um cliente e clique em "Atualizar do RM".';
  const recebUltimaAtualizacaoEl = document.getElementById('recebUltimaAtualizacao');
  recebUltimaAtualizacaoEl.style.display = temDados ? '' : 'none';
  if(temDados) recebUltimaAtualizacaoEl.querySelector('span').textContent = new Date(recebInfo.quando).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'});
  if(!temDados){ document.getElementById('recebGradeWidgets').innerHTML = ''; return; }
  recebRenderFiltros();
  recebRenderEsqueleto();
  const hoje = recebHoje();
  const linhas = recebFiltrados().map(o=>({ ...o, situacao: recebSit(o, hoje) }));
  linhas.forEach(o=>{ o.saldo = (o.situacao==='Recebida'||o.situacao==='Cancelada') ? 0 : recebSaldo(o); });
  recebRenderConteudo(linhas);
}
// o RM às vezes devolve um campo numérico como TEXTO (ex: "74111.24"
// em vez do número 74111.24) — o Excel brasileiro não reconhece ponto
// como separador decimal, então a célula vira texto alinhado à
// esquerda em vez de número alinhado à direita. Aqui a gente converte
// esses casos pro tipo number de verdade, SEM mexer em código com zero
// à esquerda (NOTA FISCAL, protocolo...), onde o zero é significativo
// e não pode sumir
function recebCoagirNumeroExcel(v){
  if(typeof v !== 'string') return v;
  const s = v.trim();
  if(!/^-?\d+(\.\d+)?$/.test(s)) return v;
  if(/^0\d/.test(s)) return v; // "000003482" etc — mantém como texto
  const n = Number(s);
  return isNaN(n) ? v : n;
}
// exporta a consulta atual (já com os filtros aplicados) pro Excel — TODAS
// as colunas que a consulta do RM devolveu de verdade (não só as que o
// painel usa), com o nome e o valor exatos de cada uma, na ordem em que
// aparecerem. "Saldo" vai no fim por ser calculado aqui, sem equivalente
// na consulta
// monta cabeçalho + linhas cruas (array de arrays) a partir dos filtros
// ativos — reaproveitado pelo Exportar Excel e pelo Exportar CSV, já que
// os dois exportam exatamente as mesmas colunas/linhas, só muda o formato
// do arquivo
function recebMontarLinhasExportacao(){
  const hoje = recebHoje();
  const linhas = recebFiltrados().map(o=>{
    const situacao = recebSit(o, hoje);
    return { ...o, situacao, saldo: (situacao==='Recebida'||situacao==='Cancelada') ? 0 : recebSaldo(o) };
  });
  if(linhas.length === 0) return null;
  const colunasRm = [];
  const vistas = new Set();
  linhas.forEach(o=>{
    Object.keys(o._rm || {}).forEach(k=>{ if(!vistas.has(k)){ vistas.add(k); colunasRm.push(k); } });
  });
  const cabecalho = [...colunasRm, 'Saldo'];
  const corpo = linhas.map(o=>[...colunasRm.map(k=>{ const v = o._rm ? o._rm[k] : undefined; return v==null ? '' : v; }), Number(o.saldo.toFixed(2))]);
  return { cabecalho, corpo, totalLinhas: linhas.length };
}
async function recebExportarExcel(){
  const r = recebMontarLinhasExportacao();
  if(!r){ toast('Nada pra exportar com esses filtros.'); return; }
  const corpoTipado = r.corpo.map(linha => linha.map(v => typeof v === 'string' ? recebCoagirNumeroExcel(v) : v));
  const livro = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(livro, XLSX.utils.aoa_to_sheet([r.cabecalho, ...corpoTipado]), 'Recebíveis');
  await salvarWorkbook(livro, `painel-recebiveis-${hojeLocalISO()}.xlsx`);
  toast(`Excel exportado com ${r.totalLinhas} linha${r.totalLinhas===1?'':'s'} e ${r.cabecalho.length} colunas.`);
}
// cada célula vira texto puro — "," no lugar de ";" (senão quebraria a
// coluna) e sem quebra de linha interna; separador de arquivo é ";"
// (igual o resto do app já faz nos outros "Exportar CSV"), já que a
// vírgula aqui é só um caractere de texto, não separador decimal
function recebCelulaCsv(v){
  if(v == null || v === '') return '';
  return String(v).replace(/;/g, ',').replace(/[\r\n]+/g, ' ');
}
// alternativa ao Exportar Excel pra consultas muito grandes — o Excel
// trava em 1.048.576 linhas por aba; CSV não tem esse teto
async function recebExportarCsv(){
  const r = recebMontarLinhasExportacao();
  if(!r){ toast('Nada pra exportar com esses filtros.'); return; }
  const csv = [r.cabecalho, ...r.corpo].map(linha => linha.map(recebCelulaCsv).join(';')).join('\r\n');
  const blob = new Blob(['﻿'+csv], { type:'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url; a.download = `painel-recebiveis-${hojeLocalISO()}.csv`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);
  toast(`CSV exportado com ${r.totalLinhas} linha${r.totalLinhas===1?'':'s'} e ${r.cabecalho.length} colunas.`);
}

/* ---------- edição do painel (entrar/sair, salvar, formulário de widget) ---------- */
function recebGerarIdWidget(){ return 'w'+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
function recebAtualizarCamposNovoWidget(){
  const tipo = document.getElementById('recebNovoWidgetTipo').value;
  const ehTabelaPronta = tipo==='tabela-abertas' || tipo==='tabela-contratos';
  const ehTabelaPersonalizada = tipo==='tabela';
  const ehKpi = tipo==='kpi';
  const ehLinha = tipo==='linha';
  const ehRankingSituacao = tipo==='ranking-situacao';
  const fonte = document.getElementById('recebNovoWidgetFonte').value || 'notas';
  // na tabela personalizada não existe campo "Medida" (quem escolhe as
  // medidas é o picker de colunas) e "Agrupar por" só se a fonte é "agrupado";
  // no ranking por situação também não tem medida — a quebra é sempre fixa
  // (Recebido/Vencido/A vencer), só precisa da dimensão de agrupamento
  const precisaMedida = !ehTabelaPronta && !ehTabelaPersonalizada && !ehRankingSituacao;
  const precisaDimensao = !ehTabelaPronta && !ehKpi && (!ehTabelaPersonalizada || fonte==='agrupado');
  // kpi sempre fica dentro do .summary de sempre — não tem "largura" própria
  document.getElementById('recebNovoWidgetCampoLargura').style.display = ehKpi ? 'none' : '';
  document.getElementById('recebNovoWidgetLinhaMedida').style.display = (precisaMedida || precisaDimensao) ? '' : 'none';
  document.getElementById('recebNovoWidgetCampoMedida').style.display = precisaMedida ? '' : 'none';
  document.getElementById('recebNovoWidgetCampoDimensao').style.display = precisaDimensao ? '' : 'none';
  document.getElementById('recebNovoWidgetCampoTop').style.display = (tipo==='barra-h'||tipo==='donut'||tipo==='barra'||ehRankingSituacao) ? '' : 'none';
  document.getElementById('recebNovoWidgetCampoMedidas2').style.display = ehLinha ? '' : 'none';
  document.getElementById('recebNovoWidgetCampoSubtitulo').style.display = ehKpi ? '' : 'none';
  document.getElementById('recebNovoWidgetCampoFonte').style.display = ehTabelaPersonalizada ? '' : 'none';
  document.getElementById('recebNovoWidgetCampoApenasAbertas').style.display = (ehTabelaPersonalizada && fonte==='notas') ? 'flex' : 'none';
  document.getElementById('recebNovoWidgetCampoFiltroRapido').style.display = (ehTabelaPersonalizada && fonte==='notas') ? '' : 'none';
  if(ehTabelaPersonalizada && fonte==='notas'){
    const selFR = document.getElementById('recebNovoWidgetFiltroRapido');
    const atualFR = selFR.value;
    selFR.innerHTML = `<option value="">(nenhum)</option>` + Object.entries(recebColunasTabelaDisponiveis()).map(([k,v])=>`<option value="${k}">${escaparHtml(typeof v==='string'?v:v.label)}</option>`).join('');
    if([...selFR.options].some(o=>o.value===atualFR)) selFR.value = atualFR;
  }
  document.getElementById('recebNovoWidgetCampoColunas').style.display = ehTabelaPersonalizada ? '' : 'none';
  document.getElementById('recebNovoWidgetCampoGrafico').style.display = (tipo==='barra'||tipo==='barra-h'||tipo==='linha'||tipo==='donut') ? '' : 'none';
  // filtro fixo do widget — vale pras duas fontes da tabela (notas e
  // agrupado), diferente do filtro rápido (chips), que só faz sentido
  // linha a linha
  document.getElementById('recebNovoWidgetLinhaFiltroFixo').style.display = ehTabelaPersonalizada ? '' : 'none';
  if(ehTabelaPersonalizada){
    const selFF = document.getElementById('recebNovoWidgetFiltroFixoCampo');
    const atualFF = selFF.value;
    selFF.innerHTML = `<option value="">(nenhum)</option>` + Object.entries(recebColunasTabelaDisponiveis()).map(([k,v])=>`<option value="${k}">${escaparHtml(typeof v==='string'?v:v.label)}</option>`).join('');
    if([...selFF.options].some(o=>o.value===atualFF)) selFF.value = atualFF;
    recebAtualizarFiltroFixoValor();
  }
  recebPopularSelectsMedidaWidget();
  const dimSel = document.getElementById('recebNovoWidgetDimensao');
  if(!dimSel.options.length) dimSel.innerHTML = Object.entries(RECEB_DIMENSOES_TODAS).map(([k,v])=>`<option value="${k}">${escaparHtml(v)}</option>`).join('');
  const multi = ehTabelaPersonalizada && fonte==='agrupado';
  document.getElementById('recebNovoWidgetCampoDimensao2').style.display = multi ? '' : 'none';
  document.getElementById('recebNovoWidgetCampoDimensao3').style.display = multi ? '' : 'none';
  if(multi){
    const dim2Sel = document.getElementById('recebNovoWidgetDimensao2'), dim3Sel = document.getElementById('recebNovoWidgetDimensao3');
    const opcoesExtra = `<option value="">(nenhum)</option>` + Object.entries(RECEB_DIMENSOES_TODAS).map(([k,v])=>`<option value="${k}">${escaparHtml(v)}</option>`).join('');
    if(!dim2Sel.options.length) dim2Sel.innerHTML = opcoesExtra;
    if(!dim3Sel.options.length) dim3Sel.innerHTML = opcoesExtra;
  }
  if(ehTabelaPersonalizada) recebRenderColunasPicker(fonte);
}
// mostra/popula o seletor "Valor" do filtro fixo, em cima do campo
// escolhido no select ao lado — chamado ao trocar de tipo/campo
function recebAtualizarFiltroFixoValor(){
  const campo = document.getElementById('recebNovoWidgetFiltroFixoCampo').value;
  const campoValor = document.getElementById('recebNovoWidgetCampoFiltroFixoValor');
  const selValor = document.getElementById('recebNovoWidgetFiltroFixoValor');
  campoValor.style.display = campo ? '' : 'none';
  if(!campo) return;
  const atual = selValor.value;
  const valores = recebValoresDistintosColuna(campo);
  selValor.innerHTML = valores.map(v=>`<option value="${escaparHtml(v)}">${escaparHtml(v)}</option>`).join('') || `<option value="">(sem valores carregados)</option>`;
  if(valores.includes(atual)) selValor.value = atual;
}
// repopula os <select> de medida do formulário de widget preservando o
// valor marcado — chamado tanto ao trocar de tipo quanto sempre que o
// catálogo de medidas muda (medida nova/editada/removida em "Medidas")
function recebPopularSelectsMedidaWidget(){
  const medidaSel = document.getElementById('recebNovoWidgetMedida');
  if(medidaSel){
    const atual = medidaSel.value;
    medidaSel.innerHTML = Object.entries(RECEB_MEDIDAS).map(([k,v])=>`<option value="${k}">${escaparHtml(v.label)}</option>`).join('');
    if([...medidaSel.options].some(o=>o.value===atual)) medidaSel.value = atual;
  }
  const medida2Sel = document.getElementById('recebNovoWidgetMedida2');
  if(medida2Sel){
    const atual2 = medida2Sel.value;
    medida2Sel.innerHTML = `<option value="">(nenhuma)</option>` + Object.entries(RECEB_MEDIDAS).map(([k,v])=>`<option value="${k}">${escaparHtml(v.label)}</option>`).join('');
    if([...medida2Sel.options].some(o=>o.value===atual2)) medida2Sel.value = atual2;
  }
}
function recebResetFormNovoWidget(){
  recebEditandoWidgetId = null;
  document.getElementById('recebNovoWidgetTipo').disabled = false;
  document.getElementById('recebNovoWidgetTipo').value = 'kpi';
  document.getElementById('recebNovoWidgetTitulo').value = '';
  document.getElementById('recebNovoWidgetTop').value = '';
  document.getElementById('recebNovoWidgetFonte').value = 'notas';
  document.getElementById('recebNovoWidgetApenasAbertas').checked = false;
  document.getElementById('recebNovoWidgetFiltroRapido').value = '';
  document.getElementById('recebNovoWidgetFiltroFixoCampo').value = '';
  document.getElementById('recebNovoWidgetFiltroFixoValor').innerHTML = '';
  recebFormColunasAtual = [];
  document.getElementById('recebNovoWidgetLegenda').checked = false;
  document.getElementById('recebNovoWidgetRotulos').checked = false;
  document.getElementById('recebNovoWidgetLargura').value = 'completa';
  document.getElementById('recebNovoWidgetAltura').value = 'padrao';
  document.getElementById('recebNovoWidgetMostrarSubtitulo').checked = true;
  document.getElementById('recebNovoWidgetSubtitulo').value = '';
  recebAtualizarCamposNovoWidget();
  document.getElementById('recebNovoWidgetMedida').value = 'faturado';
  document.getElementById('recebNovoWidgetMedida2').value = '';
  document.getElementById('recebNovoWidgetDimensao').value = 'mes';
  document.getElementById('recebNovoWidgetDimensao2').value = '';
  document.getElementById('recebNovoWidgetDimensao3').value = '';
  document.getElementById('btnRecebAdicionarWidget').textContent = 'Adicionar ao painel';
}
function recebWidgetMover(id, dir){
  const i = recebPainelWidgets.findIndex(w=>w.id===id);
  if(i<0) return;
  const j = dir==='up' ? i-1 : i+1;
  if(j<0 || j>=recebPainelWidgets.length) return;
  [recebPainelWidgets[i], recebPainelWidgets[j]] = [recebPainelWidgets[j], recebPainelWidgets[i]];
  recebRender();
}
function recebWidgetRemover(id){
  recebPainelWidgets = recebPainelWidgets.filter(w=>w.id!==id);
  if(recebEditandoWidgetId===id) recebResetFormNovoWidget();
  recebRender();
}
function recebWidgetEditar(id){
  const w = recebPainelWidgets.find(x=>x.id===id);
  if(!w) return;
  recebEditandoWidgetId = id;
  document.getElementById('recebNovoWidgetTipo').value = w.tipo;
  document.getElementById('recebNovoWidgetTipo').disabled = true; // trocar o tipo de um widget existente é mais simples remover e criar outro
  document.getElementById('recebNovoWidgetFonte').value = w.fonte || 'notas';
  document.getElementById('recebNovoWidgetApenasAbertas').checked = !!w.apenasAbertas;
  recebFormColunasAtual = w.colunas ? w.colunas.slice() : [];
  document.getElementById('recebNovoWidgetLargura').value = w.largura || 'completa';
  document.getElementById('recebNovoWidgetAltura').value = w.altura || 'padrao';
  recebAtualizarCamposNovoWidget();
  document.getElementById('recebNovoWidgetFiltroRapido').value = w.filtroRapido || '';
  document.getElementById('recebNovoWidgetFiltroFixoCampo').value = w.filtroFixoCampo || '';
  recebAtualizarFiltroFixoValor();
  document.getElementById('recebNovoWidgetFiltroFixoValor').value = w.filtroFixoValor || '';
  document.getElementById('recebNovoWidgetTitulo').value = w.titulo || '';
  document.getElementById('recebNovoWidgetMedida').value = w.medida || 'faturado';
  document.getElementById('recebNovoWidgetDimensao').value = w.dimensao || 'mes';
  document.getElementById('recebNovoWidgetDimensao2').value = w.dimensao2 || '';
  document.getElementById('recebNovoWidgetDimensao3').value = w.dimensao3 || '';
  document.getElementById('recebNovoWidgetTop').value = w.top || '';
  document.getElementById('recebNovoWidgetMedida2').value = w.medida2 || '';
  document.getElementById('recebNovoWidgetLegenda').checked = !!w.mostrarLegenda;
  document.getElementById('recebNovoWidgetRotulos').checked = !!w.mostrarRotulos;
  document.getElementById('recebNovoWidgetMostrarSubtitulo').checked = w.mostrarSubtitulo !== false;
  document.getElementById('recebNovoWidgetSubtitulo').value = w.subtitulo || '';
  document.getElementById('btnRecebAdicionarWidget').textContent = 'Salvar alterações no widget';
  document.getElementById('recebCardAddWidget').scrollIntoView({ behavior:'smooth', block:'center' });
}

/* ---------- Medidas (criar/editar o catálogo de medidas do painel) ---------- */
function recebGerarIdMedida(){ return 'medida'+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
function recebLabelCampoMedida(campo){
  if(RECEB_CAMPOS_MEDIDA_BUILTIN[campo]) return RECEB_CAMPOS_MEDIDA_BUILTIN[campo];
  if(campo && campo.startsWith('rm:')) return campo.slice(3);
  return campo || '';
}
const RECEB_FUNCOES_MEDIDA = { soma:'Soma', media:'Média', contagem:'Contagem', contagemDistinta:'Contagem distinta', min:'Mínimo', max:'Máximo', percentualDoTotal:'% do total geral' };
function recebLabelFuncaoMedida(funcao){ return RECEB_FUNCOES_MEDIDA[funcao] || funcao || ''; }
function recebRenderListaMedidas(){
  const cont = document.getElementById('recebListaMedidas');
  if(!cont) return;
  cont.innerHTML = Object.entries(RECEB_MEDIDAS).map(([id,def])=>{
    const souSistema = !!RECEB_MEDIDAS_PADRAO[id];
    const detalhe = def.campo ? ` · ${escaparHtml(recebLabelCampoMedida(def.campo))} · ${escaparHtml(recebLabelFuncaoMedida(def.funcao))}` : (def.funcao==='contagem' ? ` · ${escaparHtml(recebLabelFuncaoMedida(def.funcao))}` : '');
    const casas = Number.isInteger(def.casas) ? def.casas : (def.fmt==='pct' ? 1 : 0);
    const detalheFormato = def.fmt==='money' ? '' : ` · ${casas>0 ? casas+' casa'+(casas>1?'s':'')+' decimal'+(casas>1?'is':'') : 'inteiro'}`;
    return `<div class="row" style="align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--line);">
      <div style="flex:1;"><b>${escaparHtml(def.label)}</b><span style="font-size:11px;color:var(--muted);margin-left:6px;">${souSistema ? 'sistema' : 'personalizada'}${detalhe}${detalheFormato}</span></div>
      <button class="ghost" type="button" data-editarmedida="${escaparHtml(id)}" style="width:auto;padding:4px 10px;">Editar</button>
      ${souSistema ? '' : `<button class="ghost" type="button" data-removermedida="${escaparHtml(id)}" style="width:auto;padding:4px 10px;color:var(--bad);">Remover</button>`}
    </div>`;
  }).join('');
}
function recebPopularSelectCampoMedida(){
  const sel = document.getElementById('recebMedidaCampo');
  if(!sel) return;
  const atual = sel.value;
  sel.innerHTML = recebCamposMedidaDisponiveis().map(o=>`<option value="${escaparHtml(o.campo)}">${escaparHtml(o.label)}</option>`).join('');
  if([...sel.options].some(o=>o.value===atual)) sel.value = atual;
}
function recebAtualizarCamposFormMedida(){
  const souSistema = recebEditandoMedidaId && !!RECEB_MEDIDAS_PADRAO[recebEditandoMedidaId];
  const funcao = document.getElementById('recebMedidaFuncao').value;
  const formato = document.getElementById('recebMedidaFormato').value;
  const tipoNumero = document.getElementById('recebMedidaTipoNumero').value;
  document.getElementById('recebMedidaCampoFuncao').style.display = souSistema ? 'none' : '';
  document.getElementById('recebMedidaCampoFuncaoCampo').style.display = (souSistema || funcao==='contagem') ? 'none' : '';
  document.getElementById('recebMedidaLinhaCasas').style.display = formato!=='money' ? 'flex' : 'none';
  document.getElementById('recebMedidaCampoCasas').style.display = (formato!=='money' && tipoNumero==='decimal') ? '' : 'none';
}
function recebResetFormMedida(){
  recebEditandoMedidaId = null;
  const nomeEl = document.getElementById('recebMedidaNome'); if(!nomeEl) return;
  nomeEl.value = '';
  document.getElementById('recebMedidaFuncao').value = 'soma';
  document.getElementById('recebMedidaFormato').value = 'money';
  document.getElementById('recebMedidaTipoNumero').value = 'inteiro';
  document.getElementById('recebMedidaCasas').value = '2';
  recebPopularSelectCampoMedida();
  recebAtualizarCamposFormMedida();
  document.getElementById('btnRecebAdicionarMedida').textContent = 'Adicionar medida';
}
function recebEditarMedida(id){
  const def = RECEB_MEDIDAS[id]; if(!def) return;
  recebEditandoMedidaId = id;
  document.getElementById('recebMedidaNome').value = def.label || '';
  document.getElementById('recebMedidaFormato').value = def.fmt || 'money';
  recebPopularSelectCampoMedida();
  document.getElementById('recebMedidaFuncao').value = def.funcao || 'soma';
  const casasAtuais = Number.isInteger(def.casas) ? def.casas : (def.fmt==='pct' ? 1 : 0);
  document.getElementById('recebMedidaTipoNumero').value = casasAtuais>0 ? 'decimal' : 'inteiro';
  document.getElementById('recebMedidaCasas').value = casasAtuais>0 ? casasAtuais : 2;
  recebAtualizarCamposFormMedida();
  if(def.campo) document.getElementById('recebMedidaCampo').value = def.campo;
  document.getElementById('btnRecebAdicionarMedida').textContent = 'Salvar alterações na medida';
  document.getElementById('recebCardMedidas').scrollIntoView({ behavior:'smooth', block:'center' });
}
function recebRemoverMedida(id){
  if(RECEB_MEDIDAS_PADRAO[id]) return; // nunca remove uma medida de sistema
  recebPainelMedidas = recebPainelMedidas.filter(m=>m.id!==id);
  recebReconstruirCatalogoMedidas();
  if(recebEditandoMedidaId===id) recebResetFormMedida();
  recebRenderListaMedidas();
  recebPopularSelectsMedidaWidget();
  recebRender();
}
function recebEntrarModoEdicao(){
  const conta = contaAtual();
  const perm = permissaoMenu(conta, 'relatoriosgerenciaisrm.painelrecebiveis');
  if(!ehAdminEfetivo(conta) && perm && !perm.editar){ toast('Seu perfil só tem acesso de visualização nesse painel.'); return; }
  recebModoEdicao = true;
  document.getElementById('btnRecebEditarPainel').style.display = 'none';
  document.getElementById('btnRecebSalvarPainel').style.display = '';
  document.getElementById('btnRecebCancelarEdicaoPainel').style.display = '';
  document.getElementById('recebCardAddWidget').style.display = '';
  document.getElementById('recebLinhaAddFiltro').style.display = 'flex';
  document.getElementById('recebCardMedidas').style.display = '';
  recebPopularSelectNovoFiltro();
  recebResetFormNovoWidget();
  recebResetFormMedida();
  recebRenderListaMedidas();
  recebRender();
}
function recebSairModoEdicao(){
  recebModoEdicao = false;
  document.getElementById('btnRecebEditarPainel').style.display = '';
  document.getElementById('btnRecebSalvarPainel').style.display = 'none';
  document.getElementById('btnRecebCancelarEdicaoPainel').style.display = 'none';
  document.getElementById('recebCardAddWidget').style.display = 'none';
  document.getElementById('recebLinhaAddFiltro').style.display = 'none';
  document.getElementById('recebCardMedidas').style.display = 'none';
  recebResetFormNovoWidget();
  recebResetFormMedida();
}
function recebCancelarEdicaoPainel(){
  recebPainelWidgets = JSON.parse(JSON.stringify(recebPainelWidgetsSalvos));
  recebPainelFiltros = JSON.parse(JSON.stringify(recebPainelFiltrosSalvos));
  recebFiltros = Object.fromEntries(recebPainelFiltros.map(f=>[f.campo, recebFiltros[f.campo] || new Set()]));
  recebPainelMedidas = JSON.parse(JSON.stringify(recebPainelMedidasSalvos));
  recebReconstruirCatalogoMedidas();
  recebSairModoEdicao();
  recebRender();
}
async function recebSalvarPainel(){
  const r = await api('salvarRmPainelLayout', { contaId: contaAtual().id, slug:'painel-recebiveis', widgets: recebPainelWidgets, filtros: recebPainelFiltros, medidas: recebPainelMedidas });
  if(!r.ok){ toast(r.erro || 'Não foi possível salvar o layout.'); return; }
  recebPainelWidgetsSalvos = JSON.parse(JSON.stringify(recebPainelWidgets));
  recebPainelFiltrosSalvos = JSON.parse(JSON.stringify(recebPainelFiltros));
  recebPainelMedidasSalvos = JSON.parse(JSON.stringify(recebPainelMedidas));
  const idx = rmPainelLayouts.findIndex(p=>p.slug==='painel-recebiveis');
  if(idx>=0){ rmPainelLayouts[idx].widgets = recebPainelWidgetsSalvos; rmPainelLayouts[idx].filtros = recebPainelFiltrosSalvos; rmPainelLayouts[idx].medidas = recebPainelMedidasSalvos; }
  else rmPainelLayouts.push({ slug:'painel-recebiveis', widgets:recebPainelWidgetsSalvos, filtros:recebPainelFiltrosSalvos, medidas:recebPainelMedidasSalvos });
  recebSairModoEdicao();
  recebRender();
  toast('Layout do painel salvo.');
}

/* =========================================================
   Painel GENÉRICO (configurável, qualquer Consulta SQL) —
   mesmo motor de widgets/medidas/filtros do Painel de Recebíveis, mas sem
   NENHUM conhecimento fixo de campo (vencimento, situação, cliente...): um
   "campo" aqui é sempre uma coluna crua, do jeito que a consulta do RM
   devolveu. Cada painel genérico fica guardado em rm_paineis (nome +
   lista de Consultas SQL vinculadas, uma por cliente) e sua grade de
   widgets em rm_painel_layouts, chaveada pelo slug do painel.
   ========================================================= */
// acha, entre as consultas vinculadas a um painel, a que pertence a um
// cliente (combinação singular) — usado pelo Painel de Recebíveis, que
// assume 1 consulta por cliente (ver recebClientesDisponiveis/
// recebAtualizarDoRm). O painel GENÉRICO usa a versão plural logo abaixo
// (pnlConsultasDoCliente), porque agora um cliente pode ter várias
// consultas diferentes vinculadas ao mesmo painel (ex: Vendas + Compras)
function pnlConsultaIdParaCliente(painel, clienteId){
  const vinculadas = new Set((painel && painel.consultas || []).map(String));
  const r = rmRelatoriosGerenciais.find(x=>vinculadas.has(String(x.id)) && String(x.clienteId)===String(clienteId));
  return r ? r.id : null;
}
// TODAS as consultas vinculadas ao painel que pertencem a esse cliente —
// usado pelo painel genérico pra buscar/combinar N consultas do mesmo
// cliente (cada widget/medida depois escolhe de qual delas usar os dados)
function pnlConsultasDoCliente(painel, clienteId){
  const vinculadas = new Set((painel && painel.consultas || []).map(String));
  return rmRelatoriosGerenciais.filter(r=>vinculadas.has(String(r.id)) && String(r.clienteId)===String(clienteId));
}
function pnlClientesDoPainel(painel){
  const vinculadas = new Set((painel && painel.consultas || []).map(String));
  const clienteIds = new Set(rmRelatoriosGerenciais.filter(r=>vinculadas.has(String(r.id)) && r.clienteId).map(r=>String(r.clienteId)));
  return clientes.filter(c=>clienteIds.has(String(c.id)));
}

let pnlClienteId = '';
// linhas CRUAS de CADA consulta carregada, uma chave por consultaId — a
// chave de cada coluna dentro de uma linha é o nome exato que a sentença
// RM devolveu. pnlConsultasCarregadas guarda {id,nome} na ordem em que
// foram buscadas, pra popular os seletores "Consulta" dos formulários
let pnlDadosPorConsulta = {};
let pnlConsultasCarregadas = [];
let pnlInfo = null;
let pnlCarregando = false;
let pnlPainelFiltros = [];
let pnlPainelFiltrosSalvos = [];
let pnlFiltros = {};
let pnlFiltroColunaAberta = null;
let pnlFormColunasAtual = [];
// apelidos (nomes customizados) das colunas do Detalhe/Tabela — {campo: texto}
let pnlFormColunasApelidos = {};
// formato forçado por coluna do Detalhe/Tabela — {campo: 'texto'|'numero'|'moeda'}
// (sem entrada = automático: só mostra casas decimais quando o valor cru já
// vem com elas, que é a causa do "924" aparecer sem ",00" ao lado de um
// "2.761,92" na mesma coluna — um número cru não carrega metadado de que é
// um valor financeiro, diferente de uma Medida que tem fmt:'money')
let pnlFormColunasFormatos = {};
let pnlFormMedidasExtrasAtual = [];
// links configurados no form (fonte 'linhas') pra puxar campos de OUTRAS
// consultas numa tabela não-agrupada — {consultaId, campoPrincipal, campoLink}
let pnlFormLinksAtual = [];
// subdetalhes já adicionados no form do widget "relatorio" — cada um
// {titulo, consultaId, campoPrincipal, campoLink, colunas}
let pnlFormSubdetalhesAtual = [];
let pnlEditandoSubdetalheIndex = null;
// colunas marcadas no picker do subdetalhe que ainda está sendo montado
// (antes de clicar em "+ Adicionar subdetalhe")
let pnlFormSubdetalheColunasAtual = [];
// apelidos das colunas do subdetalhe que ainda está sendo montado — {campo: texto}
let pnlFormSubdetalheColunasApelidos = {};
// critérios de ordenação do Detalhe do widget "relatorio" — [{campo,direcao}]
let pnlFormOrdenacaoAtual = [];
// critérios de ordenação e colunas a somar do subdetalhe que ainda está
// sendo montado (antes de clicar em "+ Adicionar subdetalhe")
let pnlFormSubdetalheOrdenacaoAtual = [];
let pnlFormSubdetalheTotaisAtual = [];
// guias já adicionadas no form do widget "container" (antes de salvar)
let pnlFormGuiasContainerAtual = [];
// guia ativa (selecionada na tela) de cada container, por id do widget —
// só estado visual, não é salvo no painel
let pnlContainerGuiaAtiva = {};
let pnlPainelWidgets = [];
let pnlPainelWidgetsSalvos = [];
let pnlPainelMedidas = [];
let pnlPainelMedidasSalvos = [];
let pnlEditandoMedidaId = null;
let pnlSlugCarregado = null; // qual slug de painel já está carregado em pnlPainelWidgets/Filtros/Medidas — muda ao abrir um painel diferente
let pnlModoEdicao = false;
let pnlEditandoWidgetId = null;
// "Canvas livre" (posição/tamanho livres por widget, em pixels) — só pra
// telas largas; no celular o painel sempre usa a grade de hoje (largura em
// frações + ordem da lista), que já reflui sozinha. Ver pnlRenderEsqueleto.
let pnlModoCanvas = false;
let pnlCanvasArrastando = null; // {id, startMouseX, startMouseY, startX, startY}
let pnlCanvasRedimensionando = null; // {id, startMouseX, startMouseY, startW, startH}
// última lista de linhas (já filtrada) de cada widget — por id do widget,
// já que agora cada widget pode vir de uma consulta/filtro diferente
let pnlUltimoLinhasFiltradasPorWidget = {};
// filtro rápido (chips clicáveis) de um widget Tabela — só desse widget,
// nunca mexe no filtro geral do painel. 'todas' (ou ausente) = sem filtro.
let pnlFiltroRapidoPorWidget = {};
// ordenação "ao vivo" do Detalhe do widget Relatório, por clique no
// cabeçalho — por id do widget; NÃO é salva no painel (reseta ao
// atualizar do RM), diferente da ordenação configurada no cadastro do
// widget. Enquanto ativa, desliga a quebra/subtotal (que depende da
// ordenação configurada) e mostra só o total geral no rodapé.
let pnlOrdenacaoRuntimePorWidget = {};
// coluna "pega" (mousedown, ainda sem soltar) pra reordenar arrastando o
// cabeçalho do Detalhe — só funciona em modo de edição do painel; guarda
// {widgetId, campo} do cabeçalho de origem
let pnlRelatDragOrigem = null;
// primeira consulta carregada — usado como "consulta padrão" de um widget
// que ainda não tem consultaId salvo (widget criado antes dessa função
// existir, ou painel com 1 consulta só, onde não faz sentido perguntar)
function pnlConsultaPadrao(){ return pnlConsultasCarregadas[0] ? pnlConsultasCarregadas[0].id : null; }
// uma consulta "tem" um campo se ALGUMA linha dela tiver essa chave — varre
// todas as linhas (não só a primeira) porque o RM às vezes omite um campo
// nulo numa linha específica (mesmo caso do recebNormalizar)
function pnlConsultaTemCampo(consultaId, campo){
  const linhas = pnlDadosPorConsulta[consultaId];
  return !!linhas && linhas.some(o=>campo in o);
}

// mesma regra seguar do Painel de Recebíveis: converte string numérica
// (ex "74111.24") pro tipo number de verdade, sem mexer em código com
// zero à esquerda (NOTA FISCAL, protocolo...)
function pnlCoagirNumero(v){
  if(typeof v === 'number') return v;
  if(typeof v !== 'string') return v;
  const s = v.trim();
  if(!/^-?\d+(\.\d+)?$/.test(s)) return v;
  if(/^0\d/.test(s)) return v;
  const n = Number(s);
  return isNaN(n) ? v : n;
}
// usado pra decidir alinhamento (números à direita) em qualquer tabela
// do painel — true só quando o valor CRU (antes de formatar) é numérico
function ehNumAlinhavel(v){
  return typeof pnlCoagirNumero(v) === 'number';
}
// ordena um array de itens por 1+ critérios {campo, direcao}, aplicados em
// ordem (o 1º critério manda, os seguintes só desempatam) — valorFn(item,
// campo) extrai o valor cru de cada item (usada tanto pro Detalhe quanto
// pros Subdetalhes do widget "relatorio", cada um com sua própria extração)
function pnlCompararValorOrdenacao(a, b){
  const na = pnlCoagirNumero(a), nb = pnlCoagirNumero(b);
  if(typeof na === 'number' && typeof nb === 'number') return na - nb;
  return String(a ?? '').localeCompare(String(b ?? ''), 'pt', {numeric:true, sensitivity:'base'});
}
function pnlOrdenarPorCriterios(itens, criterios, valorFn){
  if(!criterios || !criterios.length) return itens;
  const copia = itens.slice();
  copia.sort((a,b)=>{
    for(const cr of criterios){
      const cmp = pnlCompararValorOrdenacao(valorFn(a, cr.campo), valorFn(b, cr.campo)) * (cr.direcao==='desc' ? -1 : 1);
      if(cmp !== 0) return cmp;
    }
    return 0;
  });
  return copia;
}
function pnlNum(v){
  const n = pnlCoagirNumero(v);
  if(typeof n === 'number') return n;
  if(v==null || v==='') return 0;
  const p = parseFloat(String(v).replace(/[^\d,.\-]/g,'').replace(',','.'));
  return isNaN(p) ? 0 : p;
}
// todas as colunas de UMA consulta carregada (descobertas varrendo TODAS
// as linhas — o RM às vezes omite uma coluna numa linha quando ela vem
// nula)
function pnlColunasDisponiveis(consultaId){
  const linhas = pnlDadosPorConsulta[consultaId] || [];
  const vistas = new Set(), colunas = [];
  linhas.forEach(o=>{ Object.keys(o||{}).forEach(k=>{ if(!vistas.has(k)){ vistas.add(k); colunas.push(k); } }); });
  return colunas;
}
function pnlValorFiltro(o, campo){ const v = o[campo]; return v==null ? '' : String(v); }
/* ---------- "filtro fixo" de widget (campo+operador+valor, além do filtro geral do painel) ---------- */
