const PNL_OPERADORES_FILTRO_FIXO = { '=':'Igual a (=)', '<>':'Diferente de (≠)', '>':'Maior que (>)', '<':'Menor que (<)', '>=':'Maior ou igual (≥)', '<=':'Menor ou igual (≤)', 'NULL':'Vazio (NULL)', 'NOTNULL':'Não vazio (NOT NULL)', 'ULTIMOSMESES':'Nos últimos N meses (valor = N)', 'MESESANTERIORES':'Nos N meses anteriores a esses (valor = N)' };
function pnlValorEhVazio(v){ return v===null || v===undefined || v===''; }
// extrai um "índice de mês" (ano*12+mês, sempre crescente) de uma data em
// qualquer formato comum nesse app: "YYYY-MM", "YYYY-MM-DDT..." (ISO),
// "DD/MM/YYYY" ou "MM/YYYY" — usado pelos operadores de janela móvel
// (ULTIMOSMESES/MESESANTERIORES); formato não reconhecido = null (linha
// nunca passa no filtro, mais seguro que incluir por engano)
function pnlIndiceMes(v){
  const s = String(v||'').trim();
  let m;
  if((m = s.match(/^(\d{4})-(\d{2})/))) return Number(m[1])*12 + Number(m[2]);
  if((m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/))) return Number(m[3])*12 + Number(m[2]);
  if((m = s.match(/^(\d{2})\/(\d{4})$/))) return Number(m[2])*12 + Number(m[1]);
  return null;
}
function pnlMesAtualIndice(){ const h = new Date(); return h.getFullYear()*12 + (h.getMonth()+1); }
// compara UMA linha contra o filtro fixo de um widget — >,<,>=,<= reusam a
// mesma coerção numérica/texto já usada na ordenação (pnlCompararValorOrdenacao),
// então funciona tanto pra número quanto (melhor esforço) pra texto/data
function pnlLinhaPassaFiltroFixo(o, campo, operador, valor){
  const v = o[campo];
  switch(operador){
    case 'NULL': return pnlValorEhVazio(v);
    case 'NOTNULL': return !pnlValorEhVazio(v);
    case '<>': return pnlValorFiltro(o, campo) !== valor;
    case '>': return pnlCompararValorOrdenacao(v, valor) > 0;
    case '<': return pnlCompararValorOrdenacao(v, valor) < 0;
    case '>=': return pnlCompararValorOrdenacao(v, valor) >= 0;
    case '<=': return pnlCompararValorOrdenacao(v, valor) <= 0;
    case 'ULTIMOSMESES': {
      const idx = pnlIndiceMes(v); if(idx===null) return false;
      const n = parseInt(valor, 10) || 1;
      const fim = pnlMesAtualIndice(), ini = fim - (n-1);
      return idx>=ini && idx<=fim;
    }
    case 'MESESANTERIORES': {
      const idx = pnlIndiceMes(v); if(idx===null) return false;
      const n = parseInt(valor, 10) || 1;
      const fimJanelaAtual = pnlMesAtualIndice(), iniJanelaAtual = fimJanelaAtual - (n-1);
      const fim = iniJanelaAtual - 1, ini = fim - (n-1);
      return idx>=ini && idx<=fim;
    }
    default: return pnlValorFiltro(o, campo) === valor; // '='
  }
}
// aplica o filtro fixo de um widget (se configurado) num array de linhas —
// NULL/NOT NULL não precisam de valor; os demais operadores, sem valor
// escolhido ainda, o filtro fica desligado (widget se comporta como se não
// tivesse filtro fixo nenhum), igual já era o comportamento de sempre
function pnlAplicarFiltroFixo(linhas, widget){
  if(!widget || !widget.filtroFixoCampo) return linhas;
  const operador = widget.filtroFixoOperador || '=';
  if(operador!=='NULL' && operador!=='NOTNULL' && !widget.filtroFixoValor) return linhas;
  return linhas.filter(o=>pnlLinhaPassaFiltroFixo(o, widget.filtroFixoCampo, operador, widget.filtroFixoValor));
}
// catálogo do seletor "Campo a filtrar" do widget Filtro — lista TODOS os
// campos disponíveis, mesmo os que já são filtro geral de outro widget (dois
// widgets Filtro podem apontar pro mesmo campo, já que os dois só são uma
// posição no canvas pro MESMO estado pnlPainelFiltros/pnlFiltros)
function pnlCamposParaWidgetFiltro(){
  const todasColunas = new Set();
  pnlConsultasCarregadas.forEach(c=>pnlColunasDisponiveis(c.id).forEach(col=>todasColunas.add(col)));
  return [...todasColunas].sort((a,b)=>a.localeCompare(b,'pt',{numeric:true}));
}
// catálogo do seletor "Campo a filtrar" do widget Filtro — diferente de
// pnlCamposFiltroDisponiveis, NÃO exclui campos já configurados como
// filtro geral (o widget pode ser só uma posição extra no canvas pra um
// filtro que já existe), já que widget.campo referencia o MESMO estado
// (pnlFiltros/pnlPainelFiltros) usado pela grade "Filtros" do topo
function pnlCamposParaWidgetFiltro(){
  const todasColunas = new Set();
  pnlConsultasCarregadas.forEach(c=>pnlColunasDisponiveis(c.id).forEach(col=>todasColunas.add(col)));
  return [...todasColunas].sort((a,b)=>a.localeCompare(b,'pt',{numeric:true}));
}
// linhas de UMA consulta, já filtradas pelos filtros gerais do painel —
// um filtro só se aplica se a coluna dele EXISTIR nessa consulta (mesmo
// nome de campo pode filtrar Vendas e Compras ao mesmo tempo, se as duas
// tiverem a coluna; se só uma tiver, o filtro não afeta a outra)
function pnlFiltrados(consultaId){
  const linhas = pnlDadosPorConsulta[consultaId] || [];
  return linhas.filter(o=>pnlPainelFiltros.every(f=>{
    if(!pnlConsultaTemCampo(consultaId, f.campo)) return true;
    const set = pnlFiltros[f.campo];
    return !set || set.size===0 || set.has(pnlValorFiltro(o, f.campo));
  }));
}
// linhas restritas por TODOS os outros filtros já marcados, menos o
// próprio campo — usada só pra montar as OPÇÕES do dropdown de um filtro;
// varre TODAS as consultas carregadas que têm essa coluna (pra listar
// valores vindos de qualquer uma delas) e cruza com os outros filtros
// aplicáveis em CADA consulta
function pnlLinhasParaOpcoes(campoExcluir){
  let linhas = [];
  pnlConsultasCarregadas.forEach(c=>{
    if(!pnlConsultaTemCampo(c.id, campoExcluir)) return;
    const base = pnlDadosPorConsulta[c.id] || [];
    linhas = linhas.concat(base.filter(o=>pnlPainelFiltros.every(f=>{
      if(f.campo === campoExcluir) return true;
      if(!pnlConsultaTemCampo(c.id, f.campo)) return true;
      const set = pnlFiltros[f.campo];
      return !set || set.size===0 || set.has(pnlValorFiltro(o, f.campo));
    })));
  });
  return linhas;
}

/* ---------- medidas (sempre campo+função — não existe medida "de sistema" num painel genérico) ---------- */
function pnlGerarIdMedida(){ return 'medida'+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
// campo cru usado DIRETO como "medida" de um widget (KPI/gráfico), sem
// precisar cadastrar uma Medida antes — codificado como "#consultaId::campo"
// (mesma ideia do campo linkado, prefixo diferente pra nunca colidir com
// id de medida de verdade, que é gerado por pnlGerarIdWidget). Função
// sempre soma — pra outras agregações, ainda cadastra uma Medida normal.
function pnlEhCampoCruMedida(c){ return typeof c === 'string' && c.charAt(0)==='#' && c.includes('::'); }
function pnlCodificarCampoCruMedida(consultaId, campo){ return `#${consultaId}::${campo}`; }
function pnlParseCampoCruMedida(c){ const i = c.indexOf('::'); return { consultaId: c.slice(1, i), campo: c.slice(i+2) }; }
function pnlMedidaPorId(id){
  const def = pnlPainelMedidas.find(m=>m.id===id);
  if(def) return def;
  if(pnlEhCampoCruMedida(id)){
    const { consultaId, campo } = pnlParseCampoCruMedida(id);
    return { id, label: campo, consultaId, campo, funcao: 'soma' };
  }
  return undefined;
}
const RECEB_FUNCOES_MEDIDA_REF = { soma:'Soma', media:'Média', contagem:'Contagem', contagemDistinta:'Contagem distinta', min:'Mínimo', max:'Máximo', ultimoValor:'Último valor', percentualDoTotal:'% do total geral' };
function pnlLabelFuncaoMedida(funcao){ return RECEB_FUNCOES_MEDIDA_REF[funcao] || funcao || ''; }
function pnlCalcularMedida(linhas, medidaId){
  const def = pnlMedidaPorId(medidaId);
  if(!def) return 0;
  if(def.funcao === 'contagem') return linhas.length;
  if(def.funcao === 'contagemDistinta'){
    const vistos = new Set();
    linhas.forEach(o=>{ const v = o[def.campo]; if(v!=null && v!=='') vistos.add(String(v)); });
    return vistos.size;
  }
  const vals = linhas.map(o=>pnlNum(o[def.campo]));
  switch(def.funcao){
    case 'soma': return vals.reduce((s,v)=>s+v,0);
    case 'media': return vals.length ? vals.reduce((s,v)=>s+v,0)/vals.length : 0;
    case 'min': return vals.length ? Math.min(...vals) : 0;
    case 'max': return vals.length ? Math.max(...vals) : 0;
    // valor do campo na linha "mais recente" do grupo, segundo o campo de
    // ordem escolhido (ex: DATA) — nunca passa por pnlLinhasConsultaNoContexto
    // de propósito, já recebe "linhas" já escopado ao grupo/contexto certo
    case 'ultimoValor': {
      if(!linhas.length) return def.fmt==='data' ? '' : 0;
      const ordenadas = linhas.slice().sort((a,b)=>pnlCompararValorOrdenacao(a[def.campoOrdem], b[def.campoOrdem]));
      const bruto = ordenadas[ordenadas.length-1][def.campo];
      // formato "Data" mostra o valor cru (ex: "13/10/2026"), sem forçar
      // pra número — útil quando o próprio CAMPO é uma data, não um valor
      return def.fmt==='data' ? bruto : pnlNum(bruto);
    }
    case 'percentualDoTotal': {
      const todasLinhas = pnlDadosPorConsulta[def.consultaId] || linhas;
      const totalGeral = todasLinhas.reduce((s,o)=>s+pnlNum(o[def.campo]),0);
      const soma = vals.reduce((s,v)=>s+v,0);
      return totalGeral ? soma/totalGeral : 0;
    }
    default: return 0;
  }
}
// tokeniza uma fórmula de medida: números, operadores + - * /, parênteses
// e referências [idDaMedida]
function pnlTokenizarFormulaMedida(formula){
  const tokens = [];
  const re = /\s*(?:(\[[a-zA-Z0-9_]+\])|(\d+(?:\.\d+)?)|([+\-*/()]))\s*/y;
  let i = 0;
  while(i < formula.length){
    re.lastIndex = i;
    const m = re.exec(formula);
    if(!m || m.index !== i) throw new Error('formula invalida');
    if(m[1]) tokens.push({ tipo:'ref', valor: m[1].slice(1,-1) });
    else if(m[2]) tokens.push({ tipo:'num', valor: Number(m[2]) });
    else if(m[3]) tokens.push({ tipo:'op', valor: m[3] });
    i = re.lastIndex;
  }
  return tokens;
}
// avalia a fórmula com um parser recursivo (sem eval/Function — só
// +, -, *, /, parênteses, números e [id] resolvido por "resolverRef")
function pnlAvaliarFormulaMedida(formula, resolverRef){
  let tokens;
  try { tokens = pnlTokenizarFormulaMedida(formula || ''); } catch(e){ return 0; }
  let pos = 0;
  const pico = () => tokens[pos];
  function expr(){
    let v = termo();
    while(pico() && pico().tipo==='op' && (pico().valor==='+'||pico().valor==='-')){
      const op = tokens[pos++].valor;
      const d = termo();
      v = op==='+' ? v+d : v-d;
    }
    return v;
  }
  function termo(){
    let v = fator();
    while(pico() && pico().tipo==='op' && (pico().valor==='*'||pico().valor==='/')){
      const op = tokens[pos++].valor;
      const d = fator();
      v = op==='*' ? v*d : (d ? v/d : 0);
    }
    return v;
  }
  function fator(){
    const t = pico();
    if(!t) return 0;
    if(t.tipo==='op' && t.valor==='-'){ pos++; return -fator(); }
    if(t.tipo==='op' && t.valor==='('){ pos++; const v = expr(); if(pico() && pico().valor===')') pos++; return v; }
    if(t.tipo==='num'){ pos++; return t.valor; }
    if(t.tipo==='ref'){ pos++; return resolverRef(t.valor); }
    pos++; return 0;
  }
  try { return expr(); } catch(e){ return 0; }
}
// detecta ciclo (direto ou indireto) entre fórmulas: a nova fórmula de
// "id" não pode, direta ou indiretamente, acabar referenciando "id" de
// volta — isso travaria pnlValorMedida num loop (a "pilha" ali já
// protege contra travar de verdade, mas aqui dá pra avisar na hora)
function pnlFormulaReferenciaCiclo(id, formula){
  const vistos = new Set([id]);
  function expandir(f){
    const refs = [...String(f||'').matchAll(/\[([a-zA-Z0-9_]+)\]/g)].map(m=>m[1]);
    for(const r of refs){
      if(vistos.has(r)) return true;
      vistos.add(r);
      const def = pnlMedidaPorId(r);
      if(def && def.formula && expandir(def.formula)) return true;
    }
    return false;
  }
  return expandir(formula);
}
// troca os [id] da fórmula pelo rótulo da medida, só pra exibição
function pnlFormulaParaExibicao(formula){
  return String(formula||'').replace(/\[([a-zA-Z0-9_]+)\]/g, (m, id) => {
    const def = pnlMedidaPorId(id);
    return def ? def.label : '?';
  });
}
// linhas de UMA consulta, já com os filtros gerais aplicados e, se houver
// um "grupo" ativo (agrupamento por 1-3 campos, usado nas tabelas
// agrupadas e nos gráficos por dimensão), também filtradas por esses
// campos — null quando essa consulta não tem algum desses campos (não dá
// pra saber quais das linhas dela pertencem a esse grupo, então ela
// simplesmente não contribui com esse grupo)
function pnlLinhasConsultaNoContexto(consultaId, grupo){
  let linhas = pnlFiltrados(consultaId);
  if(!grupo) return linhas;
  for(let i=0;i<grupo.campos.length;i++){
    const campo = grupo.campos[i];
    if(!pnlConsultaTemCampo(consultaId, campo)) return null;
    const valor = grupo.valores[i];
    linhas = linhas.filter(o=>pnlValorFiltro(o, campo)===valor);
  }
  return linhas;
}
/* ---------- campos "linkados" (de outra consulta, puxados por uma chave de ligação) ----------
   codificados como "@consultaId::campo" dentro do array widget.colunas, pra
   não colidir com nome de coluna normal (coluna real nunca começa com "@") */
function pnlEhCampoLinkado(c){ return typeof c === 'string' && c.charAt(0)==='@' && c.includes('::'); }
function pnlCodificarCampoLinkado(consultaId, campo){ return `@${consultaId}::${campo}`; }
function pnlParseCampoLinkado(c){ const i = c.indexOf('::'); return { consultaId: c.slice(1, i), campo: c.slice(i+2) }; }
function pnlNomeConsulta(consultaId){ return (pnlConsultasCarregadas.find(c=>c.id===consultaId)||{}).nome || consultaId; }
// pseudo-id de "coluna calculada a partir de um Subdetalhe" — soma de um
// campo (ou contagem de itens) dos filhos daquele Subdetalhe, escopados
// ao registro pai (igual pnlAgruparSubdetalhe); referencia o Subdetalhe
// pelo ID ESTÁVEL dele (não pela posição no array), pra não quebrar se
// outro Subdetalhe for removido/reordenado
function pnlGerarIdSubdetalhe(){ return 'sd'+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
function pnlEhCampoSubdetalhe(c){ return typeof c === 'string' && c.charAt(0)==='%' && /::(soma|contagem)$/.test(c); }
function pnlCodificarCampoSubdetalhe(subId, campo, funcao){ return `%${subId}::${campo}::${funcao}`; }
function pnlParseCampoSubdetalhe(c){
  const i = c.indexOf('::'), j = c.lastIndexOf('::');
  return { subId: c.slice(1, i), campo: c.slice(i+2, j), funcao: c.slice(j+2) };
}
// rótulo de exibição de QUALQUER coluna (medida, campo linkado, campo
// calculado de subdetalhe ou campo cru da consulta principal) —
// centraliza a lógica usada no cabeçalho da tabela e no picker de Colunas
function pnlLabelColuna(c, catalogoPrincipal, apelidos){
  if(apelidos && apelidos[c]) return apelidos[c];
  const medida = pnlMedidaPorId(c);
  if(medida) return medida.label;
  if(pnlEhCampoLinkado(c)){ const { consultaId, campo } = pnlParseCampoLinkado(c); return `${campo} (${pnlNomeConsulta(consultaId)})`; }
  if(pnlEhCampoSubdetalhe(c)){ const { campo, funcao } = pnlParseCampoSubdetalhe(c); return funcao==='contagem' ? 'Quantidade de itens' : `${campo} (soma)`; }
  return (catalogoPrincipal && catalogoPrincipal[c]) || c;
}
// índice (valor do campo de ligação -> 1ª linha com esse valor) de uma
// consulta linkada — montado 1x por render, não por linha
function pnlIndiceConsultaLinkada(consultaId, campoLink){
  const linhas = pnlDadosPorConsulta[consultaId] || [];
  const indice = {};
  linhas.forEach(o=>{
    const chave = pnlValorFiltro(o, campoLink);
    if(!(chave in indice)) indice[chave] = o;
  });
  return indice;
}
// um índice por link configurado no widget (fonte 'linhas')
function pnlIndicesLinksWidget(widget){
  const porConsulta = {};
  (widget.links||[]).forEach(l=>{
    porConsulta[l.consultaId] = { campoPrincipal: l.campoPrincipal, indice: pnlIndiceConsultaLinkada(l.consultaId, l.campoLink) };
  });
  return porConsulta;
}
// valor cru de uma coluna numa linha da tabela "linhas" — resolve tanto
// campo normal (da consulta principal) quanto campo linkado (de outra
// consulta, via o índice já montado)
function pnlValorColunaLinha(o, c, indicesLinks){
  if(pnlEhCampoLinkado(c)){
    const { consultaId, campo } = pnlParseCampoLinkado(c);
    const linkInfo = indicesLinks[consultaId];
    if(!linkInfo) return '';
    const linhaLinkada = linkInfo.indice[pnlValorFiltro(o, linkInfo.campoPrincipal)];
    return linhaLinkada ? linhaLinkada[campo] : '';
  }
  return o[c];
}
// valor cru de um campo linkado numa tabela AGRUPADA — a "ligação" aqui
// já é o(s) próprio(s) campo(s) de "Agrupar por" (mesma lógica das
// medidas cruzando consulta), sem precisar configurar link nenhum
function pnlValorCampoLinkadoAgrupado(c, camposChaves, valoresChaves){
  const { consultaId, campo } = pnlParseCampoLinkado(c);
  const linhas = pnlLinhasConsultaNoContexto(consultaId, {campos:camposChaves, valores:valoresChaves});
  return (linhas && linhas.length) ? pnlFormatarValorColuna(linhas[0][campo]) : '';
}
// valor de QUALQUER medida (campo+função OU fórmula) num contexto —
// grupo=null é o painel inteiro (KPI), ou {campos,valores} é um grupo
// específico (tabela agrupada / gráficos por dimensão). "pilha" evita
// loop infinito quando fórmulas se referenciam em ciclo
// filtroFixoWidget é o WIDGET (kpi) dono do filtro fixo — usado pra
// restringir a própria medida, aplicado por cima do filtro geral do
// painel, nunca mexe nos outros widgets (ver pnlAplicarFiltroFixo)
function pnlValorMedida(medidaId, grupo, pilha, filtroFixoWidget){
  const def = pnlMedidaPorId(medidaId);
  if(!def) return 0;
  pilha = pilha || new Set();
  if(pilha.has(medidaId)) return 0;
  if(def.formula){
    pilha.add(medidaId);
    const v = pnlAvaliarFormulaMedida(def.formula, id => pnlValorMedida(id, grupo, pilha, filtroFixoWidget));
    pilha.delete(medidaId);
    return v;
  }
  let linhas = pnlLinhasConsultaNoContexto(def.consultaId, grupo);
  if(linhas === null) return 0;
  linhas = pnlAplicarFiltroFixo(linhas, filtroFixoWidget);
  return pnlCalcularMedida(linhas, medidaId);
}
function pnlFormatarMedida(valor, medidaId){
  const def = pnlMedidaPorId(medidaId) || {};
  const fmt = def.fmt;
  if(fmt==='money') return fmtMoeda(valor);
  // valor cru (ex: "13/10/2026"), sem tentar reformatar — o próprio campo
  // escolhido já vem no formato de data do relatório de origem
  if(fmt==='data') return (valor==null || valor==='') ? '' : String(valor);
  const casas = Number.isInteger(def.casas) ? def.casas : (fmt==='pct' ? 1 : 0);
  if(fmt==='pct') return (valor*100).toLocaleString('pt-BR',{minimumFractionDigits:casas,maximumFractionDigits:casas})+'%';
  const numFmt = valor.toLocaleString('pt-BR',{minimumFractionDigits:casas,maximumFractionDigits:casas});
  if(fmt==='dias') return numFmt+' dias';
  return numFmt;
}

/* ---------- agrupamento por campo cru (dimensão genérica) ---------- */
function pnlFormatarValorColuna(v){
  if(v == null || v === '') return '';
  const n = pnlCoagirNumero(v);
  if(typeof n !== 'number') return String(v);
  return Number.isInteger(n) ? n.toLocaleString('pt-BR') : n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
}
function pnlValorColunaNumerico(o, campo){
  const n = pnlCoagirNumero(o[campo]);
  return typeof n === 'number' ? n : null;
}
// formato explícito escolhido no cadastro do widget pra uma coluna — undefined
// (ou qualquer valor fora da lista) cai no comportamento automático de sempre
function pnlFormatoColuna(campo, colunasFormatos){
  const f = (colunasFormatos||{})[campo];
  return (f==='texto' || f==='numero' || f==='moeda') ? f : 'auto';
}
// true = alinha à direita (é número); 'texto' força false mesmo se o valor
// cru parecer numérico, 'numero'/'moeda' forçam true mesmo com string vazia
function pnlColunaEhNumerica(valor, formato){
  if(formato==='texto') return false;
  if(formato==='numero' || formato==='moeda') return true;
  return ehNumAlinhavel(valor);
}
function pnlFormatarValorColunaComFormato(v, formato){
  if(formato==='texto') return (v==null || v==='') ? '' : String(v);
  if(v == null || v === '') return '';
  const n = pnlCoagirNumero(v);
  if(typeof n !== 'number') return String(v);
  if(formato==='numero') return n.toLocaleString('pt-BR',{minimumFractionDigits:0,maximumFractionDigits:0});
  if(formato==='moeda') return n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  return Number.isInteger(n) ? n.toLocaleString('pt-BR') : n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
}
function pnlFormatarTotalColunaComFormato(soma, formato){
  if(formato==='numero') return soma.toLocaleString('pt-BR',{minimumFractionDigits:0,maximumFractionDigits:0});
  if(formato==='moeda') return soma.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  return Number.isInteger(soma) ? soma.toLocaleString('pt-BR') : soma.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
}
function pnlFormatarTotalColuna(soma){
  return Number.isInteger(soma) ? soma.toLocaleString('pt-BR') : soma.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
}
// agrupa por 1 a 3 campos ao mesmo tempo — "colunas" pode misturar medidas
// (agregadas com pnlCalcularMedida) e campos crus (valor da 1ª linha do
// grupo, já que um campo cru não dá pra "somar" direto)
function pnlAgruparMultiplasDimensoes(linhas, camposChaves, colunas){
  const grupos = {};
  linhas.forEach(o=>{
    const chaves = camposChaves.map(c=>pnlValorFiltro(o, c));
    const chaveComposta = chaves.join('␟');
    if(!grupos[chaveComposta]) grupos[chaveComposta] = { chaves, itens:[] };
    grupos[chaveComposta].itens.push(o);
  });
  const resultado = Object.values(grupos).map(g=>({
    chaves: g.chaves,
    rotulos: g.chaves,
    valores: Object.fromEntries(colunas.map(c=>{
      if(pnlMedidaPorId(c)) return [c, pnlValorMedida(c, {campos:camposChaves, valores:g.chaves})];
      if(pnlEhCampoLinkado(c)) return [c, pnlValorCampoLinkadoAgrupado(c, camposChaves, g.chaves)];
      return [c, pnlFormatarValorColuna(g.itens[0][c])];
    })),
  }));
  const primeiraMedida = colunas.find(c=>pnlMedidaPorId(c));
  resultado.sort((a,b)=>{
    let d = primeiraMedida ? (b.valores[primeiraMedida]||0)-(a.valores[primeiraMedida]||0) : String(a.chaves[0]).localeCompare(String(b.chaves[0]),'pt',{numeric:true});
    if(d) return d;
    for(let i=1;i<a.chaves.length;i++){ d = String(a.chaves[i]).localeCompare(String(b.chaves[i]),'pt',{numeric:true}); if(d) return d; }
    return 0;
  });
  return resultado;
}
// igual pnlAgruparMultiplasDimensoes, mas devolve o valor CRU (não já
// formatado em string) nas colunas de campo — usado pelo Detalhe agrupado
// do widget Relatório, que precisa do valor cru pra aplicar o formato por
// coluna (Automático/Texto/Número/Moeda) igual já faz no modo "por
// registro" (campo linkado continua pré-formatado, mesma limitação que já
// existe na Tabela agrupada — caso raro, fora do escopo desse ajuste)
function pnlAgruparColunasCruRelatorio(linhas, camposChaves, colunas){
  const grupos = {};
  linhas.forEach(o=>{
    const chaves = camposChaves.map(c=>pnlValorFiltro(o, c));
    const chaveComposta = chaves.join('␟');
    if(!grupos[chaveComposta]) grupos[chaveComposta] = { chaves, itens:[] };
    grupos[chaveComposta].itens.push(o);
  });
  const resultado = Object.values(grupos).map(g=>{
    const linha = {};
    camposChaves.forEach((c,i)=>{ linha[c] = g.chaves[i]; });
    colunas.forEach(c=>{
      if(pnlMedidaPorId(c)) linha[c] = pnlValorMedida(c, {campos:camposChaves, valores:g.chaves});
      else if(pnlEhCampoLinkado(c)) linha[c] = pnlValorCampoLinkadoAgrupado(c, camposChaves, g.chaves);
      else linha[c] = g.itens[0][c];
    });
    return linha;
  });
  const primeiraMedida = colunas.find(c=>pnlMedidaPorId(c));
  resultado.sort((a,b)=>{
    let d = primeiraMedida ? (b[primeiraMedida]||0)-(a[primeiraMedida]||0) : String(a[camposChaves[0]]).localeCompare(String(b[camposChaves[0]]),'pt',{numeric:true});
    if(d) return d;
    for(let i=1;i<camposChaves.length;i++){ d = String(a[camposChaves[i]]).localeCompare(String(b[camposChaves[i]]),'pt',{numeric:true}); if(d) return d; }
    return 0;
  });
  return resultado;
}
// agrupa os FILHOS de um Subdetalhe (já escopados ao registro pai, via
// campoPrincipal/campoLink) por até 3 campos — diferente do agrupamento
// do Detalhe principal, aqui NÃO entra o sistema de Medida: uma Medida é
// calculada contra a consulta INTEIRA (pnlValorMedida → pnlLinhasConsultaNoContexto),
// sem jeito de restringir só aos filhos desse pai, o que somaria errado
// (ex: todos os itens daquele PRODUTO em TODAS as notas, não só dessa).
// Em vez disso, soma automaticamente qualquer coluna selecionada cujos
// valores sejam todos numéricos dentro do grupo — senão mostra o valor da
// 1ª linha, igual o Tabela/Relatório já fazem com campo cru
function pnlAgruparSubdetalhe(filhos, camposChaves, colunas){
  const grupos = {};
  filhos.forEach(f=>{
    const chaves = camposChaves.map(c=>pnlValorFiltro(f, c));
    const chaveComposta = chaves.join('␟');
    if(!grupos[chaveComposta]) grupos[chaveComposta] = { chaves, itens:[] };
    grupos[chaveComposta].itens.push(f);
  });
  const resultado = Object.values(grupos).map(g=>{
    const linha = {};
    camposChaves.forEach((c,i)=>{ linha[c] = g.chaves[i]; });
    colunas.forEach(c=>{
      const vals = g.itens.map(f=>pnlCoagirNumero(f[c])).filter(v=>typeof v==='number');
      linha[c] = (vals.length && vals.length===g.itens.length) ? vals.reduce((s,v)=>s+v,0) : g.itens[0][c];
    });
    return linha;
  });
  resultado.sort((a,b)=>{
    let d = String(a[camposChaves[0]]).localeCompare(String(b[camposChaves[0]]),'pt',{numeric:true});
    if(d) return d;
    for(let i=1;i<camposChaves.length;i++){ d = String(a[camposChaves[i]]).localeCompare(String(b[camposChaves[i]]),'pt',{numeric:true}); if(d) return d; }
    return 0;
  });
  return resultado;
}
// valor de uma "coluna calculada de subdetalhe" (soma de um campo, ou
// contagem de itens) pro registro "o" do Detalhe — igual pnlAgruparSubdetalhe
// em espírito (nunca passa pelo sistema de Medida, que calcularia contra a
// consulta inteira), só que devolve 1 valor, não agrupado por dimensão
function pnlValorCampoSubdetalhe(o, subId, campo, funcao, subdetalhesResolvidos){
  const sd = (subdetalhesResolvidos||[]).find(s=>s.id===subId);
  if(!sd) return 0;
  const chave = pnlValorFiltro(o, sd.campoPrincipal);
  const filhos = sd.indice[chave] || [];
  if(funcao === 'contagem') return filhos.length;
  return filhos.reduce((s,f)=>s+pnlNum(f[campo]), 0);
}
// agrupa por UM campo só, pra gráficos (barra/linha/donut) — "medida" pode
// ser uma medida de verdade (soma/média/...) ou, sem nenhuma configurada
// ainda, cai em "contar linhas" (sempre existe pelo menos essa leitura)
function pnlAgruparPorCampo(linhas, campo, medidaId){
  const grupos = {};
  linhas.forEach(o=>{ const k = pnlValorFiltro(o, campo); (grupos[k] = grupos[k] || []).push(o); });
  const arr = Object.entries(grupos).map(([k,itens])=>({ chave:k, rotulo:k, valor: medidaId ? pnlValorMedida(medidaId, {campos:[campo], valores:[k]}) : itens.length }));
  arr.sort((a,b)=>b.valor-a.valor);
  return arr;
}
// Curva ABC (Pareto): recebe os grupos já ordenados DESC por valor (ver
// pnlAgruparPorCampo) e calcula o % do total e o % acumulado de cada um,
// classificando em A (acumulado até 80%), B (até 95%) ou C (o resto) —
// mesma regra clássica 80/15/5 do módulo de referência em Python
function pnlClassificarCurvaAbc(grupos){
  const total = grupos.reduce((s,g)=>s+g.valor,0);
  let acumulado = 0;
  return grupos.map(g=>{
    acumulado += g.valor;
    const pctFat = total ? g.valor/total : 0;
    const pctAcum = total ? acumulado/total : 0;
    // pequena tolerância pra ponto flutuante não deixar 80.000000001% virar B à toa
    const classe = pctAcum <= 0.8000001 ? 'A' : (pctAcum <= 0.9500001 ? 'B' : 'C');
    return { ...g, pctFat, pctAcum, classe };
  });
}
function pnlFormatarPct1Casa(fracao){
  return (fracao*100).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})+'%';
}
function pnlRenderWidgetCurvaAbc(containerId, widget, linhas){
  const el = document.getElementById(containerId); if(!el) return;
  const grupos = pnlAgruparPorCampo(linhas, widget.dimensao, widget.medida);
  const classificados = pnlClassificarCurvaAbc(grupos);
  if(!classificados.length){ el.innerHTML = `<div class="dash-empty">Sem dados no período.</div>`; return; }
  const corClasse = { A:'--blue', B:'--purple', C:'--yellow' };
  const porClasse = { A:[], B:[], C:[] };
  classificados.forEach(g=>porClasse[g.classe].push(g));
  const cardsHtml = ['A','B','C'].map(cl=>{
    const itens = porClasse[cl];
    const pctSoma = itens.reduce((s,g)=>s+g.pctFat,0);
    return `<div class="recebwidget"><div class="box"><div class="k">Classe ${cl}</div><div class="v">${itens.length} ${itens.length===1?'item':'itens'}</div><div class="x" style="font-size:11px;color:var(--muted);margin-top:2px;">${pnlFormatarPct1Casa(pctSoma)} do total</div></div></div>`;
  }).join('');
  const labelMedida = (pnlMedidaPorId(widget.medida)||{}).label || widget.medida;
  const topN = widget.top ? Number(widget.top) : 15;
  const linhasTabela = classificados.map(g=>`<tr style="cursor:pointer;" data-abclinha="${escaparHtml(g.chave)}" title="Filtrar por ${escaparHtml(g.rotulo)}">
    <td>${escaparHtml(g.rotulo)}</td>
    <td class="num">${escaparHtml(pnlFormatarMedida(g.valor, widget.medida))}</td>
    <td class="num">${pnlFormatarPct1Casa(g.pctFat)}</td>
    <td class="num">${pnlFormatarPct1Casa(g.pctAcum)}</td>
    <td>${escaparHtml(g.classe)}</td>
  </tr>`).join('');
  el.innerHTML = `
    <div class="summary" style="margin-bottom:10px;">${cardsHtml}</div>
    <p style="color:var(--muted);font-size:11.5px;margin:0 0 10px;">A = itens que somam até 80% do total de "${escaparHtml(labelMedida)}"; B = até 95%; C = o restante.</p>
    <div class="pnl-abc-grafico" style="margin-bottom:14px;"></div>
    <div style="overflow-x:auto;max-height:380px;overflow-y:auto;">
      <table class="valores-table">
        <thead><tr><th>${escaparHtml(widget.dimensao)}</th><th>${escaparHtml(labelMedida)}</th><th>% do total</th><th>% Acumulado</th><th>Classe</th></tr></thead>
        <tbody>${linhasTabela}</tbody>
      </table>
    </div>
  `;
  el.querySelectorAll('tbody [data-abclinha]').forEach(tr=>{
    tr.addEventListener('click', ()=>pnlToggleFiltro(widget.dimensao, tr.dataset.abclinha));
  });
  const classificadosTop = classificados.slice(0, topN);
  const dataBar = classificadosTop.map(g=>({ label:g.rotulo, value:g.valor, tok:corClasse[g.classe] }));
  dashBarChart(el.querySelector('.pnl-abc-grafico'), { data:dataBar, horizontal:true, fmtFn: v=>pnlFormatarMedida(v, widget.medida) });
  // horizontal desenha 2 <rect> por linha (trilho + barra) — mesma
  // convenção de índice ímpar das outras barras horizontais
  const rectsAbc = el.querySelectorAll('.pnl-abc-grafico rect');
  classificadosTop.forEach((g,i)=>{ const bar = rectsAbc[i*2+1]; if(!bar) return; bar.style.cursor='pointer'; bar.addEventListener('click', ()=>pnlToggleFiltro(widget.dimensao, g.chave)); });
}

/* ---------- carregar/abrir o painel ---------- */
function pnlCarregarLayoutPainel(){
  if(!pnlPainelAtual) return;
  const layout = rmPainelLayouts.find(p=>p.slug===pnlPainelAtual.slug);
  pnlPainelWidgets = layout ? JSON.parse(JSON.stringify(layout.widgets||[])) : [];
  pnlPainelWidgetsSalvos = JSON.parse(JSON.stringify(pnlPainelWidgets));
  // cada filtro é {campo, apelido} — ver mesma normalização em
  // recebCarregarLayoutPainel
  pnlPainelFiltros = layout && Array.isArray(layout.filtros)
    ? layout.filtros.map(f=>typeof f==='string' ? {campo:f} : {campo:f.campo, ...(f.apelido?{apelido:f.apelido}:{})})
    : [];
  pnlPainelFiltrosSalvos = JSON.parse(JSON.stringify(pnlPainelFiltros));
  pnlFiltros = Object.fromEntries(pnlPainelFiltros.map(f=>[f.campo, new Set()]));
  pnlPainelMedidas = layout && Array.isArray(layout.medidas) ? JSON.parse(JSON.stringify(layout.medidas)) : [];
  pnlPainelMedidasSalvos = JSON.parse(JSON.stringify(pnlPainelMedidas));
  pnlSlugCarregado = pnlPainelAtual.slug;
}
function pnlAbrir(){
  if(!pnlPainelAtual){ goRgrmSub('paineis'); return; }
  if(pnlSlugCarregado !== pnlPainelAtual.slug){
    pnlModoEdicao = false;
    pnlClienteId = '';
    pnlDadosPorConsulta = {}; pnlConsultasCarregadas = []; pnlInfo = null;
    pnlCarregarLayoutPainel();
  }
  document.getElementById('pnlTitulo').textContent = pnlPainelAtual.nome;
  const conta = contaAtual();
  const souUsuario = conta && conta.perfil === 'USUARIO';
  let disponiveis = pnlClientesDoPainel(pnlPainelAtual);
  if(souUsuario) disponiveis = disponiveis.filter(c=>String(c.id)===String(conta.clienteId));
  const sel = document.getElementById('pnl_cliente');
  sel.disabled = souUsuario;
  sel.innerHTML = disponiveis.length === 0
    ? `<option value="">${souUsuario ? 'Seu cliente ainda não tem esse painel cadastrado' : 'Nenhum cliente vinculado a esse painel'}</option>`
    : disponiveis.map(c=>`<option value="${c.id}">${escaparHtml(c.nome)}${c.rmUrl ? '' : ' (falta configurar a conexão RM)'}</option>`).join('');
  if(disponiveis.length === 0) document.getElementById('pnlStatus').textContent = souUsuario
    ? 'Peça pro administrador vincular a consulta do seu cliente a esse painel, em Relatórios Gerenciais TOTVS RM → Painéis.'
    : 'Vincule uma Consulta SQL a esse painel em Relatórios Gerenciais TOTVS RM → Painéis.';
  else document.getElementById('pnlStatus').textContent = '';
  if(pnlClienteId && disponiveis.some(c=>String(c.id)===String(pnlClienteId))) sel.value = pnlClienteId;
  else pnlClienteId = sel.value || '';
  // painel recém-aberto (ou sessão nova) sem nada em memória ainda — tenta
  // usar o último resultado salvo localmente antes de obrigar o usuário a
  // clicar em "Atualizar do RM" só pra ver o que já tinha
  if(pnlClienteId && !pnlConsultasCarregadas.length) pnlCarregarCache(pnlClienteId);
  const perm = permissaoMenu(conta, 'relatoriosgerenciaisrm.paineis');
  document.getElementById('btnPnlEditarPainel').style.display = (ehAdminEfetivo(conta) || !perm || perm.editar) ? '' : 'none';
  pnlRender();
}
// cache local (localStorage) do último resultado de "Atualizar do RM" por
// painel+cliente — abrir o painel de novo (sessão nova, ou trocar de volta
// pra ele) já mostra o que tinha antes, sem precisar clicar em "Atualizar
// do RM" só pra ver o que já existia; o botão continua lá pra quem quiser
// dados mais recentes de verdade. Puramente no navegador — nunca passa
// pelo Supabase, então não pesa em nada no Egress.
function pnlChaveCache(painelSlug, clienteId){ return `pnlCache::${painelSlug}::${clienteId}`; }
function pnlSalvarCache(){
  if(!pnlPainelAtual || !pnlClienteId || !pnlConsultasCarregadas.length) return;
  try{
    localStorage.setItem(pnlChaveCache(pnlPainelAtual.slug, pnlClienteId), JSON.stringify({
      dadosPorConsulta: pnlDadosPorConsulta, consultasCarregadas: pnlConsultasCarregadas, info: pnlInfo,
    }));
  }catch(e){ /* quota cheia, modo privado, etc. — sem cache dessa vez, sem travar o resto */ }
}
function pnlCarregarCache(clienteId){
  if(!pnlPainelAtual || !clienteId) return false;
  try{
    const bruto = localStorage.getItem(pnlChaveCache(pnlPainelAtual.slug, clienteId));
    if(!bruto) return false;
    const cache = JSON.parse(bruto);
    if(!cache || !cache.dadosPorConsulta || !cache.info) return false;
    pnlDadosPorConsulta = cache.dadosPorConsulta;
    pnlConsultasCarregadas = cache.consultasCarregadas || [];
    pnlInfo = cache.info;
    pnlFiltros = Object.fromEntries(pnlPainelFiltros.map(f=>[f.campo, new Set()]));
    return true;
  }catch(e){ return false; }
}
async function pnlAtualizarDoRm(){
  if(pnlCarregando || !pnlPainelAtual) return;
  pnlClienteId = document.getElementById('pnl_cliente').value;
  if(!pnlClienteId){ toast('Escolha um cliente com conexão RM cadastrada.'); return; }
  // busca TODAS as consultas vinculadas ao painel que pertencem a esse
  // cliente de uma vez só (pode ser 1, pode ser várias — ex: Vendas +
  // Compras da mesma CORAL)
  const consultas = pnlConsultasDoCliente(pnlPainelAtual, pnlClienteId);
  if(!consultas.length){ document.getElementById('pnlStatus').textContent = 'Esse cliente não está vinculado a esse painel — configure em Relatórios Gerenciais TOTVS RM → Painéis.'; return; }
  const valoresParametros = await rmValoresParametrosDeConsultas(consultas);
  if(!valoresParametros) return;
  pnlCarregando = true;
  const btn = document.getElementById('btnPnlAtualizar');
  const total = consultas.length;
  let concluidas = 0;
  const inicioConsulta = Date.now();
  const atualizarProgressoBtn = () => {
    const seg = Math.max(0, Math.round((Date.now()-inicioConsulta)/1000));
    const contagem = total > 1 ? `${concluidas} de ${total} — ` : '';
    btn.textContent = `Consultando o RM… (${contagem}${seg}s)`;
  };
  const intervaloProgresso = setInterval(atualizarProgressoBtn, 1000);
  btn.disabled = true; atualizarProgressoBtn();
  document.getElementById('pnlStatus').textContent = '';
  try{
    const resultados = await Promise.all(consultas.map(c=>api('executarRmRelatorioGerencial', { contaId: contaAtual().id, clienteId: pnlClienteId, relatorioId: c.id, painelId: pnlPainelAtual.id, valoresParametros }).then(r=>{ concluidas++; atualizarProgressoBtn(); return r; })));
    const falha = resultados.find(r=>!r.ok);
    if(falha){ document.getElementById('pnlStatus').textContent = falha.erro || 'Não foi possível atualizar.'; return; }
    pnlDadosPorConsulta = {};
    consultas.forEach((c,i)=>{ pnlDadosPorConsulta[c.id] = resultados[i].linhas || []; });
    pnlConsultasCarregadas = consultas.map(c=>({ id:c.id, nome:c.nome }));
    pnlInfo = { quando: new Date().toISOString() };
    pnlFiltros = Object.fromEntries(pnlPainelFiltros.map(f=>[f.campo, new Set()]));
    const totalLinhas = consultas.reduce((s,c)=>s+(pnlDadosPorConsulta[c.id]||[]).length, 0);
    toast(`Painel atualizado com ${totalLinhas} linha${totalLinhas===1?'':'s'} do RM (${consultas.length} consulta${consultas.length===1?'':'s'}).`);
    pnlSalvarCache();
    pnlRender();
  } finally {
    clearInterval(intervaloProgresso);
    pnlCarregando = false;
    btn.disabled = false; btn.textContent = 'Atualizar do RM';
  }
}

/* ---------- filtros configuráveis (mesmo "estilo Excel" do Painel de Recebíveis) ---------- */
function pnlOpcoesPorCampo(campo){
  const linhas = pnlLinhasParaOpcoes(campo);
  const vistos = new Set();
  linhas.forEach(o=>{ const v = pnlValorFiltro(o, campo); if(v!=='') vistos.add(v); });
  return [...vistos].sort((a,b)=>a.localeCompare(b,'pt',{numeric:true})).map(v=>({ value:v, label:v }));
}
function pnlFecharFiltroColuna(){
  pnlFiltroColunaAberta = null;
  const portal = document.getElementById('pnlFiltroColunaPortal');
  if(portal){ portal.classList.remove('show'); portal.innerHTML = ''; }
}
function pnlToggleFiltroColuna(campo, spanEl){
  const jaAberto = pnlFiltroColunaAberta === campo;
  pnlFecharFiltroColuna();
  if(jaAberto) return;
  pnlFiltroColunaAberta = campo;
  const portal = document.getElementById('pnlFiltroColunaPortal');
  if(!portal || !spanEl) return;
  const set = pnlFiltros[campo] || new Set();
  const opcoes = pnlOpcoesPorCampo(campo);
  const itensDropdown = opcoes.length
    ? opcoes.map(o=>`<div class="lista-filtro-coluna-item" data-chave="${escaparHtml(campo)}" data-valor="${escaparHtml(o.value)}" data-label="${escaparHtml(o.label)}">${set.has(o.value) ? '✓ ' : ''}${escaparHtml(o.label)}</div>`).join('')
    : `<div class="lista-filtro-coluna-item" style="color:var(--muted);cursor:default;">Nenhuma opção disponível</div>`;
  portal.innerHTML = `
    <div style="padding:6px;border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--panel);">
      <input type="text" class="lista-filtro-coluna-busca" placeholder="Buscar…" autocomplete="off" style="width:100%;box-sizing:border-box;border:1px solid var(--line);border-radius:6px;padding:5px 8px;font-size:12.5px;background:var(--bg);color:inherit;">
    </div>
    <div class="lista-filtro-coluna-item" data-chave="${escaparHtml(campo)}" data-valor="" style="font-weight:700;border-bottom:1px solid var(--line);">Selecionar todos</div>
    ${itensDropdown}
  `;
  // busca filtra a lista sem fechar o dropdown — clicar múltiplos itens
  // marca um a um sem precisar reabrir (ver pnlRedesenharChecksPortal)
  const busca = portal.querySelector('.lista-filtro-coluna-busca');
  if(busca){
    busca.addEventListener('keydown', e=>e.stopPropagation());
    busca.addEventListener('input', ()=>{
      const t = busca.value.trim().toLowerCase();
      portal.querySelectorAll('.lista-filtro-coluna-item[data-label]').forEach(it=>{
        it.style.display = (!t || it.dataset.label.toLowerCase().includes(t)) ? '' : 'none';
      });
    });
  }
  const r = spanEl.getBoundingClientRect();
  portal.style.left = `${r.left}px`;
  portal.style.top = `${r.bottom + 4}px`;
  portal.classList.add('show');
  if(busca) busca.focus();
}
function pnlRedesenharChecksPortal(portal, set){
  portal.querySelectorAll('.lista-filtro-coluna-item[data-label]').forEach(it=>{
    it.textContent = (set.has(it.dataset.valor) ? '✓ ' : '') + it.dataset.label;
  });
}
// chips removíveis (× por valor) no lugar do antigo texto "N selecionados"
function pnlResumoFiltroConteudoHtml(campo){
  const set = pnlFiltros[campo] || new Set();
  if(!set.size) return 'Todos';
  return [...set].map(v=>`<span class="chip on" data-chipfiltro="${escaparHtml(campo)}" data-chipvalor="${escaparHtml(v)}" style="padding:2px 6px 2px 9px;font-size:11px;margin:1px 3px 1px 0;display:inline-flex;align-items:center;gap:4px;">${escaparHtml(v)}<b style="cursor:pointer;font-weight:900;">×</b></span>`).join('');
}
// atualiza só o resumo/chips e a cor do ▾ de UM campo — usado depois de
// marcar/desmarcar um valor, sem refazer a grade inteira de filtros (o
// que fecharia o dropdown que acabou de ser clicado)
// sem escopo a um container só — o mesmo campo pode aparecer tanto na
// grade "Filtros" do topo quanto num widget Filtro no canvas, e os dois
// precisam refletir o mesmo estado (pnlFiltros) ao mesmo tempo
function pnlAtualizarResumoFiltro(campo){
  document.querySelectorAll(`[data-resumo-filtro="${CSS.escape(campo)}"]`).forEach(el=>{ el.innerHTML = pnlResumoFiltroConteudoHtml(campo); });
  document.querySelectorAll(`[data-rfiltro="${CSS.escape(campo)}"]`).forEach(trig=>{ trig.style.color = (pnlFiltros[campo]||new Set()).size > 0 ? 'var(--accent)' : ''; });
}
// não existe mais uma grade "Filtros" fixa pra re-renderizar — os únicos
// controles de filtro são os widgets tipo "Filtro" (dentro de pnlGradeWidgets,
// já recriados do zero a cada pnlRenderEsqueleto) — só falta fechar qualquer
// dropdown de filtro que tenha ficado aberto antes de um render geral
function pnlRenderFiltros(){
  if(pnlFiltroColunaAberta) pnlFecharFiltroColuna();
}
// clique num gráfico/tabela pode filtrar por um campo que ainda não é
// "filtro geral" do painel — nesse caso registra ele na hora, pra aparecer
// como chip removível em qualquer widget Filtro desse campo (ou pra já
// deixar o campo pronto caso um widget Filtro seja criado depois)
function pnlToggleFiltro(campo, valor){
  if(!pnlPainelFiltros.some(f=>f.campo===campo)) pnlPainelFiltros.push({campo});
  const set = pnlFiltros[campo] = pnlFiltros[campo] || new Set();
  if(set.has(valor)) set.delete(valor); else set.add(valor);
  pnlRender();
}

/* ---------- render de cada tipo de widget ---------- */
function pnlRenderWidgetKpi(containerId, widget, linhas){
  const el = document.getElementById(containerId); if(!el) return;
  const valor = pnlValorMedida(widget.medida, null, undefined, widget);
  const def = pnlMedidaPorId(widget.medida) || {};
  const sub = widget.subtitulo || '';
  // "Comparar com os N meses anteriores" — só faz sentido com o filtro
  // fixo "Nos últimos N meses" (ULTIMOSMESES); reaproveita o MESMO campo e
  // N, só trocando o operador pra MESESANTERIORES (mesmo truque usado por
  // pnlAplicarFiltroFixo, que só olha esses 3 campos do objeto)
  let comparacaoHtml = '';
  if(widget.compararPeriodoAnterior && widget.filtroFixoCampo && widget.filtroFixoOperador==='ULTIMOSMESES' && widget.filtroFixoValor){
    const filtroAnterior = { filtroFixoCampo: widget.filtroFixoCampo, filtroFixoOperador: 'MESESANTERIORES', filtroFixoValor: widget.filtroFixoValor };
    const valorAnterior = pnlValorMedida(widget.medida, null, undefined, filtroAnterior);
    const variacao = valorAnterior ? ((valor - valorAnterior) / Math.abs(valorAnterior) * 100) : null;
    const cor = variacao===null ? 'var(--muted)' : (variacao>=0 ? 'var(--ok)' : 'var(--bad)');
    const variacaoTxt = variacao===null ? '—' : `${variacao>=0?'+':''}${variacao.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})}%`;
    comparacaoHtml = `<div class="x" style="font-size:11px;color:var(--muted);margin-top:4px;display:flex;gap:10px;flex-wrap:wrap;">
      <span>Período anterior: ${escaparHtml(pnlFormatarMedida(valorAnterior, widget.medida))}</span>
      <span style="color:${cor};font-weight:700;">Variação: ${variacaoTxt}</span>
    </div>`;
  }
  el.innerHTML = `<div class="box"${pnlEstiloCorWidget(widget)}><div class="k"${pnlAtributoEstiloTexto(widget.estiloTitulo)}>${escaparHtml(widget.titulo || def.label || '')}</div><div class="v"${pnlAtributoEstiloTexto(widget.estiloValor)}>${pnlFormatarMedida(valor, widget.medida)}</div>${sub ? `<div class="x" style="font-size:11px;color:var(--muted);margin-top:2px;">${escaparHtml(sub)}</div>` : ''}${comparacaoHtml}</div>`;
}
function pnlLigarCliqueBarras(container, grupos, campoFiltro){
  const rects = container.querySelectorAll('rect');
  grupos.forEach((g,i)=>{
    const bar = rects[i]; // dashBarChart vertical: 1 <rect> por barra; horizontal teria 2 (trilho+barra) — ver recebLigarCliqueBarras
    if(!bar) return;
    bar.style.cursor = 'pointer';
    bar.addEventListener('click', ()=>pnlToggleFiltro(campoFiltro, g.chave));
  });
}
// dashDonut desenha 1 <path> por fatia, na mesma ordem dos dados passados
function pnlLigarCliqueDonut(container, grupos, campoFiltro){
  const paths = container.querySelectorAll('path');
  grupos.forEach((g,i)=>{
    const fatia = paths[i];
    if(!fatia) return;
    fatia.style.cursor = 'pointer';
    fatia.addEventListener('click', ()=>pnlToggleFiltro(campoFiltro, g.chave));
  });
}
// dashLineChart desenha 2 <circle> por ponto (um visível + um invisível de
// r:9 só pra tooltip/clique) — nessa ordem, repetidos série após série na
// mesma ordem de "chaves"; por isso o índice ímpar módulo chaves.length
// recupera a chave certa (igual índice ímpar nas barras horizontais)
function pnlLigarCliqueLinha(container, chaves, campoFiltro, numSeries){
  const circles = container.querySelectorAll('circle');
  const totalPontos = chaves.length * numSeries;
  for(let i=0;i<totalPontos;i++){
    const alvo = circles[i*2+1];
    if(!alvo) continue;
    const chave = chaves[i % chaves.length];
    alvo.style.cursor = 'pointer';
    alvo.addEventListener('click', ()=>pnlToggleFiltro(campoFiltro, chave));
  }
}
// dashGroupedBarChart desenha 1 <rect> por combinação (chave, série),
// agrupadas por chave — clicar em qualquer série do cluster filtra pela
// mesma chave (a categoria do eixo X), não por qual medida foi clicada
function pnlLigarCliqueBarrasAgrupadas(container, chaves, numSeries, campoFiltro){
  const rects = container.querySelectorAll('rect');
  chaves.forEach((chave,i)=>{
    for(let si=0; si<numSeries; si++){
      const bar = rects[i*numSeries+si];
      if(!bar) continue;
      bar.style.cursor = 'pointer';
      bar.addEventListener('click', ()=>pnlToggleFiltro(campoFiltro, chave));
    }
  });
}
// medidas adicionais de um widget barra/linha — novo campo
// "medidasExtras" (array), com fallback pro antigo "medida2" (1 só),
// salvo por widgets criados antes dessa opção existir
function pnlMedidasExtrasWidget(widget){
  if(Array.isArray(widget.medidasExtras)) return widget.medidasExtras;
  return widget.medida2 ? [widget.medida2] : [];
}
function pnlRenderWidgetGrafico(containerId, widget, linhas, tipo){
  const cont = document.getElementById(containerId); if(!cont) return;
  const altura = RECEB_ALTURAS_WIDGET[widget.altura];
  const cores = ['--blue','--ok','--bad','--warn','--purple','--yellow'];
  if(tipo==='linha'){
    const dimensao = widget.dimensao;
    const medidas = [widget.medida, ...pnlMedidasExtrasWidget(widget)];
    const porMedida = medidas.map(m=>pnlAgruparPorCampo(linhas, dimensao, m));
    const chaves = [...new Set(porMedida.flatMap(arr=>arr.map(g=>g.chave)))].sort((a,b)=>a.localeCompare(b,'pt',{numeric:true}));
    const series = medidas.map((m,i)=>{
      const porChave = {}; porMedida[i].forEach(g=>{ porChave[g.chave]=g.valor; });
      return { label:(pnlMedidaPorId(m)||{}).label||m, tok:cores[i%cores.length], data: chaves.map(c=>porChave[c]||0), fmtFn: v=>pnlFormatarMedida(v, m) };
    });
    dashLineChart(cont, { labels: chaves, series, mostrarRotulos: !!widget.mostrarRotulos, ...(altura ? {height:altura} : {}) });
    pnlLigarCliqueLinha(cont, chaves, dimensao, medidas.length);
    if(widget.mostrarLegenda) cont.insertAdjacentHTML('beforeend', `<div class="dash-legend">${dashLegendHtml(series.map(s=>({label:s.label, cor:dashCss(s.tok)})))}</div>`);
    return;
  }
  const medidasExtras = tipo==='barra' ? pnlMedidasExtrasWidget(widget) : [];
  if(medidasExtras.length){
    // barra com mais de uma medida: clusters por valor do "Agrupar por",
    // uma barra por medida dentro de cada cluster (comparação lado a lado)
    const medidas = [widget.medida, ...medidasExtras];
    const porMedida = medidas.map(m=>pnlAgruparPorCampo(linhas, widget.dimensao, m));
    let chaves = [...new Set(porMedida.flatMap(arr=>arr.map(g=>g.chave)))].sort((a,b)=>a.localeCompare(b,'pt',{numeric:true}));
    if(widget.top) chaves = chaves.slice(0, Number(widget.top));
    const series = medidas.map((m,i)=>{
      const porChave = {}; porMedida[i].forEach(g=>{ porChave[g.chave]=g.valor; });
      return { label:(pnlMedidaPorId(m)||{}).label||m, tok:cores[i%cores.length], data: chaves.map(c=>porChave[c]||0), fmtFn: v=>pnlFormatarMedida(v, m) };
    });
    dashGroupedBarChart(cont, { labels: chaves, series, mostrarRotulos: !!widget.mostrarRotulos, ...(altura ? {height:altura} : {}) });
    pnlLigarCliqueBarrasAgrupadas(cont, chaves, medidas.length, widget.dimensao);
    if(widget.mostrarLegenda) cont.insertAdjacentHTML('beforeend', `<div class="dash-legend">${dashLegendHtml(series.map(s=>({label:s.label, cor:dashCss(s.tok)})))}</div>`);
    return;
  }
  let grupos = pnlAgruparPorCampo(linhas, widget.dimensao, widget.medida);
  if(widget.top) grupos = grupos.slice(0, Number(widget.top));
  if(tipo==='donut'){
    const total = grupos.reduce((s,g)=>s+g.valor,0);
    dashDonut(cont, grupos.map((g,i)=>({ label:g.rotulo, value:g.valor, cor:dashCss(cores[i%cores.length]) })), { fmtFn: v=>pnlFormatarMedida(v, widget.medida), ...(altura ? {size:altura} : {}) });
    pnlLigarCliqueDonut(cont, grupos, widget.dimensao);
    if(widget.mostrarLegenda){
      const itens = grupos.map((g,i)=>({ label: widget.mostrarRotulos && total ? `${g.rotulo} (${Math.round(g.valor/total*100)}%)` : g.rotulo, cor:dashCss(cores[i%cores.length]) }));
      cont.insertAdjacentHTML('beforeend', `<div class="dash-legend">${dashLegendHtml(itens)}</div>`);
    }
    return;
  }
  if(tipo==='treemap'){
    dashTreemap(cont, grupos.map((g,i)=>({ label:g.rotulo, value:g.valor, tok:cores[i%cores.length] })), { fmtFn: v=>pnlFormatarMedida(v, widget.medida), mostrarRotulos: !!widget.mostrarRotulos, ...(altura ? {height:altura} : {}) });
    pnlLigarCliqueTreemap(cont, grupos, widget.dimensao);
    if(widget.mostrarLegenda){
      const itens = grupos.map((g,i)=>({ label:g.rotulo, cor:dashCss(cores[i%cores.length]) }));
      cont.insertAdjacentHTML('beforeend', `<div class="dash-legend">${dashLegendHtml(itens)}</div>`);
    }
    return;
  }
  const data = grupos.map(g=>({ label:g.rotulo, value:g.valor, tok:'--blue' }));
  const horizontal = tipo==='barra-h';
  dashBarChart(cont, { data, horizontal, rotateLabels: tipo==='barra', fmtFn: v=>pnlFormatarMedida(v, widget.medida), mostrarRotulos: !!widget.mostrarRotulos, ...(altura ? {height:altura} : {}) });
  if(horizontal){
    // horizontal desenha 2 <rect> por linha (trilho + barra) — reaproveita
    // a mesma convenção de índice ímpar do recebLigarCliqueBarras
    const rects = cont.querySelectorAll('rect');
    grupos.forEach((g,i)=>{ const bar = rects[i*2+1]; if(!bar) return; bar.style.cursor='pointer'; bar.addEventListener('click', ()=>pnlToggleFiltro(widget.dimensao, g.chave)); });
  } else {
    pnlLigarCliqueBarras(cont, grupos, widget.dimensao);
  }
}
// catálogo de colunas disponíveis de UMA consulta pra "Tabela (colunas à
// sua escolha)" — tudo que ela trouxer, sem distinção (não existe campo
// "processado" num painel genérico, é tudo coluna crua)
function pnlColunasTabelaDisponiveis(consultaId){
  const opcoes = {};
  pnlColunasDisponiveis(consultaId).forEach(c=>{ opcoes[c] = c; });
  return opcoes;
}
// valores distintos de uma coluna de UMA consulta — popula o seletor
// "Valor" do filtro fixo do widget
function pnlValoresDistintosColuna(campo, consultaId){
  if(!campo) return [];
  const linhas = pnlDadosPorConsulta[consultaId] || [];
  return [...new Set(linhas.map(o=>pnlValorFiltro(o, campo)))]
    .filter(v=>v!=='').sort((a,b)=>a.localeCompare(b,'pt',{numeric:true}));
}
// monta os chips do filtro rápido (um widget Tabela só) em cima das
// linhas-base (antes da busca e do próprio filtro rápido, senão o valor
// escolhido sumiria da lista assim que fosse aplicado)
function pnlRenderOpcoesFiltroRapido(widget, itensBase){
  const cont = document.getElementById(`pnl-${widget.id}-filtrorapido`);
  if(!cont) return;
  const valores = [...new Set(itensBase.map(o=>pnlValorFiltro(o, widget.filtroRapido)))]
    .filter(v=>v!=='').sort((a,b)=>a.localeCompare(b,'pt',{numeric:true}));
  const atual = pnlFiltroRapidoPorWidget[widget.id] || 'todas';
  cont.innerHTML = `<div class="chip ${atual==='todas'?'on':''}" data-wfiltrorapido="todas" data-wid="${widget.id}">Todas</div>` +
    valores.map(v=>`<div class="chip ${atual===v?'on':''}" data-wfiltrorapido="${escaparHtml(v)}" data-wid="${widget.id}">${escaparHtml(v)}</div>`).join('');
}
function pnlRenderWidgetTabelaPersonalizada(widget, linhas){
  const tab = document.getElementById(`pnl-${widget.id}-tabela`); if(!tab) return;
  tab.classList.toggle('pnl-tabela-zebrada', !!widget.zebrado);
  const consultaId = widget.consultaId || pnlConsultaPadrao();
  const colunas = (widget.colunas && widget.colunas.length) ? widget.colunas : pnlColunasDisponiveis(consultaId).slice(0,8);
  const catalogo = pnlColunasTabelaDisponiveis(consultaId);
  // filtro fixo do widget — restrição permanente (ex: só o cliente X),
  // independente do filtro geral e do filtro rápido; vale pras duas
  // fontes (linhas e agrupado)
  linhas = pnlAplicarFiltroFixo(linhas, widget);
  if(widget.fonte === 'agrupado'){
    const dimensoes = [widget.dimensao, widget.dimensao2, widget.dimensao3].filter(Boolean);
    const grupos = pnlAgruparMultiplasDimensoes(linhas, dimensoes, colunas);
    const cab = [...dimensoes, ...colunas.map(c=>pnlLabelColuna(c, catalogo, widget.colunasApelidos))];
    const corpo = grupos.map(g=>{
      // célula de dimensão clicável filtra só por ELA (campo+valor daquela
      // coluna), não pela linha inteira — evita ambiguidade quando a tabela
      // agrupa por mais de uma dimensão (2º/3º nível)
      const celulasDimHtml = g.rotulos.map((v,i)=>`<td${ehNumAlinhavel(v)?' class="num"':''} style="cursor:pointer;" data-tcampo="${escaparHtml(dimensoes[i])}" data-tvalor="${escaparHtml(g.chaves[i])}" title="Filtrar por ${escaparHtml(String(v))}">${escaparHtml(String(v))}</td>`).join('');
      const celulasValHtml = colunas.map(c=>{
        const medida = pnlMedidaPorId(c);
        const html = medida ? pnlFormatarMedida(g.valores[c], c) : String(g.valores[c]);
        const numerico = medida ? true : ehNumAlinhavel(g.valores[c]);
        return `<td${numerico?' class="num"':''}>${escaparHtml(html)}</td>`;
      }).join('');
      return `<tr>${celulasDimHtml}${celulasValHtml}</tr>`;
    }).join('');
    tab.innerHTML = `<thead><tr>${cab.map(c=>`<th>${escaparHtml(c)}</th>`).join('')}</tr></thead>
      <tbody>${corpo || `<tr><td colspan="${cab.length}" class="empty">${(pnlDadosPorConsulta[consultaId]||[]).length ? 'Nenhum grupo com esses filtros.' : 'Sem dados — atualize do RM primeiro.'}</td></tr>`}</tbody>`;
    tab.querySelectorAll('tbody [data-tcampo]').forEach(td=>{
      td.addEventListener('click', ()=>pnlToggleFiltro(td.dataset.tcampo, td.dataset.tvalor));
    });
    return;
  }
  // fonte 'linhas' — uma linha por registro, com busca livre (qualquer coluna)
  let itens = linhas;
  if(widget.filtroRapido){
    pnlRenderOpcoesFiltroRapido(widget, itens);
    const seg = pnlFiltroRapidoPorWidget[widget.id];
    if(seg && seg!=='todas') itens = itens.filter(o=>pnlValorFiltro(o, widget.filtroRapido)===seg);
  }
  const buscaEl = document.querySelector(`[data-wbusca][data-wid="${widget.id}"]`);
  const busca = (buscaEl?.value || '').trim().toLowerCase();
  if(busca) itens = itens.filter(o=>Object.values(o).some(v=>v!=null && String(v).toLowerCase().includes(busca)));
  const indicesLinks = pnlIndicesLinksWidget(widget);
  const cab = colunas.map(c=>pnlLabelColuna(c, catalogo, widget.colunasApelidos));
  const corpo = itens.map(o=>`<tr>${colunas.map(c=>{
    const raw = pnlValorColunaLinha(o, c, indicesLinks);
    const formato = pnlFormatoColuna(c, widget.colunasFormatos);
    return `<td${pnlColunaEhNumerica(raw, formato)?' class="num"':''}>${escaparHtml(pnlFormatarValorColunaComFormato(raw, formato))}</td>`;
  }).join('')}</tr>`).join('');
  const totais = colunas.map((c,i)=>{
    if(i===0) return `<td><b>${itens.length} linha${itens.length===1?'':'s'}</b></td>`;
    const formato = pnlFormatoColuna(c, widget.colunasFormatos);
    if(formato==='texto') return '<td></td>';
    const vals = itens.map(o=>pnlCoagirNumero(pnlValorColunaLinha(o,c,indicesLinks))).filter(v=>typeof v==='number');
    return vals.length ? `<td class="num"><b>${pnlFormatarTotalColunaComFormato(vals.reduce((s,v)=>s+v,0), formato)}</b></td>` : '<td></td>';
  }).join('');
  tab.innerHTML = `<thead><tr>${cab.map(c=>`<th>${escaparHtml(c)}</th>`).join('')}</tr></thead>
    <tbody>${corpo || `<tr><td colspan="${cab.length}" class="empty">${(pnlDadosPorConsulta[consultaId]||[]).length ? 'Nenhuma linha com esses filtros.' : 'Sem dados — atualize do RM primeiro.'}</td></tr>`}</tbody>
    ${itens.length ? `<tfoot><tr>${totais}</tr></tfoot>` : ''}`;
}
// índice (valor do campo de ligação -> TODAS as linhas com esse valor) de
// uma consulta de subdetalhe — igual pnlIndiceConsultaLinkada, mas
// guardando o array inteiro em vez de só a 1ª (aqui expande, lá só puxa 1
// valor); usa a mesma convenção de dados crus (sem filtro geral) do link
// simples da Tabela
function pnlIndiceConsultaLinkadaMultiplo(consultaId, campoLink){
  const linhas = pnlDadosPorConsulta[consultaId] || [];
  const indice = {};
  linhas.forEach(o=>{
    const chave = pnlValorFiltro(o, campoLink);
    (indice[chave] = indice[chave] || []).push(o);
  });
  return indice;
}
// widget "relatorio" — Detalhe (uma linha por registro da consulta
// principal, igual a Tabela fonte 'linhas', inclusive com "Ligar com
// outra consulta" pra trazer 1 campo) seguido de 1+ Subdetalhes
// (listas aninhadas, uma por registro do Detalhe, ligadas por chave)
// linha de total/subtotal reaproveitada tanto pro rodapé geral quanto
// pros subtotais de quebra — 1ª coluna vira o rótulo, as outras somam
// (quando dá) os valores cru das linhas desse grupo
function pnlLinhaTotalColunas(grupoLinhas, colunas, indicesLinks, rotulo, prefixoHtml, colunasFormatos, valorFn){
  const obterValor = valorFn || ((o,c)=>pnlValorColunaLinha(o,c,indicesLinks));
  return colunas.map((c,i)=>{
    if(i===0) return `<td><b>${prefixoHtml||''}${escaparHtml(rotulo)}</b></td>`;
    // medida (Detalhe agrupado) já é uma agregação por grupo — somar de
    // novo no rodapé só é correto pra "soma"; pra média/mín/máx/etc dá um
    // número sem sentido, então não soma medida nenhuma aqui
    if(pnlMedidaPorId(c)) return '<td></td>';
    const formato = pnlFormatoColuna(c, colunasFormatos);
    if(formato==='texto') return '<td></td>';
    const vals = grupoLinhas.map(o=>pnlCoagirNumero(obterValor(o,c))).filter(v=>typeof v==='number');
    return vals.length ? `<td class="num"><b>${pnlFormatarTotalColunaComFormato(vals.reduce((s,v)=>s+v,0), formato)}</b></td>` : '<td></td>';
  }).join('');
}
function pnlRenderWidgetRelatorio(containerId, widget, linhas){
  const el = document.getElementById(containerId); if(!el) return;
  const consultaId = widget.consultaId || pnlConsultaPadrao();
  const catalogo = pnlColunasTabelaDisponiveis(consultaId);
  linhas = pnlAplicarFiltroFixo(linhas, widget);
  const ehAgrupado = widget.fonte === 'agrupado';
  if(widget.filtroRapido){
    pnlRenderOpcoesFiltroRapido(widget, linhas);
    const seg = pnlFiltroRapidoPorWidget[widget.id];
    if(seg && seg!=='todas') linhas = linhas.filter(o=>pnlValorFiltro(o, widget.filtroRapido)===seg);
  }
  let colunas = (widget.colunas && widget.colunas.length) ? widget.colunas : pnlColunasDisponiveis(consultaId).slice(0,4);
  const indicesLinks = pnlIndicesLinksWidget(widget);
  // Detalhe agrupado: cada "linha" vira um grupo sintético (chaves de
  // dimensão + medidas/campos agregados) — Subdetalhes não se aplicam (não
  // existe mais 1 registro por linha pra ligar filhos)
  let subdetalhes = [];
  if(ehAgrupado){
    const dimensoes = [widget.dimensao, widget.dimensao2, widget.dimensao3].filter(Boolean);
    linhas = pnlAgruparColunasCruRelatorio(linhas, dimensoes, colunas);
    colunas = [...dimensoes, ...colunas];
  }else{
    subdetalhes = (widget.subdetalhes||[]).map(sd=>({
      ...sd,
      indice: pnlIndiceConsultaLinkadaMultiplo(sd.consultaId, sd.campoLink),
      catalogo: pnlColunasTabelaDisponiveis(sd.consultaId),
    }));
  }
  // valor cru de uma coluna numa "linha" — em modo agrupado a linha já é o
  // objeto sintético acima (lê a chave direto); senão, uma coluna "%subId::
  // campo::funcao" é calculada a partir de um Subdetalhe (soma/contagem
  // escopada ao registro pai), e qualquer outra resolve campo normal ou
  // linkado da consulta principal (fonte 'linhas', registro de verdade)
  const valorColuna = ehAgrupado ? ((o,c)=>o[c]) : ((o,c)=>{
    if(pnlEhCampoSubdetalhe(c)){
      const p = pnlParseCampoSubdetalhe(c);
      return pnlValorCampoSubdetalhe(o, p.subId, p.campo, p.funcao, subdetalhes);
    }
    return pnlValorColunaLinha(o,c,indicesLinks);
  });
  // ordenação "ao vivo" (clique no cabeçalho) substitui a configurada — e,
  // como a quebra/subtotal depende da ordem configurada pra agrupar certo,
  // fica desligada enquanto uma ordenação ao vivo estiver ativa (a
  // ordenação CONFIGURADA nem existe em modo agrupado — a própria
  // agregação já define a ordem padrão, por medida ou alfabética)
  const ordenacaoRuntime = pnlOrdenacaoRuntimePorWidget[widget.id];
  if(ordenacaoRuntime){
    linhas = pnlOrdenarPorCriterios(linhas, [{campo:ordenacaoRuntime.campo, direcao:ordenacaoRuntime.direcao}], valorColuna);
  }else if(!ehAgrupado && widget.ordenacao && widget.ordenacao.length){
    linhas = pnlOrdenarPorCriterios(linhas, widget.ordenacao, valorColuna);
  }
  const cab = colunas.map(c=>{
    const label = pnlLabelColuna(c, catalogo, widget.colunasApelidos);
    const seta = ordenacaoRuntime && ordenacaoRuntime.campo===c ? (ordenacaoRuntime.direcao==='asc' ? ' ▲' : ' ▼') : '';
    return `<th data-relatsort="${widget.id}::${escaparHtml(c)}" data-relatcoluna="${widget.id}::${escaparHtml(c)}" draggable="true" style="cursor:pointer;user-select:none;" title="Clique pra ordenar · arraste pra reordenar (modo de edição)">${escaparHtml(label)}${seta}</th>`;
  });
  // níveis de quebra — ordem do array de ordenação = ordem de quebra (do
  // mais externo pro mais interno); só entram os critérios marcados —
  // nenhum nível enquanto a ordenação ao vivo estiver ativa (ver acima)
  const niveisQuebra = (ehAgrupado || ordenacaoRuntime) ? [] : (widget.ordenacao||[]).filter(cr=>cr.quebra);
  const acumuladores = niveisQuebra.map(()=>[]);
  let valoresAnteriores = null;
  const partes = [];
  // id do grupo "aberto" em cada nível de quebra (null = ainda não começou
  // um grupo novo) — cada grupo vira alvo de um botão +/- próprio, e os
  // níveis mais internos carregam o(s) id(s) dos níveis mais externos que
  // os contêm, pra colapsar o de fora também esconder o de dentro
  let grupoContador = 0;
  const grupoIds = niveisQuebra.map(()=>null);
  const assegurarGrupoId = i => { if(grupoIds[i]===null) grupoIds[i] = `${widget.id}-q${i}-${grupoContador++}`; return grupoIds[i]; };
  const emitirSubtotais = (ateONivel)=>{
    for(let i=niveisQuebra.length-1; i>=ateONivel; i--){
      if(acumuladores[i].length){
        const rotuloCampo = pnlLabelColuna(niveisQuebra[i].campo, catalogo, widget.colunasApelidos);
        const rotuloValor = pnlFormatarValorColunaComFormato(valoresAnteriores[i], pnlFormatoColuna(niveisQuebra[i].campo, widget.colunasFormatos));
        const idGrupo = grupoIds[i];
        const gruposAncestrais = grupoIds.slice(0,i).filter(Boolean).join(' ');
        const toggle = idGrupo ? `<button type="button" class="pnl-relat-toggle" data-relatquebra="${idGrupo}" title="Expandir/colapsar grupo">−</button>` : '';
        partes.push(`<tr class="pnl-relat-subtotal"${gruposAncestrais?` data-quebragrupos="${gruposAncestrais}"`:''}>${pnlLinhaTotalColunas(acumuladores[i], colunas, indicesLinks, `Subtotal — ${rotuloCampo}: ${rotuloValor}`, toggle, widget.colunasFormatos, valorColuna)}</tr>`);
      }
      acumuladores[i] = [];
      grupoIds[i] = null;
    }
  };
  linhas.forEach((o, idx)=>{
    if(niveisQuebra.length){
      const valoresAtuais = niveisQuebra.map(cr=>valorColuna(o, cr.campo));
      if(idx>0){
        let nivelQueMudou = -1;
        for(let i=0;i<niveisQuebra.length;i++){
          if(String(valoresAtuais[i]) !== String(valoresAnteriores[i])){ nivelQueMudou = i; break; }
        }
        if(nivelQueMudou>=0) emitirSubtotais(nivelQueMudou);
      }
      valoresAnteriores = valoresAtuais;
    }
    niveisQuebra.forEach((_,i)=>assegurarGrupoId(i));
    const gruposDaLinha = grupoIds.filter(Boolean).join(' ');
    const atribQuebra = gruposDaLinha ? ` data-quebragrupos="${gruposDaLinha}"` : '';
    const idLinha = `${widget.id}-${idx}`;
    const blocosSub = subdetalhes.map(sd=>{
      const chave = pnlValorFiltro(o, sd.campoPrincipal);
      let filhos = sd.indice[chave] || [];
      if(!filhos.length) return '';
      let colunasSub = sd.colunas;
      if(sd.fonte === 'agrupado'){
        const dimensoesSub = [sd.dimensao, sd.dimensao2, sd.dimensao3].filter(Boolean);
        filhos = pnlAgruparSubdetalhe(filhos, dimensoesSub, sd.colunas);
        colunasSub = [...dimensoesSub, ...sd.colunas];
      }
      if(sd.ordenacao && sd.ordenacao.length){
        filhos = pnlOrdenarPorCriterios(filhos, sd.ordenacao, (f,c)=>f[c]);
      }
      const cabSub = colunasSub.map(c=>pnlLabelColuna(c, sd.catalogo, sd.colunasApelidos));
      const linhasSub = filhos.map(f=>`<tr>${colunasSub.map(c=>`<td${ehNumAlinhavel(f[c])?' class="num"':''}>${escaparHtml(pnlFormatarValorColuna(f[c]))}</td>`).join('')}</tr>`).join('');
      const totaisSub = (sd.colunasTotais && sd.colunasTotais.length) ? colunasSub.map(c=>{
        if(!sd.colunasTotais.includes(c)) return '<td></td>';
        const vals = filhos.map(f=>pnlCoagirNumero(f[c])).filter(v=>typeof v==='number');
        return vals.length ? `<td class="num"><b>${pnlFormatarTotalColuna(vals.reduce((s,v)=>s+v,0))}</b></td>` : '<td></td>';
      }).join('') : '';
      return `<tr class="pnl-relat-sub-wrap" data-detpai="${idLinha}"${atribQuebra}><td colspan="${colunas.length}">
        <div class="pnl-relat-sub-label">${escaparHtml(sd.titulo || 'Detalhes')}</div>
        <table class="pnl-relat-sub-tabela"${pnlAtributoFonteLinhasTabela(sd)}><thead><tr>${cabSub.map(c=>`<th>${escaparHtml(c)}</th>`).join('')}</tr></thead>
        <tbody>${linhasSub}</tbody>${totaisSub ? `<tfoot><tr>${totaisSub}</tr></tfoot>` : ''}</table>
      </td></tr>`;
    }).join('');
    const temSubdetalhe = subdetalhes.some(sd=>(sd.indice[pnlValorFiltro(o, sd.campoPrincipal)]||[]).length);
    const classeZebra = (widget.zebrado && idx%2===1) ? ' pnl-relat-zebra-impar' : '';
    const linhaDetalhe = `<tr class="pnl-relat-detalhe${classeZebra}"${atribQuebra}>${colunas.map((c,i)=>{
      const raw = valorColuna(o, c);
      const toggle = (i===0 && temSubdetalhe) ? `<button type="button" class="pnl-relat-toggle" data-relattoggle="${idLinha}" title="Expandir/colapsar subdetalhes">−</button>` : '';
      // coluna de medida (só existe no Detalhe agrupado) usa o formato
      // próprio da medida (fmt:money/pct/dias), igual já faz o Tabela
      // agrupado — o formato por coluna (colunasFormatos) é só pra campo cru
      const medida = pnlMedidaPorId(c);
      if(medida) return `<td class="num">${toggle}${escaparHtml(pnlFormatarMedida(raw, c))}</td>`;
      const formato = pnlFormatoColuna(c, widget.colunasFormatos);
      return `<td${pnlColunaEhNumerica(raw, formato)?' class="num"':''}>${toggle}${escaparHtml(pnlFormatarValorColunaComFormato(raw, formato))}</td>`;
    }).join('')}</tr>`;
    partes.push(linhaDetalhe + blocosSub);
    niveisQuebra.forEach((_,i)=>acumuladores[i].push(o));
  });
  if(niveisQuebra.length) emitirSubtotais(0);
  const corpo = partes.join('');
  const totais = pnlLinhaTotalColunas(linhas, colunas, indicesLinks, `${linhas.length} registro${linhas.length===1?'':'s'}`, '', widget.colunasFormatos, valorColuna);
  el.innerHTML = `<table class="valores-table pnl-relatorio-tabela"${pnlAtributoFonteLinhasTabela(widget)}>
    <thead><tr>${cab.join('')}</tr></thead>
    <tbody>${corpo || `<tr><td colspan="${cab.length}" class="empty">${(pnlDadosPorConsulta[consultaId]||[]).length ? 'Nenhum registro com esses filtros.' : 'Sem dados — atualize do RM primeiro.'}</td></tr>`}</tbody>
    ${linhas.length ? `<tfoot><tr>${totais}</tr></tfoot>` : ''}
  </table>`;
}

/* ---------- grade configurável (montagem do esqueleto + edição) ---------- */
function pnlWidgetTitulo(w){
  if(w.titulo) return w.titulo;
  if(w.tipo==='tabela') return 'Tabela';
  if(w.tipo==='relatorio') return 'Relatório';
  if(w.tipo==='titulo') return 'Título';
  if(w.tipo==='container') return 'Container';
  if(w.tipo==='curvaabc') return 'Curva ABC';
  if(w.tipo==='filtro') return w.campo || 'Filtro';
  return (pnlMedidaPorId(w.medida)||{}).label || w.medida || '(sem título)';
}
// opções (chave->label) da última renderização do picker de colunas —
// cacheado só pra pnlMoverColuna conseguir re-render a lista de ordem
// sem precisar recalcular tudo de novo
let pnlColunasOrdemOpcoes = {};
function pnlRenderColunasOrdem(opcoes){
  pnlColunasOrdemOpcoes = opcoes;
  const cont = document.getElementById('pnlNovoWidgetColunasOrdem');
  if(!cont) return;
  if(!pnlFormColunasAtual.length){ cont.innerHTML = ''; return; }
  const opcoesFormato = { auto:'Automático', texto:'Texto', numero:'Número (sem casas)', moeda:'Moeda (2 casas)' };
  cont.innerHTML = `<div style="font-size:11px;color:var(--muted);margin-bottom:4px;">Ordem das colunas (use ↑/↓) — o campo de texto troca o nome exibido, o formato força como o valor aparece</div>` +
    pnlFormColunasAtual.map((c,i)=>{
      const v = opcoes[c];
      const label = typeof v === 'string' ? v : (v ? v.label : c);
      const formatoAtual = pnlFormatoColuna(c, pnlFormColunasFormatos);
      return `<div style="display:flex;align-items:center;gap:4px;padding:2px 0;flex-wrap:wrap;">
        <button type="button" data-movercoluna="up" data-coluna="${escaparHtml(c)}" ${i===0?'disabled':''} style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:13px;line-height:1;padding:2px;">↑</button>
        <button type="button" data-movercoluna="down" data-coluna="${escaparHtml(c)}" ${i===pnlFormColunasAtual.length-1?'disabled':''} style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:13px;line-height:1;padding:2px;">↓</button>
        <span style="font-size:13px;flex:0 0 auto;min-width:110px;">${escaparHtml(label)}</span>
        <input type="text" data-apelidocoluna="${escaparHtml(c)}" value="${escaparHtml(pnlFormColunasApelidos[c]||'')}" placeholder="${escaparHtml(label)}" style="flex:1 1 120px;font-size:12px;padding:3px 6px;">
        <select data-formatocoluna="${escaparHtml(c)}" style="flex:0 0 auto;font-size:12px;padding:3px 4px;">
          ${Object.entries(opcoesFormato).map(([k,lbl])=>`<option value="${k}" ${formatoAtual===k?'selected':''}>${lbl}</option>`).join('')}
        </select>
      </div>`;
    }).join('');
}
function pnlMoverColuna(campo, dir){
  const i = pnlFormColunasAtual.indexOf(campo);
  if(i<0) return;
  const j = dir==='up' ? i-1 : i+1;
  if(j<0 || j>=pnlFormColunasAtual.length) return;
  [pnlFormColunasAtual[i], pnlFormColunasAtual[j]] = [pnlFormColunasAtual[j], pnlFormColunasAtual[i]];
  pnlRenderColunasOrdem(pnlColunasOrdemOpcoes);
}
function pnlRenderColunasPicker(fonte, consultaId, subdetalhesForm){
  const marcadas = new Set(pnlFormColunasAtual);
  const montaItens = opcoes => Object.entries(opcoes).map(([k,v])=>{
    const label = typeof v === 'string' ? v : v.label;
    return `<label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:normal;">
      <input type="checkbox" data-wcoluna value="${k}" ${marcadas.has(k)?'checked':''} style="width:auto;"> ${escaparHtml(label)}
    </label>`;
  }).join('');
  // qualquer medida vale aqui, independente da consulta onde ela foi
  // criada — pnlValorMedida já sabe resolver uma medida de "Vendas"
  // dentro de um agrupamento rodando sobre "Compras", cruzando pelo
  // valor da própria dimensão (mesma lógica das medidas-fórmula)
  const medidasDaConsulta = pnlPainelMedidas;
  let opcoesCombinadas;
  if(fonte === 'agrupado'){
    const medidas = Object.fromEntries(medidasDaConsulta.map(m=>[m.id, m.label]));
    const campos = pnlColunasTabelaDisponiveis(consultaId);
    // campos de OUTRAS consultas também valem aqui — a "ligação" é o
    // próprio campo de "Agrupar por", igual já funciona pras medidas
    const camposLinkados = {};
    pnlConsultasCarregadas.filter(c=>c.id!==consultaId).forEach(c=>{
      pnlColunasDisponiveis(c.id).forEach(campo=>{ camposLinkados[pnlCodificarCampoLinkado(c.id, campo)] = `${campo} (${c.nome})`; });
    });
    opcoesCombinadas = { ...medidas, ...campos, ...camposLinkados };
    document.getElementById('pnlNovoWidgetLabelColunas').textContent = 'Colunas (medidas e campos)';
    document.getElementById('pnlNovoWidgetColunasLista').innerHTML =
      (medidasDaConsulta.length ? `<div style="font-weight:700;font-size:11px;color:var(--muted);margin:2px 0;">MEDIDAS (calculadas por grupo)</div>${montaItens(medidas)}` : '') +
      `<div style="font-weight:700;font-size:11px;color:var(--muted);margin:10px 0 2px;">CAMPOS (valor da 1ª linha do grupo)</div>${montaItens(campos)}` +
      (Object.keys(camposLinkados).length ? `<div style="font-weight:700;font-size:11px;color:var(--muted);margin:10px 0 2px;">CAMPOS DE OUTRAS CONSULTAS (ligados por "Agrupar por")</div>${montaItens(camposLinkados)}` : '');
  }else{
    const campos = pnlColunasTabelaDisponiveis(consultaId);
    // campos linkados (fonte 'linhas') só aparecem depois de configurar
    // o link em "Ligar com outra consulta", logo abaixo
    const camposLinkados = {};
    pnlFormLinksAtual.forEach(l=>{
      pnlColunasDisponiveis(l.consultaId).forEach(campo=>{ camposLinkados[pnlCodificarCampoLinkado(l.consultaId, campo)] = `${campo} (${pnlNomeConsulta(l.consultaId)})`; });
    });
    // "coluna calculada" a partir de um Subdetalhe (soma de um campo, ou
    // contagem de itens) — escopada ao registro pai, só faz sentido no
    // Detalhe (widget Relatório) em fonte 'linhas', nunca na Tabela
    const camposSubdetalhe = {};
    (subdetalhesForm||[]).forEach(sd=>{
      if(!sd.id) return;
      camposSubdetalhe[pnlCodificarCampoSubdetalhe(sd.id, '', 'contagem')] = `Quantidade de itens (${sd.titulo||'Detalhes'})`;
      const catalogoSub = pnlColunasTabelaDisponiveis(sd.consultaId);
      Object.entries(catalogoSub).forEach(([campo,label])=>{
        camposSubdetalhe[pnlCodificarCampoSubdetalhe(sd.id, campo, 'soma')] = `${label} — soma (${sd.titulo||'Detalhes'})`;
      });
    });
    opcoesCombinadas = { ...campos, ...camposLinkados, ...camposSubdetalhe };
    document.getElementById('pnlNovoWidgetLabelColunas').textContent = 'Colunas';
    document.getElementById('pnlNovoWidgetColunasLista').innerHTML = montaItens(campos) +
      (Object.keys(camposLinkados).length ? `<div style="font-weight:700;font-size:11px;color:var(--muted);margin:10px 0 2px;">CAMPOS LINKADOS</div>${montaItens(camposLinkados)}` : '') +
      (Object.keys(camposSubdetalhe).length ? `<div style="font-weight:700;font-size:11px;color:var(--muted);margin:10px 0 2px;">CALCULADO A PARTIR DO SUBDETALHE</div>${montaItens(camposSubdetalhe)}` : '');
  }
  pnlRenderColunasOrdem(opcoesCombinadas);
}
// lista dos links já configurados no form (fonte 'linhas'), com botão de remover
function pnlRenderLinksLista(){
  const cont = document.getElementById('pnlNovoWidgetLinksLista');
  if(!cont) return;
  cont.innerHTML = pnlFormLinksAtual.length ? pnlFormLinksAtual.map((l,i)=>`
    <div style="display:flex;align-items:center;gap:6px;font-size:12.5px;padding:2px 0;">
      <span>${escaparHtml(l.campoPrincipal)} = ${escaparHtml(pnlNomeConsulta(l.consultaId))}.${escaparHtml(l.campoLink)}</span>
      <button type="button" data-removerlink="${i}" title="Remover link" style="background:none;border:none;color:var(--bad);cursor:pointer;font-size:14px;line-height:1;padding:2px;">✕</button>
    </div>`).join('') : `<div class="empty" style="padding:2px 0;font-size:12px;">Nenhum link configurado ainda.</div>`;
}
// popula os selects do form "+ Adicionar link" (consulta secundária +
// campo desta consulta principal); chamado sempre que a Consulta
// principal ou a fonte do widget mudam
function pnlPopularFormNovoLink(consultaIdPrincipal){
  const selConsulta = document.getElementById('pnlNovoWidgetLinkConsulta');
  if(!selConsulta) return;
  const outras = pnlConsultasCarregadas.filter(c=>c.id!==consultaIdPrincipal);
  const atual = selConsulta.value;
  selConsulta.innerHTML = outras.map(c=>`<option value="${escaparHtml(c.id)}">${escaparHtml(c.nome)}</option>`).join('') || `<option value="">(nenhuma outra consulta carregada)</option>`;
  if(outras.some(c=>c.id===atual)) selConsulta.value = atual;
  const selCampoPrincipal = document.getElementById('pnlNovoWidgetLinkCampoPrincipal');
  const atualCampo = selCampoPrincipal.value;
  const camposPrincipal = pnlColunasDisponiveis(consultaIdPrincipal);
  selCampoPrincipal.innerHTML = camposPrincipal.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
  if(camposPrincipal.includes(atualCampo)) selCampoPrincipal.value = atualCampo;
  pnlAtualizarCampoLinkSecundario();
}
function pnlAtualizarCampoLinkSecundario(){
  const consultaSecundaria = document.getElementById('pnlNovoWidgetLinkConsulta').value;
  const selCampoLink = document.getElementById('pnlNovoWidgetLinkCampoLink');
  if(!selCampoLink) return;
  const atual = selCampoLink.value;
  const campos = consultaSecundaria ? pnlColunasDisponiveis(consultaSecundaria) : [];
  selCampoLink.innerHTML = campos.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
  if(campos.includes(atual)) selCampoLink.value = atual;
}
/* ---------- widget "relatorio": construtor de Subdetalhes no form ---------- */
function pnlRenderSubdetalhesLista(){
  const cont = document.getElementById('pnlNovoWidgetSubdetalhesLista');
  if(!cont) return;
  cont.innerHTML = pnlFormSubdetalhesAtual.length ? pnlFormSubdetalhesAtual.map((sd,i)=>`
    <div style="display:flex;align-items:center;gap:6px;font-size:12.5px;padding:4px 0;border-bottom:1px solid var(--line);${pnlEditandoSubdetalheIndex===i?'background:var(--highlight,#fff3cd);':''}">
      <span style="flex:1;"><b>${escaparHtml(sd.titulo||'(sem título)')}</b> · ${escaparHtml(pnlNomeConsulta(sd.consultaId))} · ${escaparHtml(sd.campoPrincipal)} = ${escaparHtml(sd.campoLink)} · ${sd.colunas.length} coluna${sd.colunas.length===1?'':'s'}${sd.fonte==='agrupado'?` · agrupado por ${escaparHtml(sd.dimensao)}`:''}</span>
      <button type="button" data-editarsubdetalhe="${i}" title="Editar subdetalhe" style="background:none;border:none;color:var(--accent,#2563eb);cursor:pointer;font-size:14px;line-height:1;padding:2px;">✎</button>
      <button type="button" data-removersubdetalhe="${i}" title="Remover subdetalhe" style="background:none;border:none;color:var(--bad);cursor:pointer;font-size:14px;line-height:1;padding:2px;">✕</button>
    </div>`).join('') : `<div class="empty" style="padding:2px 0;font-size:12px;">Nenhum subdetalhe adicionado ainda.</div>`;
}
function pnlRenderSubdetalheColunasPicker(consultaSub){
  const cont = document.getElementById('pnlNovoWidgetSubdetalheColunasLista');
  if(!cont) return;
  const marcadas = new Set(pnlFormSubdetalheColunasAtual);
  const campos = consultaSub ? pnlColunasTabelaDisponiveis(consultaSub) : {};
  cont.innerHTML = Object.entries(campos).map(([k,v])=>`<label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:normal;">
      <input type="checkbox" data-wsubcoluna value="${escaparHtml(k)}" ${marcadas.has(k)?'checked':''} style="width:auto;"> ${escaparHtml(v)}
    </label>`).join('') || `<div class="empty" style="padding:2px 0;">Escolha uma consulta primeiro.</div>`;
}
// lista html de critérios {campo,direcao} já adicionados — "opcoes" é o
// catálogo chave->label (ou chave->{label}) pra mostrar o rótulo certo,
// reaproveitado tanto pro Detalhe quanto pra cada Subdetalhe
function pnlRenderCriteriosOrdenacaoHtml(criterios, opcoes, removerAttr){
  if(!criterios.length) return `<div class="empty" style="padding:2px 0;font-size:12px;">Nenhum critério, mantém a ordem original.</div>`;
  return criterios.map((cr,i)=>{
    const v = opcoes[cr.campo];
    const label = typeof v === 'string' ? v : (v ? v.label : cr.campo);
    return `<div style="display:flex;align-items:center;gap:6px;font-size:12.5px;padding:3px 0;border-bottom:1px solid var(--line);">
      <span style="flex:1;">${i+1}. ${escaparHtml(label)} ${cr.direcao==='desc'?'↓ decrescente':'↑ crescente'}${cr.quebra?' · <b>quebra (subtotal)</b>':''}</span>
      <button type="button" data-${removerAttr}="${i}" title="Remover critério" style="background:none;border:none;color:var(--bad);cursor:pointer;font-size:14px;line-height:1;padding:2px;">✕</button>
    </div>`;
  }).join('');
}
function pnlRenderOrdenacaoLista(){
  const cont = document.getElementById('pnlNovoWidgetOrdenacaoLista');
  if(!cont) return;
  const catalogo = pnlColunasTabelaDisponiveis(pnlConsultaSelecionadaNoForm());
  cont.innerHTML = pnlRenderCriteriosOrdenacaoHtml(pnlFormOrdenacaoAtual, catalogo, 'removerordenacao');
}
function pnlRenderSubdetalheOrdenacaoLista(){
  const cont = document.getElementById('pnlNovoWidgetSubdetalheOrdenacaoLista');
  if(!cont) return;
  const consultaSub = document.getElementById('pnlNovoWidgetSubdetalheConsulta')?.value;
  const catalogo = consultaSub ? pnlColunasTabelaDisponiveis(consultaSub) : {};
  cont.innerHTML = pnlRenderCriteriosOrdenacaoHtml(pnlFormSubdetalheOrdenacaoAtual, catalogo, 'removersubdetalheordenacao');
}
function pnlRenderSubdetalheTotaisPicker(){
  const cont = document.getElementById('pnlNovoWidgetSubdetalheTotaisLista');
  if(!cont) return;
  const consultaSub = document.getElementById('pnlNovoWidgetSubdetalheConsulta')?.value;
  const catalogo = consultaSub ? pnlColunasTabelaDisponiveis(consultaSub) : {};
  const marcadas = new Set(pnlFormSubdetalheTotaisAtual);
  cont.innerHTML = pnlFormSubdetalheColunasAtual.length
    ? pnlFormSubdetalheColunasAtual.map(c=>`<label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:normal;">
        <input type="checkbox" data-wsubtotal value="${escaparHtml(c)}" ${marcadas.has(c)?'checked':''} style="width:auto;"> ${escaparHtml(catalogo[c]||c)}
      </label>`).join('')
    : `<div class="empty" style="padding:2px 0;">Escolha as colunas do subdetalhe primeiro.</div>`;
}
function pnlRenderSubdetalheApelidosPicker(){
  const cont = document.getElementById('pnlNovoWidgetSubdetalheApelidosLista');
  if(!cont) return;
  const consultaSub = document.getElementById('pnlNovoWidgetSubdetalheConsulta')?.value;
  const catalogo = consultaSub ? pnlColunasTabelaDisponiveis(consultaSub) : {};
  cont.innerHTML = pnlFormSubdetalheColunasAtual.length
    ? pnlFormSubdetalheColunasAtual.map(c=>{
        const label = catalogo[c]||c;
        return `<div style="display:flex;align-items:center;gap:6px;">
          <span style="font-size:12px;flex:0 0 auto;min-width:100px;">${escaparHtml(label)}</span>
          <input type="text" data-subapelidocoluna="${escaparHtml(c)}" value="${escaparHtml(pnlFormSubdetalheColunasApelidos[c]||'')}" placeholder="${escaparHtml(label)}" style="flex:1;font-size:12px;padding:3px 6px;">
        </div>`;
      }).join('')
    : `<div class="empty" style="padding:2px 0;">Escolha as colunas do subdetalhe primeiro.</div>`;
}
function pnlAtualizarCamposSubdetalhe(){
  const consultaIdPrincipal = pnlConsultaSelecionadaNoForm();
  const selCampoPrincipal = document.getElementById('pnlNovoWidgetSubdetalheCampoPrincipal');
  if(!selCampoPrincipal) return;
  selCampoPrincipal.innerHTML = pnlColunasDisponiveis(consultaIdPrincipal).map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
  const consultaSub = document.getElementById('pnlNovoWidgetSubdetalheConsulta').value;
  const selCampoLink = document.getElementById('pnlNovoWidgetSubdetalheCampoLink');
  const camposSub = consultaSub ? pnlColunasDisponiveis(consultaSub) : [];
  selCampoLink.innerHTML = camposSub.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
  const fonteSub = document.getElementById('pnlNovoWidgetSubdetalheFonte').value || 'linhas';
  const ehSubAgrupado = fonteSub === 'agrupado';
  document.getElementById('pnlNovoWidgetSubdetalheCampoDimensao').style.display = ehSubAgrupado ? '' : 'none';
  document.getElementById('pnlNovoWidgetSubdetalheCampoDimensao2').style.display = ehSubAgrupado ? '' : 'none';
  document.getElementById('pnlNovoWidgetSubdetalheCampoDimensao3').style.display = ehSubAgrupado ? '' : 'none';
  if(ehSubAgrupado){
    const selDim = document.getElementById('pnlNovoWidgetSubdetalheDimensao');
    const atualDim = selDim.value;
    selDim.innerHTML = camposSub.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
    if(camposSub.includes(atualDim)) selDim.value = atualDim;
    const selDim2 = document.getElementById('pnlNovoWidgetSubdetalheDimensao2');
    const selDim3 = document.getElementById('pnlNovoWidgetSubdetalheDimensao3');
    const atualDim2 = selDim2.value, atualDim3 = selDim3.value;
    const opcoesExtra = `<option value="">(nenhum)</option>` + camposSub.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
    selDim2.innerHTML = opcoesExtra;
    selDim3.innerHTML = opcoesExtra;
    if(camposSub.includes(atualDim2)) selDim2.value = atualDim2;
    if(camposSub.includes(atualDim3)) selDim3.value = atualDim3;
  }
  const labelColunasSub = document.getElementById('pnlNovoWidgetSubdetalheLabelColunas');
  if(labelColunasSub) labelColunasSub.textContent = ehSubAgrupado ? 'Colunas (soma automática quando numéricas)' : 'Colunas deste subdetalhe';
  pnlRenderSubdetalheColunasPicker(consultaSub);
  const selOrdenacaoSub = document.getElementById('pnlNovoWidgetSubdetalheOrdenacaoCampo');
  if(selOrdenacaoSub) selOrdenacaoSub.innerHTML = camposSub.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
  pnlRenderSubdetalheOrdenacaoLista();
  pnlRenderSubdetalheTotaisPicker();
  pnlRenderSubdetalheApelidosPicker();
}
function pnlPopularFormNovoSubdetalhe(){
  const selConsulta = document.getElementById('pnlNovoWidgetSubdetalheConsulta');
  if(!selConsulta) return;
  const atual = selConsulta.value;
  selConsulta.innerHTML = pnlConsultasCarregadas.map(c=>`<option value="${escaparHtml(c.id)}">${escaparHtml(c.nome)}</option>`).join('');
  if(pnlConsultasCarregadas.some(c=>c.id===atual)) selConsulta.value = atual;
  pnlAtualizarCamposSubdetalhe();
}
function pnlHtmlToolbar(w, i, total){
  if(!pnlModoEdicao) return '';
  // no canvas livre a posição é por arrastar, não por ordem da lista — o
  // cima/baixo não faz sentido ali (ver pnlMontarCanvasHtml pras alças)
  const moverHtml = pnlModoCanvas ? '' : `
    <button type="button" data-wtoolbar="up" data-wid="${w.id}" ${i===0?'disabled':''} title="Mover pra cima">↑</button>
    <button type="button" data-wtoolbar="down" data-wid="${w.id}" ${i===total-1?'disabled':''} title="Mover pra baixo">↓</button>`;
  return `<div class="recebwidget-toolbar">${moverHtml}
    <button type="button" data-wtoolbar="editar" data-wid="${w.id}" title="Editar">✎</button>
    <button type="button" data-wtoolbar="duplicar" data-wid="${w.id}" title="Duplicar">⧉</button>
    <button type="button" data-wtoolbar="remover" data-wid="${w.id}" title="Remover">✕</button>
  </div>`;
}
// atributo style="..." (ou "") pra aplicar a cor de borda/fundo custom de um
// widget, se configuradas (w.corBorda/w.corFundo) — mesmo helper serve pro
// wrapper de qualquer tipo e pro .box do KPI (ver pnlRenderWidgetKpi), que é
// quem de fato tem a aparência de "cartão" nesse tipo
function pnlEstiloCorWidget(w, extraCss){
  let css = extraCss || '';
  if(w.corBorda) css += `border:2px solid ${w.corBorda};`;
  if(w.corFundo) css += `background:${w.corFundo};`;
  if(w.bordaEstilo==='reta') css += 'border-radius:0;';
  else if(w.bordaEstilo==='levemente') css += 'border-radius:6px;';
  else if(w.bordaEstilo==='arredondada') css += 'border-radius:16px;';
  return css ? ` style="${css}"` : '';
}
// estilo de texto (título do widget ou valor do Indicador) — mesmo formato
// {alinhamento, tamanho, negrito, italico, sublinhado} pros dois casos.
// pnlCssEstiloTexto devolve só o fragmento CSS (pra misturar com outro
// style já existente, ex: o <h2> do widget Filtro); pnlAtributoEstiloTexto
// devolve o atributo style="..." pronto (ou '' se não tem nada configurado)
function pnlCssEstiloTexto(estilo){
  if(!estilo) return '';
  let css = '';
  if(estilo.alinhamento) css += `text-align:${estilo.alinhamento};`;
  if(estilo.tamanho) css += `font-size:${estilo.tamanho}px;`;
  if(estilo.negrito) css += 'font-weight:700;';
  if(estilo.italico) css += 'font-style:italic;';
  if(estilo.sublinhado) css += 'text-decoration:underline;';
  return css;
}
function pnlAtributoEstiloTexto(estilo){
  const css = pnlCssEstiloTexto(estilo);
  return css ? ` style="${css}"` : '';
}
// tamanho de fonte das linhas de tabela (widget Tabela/Relatório) — aplicado
// no próprio <table>, não em cada <td>: o cabeçalho (th) tem font-size
// próprio no CSS (.valores-table th) e continua do tamanho de sempre,
// só o corpo (que herda da tabela) muda de tamanho
function pnlAtributoFonteLinhasTabela(widget){
  return widget && widget.tamanhoFonteLinhas ? ` style="font-size:${widget.tamanhoFonteLinhas}px;"` : '';
}
// formulário de estilo de texto: mesmos 5 campos (alinhamento/tamanho/
// negrito/itálico/sublinhado) servem pro "Título" de qualquer widget e,
// só no Indicador, também pro "Valor" — prefixo é 'Titulo' ou 'Valor'
function pnlResetEstiloTextoForm(prefixo){
  document.getElementById(`pnlNovoWidget${prefixo}Alinhamento`).value = '';
  document.getElementById(`pnlNovoWidget${prefixo}Tamanho`).value = '';
  document.getElementById(`pnlNovoWidget${prefixo}Negrito`).checked = false;
  document.getElementById(`pnlNovoWidget${prefixo}Italico`).checked = false;
  document.getElementById(`pnlNovoWidget${prefixo}Sublinhado`).checked = false;
}
function pnlCarregarEstiloTextoForm(prefixo, estilo){
  document.getElementById(`pnlNovoWidget${prefixo}Alinhamento`).value = (estilo && estilo.alinhamento) || '';
  document.getElementById(`pnlNovoWidget${prefixo}Tamanho`).value = (estilo && estilo.tamanho) || '';
  document.getElementById(`pnlNovoWidget${prefixo}Negrito`).checked = !!(estilo && estilo.negrito);
  document.getElementById(`pnlNovoWidget${prefixo}Italico`).checked = !!(estilo && estilo.italico);
  document.getElementById(`pnlNovoWidget${prefixo}Sublinhado`).checked = !!(estilo && estilo.sublinhado);
}
function pnlLerEstiloTextoForm(prefixo){
  const alinhamento = document.getElementById(`pnlNovoWidget${prefixo}Alinhamento`).value;
  const tamanho = document.getElementById(`pnlNovoWidget${prefixo}Tamanho`).value;
  const negrito = document.getElementById(`pnlNovoWidget${prefixo}Negrito`).checked;
  const italico = document.getElementById(`pnlNovoWidget${prefixo}Italico`).checked;
  const sublinhado = document.getElementById(`pnlNovoWidget${prefixo}Sublinhado`).checked;
  const estilo = {};
  if(alinhamento) estilo.alinhamento = alinhamento;
  if(tamanho) estilo.tamanho = Number(tamanho);
  if(negrito) estilo.negrito = true;
  if(italico) estilo.italico = true;
  if(sublinhado) estilo.sublinhado = true;
  return Object.keys(estilo).length ? estilo : null;
}
function pnlHtmlWidget(w, i, total){
  const toolbar = pnlHtmlToolbar(w, i, total);
  const classeEdit = pnlModoEdicao ? ' editando' : '';
  const estiloAltura = recebEstiloAlturaScroll(w);
  if(w.tipo === 'tabela'){
    const buscaHtml = w.fonte !== 'agrupado' ? `<input type="search" data-wbusca data-wid="${w.id}" placeholder="Buscar..." style="margin-bottom:10px;">` : '';
    const filtroRapidoHtml = (w.fonte !== 'agrupado' && w.filtroRapido) ? `<div class="filters" id="pnl-${w.id}-filtrorapido"></div>` : '';
    return `<div class="card recebwidget${classeEdit}" data-wid="${w.id}"${pnlEstiloCorWidget(w)}>${toolbar}
      <h2${pnlAtributoEstiloTexto(w.estiloTitulo)}>${escaparHtml(pnlWidgetTitulo(w))}</h2>
      ${filtroRapidoHtml}
      ${buscaHtml}
      <div style="overflow-x:auto;${estiloAltura}"><table class="valores-table" id="pnl-${w.id}-tabela"${pnlAtributoFonteLinhasTabela(w)}></table></div>
    </div>`;
  }
  if(w.tipo === 'relatorio'){
    const filtroRapidoHtml = (w.fonte !== 'agrupado' && w.filtroRapido) ? `<div class="filters" id="pnl-${w.id}-filtrorapido"></div>` : '';
    return `<div class="card recebwidget${classeEdit}" data-wid="${w.id}"${pnlEstiloCorWidget(w)}>${toolbar}
      <h2${pnlAtributoEstiloTexto(w.estiloTitulo)}>${escaparHtml(pnlWidgetTitulo(w))}</h2>
      ${filtroRapidoHtml}
      <div style="overflow-x:auto;${estiloAltura}" id="pnl-${w.id}-conteudo"></div>
    </div>`;
  }
  if(w.tipo === 'kpi'){
    return `<div class="recebwidget${classeEdit}" data-wid="${w.id}">${toolbar}<div id="pnl-${w.id}-conteudo"></div></div>`;
  }
  if(w.tipo === 'filtro'){
    const campo = w.campo;
    const label = pnlWidgetTitulo(w);
    // o gatilho ▾ fica colado no texto do título (não espalhado até a
    // borda direita do card) pra nunca ficar embaixo da toolbar de
    // edição, que é absoluta no canto superior direito (ver .recebwidget-toolbar)
    return `<div class="card recebwidget${classeEdit}" data-wid="${w.id}"${pnlEstiloCorWidget(w)}>${toolbar}
      <h2 style="display:flex;align-items:center;gap:6px;${pnlCssEstiloTexto(w.estiloTitulo)}">${escaparHtml(label)}<span data-rfiltro="${escaparHtml(campo)}" style="cursor:pointer;font-weight:400;text-transform:none;font-size:14px;" title="Filtrar ${escaparHtml(label)}">▾</span></h2>
      <div style="font-size:12.5px;color:var(--muted);margin-top:8px;" data-resumo-filtro="${escaparHtml(campo)}">${pnlResumoFiltroConteudoHtml(campo)}</div>
    </div>`;
  }
  if(w.tipo === 'titulo'){
    const icone = w.icone ? `<span class="pnl-container-icone">${escaparHtml(w.icone)}</span>` : '';
    const estiloTextoAttr = pnlAtributoEstiloTexto(w.estiloTitulo);
    const sub = w.subtitulo ? `<div class="sub"${estiloTextoAttr}>${escaparHtml(w.subtitulo)}</div>` : '';
    return `<div class="pnl-container-titulo recebwidget${classeEdit}" data-wid="${w.id}"${pnlEstiloCorWidget(w)}>${toolbar}
      ${icone}<div class="pnl-container-textos"><h2${estiloTextoAttr}>${escaparHtml(pnlWidgetTitulo(w))}</h2>${sub}</div>
    </div>`;
  }
  if(w.tipo === 'container'){
    const guias = (w.guias && w.guias.length) ? w.guias : [{ id:'_unica', titulo:'' }];
    const guiaAtiva = (pnlContainerGuiaAtiva[w.id] && guias.some(g=>g.id===pnlContainerGuiaAtiva[w.id])) ? pnlContainerGuiaAtiva[w.id] : guias[0].id;
    const tabsHtml = guias.length > 1 ? `<div class="subtabs" data-containertabs="${w.id}">${guias.map(g=>`<div class="subtab ${g.id===guiaAtiva?'active':''}" data-containerguia="${w.id}::${g.id}">${escaparHtml(g.titulo)}</div>`).join('')}</div>` : '';
    const filhos = pnlPainelWidgets.filter(c=>c.containerId===w.id);
    const corposGuias = guias.map(g=>{
      const filhosDaGuia = filhos.filter(f=>(f.guiaId||guias[0].id)===g.id);
      const corpo = pnlMontarGradeHtml(filhosDaGuia) || `<div class="empty" style="padding:12px 0;">Nenhum widget nessa guia ainda.</div>`;
      return `<div class="pnl-grade-wrap" data-containerguiaconteudo="${w.id}::${g.id}" style="${g.id===guiaAtiva?'':'display:none;'}">${corpo}</div>`;
    }).join('');
    return `<div class="card recebwidget${classeEdit}" data-wid="${w.id}"${pnlEstiloCorWidget(w)}>${toolbar}
      <h2${pnlAtributoEstiloTexto(w.estiloTitulo)}>${escaparHtml(pnlWidgetTitulo(w))}</h2>
      ${tabsHtml}
      ${corposGuias}
    </div>`;
  }
  // barra-h ignora o "height" do dashBarChart (altura sempre nasce do
  // número de linhas) — "Altura" vira um teto com rolagem, igual na tabela
  const estiloAlturaRanking = w.tipo==='barra-h' ? estiloAltura : '';
  return `<div class="card recebwidget${classeEdit}" data-wid="${w.id}"${pnlEstiloCorWidget(w, w.tipo==='linha'?'overflow-x:auto;':'')}>${toolbar}
    <h2${pnlAtributoEstiloTexto(w.estiloTitulo)}>${escaparHtml(pnlWidgetTitulo(w))}</h2>
    <div id="pnl-${w.id}-conteudo" style="margin-top:8px;${estiloAlturaRanking}"></div>
  </div>`;
}
// monta o HTML de uma grade (nível principal do painel, ou a guia de um
// Container) — mesma regra em qualquer nível: KPIs seguidos agrupam numa
// única linha "summary", os demais widgets respeitam a Largura escolhida
function pnlMontarGradeHtml(ws){
  let html = '', i = 0;
  while(i < ws.length){
    if(ws[i].tipo === 'kpi'){
      let j = i, grupoHtml = '';
      while(j < ws.length && ws[j].tipo === 'kpi'){ grupoHtml += pnlHtmlWidget(ws[j], j, ws.length); j++; }
      html += `<div style="flex:1 1 100%;min-width:0;"><div class="summary">${grupoHtml}</div></div>`;
      i = j;
    }else{
      const largura = RECEB_LARGURAS_WIDGET[ws[i].largura] || RECEB_LARGURAS_WIDGET.completa;
      html += `<div style="flex:0 1 ${largura};min-width:280px;">${pnlHtmlWidget(ws[i], i, ws.length)}</div>`;
      i++;
    }
  }
  return html;
}
// só conta como "painel em canvas" quando TODO widget de nível principal já
// tem uma posição válida — enquanto isso não acontecer (painel nunca editado
// em canvas, ou widget novo ainda sem posição), cai pra grade de sempre
function pnlWidgetTemCanvasValido(w){
  return !!w.canvas && Number.isFinite(w.canvas.x) && Number.isFinite(w.canvas.y) && Number.isFinite(w.canvas.w) && Number.isFinite(w.canvas.h);
}
// Filtro/Indicador/Título são só uma ou duas linhas de texto (rótulo,
// número ou título+subtítulo) — não precisam dos 120px de altura mínima
// que um gráfico/tabela exige pra ficar legível, então ganham um mínimo
// bem mais baixo no canvas livre; Título é só 1 linha de texto na prática
// (mesmo com subtítulo, o conteúdo pode passar um pouco do box, que não
// corta — ver .pnl-canvas-item, sem overflow:hidden), então o mínimo dele
// é ainda mais apertado que o de Filtro/Indicador
function pnlCanvasAlturaMinima(tipo){
  if(tipo==='titulo') return 32;
  return (tipo==='filtro' || tipo==='kpi') ? 60 : 120;
}
function pnlPainelUsaCanvas(topo){
  return topo.length>0 && topo.every(pnlWidgetTemCanvasValido);
}
// canvas livre é só pra tela larga — no celular a grade de hoje já reflui
// sozinha, então é sempre ela; a edição do canvas (pnlModoCanvas) é decisão
// explícita do admin e vale mesmo se a tela ficar momentaneamente estreita
function pnlTelaLargaParaCanvas(){
  return window.matchMedia('(min-width: 900px)').matches;
}
// gera uma posição padrão (grade 2 colunas) só pros widgets que AINDA não
// têm uma — os que já têm posição (de uma edição anterior) não são mexidos
function pnlGerarCanvasPadraoSeNecessario(){
  const topo = pnlPainelWidgets.filter(w=>!w.containerId || !pnlPainelWidgets.some(c=>c.id===w.containerId && c.tipo==='container'));
  const colunas = 2, largura = 380, altura = 260, gap = 20;
  topo.forEach((w,i)=>{
    if(pnlWidgetTemCanvasValido(w)) return;
    const col = i % colunas, lin = Math.floor(i / colunas);
    w.canvas = { x: 20 + col*(largura+gap), y: 20 + lin*(altura+gap), w: largura, h: altura };
  });
}
function pnlMontarCanvasHtml(ws){
  if(!ws.length) return '';
  let maxX = 600, maxY = 400;
  ws.forEach(w=>{
    const c = w.canvas || { x:20, y:20, w:360, h:240 };
    maxX = Math.max(maxX, c.x + c.w + 20);
    maxY = Math.max(maxY, c.y + c.h + 20);
  });
  const itensHtml = ws.map((w,i)=>{
    const c = w.canvas || { x:20, y:20, w:360, h:240 };
    const alcasHtml = pnlModoCanvas ? `
      <div class="pnl-canvas-alca" data-canvasarrastar data-wid="${w.id}" title="Arrastar">⣿</div>
      <div class="pnl-canvas-resize" data-canvasredimensionar data-wid="${w.id}" title="Redimensionar"></div>` : '';
    return `<div class="pnl-canvas-item" data-canvasitem data-wid="${w.id}" style="left:${c.x}px;top:${c.y}px;width:${c.w}px;height:${c.h}px;">${pnlHtmlWidget(w, i, ws.length)}${alcasHtml}</div>`;
  }).join('');
  return `<div class="pnl-canvas-superficie${pnlModoCanvas?' editando':''}" style="width:${maxX}px;height:${maxY}px;">${itensHtml}</div>`;
}
// durante o arrastar/redimensionar, só muda o style do item na tela (não
// refaz o HTML) — refazer o innerHTML a cada pixel destruiria os gráficos
// SVG já desenhados e deixaria o arrastar com saltos
function pnlAtualizarPosicaoCanvasNaTela(id){
  const w = pnlPainelWidgets.find(x=>x.id===id);
  if(!w || !w.canvas) return;
  const el = document.querySelector(`#pnlGradeWidgets [data-canvasitem][data-wid="${CSS.escape(id)}"]`);
  if(el){
    el.style.left = w.canvas.x+'px';
    el.style.top = w.canvas.y+'px';
    el.style.width = w.canvas.w+'px';
    el.style.height = w.canvas.h+'px';
  }
}
function pnlCanvasIniciarArraste(id, e){
  const w = pnlPainelWidgets.find(x=>x.id===id);
  if(!w || !pnlWidgetTemCanvasValido(w)) return;
  pnlCanvasArrastando = { id, startMouseX:e.clientX, startMouseY:e.clientY, startX:w.canvas.x, startY:w.canvas.y };
}
function pnlCanvasIniciarRedimensionar(id, e){
  const w = pnlPainelWidgets.find(x=>x.id===id);
  if(!w || !pnlWidgetTemCanvasValido(w)) return;
  pnlCanvasRedimensionando = { id, startMouseX:e.clientX, startMouseY:e.clientY, startW:w.canvas.w, startH:w.canvas.h };
}
function pnlCanvasMoverArraste(e){
  const info = pnlCanvasArrastando;
  const w = pnlPainelWidgets.find(x=>x.id===info.id);
  if(!w) return;
  const dx = e.clientX-info.startMouseX, dy = e.clientY-info.startMouseY;
  w.canvas.x = Math.max(0, Math.round((info.startX+dx)/8)*8);
  w.canvas.y = Math.max(0, Math.round((info.startY+dy)/8)*8);
  pnlAtualizarPosicaoCanvasNaTela(w.id);
}
function pnlCanvasMoverRedimensionar(e){
  const info = pnlCanvasRedimensionando;
  const w = pnlPainelWidgets.find(x=>x.id===info.id);
  if(!w) return;
  const dx = e.clientX-info.startMouseX, dy = e.clientY-info.startMouseY;
  w.canvas.w = Math.max(200, Math.round((info.startW+dx)/8)*8);
  w.canvas.h = Math.max(pnlCanvasAlturaMinima(w.tipo), Math.round((info.startH+dy)/8)*8);
  pnlAtualizarPosicaoCanvasNaTela(w.id);
}
// retrair/expandir o corpo de um card (Medidas, Widgets, Propriedades) —
// só esconde o conteúdo, o cabeçalho com o botão continua visível pra
// expandir de novo; estado fica só na seta do botão, não precisa de
// variável separada (menos uma coisa pra dessincronizar do DOM)
function pnlAlternarRetrairCard(idCorpo, idBotao){
  const corpo = document.getElementById(idCorpo);
  const botao = document.getElementById(idBotao);
  if(!corpo || !botao) return;
  const retraindo = corpo.style.display !== 'none';
  corpo.style.display = retraindo ? 'none' : '';
  botao.textContent = retraindo ? '▸' : '▾';
}
// no canvas livre, a barra lateral alterna entre a paleta de tipos (ponto
// de partida) e o formulário de sempre (pra configurar o widget escolhido)
// — fora do canvas, o formulário fica sempre visível, igual sempre foi
function pnlCanvasMostrarPaleta(){
  if(!pnlModoCanvas) return;
  document.getElementById('pnlCanvasPaleta').style.display = '';
  document.getElementById('pnlCardAddWidget').style.display = 'none';
}
function pnlCanvasMostrarForm(){
  if(!pnlModoCanvas) return;
  document.getElementById('pnlCanvasPaleta').style.display = 'none';
  document.getElementById('pnlCardAddWidget').style.display = '';
  document.getElementById('btnPnlCanvasVoltarPaleta').style.display = '';
}
function pnlCanvasEscolherTipoNaPaleta(tipo){
  pnlResetFormNovoWidget();
  document.getElementById('pnlNovoWidgetTipo').value = tipo;
  pnlAtualizarCamposNovoWidget();
  pnlCanvasMostrarForm();
}
function pnlAlternarModoCanvas(){
  if(!pnlModoCanvas) pnlGerarCanvasPadraoSeNecessario();
  pnlModoCanvas = !pnlModoCanvas;
  document.getElementById('btnPnlModoCanvas').classList.toggle('on', pnlModoCanvas);
  document.getElementById('pnlCanvasLayoutWrap').classList.toggle('pnl-canvas-modo-ativo', pnlModoCanvas);
  if(pnlModoCanvas) pnlCanvasMostrarPaleta();
  else{
    document.getElementById('pnlCanvasPaleta').style.display = 'none';
    document.getElementById('pnlCardAddWidget').style.display = '';
    document.getElementById('btnPnlCanvasVoltarPaleta').style.display = 'none';
  }
  pnlAtualizarCamposNovoWidget();
  pnlRenderEsqueleto();
  pnlRenderConteudo();
}
function pnlRenderEsqueleto(){
  const grade = document.getElementById('pnlGradeWidgets');
  // só os widgets de "nível principal" — quem tem containerId resolvendo
  // pra um container de verdade é desenhado DENTRO dele (ver pnlHtmlWidget
  // tipo 'container'); se o container foi removido, cai de volta pro nível
  // principal em vez de simplesmente sumir
  const topo = pnlPainelWidgets.filter(w=>!w.containerId || !pnlPainelWidgets.some(c=>c.id===w.containerId && c.tipo==='container'));
  if(!topo.length){ grade.innerHTML = `<div class="empty">Nenhum widget nesse painel ainda. Clique em "⚙ Configurar painel" pra adicionar.</div>`; return; }
  const usaCanvas = pnlModoCanvas || (pnlPainelUsaCanvas(topo) && pnlTelaLargaParaCanvas());
  grade.innerHTML = usaCanvas ? pnlMontarCanvasHtml(topo) : pnlMontarGradeHtml(topo);
}
// cada widget lê de UMA consulta (widget.consultaId — ou a 1ª carregada,
// pra widget salvo antes dessa configuração existir); por isso cada um
// calcula sua própria lista já filtrada, em vez de todos dividirem a
// mesma "linhas" de antes
function pnlRenderConteudo(){
  pnlPainelWidgets.forEach(w=>{
    // Título/Container não têm dado pra buscar nem um "pnl-{id}-conteudo"
    // próprio — já saem inteiros do esqueleto (pnlHtmlWidget)
    if(w.tipo==='titulo' || w.tipo==='container' || w.tipo==='filtro') return;
    const consultaId = w.consultaId || pnlConsultaPadrao();
    const linhas = pnlFiltrados(consultaId);
    pnlUltimoLinhasFiltradasPorWidget[w.id] = linhas;
    if(w.tipo==='kpi') pnlRenderWidgetKpi(`pnl-${w.id}-conteudo`, w, linhas);
    else if(w.tipo==='tabela') pnlRenderWidgetTabelaPersonalizada(w, linhas);
    else if(w.tipo==='relatorio') pnlRenderWidgetRelatorio(`pnl-${w.id}-conteudo`, w, linhas);
    else if(w.tipo==='curvaabc') pnlRenderWidgetCurvaAbc(`pnl-${w.id}-conteudo`, w, linhas);
    else if(w.tipo==='mapa') pnlRenderWidgetMapa(`pnl-${w.id}-conteudo`, w, linhas);
    else pnlRenderWidgetGrafico(`pnl-${w.id}-conteudo`, w, linhas, w.tipo);
  });
}
// true se existe pelo menos 1 valor marcado em algum filtro (geral ou
// registrado por clique-pra-filtrar) — usado só pra habilitar/desabilitar
// o botão "Limpar filtros"
function pnlTemAlgumFiltroAtivo(){
  return Object.values(pnlFiltros).some(set=>set && set.size>0);
}
function pnlLimparTodosFiltros(){
  pnlFiltros = {};
  pnlRender();
}
function pnlRender(){
  const temDados = pnlConsultasCarregadas.length > 0;
  document.getElementById('pnlCardGradeTopo').style.display = temDados ? '' : 'none';
  document.getElementById('btnPnlExportarExcel').style.display = temDados ? '' : 'none';
  document.getElementById('btnPnlExportarCsv').style.display = (temDados && pnlConsultasCarregadas.length===1) ? '' : 'none';
  document.getElementById('btnPnlExportarMontado').style.display = (temDados && pnlPainelWidgets.length>0) ? '' : 'none';
  document.getElementById('btnPnlLimparFiltros').disabled = !pnlTemAlgumFiltroAtivo();
  if(temDados){
    const resumo = pnlConsultasCarregadas.map(c=>`${c.nome}: ${(pnlDadosPorConsulta[c.id]||[]).length} linha${(pnlDadosPorConsulta[c.id]||[]).length===1?'':'s'}`).join(' · ');
    document.getElementById('pnlBaseInfo').textContent = `${resumo}.`;
  }else{
    document.getElementById('pnlBaseInfo').textContent = 'Nenhum dado ainda. Escolha um cliente e clique em "Atualizar do RM".';
  }
  const pnlUltimaAtualizacaoEl = document.getElementById('pnlUltimaAtualizacao');
  pnlUltimaAtualizacaoEl.style.display = temDados ? '' : 'none';
  if(temDados) pnlUltimaAtualizacaoEl.querySelector('span').textContent = new Date(pnlInfo.quando).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'});
  if(!temDados){ document.getElementById('pnlGradeWidgets').innerHTML = ''; return; }
  pnlRenderFiltros();
  pnlRenderEsqueleto();
  pnlRenderConteudo();
}

/* ---------- exportar Excel/CSV ---------- */
// uma aba (sheet) por consulta carregada — cada uma com suas próprias
// colunas e já filtrada pelos filtros gerais que fizerem sentido nela
function pnlMontarAbasExportacao(){
  return pnlConsultasCarregadas.map(c=>{
    const linhas = pnlFiltrados(c.id);
    const colunas = pnlColunasDisponiveis(c.id);
    const corpo = linhas.map(o=>colunas.map(col=>{ const v = o[col]; return v==null ? '' : v; }));
    return { nome: c.nome, cabecalho: colunas, corpo, totalLinhas: linhas.length };
  }).filter(aba=>aba.totalLinhas>0);
}
// exportação em CSV (1 arquivo só) — só funciona com 1 consulta carregada,
// já que CSV não tem conceito de "aba"; ver pnlMontarAbasExportacao pro Excel
function pnlMontarLinhasExportacao(){
  if(pnlConsultasCarregadas.length !== 1) return null;
  const abas = pnlMontarAbasExportacao();
  return abas[0] || null;
}
// nome de aba do Excel não pode passar de 31 caracteres nem ter : \ / ? * [ ]
function pnlNomeAbaExcel(nome, usados){
  let base = String(nome).replace(/[:\\\/?*\[\]]/g, ' ').trim().slice(0, 31) || 'Painel';
  let final = base, n = 2;
  while(usados.has(final)){ final = `${base.slice(0, 28)} ${n}`; n++; }
  usados.add(final);
  return final;
}
async function pnlExportarExcel(){
  const abas = pnlMontarAbasExportacao();
  if(!abas.length){ toast('Nada pra exportar com esses filtros.'); return; }
  const livro = XLSX.utils.book_new();
  const nomesUsados = new Set();
  let totalLinhas = 0;
  abas.forEach(aba=>{
    const corpoTipado = aba.corpo.map(linha => linha.map(v => typeof v === 'string' ? pnlCoagirNumero(v) : v));
    XLSX.utils.book_append_sheet(livro, XLSX.utils.aoa_to_sheet([aba.cabecalho, ...corpoTipado]), pnlNomeAbaExcel(aba.nome, nomesUsados));
    totalLinhas += aba.totalLinhas;
  });
  await salvarWorkbook(livro, `${pnlPainelAtual.slug}-${hojeLocalISO()}.xlsx`);
  toast(abas.length > 1
    ? `Excel exportado com ${totalLinhas} linha${totalLinhas===1?'':'s'} em ${abas.length} abas (1 por consulta).`
    : `Excel exportado com ${totalLinhas} linha${totalLinhas===1?'':'s'} e ${abas[0].cabecalho.length} colunas.`);
}
function pnlCelulaCsv(v){
  if(v == null || v === '') return '';
  return String(v).replace(/;/g, ',').replace(/[\r\n]+/g, ' ');
}
async function pnlExportarCsv(){
  const r = pnlMontarLinhasExportacao();
  if(!r){ toast(pnlConsultasCarregadas.length > 1 ? 'CSV só funciona com 1 consulta carregada — use o Exportar Excel (uma aba por consulta).' : 'Nada pra exportar com esses filtros.'); return; }
  const csv = [r.cabecalho, ...r.corpo].map(linha => linha.map(pnlCelulaCsv).join(';')).join('\r\n');
  const blob = new Blob(['﻿'+csv], { type:'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url; a.download = `${pnlPainelAtual.slug}-${hojeLocalISO()}.csv`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);
  toast(`CSV exportado com ${r.totalLinhas} linha${r.totalLinhas===1?'':'s'} e ${r.cabecalho.length} colunas.`);
}

/* ---------- exportar o painel MONTADO (1 aba por widget, igual a tela) ---------- */
// cabeçalho azul/branco em negrito — mesmo padrão visual já usado nos
// outros exports Excel do sistema (gerarExcelLancamentos etc.)
function pnlEstilarCabecalhoExcel(planilha, numColunas, linha, offsetColuna){
  offsetColuna = offsetColuna || 0;
  for(let i=0;i<numColunas;i++){
    const cel = planilha[XLSX.utils.encode_cell({ r:linha, c:i+offsetColuna })];
    if(cel) cel.s = { font:{ bold:true, color:{ rgb:'FFFFFF' } }, fill:{ fgColor:{ rgb:'305496' } }, alignment:{ vertical:'center' } };
  }
}
function pnlExportValorCelula(v){
  return (typeof v === 'string') ? pnlCoagirNumero(v) : v;
}
function pnlExportLinhaKpi(widget){
  const valor = pnlValorMedida(widget.medida, null);
  const def = pnlMedidaPorId(widget.medida) || {};
  return [widget.titulo || def.label || widget.medida, valor];
}
// widget "tabela" (fonte linhas ou agrupado) — mesma base de dados
// (pnlUltimoLinhasFiltradasPorWidget, já filtrada pelos filtros GERAIS do
// painel) e mesma lógica de filtro fixo do widget usada na tela; ignora
// de propósito o filtro rápido (chip) e a busca por texto, que são estado
// só da tela, não da configuração do widget — mesmo critério já usado no
// "Exportar Excel" por consulta
function pnlExportDadosWidgetTabela(widget){
  const consultaId = widget.consultaId || pnlConsultaPadrao();
  const colunas = (widget.colunas && widget.colunas.length) ? widget.colunas : pnlColunasDisponiveis(consultaId).slice(0,8);
  const catalogo = pnlColunasTabelaDisponiveis(consultaId);
  let linhas = pnlUltimoLinhasFiltradasPorWidget[widget.id] || [];
  linhas = pnlAplicarFiltroFixo(linhas, widget);
  if(widget.fonte === 'agrupado'){
    const dimensoes = [widget.dimensao, widget.dimensao2, widget.dimensao3].filter(Boolean);
    const grupos = pnlAgruparMultiplasDimensoes(linhas, dimensoes, colunas);
    const cab = [...dimensoes, ...colunas.map(c=>pnlLabelColuna(c, catalogo, widget.colunasApelidos))];
    const corpo = grupos.map(g=>[...g.rotulos, ...colunas.map(c=>pnlExportValorCelula(g.valores[c]))]);
    return { cab, corpo };
  }
  const indicesLinks = pnlIndicesLinksWidget(widget);
  const cab = colunas.map(c=>pnlLabelColuna(c, catalogo, widget.colunasApelidos));
  const corpo = linhas.map(o=>colunas.map(c=>pnlExportValorCelula(pnlValorColunaLinha(o, c, indicesLinks))));
  const totais = colunas.map((c,i)=>{
    if(i===0) return `${linhas.length} linha${linhas.length===1?'':'s'}`;
    const vals = linhas.map(o=>pnlCoagirNumero(pnlValorColunaLinha(o,c,indicesLinks))).filter(v=>typeof v==='number');
    return vals.length ? vals.reduce((s,v)=>s+v,0) : '';
  });
  return { cab, corpo, totais: linhas.length ? totais : null };
}
// widget "relatorio" (Mestre + Detalhe) — reconstrói a mesma hierarquia
// Detalhe→Subdetalhes da tela numa única aba: cada registro do Detalhe
// vira uma linha, seguida (indentada 1 coluna) do cabeçalho+linhas+total
// de cada subdetalhe que tiver filhos, igual ordenação/total configurados
// mesma ideia de pnlLinhaTotalColunas, só que devolve um array (linha de
// planilha) em vez de HTML — reaproveitado pro total geral e pelos
// subtotais de quebra na exportação
function pnlLinhaTotalColunasAoa(grupoLinhas, colunas, indicesLinks, rotulo){
  return colunas.map((c,i)=>{
    if(i===0) return rotulo;
    const vals = grupoLinhas.map(o=>pnlCoagirNumero(pnlValorColunaLinha(o,c,indicesLinks))).filter(v=>typeof v==='number');
    return vals.length ? vals.reduce((s,v)=>s+v,0) : '';
  });
}
function pnlExportAoaWidgetRelatorio(widget){
  const consultaId = widget.consultaId || pnlConsultaPadrao();
  const catalogo = pnlColunasTabelaDisponiveis(consultaId);
  const ehAgrupado = widget.fonte === 'agrupado';
  let colunas = (widget.colunas && widget.colunas.length) ? widget.colunas : pnlColunasDisponiveis(consultaId).slice(0,4);
  let linhas = pnlUltimoLinhasFiltradasPorWidget[widget.id] || [];
  linhas = pnlAplicarFiltroFixo(linhas, widget);
  const indicesLinks = pnlIndicesLinksWidget(widget);
  let subdetalhes = [];
  if(ehAgrupado){
    const dimensoes = [widget.dimensao, widget.dimensao2, widget.dimensao3].filter(Boolean);
    linhas = pnlAgruparColunasCruRelatorio(linhas, dimensoes, colunas);
    colunas = [...dimensoes, ...colunas];
  }else{
    subdetalhes = (widget.subdetalhes||[]).map(sd=>({
      ...sd,
      indice: pnlIndiceConsultaLinkadaMultiplo(sd.consultaId, sd.campoLink),
      catalogo: pnlColunasTabelaDisponiveis(sd.consultaId),
    }));
  }
  const valorColuna = ehAgrupado ? ((o,c)=>o[c]) : ((o,c)=>{
    if(pnlEhCampoSubdetalhe(c)){
      const p = pnlParseCampoSubdetalhe(c);
      return pnlValorCampoSubdetalhe(o, p.subId, p.campo, p.funcao, subdetalhes);
    }
    return pnlValorColunaLinha(o,c,indicesLinks);
  });
  if(!ehAgrupado && widget.ordenacao && widget.ordenacao.length){
    linhas = pnlOrdenarPorCriterios(linhas, widget.ordenacao, valorColuna);
  }
  const cab = colunas.map(c=>pnlLabelColuna(c, catalogo, widget.colunasApelidos));
  const aoa = [cab];
  const headerStyles = [{ row:0, cols:cab.length, offset:0 }];
  const niveisQuebra = ehAgrupado ? [] : (widget.ordenacao||[]).filter(cr=>cr.quebra);
  const acumuladores = niveisQuebra.map(()=>[]);
  let valoresAnteriores = null;
  const emitirSubtotais = (ateONivel)=>{
    for(let i=niveisQuebra.length-1; i>=ateONivel; i--){
      if(acumuladores[i].length){
        const rotuloCampo = pnlLabelColuna(niveisQuebra[i].campo, catalogo, widget.colunasApelidos);
        const rotuloValor = pnlFormatarValorColuna(valoresAnteriores[i]);
        aoa.push(pnlLinhaTotalColunasAoa(acumuladores[i], colunas, indicesLinks, `Subtotal — ${rotuloCampo}: ${rotuloValor}`));
      }
      acumuladores[i] = [];
    }
  };
  linhas.forEach((o, idx)=>{
    if(niveisQuebra.length){
      const valoresAtuais = niveisQuebra.map(cr=>valorColuna(o, cr.campo));
      if(idx>0){
        let nivelQueMudou = -1;
        for(let i=0;i<niveisQuebra.length;i++){
          if(String(valoresAtuais[i]) !== String(valoresAnteriores[i])){ nivelQueMudou = i; break; }
        }
        if(nivelQueMudou>=0) emitirSubtotais(nivelQueMudou);
      }
      valoresAnteriores = valoresAtuais;
    }
    aoa.push(colunas.map(c=>pnlExportValorCelula(valorColuna(o, c))));
    subdetalhes.forEach(sd=>{
      const chave = pnlValorFiltro(o, sd.campoPrincipal);
      let filhos = sd.indice[chave] || [];
      if(!filhos.length) return;
      let colunasSub = sd.colunas;
      if(sd.fonte === 'agrupado'){
        const dimensoesSub = [sd.dimensao, sd.dimensao2, sd.dimensao3].filter(Boolean);
        filhos = pnlAgruparSubdetalhe(filhos, dimensoesSub, sd.colunas);
        colunasSub = [...dimensoesSub, ...sd.colunas];
      }
      if(sd.ordenacao && sd.ordenacao.length){
        filhos = pnlOrdenarPorCriterios(filhos, sd.ordenacao, (f,c)=>f[c]);
      }
      aoa.push(['', `↳ ${sd.titulo || 'Detalhes'}`]);
      const cabSub = colunasSub.map(c=>pnlLabelColuna(c, sd.catalogo, sd.colunasApelidos));
      aoa.push(['', ...cabSub]);
      headerStyles.push({ row:aoa.length-1, cols:cabSub.length, offset:1 });
      filhos.forEach(f=>{
        aoa.push(['', ...colunasSub.map(c=>pnlExportValorCelula(f[c]))]);
      });
      if(sd.colunasTotais && sd.colunasTotais.length){
        aoa.push(['', ...colunasSub.map(c=>{
          if(!sd.colunasTotais.includes(c)) return '';
          const vals = filhos.map(f=>pnlCoagirNumero(f[c])).filter(v=>typeof v==='number');
          return vals.length ? vals.reduce((s,v)=>s+v,0) : '';
        })]);
      }
    });
    aoa.push([]);
    niveisQuebra.forEach((_,i)=>acumuladores[i].push(o));
  });
  if(niveisQuebra.length) emitirSubtotais(0);
  if(linhas.length){
    aoa.push(pnlLinhaTotalColunasAoa(linhas, colunas, indicesLinks, `${linhas.length} registro${linhas.length===1?'':'s'}`));
  }
  return { aoa, headerStyles };
}
// widgets de gráfico (barra, barra-h, donut, linha) — mesmo agrupamento
// (pnlAgruparPorCampo) e mesma ordenação/Top N usados pra desenhar o
// gráfico na tela, só que como tabela de rótulo+valor(es)
function pnlExportDadosWidgetGrafico(widget, tipo){
  const linhas = pnlUltimoLinhasFiltradasPorWidget[widget.id] || [];
  const medidasExtras = (tipo==='linha' || tipo==='barra') ? pnlMedidasExtrasWidget(widget) : [];
  if(medidasExtras.length){
    const medidas = [widget.medida, ...medidasExtras];
    const porMedida = medidas.map(m=>pnlAgruparPorCampo(linhas, widget.dimensao, m));
    let chaves = [...new Set(porMedida.flatMap(arr=>arr.map(g=>g.chave)))].sort((a,b)=>a.localeCompare(b,'pt',{numeric:true}));
    if(tipo!=='linha' && widget.top) chaves = chaves.slice(0, Number(widget.top));
    const porChaveRotulo = {}; porMedida[0].forEach(g=>{ porChaveRotulo[g.chave]=g.rotulo; });
    const cab = [widget.dimensao, ...medidas.map(m=>(pnlMedidaPorId(m)||{}).label||m)];
    const corpo = chaves.map(chave=>[porChaveRotulo[chave]||chave, ...porMedida.map(arr=>{ const f = arr.find(g=>g.chave===chave); return f ? f.valor : 0; })]);
    return { cab, corpo };
  }
  if(tipo==='mapa' && widget.campoUf){
    let grupos = pnlAgruparPorCidade(linhas, widget.dimensao, widget.campoUf, widget.medida);
    if(widget.top) grupos = grupos.slice(0, Number(widget.top));
    const cab = [widget.dimensao, widget.campoUf, (pnlMedidaPorId(widget.medida)||{}).label || widget.medida];
    const corpo = grupos.map(g=>[g.rotulo, g.uf, g.valor]);
    return { cab, corpo };
  }
  let grupos = pnlAgruparPorCampo(linhas, widget.dimensao, widget.medida);
  if(widget.top) grupos = grupos.slice(0, Number(widget.top));
  const cab = [widget.dimensao, (pnlMedidaPorId(widget.medida)||{}).label || widget.medida];
  const corpo = grupos.map(g=>[g.rotulo, g.valor]);
  return { cab, corpo };
}
async function pnlExportarPainelMontado(){
  if(typeof XLSX === 'undefined'){ toast('Não foi possível carregar o gerador de Excel. Confira sua internet.'); return; }
  if(!pnlPainelWidgets.length){ toast('Esse painel ainda não tem nenhum widget montado.'); return; }
  const livro = XLSX.utils.book_new();
  const nomesUsados = new Set();
  let sheetsCriadas = 0;
  const kpis = pnlPainelWidgets.filter(w=>w.tipo==='kpi');
  if(kpis.length){
    const aoa = [['Indicador','Valor'], ...kpis.map(w=>pnlExportLinhaKpi(w))];
    const planilha = XLSX.utils.aoa_to_sheet(aoa);
    pnlEstilarCabecalhoExcel(planilha, 2, 0);
    planilha['!cols'] = [{wch:34},{wch:18}];
    XLSX.utils.book_append_sheet(livro, planilha, pnlNomeAbaExcel('Resumo (KPIs)', nomesUsados));
    sheetsCriadas++;
  }
  pnlPainelWidgets.forEach(w=>{
    if(w.tipo==='kpi') return;
    if(w.tipo==='tabela'){
      const { cab, corpo, totais } = pnlExportDadosWidgetTabela(w);
      if(!corpo.length) return;
      const aoa = [cab, ...corpo];
      if(totais) aoa.push(totais);
      const planilha = XLSX.utils.aoa_to_sheet(aoa);
      pnlEstilarCabecalhoExcel(planilha, cab.length, 0);
      XLSX.utils.book_append_sheet(livro, planilha, pnlNomeAbaExcel(pnlWidgetTitulo(w), nomesUsados));
      sheetsCriadas++;
    }else if(w.tipo==='relatorio'){
      const { aoa, headerStyles } = pnlExportAoaWidgetRelatorio(w);
      if(aoa.length <= 1) return;
      const planilha = XLSX.utils.aoa_to_sheet(aoa);
      headerStyles.forEach(hs=>pnlEstilarCabecalhoExcel(planilha, hs.cols, hs.row, hs.offset));
      XLSX.utils.book_append_sheet(livro, planilha, pnlNomeAbaExcel(pnlWidgetTitulo(w), nomesUsados));
      sheetsCriadas++;
    }else if(['barra','barra-h','linha','donut','treemap','mapa'].includes(w.tipo)){
      const { cab, corpo } = pnlExportDadosWidgetGrafico(w, w.tipo);
      if(!corpo.length) return;
      const aoa = [cab, ...corpo];
      const planilha = XLSX.utils.aoa_to_sheet(aoa);
      pnlEstilarCabecalhoExcel(planilha, cab.length, 0);
      XLSX.utils.book_append_sheet(livro, planilha, pnlNomeAbaExcel(pnlWidgetTitulo(w), nomesUsados));
      sheetsCriadas++;
    }
  });
  if(!sheetsCriadas){ toast('Nada pra exportar com esses filtros.'); return; }
  await salvarWorkbook(livro, `${pnlPainelAtual.slug}-montado-${hojeLocalISO()}.xlsx`);
  toast(`Painel exportado com ${sheetsCriadas} aba${sheetsCriadas===1?'':'s'} (1 por widget).`);
}

/* ---------- edição do painel (entrar/sair, salvar, formulário de widget) ---------- */
function pnlGerarIdWidget(){ return 'w'+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
// guias do widget "container" que ainda está sendo montado — mesmo padrão
// simples de adicionar/remover (sem reordenar) já usado pros Setores do
// Cliente; cada guia é só {id, titulo}
function pnlRenderGuiasContainerLista(){
  const cont = document.getElementById('listGuiasContainer');
  if(!cont) return;
  cont.innerHTML = pnlFormGuiasContainerAtual.length === 0
    ? `<p style="color:var(--muted);font-size:12px;margin:0;">Nenhuma guia ainda — sem guia, o container vira um bloco único.</p>`
    : pnlFormGuiasContainerAtual.map(g=>`<span class="lookup-tag">${escaparHtml(g.titulo)}<button type="button" data-removerguiacontainer="${g.id}">×</button></span>`).join(' ');
}
function pnlAdicionarGuiaContainer(){
  const input = document.getElementById('pnlNovaGuiaContainer');
  const titulo = input.value.trim();
  if(!titulo){ toast('Informe o nome da guia.'); return; }
  pnlFormGuiasContainerAtual.push({ id: pnlGerarIdWidget(), titulo });
  input.value = '';
  pnlRenderGuiasContainerLista();
}
function pnlRemoverGuiaContainer(id){
  pnlFormGuiasContainerAtual = pnlFormGuiasContainerAtual.filter(g=>g.id!==id);
  pnlRenderGuiasContainerLista();
}
// true se "candidatoId" é o próprio widget em edição OU um descendente dele
// (já está dentro dele, direto ou aninhado) — impede um container de virar
// filho de si mesmo ou de um dos seus próprios netos
function pnlEhDescendenteOuProprio(candidatoId, raizId){
  if(candidatoId === raizId) return true;
  const w = pnlPainelWidgets.find(x=>x.id===candidatoId);
  if(!w || !w.containerId) return false;
  return pnlEhDescendenteOuProprio(w.containerId, raizId);
}
// select "Dentro do Container" — lista todo CONTAINER já salvo no painel,
// exceto o próprio widget em edição e qualquer container aninhado dentro
// dele (evitaria um ciclo)
function pnlPopularSelectContainerPai(valorAtual, guiaValorAtual){
  const sel = document.getElementById('pnlNovoWidgetContainerPai');
  if(!sel) return;
  const excluirId = pnlEditandoWidgetId;
  const containers = pnlPainelWidgets.filter(w=>w.tipo==='container' && (!excluirId || !pnlEhDescendenteOuProprio(w.id, excluirId)));
  sel.innerHTML = `<option value="">(nível principal)</option>` + containers.map(w=>`<option value="${escaparHtml(w.id)}">${escaparHtml(pnlWidgetTitulo(w))}</option>`).join('');
  sel.value = (valorAtual && containers.some(w=>w.id===valorAtual)) ? valorAtual : '';
  pnlAtualizarSelectContainerGuia(guiaValorAtual);
}
function pnlAtualizarSelectContainerGuia(valorAtual){
  const containerId = document.getElementById('pnlNovoWidgetContainerPai').value;
  const campo = document.getElementById('pnlNovoWidgetCampoContainerGuia');
  const sel = document.getElementById('pnlNovoWidgetContainerGuia');
  const container = pnlPainelWidgets.find(w=>w.id===containerId);
  const guias = (container && container.guias) || [];
  campo.style.display = guias.length ? '' : 'none';
  sel.innerHTML = guias.map(g=>`<option value="${escaparHtml(g.id)}">${escaparHtml(g.titulo)}</option>`).join('');
  if(valorAtual && guias.some(g=>g.id===valorAtual)) sel.value = valorAtual;
}
// qual consulta o formulário de widget está usando agora — o seletor só
// aparece quando o painel carregou mais de 1 consulta pro cliente atual;
// com 1 só, nem precisa perguntar (resolve sozinho)
function pnlConsultaSelecionadaNoForm(){
  const sel = document.getElementById('pnlNovoWidgetConsulta');
  return (sel && sel.value) || pnlConsultaPadrao();
}
function pnlAtualizarCamposNovoWidget(){
  const tipo = document.getElementById('pnlNovoWidgetTipo').value;
  const ehTabelaPersonalizada = tipo==='tabela';
  const ehRelatorio = tipo==='relatorio';
  const ehKpi = tipo==='kpi';
  const ehLinha = tipo==='linha';
  const ehTitulo = tipo==='titulo';
  const ehContainer = tipo==='container';
  const ehFiltro = tipo==='filtro';
  // Título/Container/Filtro não têm dado próprio — não usam Consulta/Medida/Dimensão
  const semDado = ehTitulo || ehContainer || ehFiltro;
  const fonte = document.getElementById('pnlNovoWidgetFonte').value || 'linhas';
  const precisaMedida = !ehTabelaPersonalizada && !ehRelatorio && !semDado;
  // Relatório também ganha "Agrupar por" quando a fonte é 'agrupado' — igual
  // à Tabela, o Detalhe vira 1 linha por valor (ou combinação de até 3
  // campos) com medidas somadas, em vez de 1 linha por registro
  const precisaDimensao = !ehKpi && !semDado && ((!ehTabelaPersonalizada && !ehRelatorio) || fonte==='agrupado');
  const selConsulta = document.getElementById('pnlNovoWidgetConsulta');
  document.getElementById('pnlNovoWidgetCampoConsulta').style.display = (pnlConsultasCarregadas.length > 1 && !semDado) ? '' : 'none';
  if(pnlConsultasCarregadas.length){
    const atualConsulta = selConsulta.value;
    selConsulta.innerHTML = pnlConsultasCarregadas.map(c=>`<option value="${escaparHtml(c.id)}">${escaparHtml(c.nome)}</option>`).join('');
    if(pnlConsultasCarregadas.some(c=>c.id===atualConsulta)) selConsulta.value = atualConsulta;
  }
  const consultaId = pnlConsultaSelecionadaNoForm();
  // posição/tamanho no canvas livre só fazem sentido editando um widget que
  // JÁ tem uma posição válida (novo widget ainda não tem — ganha uma só ao
  // salvar, ver pnlGerarCanvasPadraoSeNecessario; reabra pra editar depois)
  const widgetEmEdicao = pnlEditandoWidgetId ? pnlPainelWidgets.find(w=>w.id===pnlEditandoWidgetId) : null;
  const mostraPosicaoCanvas = pnlModoCanvas && widgetEmEdicao && pnlWidgetTemCanvasValido(widgetEmEdicao);
  document.getElementById('pnlNovoWidgetCampoCanvasPos').style.display = mostraPosicaoCanvas ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoCanvasTamanho').style.display = mostraPosicaoCanvas ? '' : 'none';
  document.getElementById('pnlNovoWidgetCanvasH').min = pnlCanvasAlturaMinima(tipo);
  document.getElementById('pnlNovoWidgetCampoFiltroWidget').style.display = ehFiltro ? '' : 'none';
  if(ehFiltro){
    const selCampoFiltro = document.getElementById('pnlNovoWidgetFiltroWidgetCampo');
    const atualCampoFiltro = selCampoFiltro.value;
    const camposFiltro = pnlCamposParaWidgetFiltro();
    selCampoFiltro.innerHTML = camposFiltro.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('') || `<option value="">(nenhum campo disponível)</option>`;
    if(camposFiltro.includes(atualCampoFiltro)) selCampoFiltro.value = atualCampoFiltro;
  }
  document.getElementById('pnlNovoWidgetCampoLargura').style.display = ehKpi ? 'none' : '';
  document.getElementById('pnlNovoWidgetLinhaMedida').style.display = (precisaMedida || precisaDimensao) ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoMedida').style.display = precisaMedida ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoDimensao').style.display = precisaDimensao ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoTop').style.display = (tipo==='barra-h'||tipo==='donut'||tipo==='barra'||tipo==='curvaabc'||tipo==='treemap'||tipo==='mapa') ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoMedidas2').style.display = (ehLinha || tipo==='barra') ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoSubtitulo').style.display = (ehKpi || ehTitulo) ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoEstiloValor').style.display = ehKpi ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoIcone').style.display = ehTitulo ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoGuias').style.display = ehContainer ? '' : 'none';
  if(ehContainer) pnlRenderGuiasContainerLista();
  const existemContainers = pnlPainelWidgets.some(w=>w.tipo==='container' && w.id!==pnlEditandoWidgetId);
  document.getElementById('pnlNovoWidgetCampoDentroContainer').style.display = existemContainers ? '' : 'none';
  if(existemContainers) pnlPopularSelectContainerPai();
  document.getElementById('pnlNovoWidgetCampoFonte').style.display = (ehTabelaPersonalizada || ehRelatorio) ? '' : 'none';
  const mostraFiltroRapido = (ehTabelaPersonalizada || ehRelatorio) && fonte==='linhas';
  document.getElementById('pnlNovoWidgetCampoFiltroRapido').style.display = mostraFiltroRapido ? '' : 'none';
  if(mostraFiltroRapido){
    const selFR = document.getElementById('pnlNovoWidgetFiltroRapido');
    const atualFR = selFR.value;
    selFR.innerHTML = `<option value="">(nenhum)</option>` + Object.entries(pnlColunasTabelaDisponiveis(consultaId)).map(([k,v])=>`<option value="${escaparHtml(k)}">${escaparHtml(v)}</option>`).join('');
    if([...selFR.options].some(o=>o.value===atualFR)) selFR.value = atualFR;
  }
  document.getElementById('pnlNovoWidgetCampoColunas').style.display = (ehTabelaPersonalizada || ehRelatorio) ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoGrafico').style.display = (tipo==='barra'||tipo==='barra-h'||tipo==='linha'||tipo==='donut'||tipo==='treemap'||tipo==='mapa') ? '' : 'none';
  document.getElementById('pnlNovoWidgetLinhaFiltroFixo').style.display = (ehTabelaPersonalizada || ehRelatorio || ehKpi) ? '' : 'none';
  // Links e Subdetalhes são por REGISTRO — não fazem sentido quando o
  // Detalhe já vem agrupado (igual a Tabela: Links some em fonte 'agrupado')
  const mostraLinks = ((ehTabelaPersonalizada || ehRelatorio) && fonte==='linhas') && pnlConsultasCarregadas.length > 1;
  document.getElementById('pnlNovoWidgetCampoLinks').style.display = mostraLinks ? '' : 'none';
  if(mostraLinks){ pnlPopularFormNovoLink(consultaId); pnlRenderLinksLista(); }
  const mostraSubdetalhes = ehRelatorio && fonte==='linhas';
  document.getElementById('pnlNovoWidgetCampoSubdetalhes').style.display = mostraSubdetalhes ? '' : 'none';
  if(mostraSubdetalhes){ pnlPopularFormNovoSubdetalhe(); pnlRenderSubdetalhesLista(); }
  if(ehTabelaPersonalizada || ehRelatorio || ehKpi){
    const selFF = document.getElementById('pnlNovoWidgetFiltroFixoCampo');
    const atualFF = selFF.value;
    selFF.innerHTML = `<option value="">(nenhum)</option>` + Object.entries(pnlColunasTabelaDisponiveis(consultaId)).map(([k,v])=>`<option value="${escaparHtml(k)}">${escaparHtml(v)}</option>`).join('');
    if([...selFF.options].some(o=>o.value===atualFF)) selFF.value = atualFF;
    const selOp = document.getElementById('pnlNovoWidgetFiltroFixoOperador');
    if(!selOp.options.length) selOp.innerHTML = Object.entries(PNL_OPERADORES_FILTRO_FIXO).map(([k,v])=>`<option value="${escaparHtml(k)}">${escaparHtml(v)}</option>`).join('');
    pnlAtualizarFiltroFixoValor();
  }
  pnlPopularSelectsMedidaWidget();
  const colunas = pnlColunasDisponiveis(consultaId);
  const dimSel = document.getElementById('pnlNovoWidgetDimensao');
  dimSel.innerHTML = colunas.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
  const multi = (ehTabelaPersonalizada || ehRelatorio) && fonte==='agrupado';
  document.getElementById('pnlNovoWidgetCampoDimensao2').style.display = multi ? '' : 'none';
  document.getElementById('pnlNovoWidgetCampoDimensao3').style.display = multi ? '' : 'none';
  if(multi){
    const opcoesExtra = `<option value="">(nenhum)</option>` + colunas.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
    document.getElementById('pnlNovoWidgetDimensao2').innerHTML = opcoesExtra;
    document.getElementById('pnlNovoWidgetDimensao3').innerHTML = opcoesExtra;
  }
  document.getElementById('pnlNovoWidgetCampoMapaUf').style.display = tipo==='mapa' ? '' : 'none';
  if(tipo==='mapa'){
    const selUf = document.getElementById('pnlNovoWidgetMapaUf');
    const atualUf = selUf.value;
    selUf.innerHTML = `<option value="">(nenhum)</option>` + colunas.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
    if(colunas.includes(atualUf)) selUf.value = atualUf;
  }
  if(ehTabelaPersonalizada) pnlRenderColunasPicker(fonte, consultaId);
  else if(ehRelatorio){
    pnlRenderColunasPicker(fonte, consultaId, fonte==='linhas' ? pnlFormSubdetalhesAtual : null);
    if(fonte!=='agrupado') document.getElementById('pnlNovoWidgetLabelColunas').textContent = 'Colunas do Detalhe';
  }
  // Ordenação/Quebra (subtotal) assume linhas por registro — não faz
  // sentido sobre linhas já agregadas por grupo
  const mostraOrdenacao = ehRelatorio && fonte==='linhas';
  document.getElementById('pnlNovoWidgetCampoOrdenacao').style.display = mostraOrdenacao ? '' : 'none';
  if(mostraOrdenacao){
    const selOrdenacao = document.getElementById('pnlNovoWidgetOrdenacaoCampo');
    const atualOrdenacao = selOrdenacao.value;
    selOrdenacao.innerHTML = colunas.map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
    if(colunas.includes(atualOrdenacao)) selOrdenacao.value = atualOrdenacao;
    pnlRenderOrdenacaoLista();
  }
  document.getElementById('pnlNovoWidgetCampoZebrado').style.display = (ehTabelaPersonalizada || ehRelatorio) ? '' : 'none';
}
// mostra/popula o seletor "Valor" do filtro fixo, em cima do campo
// escolhido no select ao lado
function pnlAtualizarFiltroFixoValor(){
  const campo = document.getElementById('pnlNovoWidgetFiltroFixoCampo').value;
  const operador = document.getElementById('pnlNovoWidgetFiltroFixoOperador').value || '=';
  const campoOperador = document.getElementById('pnlNovoWidgetCampoFiltroFixoOperador');
  const campoValor = document.getElementById('pnlNovoWidgetCampoFiltroFixoValor');
  const campoMeses = document.getElementById('pnlNovoWidgetCampoFiltroFixoMeses');
  const selValor = document.getElementById('pnlNovoWidgetFiltroFixoValor');
  campoOperador.style.display = campo ? '' : 'none';
  // ULTIMOSMESES/MESESANTERIORES usam um número de meses (N), não um valor
  // escolhido entre os distintos da coluna — NULL/NOT NULL não precisam de
  // valor nenhum pra comparar
  const ehJanelaMeses = operador==='ULTIMOSMESES' || operador==='MESESANTERIORES';
  campoMeses.style.display = (campo && ehJanelaMeses) ? '' : 'none';
  const precisaValor = campo && operador!=='NULL' && operador!=='NOTNULL' && !ehJanelaMeses;
  campoValor.style.display = precisaValor ? '' : 'none';
  const tipo = document.getElementById('pnlNovoWidgetTipo').value;
  const campoComparacao = document.getElementById('pnlNovoWidgetCampoComparacao');
  const mostraComparacao = tipo==='kpi' && operador==='ULTIMOSMESES';
  campoComparacao.style.display = mostraComparacao ? '' : 'none';
  if(!mostraComparacao) document.getElementById('pnlNovoWidgetComparacao').checked = false;
  if(!precisaValor) return;
  const atual = selValor.value;
  const valores = pnlValoresDistintosColuna(campo, pnlConsultaSelecionadaNoForm());
  selValor.innerHTML = valores.map(v=>`<option value="${escaparHtml(v)}">${escaparHtml(v)}</option>`).join('') || `<option value="">(sem valores carregados)</option>`;
  if(valores.includes(atual)) selValor.value = atual;
}
// de onde vem o "Valor" do filtro fixo na hora de salvar — ULTIMOSMESES/
// MESESANTERIORES usam o campo numérico de meses, os demais o select de
// valores distintos de sempre
function pnlLerFiltroFixoValorForm(operador){
  if(operador==='ULTIMOSMESES' || operador==='MESESANTERIORES') return document.getElementById('pnlNovoWidgetFiltroFixoMeses').value.trim();
  return document.getElementById('pnlNovoWidgetFiltroFixoValor').value;
}
// checklist de "medidas adicionais" (comparar lado a lado, nos tipos
// barra/linha) — exclui a medida já escolhida como principal, pra não
// deixar selecionar a mesma duas vezes
function pnlRenderMedidasExtrasPicker(){
  const cont = document.getElementById('pnlNovoWidgetMedidasExtras');
  if(!cont) return;
  // ao contrário da Medida principal (presa à consulta escolhida no
  // widget), as medidas adicionais podem vir de QUALQUER consulta — é
  // exatamente pra isso que elas servem: comparar lado a lado medidas de
  // consultas diferentes (ex: Medido x Faturado)
  const medidaPrincipal = document.getElementById('pnlNovoWidgetMedida').value;
  const disponiveis = pnlPainelMedidas.filter(m=>m.id!==medidaPrincipal);
  pnlFormMedidasExtrasAtual = pnlFormMedidasExtrasAtual.filter(id=>disponiveis.some(m=>m.id===id));
  const marcadas = new Set(pnlFormMedidasExtrasAtual);
  cont.innerHTML = disponiveis.map(m=>`<label style="display:flex;align-items:center;gap:8px;cursor:pointer;font-weight:normal;">
      <input type="checkbox" data-wmedidaextra value="${escaparHtml(m.id)}" ${marcadas.has(m.id)?'checked':''} style="width:auto;"> ${escaparHtml(m.label)}
    </label>`).join('') || `<div class="empty" style="padding:2px 0;">Crie outras medidas primeiro pra poder comparar.</div>`;
}
function pnlPopularSelectsMedidaWidget(){
  // qualquer medida vale em qualquer widget, independente da Consulta
  // escolhida nele — ver comentário equivalente em pnlRenderColunasPicker
  const medidaSel = document.getElementById('pnlNovoWidgetMedida');
  if(medidaSel){
    const atual = medidaSel.value;
    const consultaId = pnlConsultaSelecionadaNoForm();
    const opcoesMedidas = pnlPainelMedidas.map(m=>`<option value="${escaparHtml(m.id)}">${escaparHtml(m.label)}</option>`).join('');
    // campos crus da consulta deste widget — dá pra usar DIRETO como
    // medida (soma), sem precisar cadastrar uma Medida só pra isso
    const campos = consultaId ? pnlColunasDisponiveis(consultaId) : [];
    const opcoesCampos = campos.map(c=>`<option value="${escaparHtml(pnlCodificarCampoCruMedida(consultaId, c))}">${escaparHtml(c)}</option>`).join('');
    medidaSel.innerHTML = (opcoesMedidas ? `<optgroup label="Medidas">${opcoesMedidas}</optgroup>` : '')
      + (opcoesCampos ? `<optgroup label="Campos da consulta (soma)">${opcoesCampos}</optgroup>` : '')
      || `<option value="">(nenhuma medida ou campo disponível)</option>`;
    if([...medidaSel.options].some(o=>o.value===atual)) medidaSel.value = atual;
  }
  pnlRenderMedidasExtrasPicker();
}
