// move um widget dentro do seu próprio grupo (nível principal, ou a mesma
// guia do mesmo container) — nunca mistura posição com widgets de outro
// grupo, mesmo os dois estando no mesmo array pnlPainelWidgets por baixo
function pnlWidgetMover(id, dir){
  const w = pnlPainelWidgets.find(x=>x.id===id);
  if(!w) return;
  const irmaos = pnlPainelWidgets.filter(x=>(x.containerId||'')===(w.containerId||'') && (x.guiaId||'')===(w.guiaId||''));
  const pos = irmaos.findIndex(x=>x.id===id);
  const alvoPos = dir==='up' ? pos-1 : pos+1;
  if(alvoPos<0 || alvoPos>=irmaos.length) return;
  const alvo = irmaos[alvoPos];
  const iReal = pnlPainelWidgets.findIndex(x=>x.id===w.id);
  const jReal = pnlPainelWidgets.findIndex(x=>x.id===alvo.id);
  [pnlPainelWidgets[iReal], pnlPainelWidgets[jReal]] = [pnlPainelWidgets[jReal], pnlPainelWidgets[iReal]];
  pnlRender();
}
// cópia exata do widget (mesmo tipo/medida/dimensão/aparência/etc.), com
// um id novo, inserida logo depois do original — pra não ter que
// reconfigurar um widget parecido do zero. Não duplica os "filhos" de um
// Container (os widgets que apontam containerId pra ele), só o container
// em si.
function pnlWidgetDuplicar(id){
  const w = pnlPainelWidgets.find(x=>x.id===id);
  if(!w) return;
  const copia = JSON.parse(JSON.stringify(w));
  copia.id = pnlGerarIdWidget();
  if(copia.titulo) copia.titulo += ' (cópia)';
  // desloca um pouco no canvas livre, senão a cópia nasce exatamente em
  // cima do original e parece que nada aconteceu
  if(pnlWidgetTemCanvasValido(copia)){
    copia.canvas = { x: copia.canvas.x+24, y: copia.canvas.y+24, w: copia.canvas.w, h: copia.canvas.h };
  }
  const posOriginal = pnlPainelWidgets.findIndex(x=>x.id===id);
  pnlPainelWidgets.splice(posOriginal+1, 0, copia);
  pnlRender();
}
function pnlWidgetRemover(id){
  pnlPainelWidgets = pnlPainelWidgets.filter(w=>w.id!==id);
  // widget Mapa guarda uma instância viva do Leaflet (fazendo requisições
  // de tile em segundo plano) — sem isso, removê-lo deixaria o mapa
  // "zumbi" rodando pra sempre, preso só pela referência no registro
  if(PNL_MAPA_LEAFLET[id]){ PNL_MAPA_LEAFLET[id].map.remove(); delete PNL_MAPA_LEAFLET[id]; }
  delete PNL_MAPA_VISTA[id];
  if(pnlEditandoWidgetId===id){
    pnlResetFormNovoWidget();
    if(pnlModoCanvas) pnlCanvasMostrarPaleta();
  }
  pnlRender();
}
function pnlWidgetEditar(id){
  const w = pnlPainelWidgets.find(x=>x.id===id);
  if(!w) return;
  pnlEditandoWidgetId = id;
  document.getElementById('pnlNovoWidgetTipo').value = w.tipo;
  document.getElementById('pnlNovoWidgetTipo').disabled = true;
  document.getElementById('pnlNovoWidgetFonte').value = w.fonte || 'linhas';
  document.getElementById('pnlNovoWidgetConsulta').value = w.consultaId || pnlConsultaPadrao() || '';
  pnlFormColunasAtual = w.colunas ? w.colunas.slice() : [];
  pnlFormColunasApelidos = w.colunasApelidos ? JSON.parse(JSON.stringify(w.colunasApelidos)) : {};
  pnlFormColunasFormatos = w.colunasFormatos ? JSON.parse(JSON.stringify(w.colunasFormatos)) : {};
  pnlFormMedidasExtrasAtual = pnlMedidasExtrasWidget(w);
  pnlFormLinksAtual = w.links ? JSON.parse(JSON.stringify(w.links)) : [];
  pnlFormSubdetalhesAtual = w.subdetalhes ? JSON.parse(JSON.stringify(w.subdetalhes)) : [];
  // subdetalhe salvo antes dessa funcionalidade existir não tem id —
  // preenche agora, pra já poder ser referenciado por uma "coluna
  // calculada" do Detalhe (só persiste de verdade quando o widget for
  // salvo de novo)
  pnlFormSubdetalhesAtual.forEach(sd=>{ if(!sd.id) sd.id = pnlGerarIdSubdetalhe(); });
  pnlFormSubdetalheColunasAtual = [];
  pnlEditandoSubdetalheIndex = null;
  pnlFormOrdenacaoAtual = w.ordenacao ? JSON.parse(JSON.stringify(w.ordenacao)) : [];
  pnlFormSubdetalheOrdenacaoAtual = [];
  pnlFormSubdetalheTotaisAtual = [];
  pnlFormSubdetalheColunasApelidos = {};
  pnlFormGuiasContainerAtual = w.guias ? JSON.parse(JSON.stringify(w.guias)) : [];
  document.getElementById('btnPnlAdicionarSubdetalhe').textContent = 'Adicionar subdetalhe';
  document.getElementById('pnlNovoWidgetLargura').value = w.largura || 'completa';
  document.getElementById('pnlNovoWidgetAltura').value = w.altura || 'padrao';
  document.getElementById('pnlNovoWidgetZebrado').checked = !!w.zebrado;
  document.getElementById('pnlNovoWidgetTamanhoFonteLinhas').value = w.tamanhoFonteLinhas || '';
  pnlAtualizarCamposNovoWidget();
  if(pnlModoCanvas && pnlWidgetTemCanvasValido(w)){
    document.getElementById('pnlNovoWidgetCanvasX').value = w.canvas.x;
    document.getElementById('pnlNovoWidgetCanvasY').value = w.canvas.y;
    document.getElementById('pnlNovoWidgetCanvasW').value = w.canvas.w;
    document.getElementById('pnlNovoWidgetCanvasH').value = w.canvas.h;
  }
  document.getElementById('pnlNovoWidgetCorBordaAtiva').checked = !!w.corBorda;
  document.getElementById('pnlNovoWidgetCorBorda').disabled = !w.corBorda;
  document.getElementById('pnlNovoWidgetCorBorda').value = w.corBorda || '#63c3d9';
  const fundoTransparente = w.corFundo === 'transparent';
  document.getElementById('pnlNovoWidgetFundoTransparente').checked = fundoTransparente;
  document.getElementById('pnlNovoWidgetCorFundoAtiva').checked = !!w.corFundo && !fundoTransparente;
  document.getElementById('pnlNovoWidgetCorFundo').disabled = !w.corFundo || fundoTransparente;
  document.getElementById('pnlNovoWidgetCorFundo').value = fundoTransparente ? '#1b2430' : (w.corFundo || '#1b2430');
  document.getElementById('pnlNovoWidgetBordaEstilo').value = w.bordaEstilo || '';
  pnlCarregarEstiloTextoForm('Titulo', w.estiloTitulo);
  pnlCarregarEstiloTextoForm('Valor', w.estiloValor);
  pnlPopularSelectContainerPai(w.containerId || '', w.guiaId || '');
  document.getElementById('pnlNovoWidgetFiltroRapido').value = w.filtroRapido || '';
  document.getElementById('pnlNovoWidgetFiltroFixoCampo').value = w.filtroFixoCampo || '';
  document.getElementById('pnlNovoWidgetFiltroFixoOperador').value = w.filtroFixoOperador || '=';
  pnlAtualizarFiltroFixoValor();
  document.getElementById('pnlNovoWidgetFiltroFixoValor').value = w.filtroFixoValor || '';
  document.getElementById('pnlNovoWidgetFiltroFixoMeses').value = w.filtroFixoValor || '';
  document.getElementById('pnlNovoWidgetComparacao').checked = !!w.compararPeriodoAnterior;
  document.getElementById('pnlNovoWidgetTitulo').value = w.titulo || '';
  if(w.medida) document.getElementById('pnlNovoWidgetMedida').value = w.medida;
  if(w.dimensao) document.getElementById('pnlNovoWidgetDimensao').value = w.dimensao;
  if(w.tipo==='filtro' && w.campo) document.getElementById('pnlNovoWidgetFiltroWidgetCampo').value = w.campo;
  document.getElementById('pnlNovoWidgetDimensao2').value = w.dimensao2 || '';
  document.getElementById('pnlNovoWidgetDimensao3').value = w.dimensao3 || '';
  document.getElementById('pnlNovoWidgetMapaUf').value = w.campoUf || '';
  document.getElementById('pnlNovoWidgetTop').value = w.top || '';
  pnlFormMedidasExtrasAtual = pnlMedidasExtrasWidget(w);
  pnlRenderMedidasExtrasPicker();
  document.getElementById('pnlNovoWidgetLegenda').checked = !!w.mostrarLegenda;
  document.getElementById('pnlNovoWidgetRotulos').checked = !!w.mostrarRotulos;
  document.getElementById('pnlNovoWidgetSubtitulo').value = w.subtitulo || '';
  document.getElementById('pnlNovoWidgetIcone').value = w.icone || '';
  if(w.tipo==='container') pnlRenderGuiasContainerLista();
  document.getElementById('btnPnlAdicionarWidget').textContent = 'Salvar alterações no widget';
  pnlCanvasMostrarForm();
  document.getElementById('pnlCardAddWidget').scrollIntoView({ behavior:'smooth', block:'center' });
}

/* ---------- Medidas (criar/editar — tudo campo+função, sem nenhuma "de sistema") ---------- */
function pnlRenderListaMedidas(){
  const cont = document.getElementById('pnlListaMedidas');
  if(!cont) return;
  cont.innerHTML = pnlPainelMedidas.map(def=>{
    const detalheOrdem = (def.funcao==='ultimoValor' && def.campoOrdem) ? ` (ordenado por ${escaparHtml(def.campoOrdem)})` : '';
    const detalhe = def.formula ? ` · Fórmula: ${escaparHtml(pnlFormulaParaExibicao(def.formula))}`
      : (def.funcao==='contagem' ? ` · ${escaparHtml(pnlLabelFuncaoMedida(def.funcao))}` : ` · ${escaparHtml(def.campo||'')} · ${escaparHtml(pnlLabelFuncaoMedida(def.funcao))}${detalheOrdem}`);
    const casas = Number.isInteger(def.casas) ? def.casas : (def.fmt==='pct' ? 1 : 0);
    const detalheFormato = def.fmt==='money' ? '' : ` · ${casas>0 ? casas+' casa'+(casas>1?'s':'')+' decimal'+(casas>1?'is':'') : 'inteiro'}`;
    const consulta = (!def.formula && pnlConsultasCarregadas.length > 1) ? pnlConsultasCarregadas.find(c=>c.id===def.consultaId) : null;
    const detalheConsulta = consulta ? ` · ${escaparHtml(consulta.nome)}` : '';
    return `<div class="row" style="align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--line);">
      <div style="flex:1;"><b>${escaparHtml(def.label)}</b><span style="font-size:11px;color:var(--muted);margin-left:6px;">${detalhe}${detalheFormato}${detalheConsulta}</span></div>
      <button class="ghost" type="button" data-editarmedida="${escaparHtml(def.id)}" style="width:auto;padding:4px 10px;">Editar</button>
      <button class="ghost" type="button" data-removermedida="${escaparHtml(def.id)}" style="width:auto;padding:4px 10px;color:var(--bad);">Remover</button>
    </div>`;
  }).join('') || `<div class="empty">Nenhuma medida criada ainda.</div>`;
}
// qual consulta o formulário de medida está usando agora — mesma lógica
// do formulário de widget (seletor só aparece com mais de 1 consulta)
function pnlConsultaSelecionadaNoFormMedida(){
  const sel = document.getElementById('pnlMedidaConsulta');
  return (sel && sel.value) || pnlConsultaPadrao();
}
function pnlPopularSelectCampoMedida(){
  const sel = document.getElementById('pnlMedidaCampo');
  if(!sel) return;
  const selConsulta = document.getElementById('pnlMedidaConsulta');
  const campoConsulta = document.getElementById('pnlMedidaCampoConsulta');
  if(campoConsulta) campoConsulta.style.display = pnlConsultasCarregadas.length > 1 ? '' : 'none';
  if(selConsulta && pnlConsultasCarregadas.length){
    const atualConsulta = selConsulta.value;
    selConsulta.innerHTML = pnlConsultasCarregadas.map(c=>`<option value="${escaparHtml(c.id)}">${escaparHtml(c.nome)}</option>`).join('');
    if(pnlConsultasCarregadas.some(c=>c.id===atualConsulta)) selConsulta.value = atualConsulta;
  }
  const atual = sel.value;
  const opcoesCampos = pnlColunasDisponiveis(pnlConsultaSelecionadaNoFormMedida()).map(c=>`<option value="${escaparHtml(c)}">${escaparHtml(c)}</option>`).join('');
  sel.innerHTML = opcoesCampos;
  if([...sel.options].some(o=>o.value===atual)) sel.value = atual;
  const selOrdem = document.getElementById('pnlMedidaOrdem');
  if(selOrdem){
    const atualOrdem = selOrdem.value;
    selOrdem.innerHTML = opcoesCampos;
    if([...selOrdem.options].some(o=>o.value===atualOrdem)) selOrdem.value = atualOrdem;
  }
}
// paleta de botões (medidas existentes + operadores) pra montar a
// fórmula sem precisar decorar/digitar o id de cada medida na mão
function pnlRenderPaletaFormula(){
  const cont = document.getElementById('pnlMedidaPaletaFormula');
  if(!cont) return;
  const medidasDisponiveis = pnlPainelMedidas.filter(m=>m.id!==pnlEditandoMedidaId);
  const botoesMedida = medidasDisponiveis.map(m=>`<button type="button" data-inserirformula="[${escaparHtml(m.id)}]" style="background:var(--bg2,#eef2f6);border:1px solid var(--line);border-radius:6px;padding:3px 8px;font-size:12px;cursor:pointer;">${escaparHtml(m.label)}</button>`).join('');
  const botoesOperador = ['+','-','×','÷','(',')'].map(op=>{
    const token = op==='×' ? '*' : (op==='÷' ? '/' : op);
    return `<button type="button" data-inserirformula="${escaparHtml(token)}" style="background:var(--bg2,#eef2f6);border:1px solid var(--line);border-radius:6px;padding:3px 10px;font-size:13px;font-weight:700;cursor:pointer;">${op}</button>`;
  }).join('');
  cont.innerHTML = (medidasDisponiveis.length ? botoesMedida + `<span style="width:100%;height:0;"></span>` : `<div class="empty" style="padding:2px 0;">Crie outras medidas primeiro pra poder combiná-las aqui.</div>`) + botoesOperador;
}
function pnlInserirTokenFormula(token){
  const input = document.getElementById('pnlMedidaFormula');
  if(!input) return;
  const start = input.selectionStart ?? input.value.length;
  const end = input.selectionEnd ?? input.value.length;
  input.value = input.value.slice(0, start) + token + input.value.slice(end);
  const pos = start + token.length;
  input.focus();
  input.setSelectionRange(pos, pos);
}
function pnlAtualizarCamposFormMedida(){
  const ehFormula = document.getElementById('pnlMedidaTipo').value === 'formula';
  document.getElementById('pnlMedidaCampoFormula').style.display = ehFormula ? '' : 'none';
  document.getElementById('pnlMedidaCampoFuncao').style.display = ehFormula ? 'none' : '';
  document.getElementById('pnlMedidaCampoConsulta').style.display = (!ehFormula && pnlConsultasCarregadas.length > 1) ? '' : 'none';
  if(ehFormula){ pnlRenderPaletaFormula(); }
  const funcao = document.getElementById('pnlMedidaFuncao').value;
  const formato = document.getElementById('pnlMedidaFormato').value;
  const tipoNumero = document.getElementById('pnlMedidaTipoNumero').value;
  document.getElementById('pnlMedidaCampoCampo').style.display = (ehFormula || funcao==='contagem') ? 'none' : '';
  document.getElementById('pnlMedidaCampoOrdem').style.display = (!ehFormula && funcao==='ultimoValor') ? '' : 'none';
  document.getElementById('pnlMedidaLinhaCasas').style.display = (formato!=='money' && formato!=='data') ? 'flex' : 'none';
  document.getElementById('pnlMedidaCampoCasas').style.display = (formato!=='money' && tipoNumero==='decimal') ? '' : 'none';
}
function pnlResetFormMedida(){
  pnlEditandoMedidaId = null;
  const nomeEl = document.getElementById('pnlMedidaNome'); if(!nomeEl) return;
  nomeEl.value = '';
  document.getElementById('pnlMedidaTipo').value = 'campo';
  document.getElementById('pnlMedidaFormula').value = '';
  const selConsultaMedida = document.getElementById('pnlMedidaConsulta');
  if(selConsultaMedida) selConsultaMedida.value = pnlConsultaPadrao() || '';
  document.getElementById('pnlMedidaFuncao').value = 'soma';
  document.getElementById('pnlMedidaFormato').value = 'money';
  document.getElementById('pnlMedidaTipoNumero').value = 'inteiro';
  document.getElementById('pnlMedidaCasas').value = '2';
  pnlPopularSelectCampoMedida();
  pnlAtualizarCamposFormMedida();
  document.getElementById('btnPnlAdicionarMedida').textContent = 'Adicionar medida';
}
function pnlEditarMedida(id){
  const def = pnlMedidaPorId(id); if(!def) return;
  pnlEditandoMedidaId = id;
  document.getElementById('pnlMedidaNome').value = def.label || '';
  document.getElementById('pnlMedidaFormato').value = def.fmt || 'money';
  document.getElementById('pnlMedidaTipo').value = def.formula ? 'formula' : 'campo';
  document.getElementById('pnlMedidaFormula').value = def.formula || '';
  const selConsultaMedida = document.getElementById('pnlMedidaConsulta');
  if(selConsultaMedida) selConsultaMedida.value = def.consultaId || pnlConsultaPadrao() || '';
  pnlPopularSelectCampoMedida();
  document.getElementById('pnlMedidaFuncao').value = def.funcao || 'soma';
  const casasAtuais = Number.isInteger(def.casas) ? def.casas : (def.fmt==='pct' ? 1 : 0);
  document.getElementById('pnlMedidaTipoNumero').value = casasAtuais>0 ? 'decimal' : 'inteiro';
  document.getElementById('pnlMedidaCasas').value = casasAtuais>0 ? casasAtuais : 2;
  pnlAtualizarCamposFormMedida();
  if(def.campo) document.getElementById('pnlMedidaCampo').value = def.campo;
  if(def.campoOrdem) document.getElementById('pnlMedidaOrdem').value = def.campoOrdem;
  document.getElementById('btnPnlAdicionarMedida').textContent = 'Salvar alterações na medida';
  document.getElementById('pnlCardMedidas').scrollIntoView({ behavior:'smooth', block:'center' });
}
function pnlRemoverMedida(id){
  pnlPainelMedidas = pnlPainelMedidas.filter(m=>m.id!==id);
  if(pnlEditandoMedidaId===id) pnlResetFormMedida();
  pnlRenderListaMedidas();
  pnlPopularSelectsMedidaWidget();
  pnlRender();
}
function pnlEntrarModoEdicao(){
  const conta = contaAtual();
  const perm = permissaoMenu(conta, 'relatoriosgerenciaisrm.paineis');
  if(!ehAdminEfetivo(conta) && perm && !perm.editar){ toast('Seu perfil só tem acesso de visualização nesse painel.'); return; }
  pnlModoEdicao = true;
  document.getElementById('btnPnlEditarPainel').style.display = 'none';
  document.getElementById('btnPnlModoCanvas').style.display = '';
  document.getElementById('btnPnlSalvarPainel').style.display = '';
  document.getElementById('btnPnlCancelarEdicaoPainel').style.display = '';
  document.getElementById('pnlCardAddWidget').style.display = '';
  document.getElementById('pnlCardMedidas').style.display = '';
  pnlResetFormNovoWidget();
  pnlResetFormMedida();
  pnlRenderListaMedidas();
  pnlRender();
}
function pnlSairModoEdicao(){
  pnlModoEdicao = false;
  pnlModoCanvas = false;
  document.getElementById('btnPnlEditarPainel').style.display = '';
  document.getElementById('btnPnlModoCanvas').style.display = 'none';
  document.getElementById('btnPnlModoCanvas').classList.remove('on');
  document.getElementById('pnlCanvasLayoutWrap').classList.remove('pnl-canvas-modo-ativo');
  document.getElementById('pnlCanvasPaleta').style.display = 'none';
  document.getElementById('btnPnlCanvasVoltarPaleta').style.display = 'none';
  document.getElementById('btnPnlSalvarPainel').style.display = 'none';
  document.getElementById('btnPnlCancelarEdicaoPainel').style.display = 'none';
  document.getElementById('pnlCardAddWidget').style.display = 'none';
  document.getElementById('pnlCardMedidas').style.display = 'none';
  pnlResetFormNovoWidget();
  pnlResetFormMedida();
}
function pnlCancelarEdicaoPainel(){
  pnlPainelWidgets = JSON.parse(JSON.stringify(pnlPainelWidgetsSalvos));
  pnlPainelFiltros = JSON.parse(JSON.stringify(pnlPainelFiltrosSalvos));
  pnlFiltros = Object.fromEntries(pnlPainelFiltros.map(f=>[f.campo, pnlFiltros[f.campo] || new Set()]));
  pnlPainelMedidas = JSON.parse(JSON.stringify(pnlPainelMedidasSalvos));
  pnlSairModoEdicao();
  pnlRender();
}
async function pnlSalvarPainel(){
  const slug = pnlPainelAtual.slug;
  const r = await api('salvarRmPainelLayout', { contaId: contaAtual().id, slug, widgets: pnlPainelWidgets, filtros: pnlPainelFiltros, medidas: pnlPainelMedidas });
  if(!r.ok){ toast(r.erro || 'Não foi possível salvar o layout.'); return; }
  pnlPainelWidgetsSalvos = JSON.parse(JSON.stringify(pnlPainelWidgets));
  pnlPainelFiltrosSalvos = JSON.parse(JSON.stringify(pnlPainelFiltros));
  pnlPainelMedidasSalvos = JSON.parse(JSON.stringify(pnlPainelMedidas));
  const idx = rmPainelLayouts.findIndex(p=>p.slug===slug);
  if(idx>=0){ rmPainelLayouts[idx].widgets = pnlPainelWidgetsSalvos; rmPainelLayouts[idx].filtros = pnlPainelFiltrosSalvos; rmPainelLayouts[idx].medidas = pnlPainelMedidasSalvos; }
  else rmPainelLayouts.push({ slug, widgets:pnlPainelWidgetsSalvos, filtros:pnlPainelFiltrosSalvos, medidas:pnlPainelMedidasSalvos });
  pnlSairModoEdicao();
  pnlRender();
  toast('Layout do painel salvo.');
}

function renderValoresForm(){
  document.getElementById('vl_atendente').innerHTML = contas.filter(c=>c.perfil==='ATENDENTE').map(a=>`<option value="${a.id}">${a.nome}</option>`).join('');
  document.getElementById('vl_cliente').innerHTML = clientesParaSelecao().map(c=>`<option value="${c.id}">${c.nome}</option>`).join('');
  document.getElementById('vl_tipo').innerHTML = tipos.map(t=>`<option value="${t.id}">${t.nome}</option>`).join('');

  const atendentes = contas.filter(c=>c.perfil==='ATENDENTE');
  const filtroEl = document.getElementById('filtroValoresAtendente');
  filtroEl.innerHTML = `<div class="chip ${filtroValoresAtendenteId==='TODOS'?'on':''}" data-atendente="TODOS">Todos</div>` +
    atendentes.map(a=>`<div class="chip ${filtroValoresAtendenteId===a.id?'on':''}" data-atendente="${a.id}">${a.nome}</div>`).join('');
}
function renderTabelaValores(){
  const el = document.getElementById('tabelaValores');
  let itens = valores.slice();
  if(filtroValoresAtendenteId !== 'TODOS') itens = itens.filter(v=>String(v.atendenteId)===String(filtroValoresAtendenteId));
  if(itens.length===0){ el.innerHTML = `<tr><td>Nenhum valor definido.</td></tr>`; return; }
  const linhas = itens.map(v=>{
    const atendente = contas.find(c=>String(c.id)===String(v.atendenteId))?.nome || '—';
    const cliente = clientes.find(c=>String(c.id)===String(v.clienteId))?.nome || '—';
    const tipo = tipos.find(t=>String(t.id)===String(v.tipoId))?.nome || '—';
    return `<tr><td>${atendente}</td><td>${cliente}</td><td>${labelTipo(tipo)}</td><td>${fmtMoeda(Number(v.real))}</td><td>${fmtMoeda(Number(v.ananda))}</td><td>${fmtMoeda(Number(v.valorSegundoAtend)||0)}</td>
      <td><button class="danger" onclick="pedirConfirmacao('Remover valor?','', ()=>removerValor('${v.id}'))">✕</button></td></tr>`;
  }).join('');
  el.innerHTML = `<tr><th>Atendente</th><th>Cliente</th><th>Tipo</th><th>Real/h</th><th>Valor Atendente/h</th><th>Valor 2º Atendente/h</th><th></th></tr>${linhas}`;
}
async function removerValor(id){
  const r = await api('removerValor', { contaId: contaAtual().id, id });
  if(!r.ok){ toast(r.erro || 'Não foi possível remover.'); return; }
  await carregarTudo({ comAtendimentos: false }); renderTabelaValores();
  toast('Valor removido');
}

async function recalcularValores(){
  const btn = document.getElementById('btnRecalcularValores');
  btn.disabled = true;
  btn.textContent = 'Recalculando…';
  try{
    const conta = contaAtual();
    const r = await api('recalcularValores', { contaId: conta.id, empresaId: empresaAtual ? empresaAtual.id : '' });
    if(!r.ok){ toast(r.erro || 'Não foi possível recalcular.'); return; }
    await carregarTudo();
    renderLista(); renderResumo();
    toast(`${r.atualizados} atualizados, ${r.semCorrespondencia||0} sem valor cadastrado (não mexidos), de ${r.total} no total`);
  }catch(e){
    toast(e && e.message ? e.message : 'Não foi possível recalcular.');
  } finally {
    btn.disabled = false;
    btn.textContent = 'Recalcular valores de todos os atendimentos';
  }
}

// termo de busca da lista de usuários (Cadastros → Usuários) — cliente-side
// só, já que a lista inteira já vem carregada; filtra por nome/login/
// cliente/e-mail, sem diferenciar maiúsculas/acentos
let usuariosBusca = '';
function normalizarBuscaTexto(s){
  return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
}
function renderListUsuarios(){
  document.getElementById('us_cliente').innerHTML = clientesParaSelecao().map(c=>`<option value="${c.id}">${c.nome}</option>`).join('');
  let lista = contas.filter(c=>c.perfil==='USUARIO');
  const termo = normalizarBuscaTexto(usuariosBusca.trim());
  if(termo){
    lista = lista.filter(u=>{
      const cliente = clientes.find(c=>String(c.id)===String(u.clienteId))?.nome || '';
      return [u.nome, u.login, cliente, u.email].some(v=>normalizarBuscaTexto(v).includes(termo));
    });
  }
  const el = document.getElementById('listUsuarios');
  if(lista.length===0){ el.innerHTML = `<div class="empty">${termo ? 'Nenhum usuário encontrado com esse filtro.' : 'Nenhum usuário cadastrado.'}</div>`; return; }
  el.innerHTML = lista.map(u=>{
    const cliente = clientes.find(c=>String(c.id)===String(u.clienteId))?.nome || '—';
    const contatos = linhaContatos(u.email, u.telefone);
    const selo = u.adminCliente ? ` <span class="tag" style="color:var(--accent);">admin do cliente</span>` : '';
    return `<div class="cad-item" style="cursor:pointer;" onclick="editarUsuario('${u.id}')">
      <div class="info"><b>${u.nome}${selo}</b><span>${cliente} · login: ${u.login}</span>${contatos}</div>
      <div class="acts"><button class="danger" onclick="event.stopPropagation();pedirConfirmacao('Remover usuário?','${u.nome} perderá acesso ao sistema.', ()=>removerConta('${u.id}'))">Remover</button></div>
    </div>`;
  }).join('');
}

function editarUsuario(id){
  const u = contas.find(c=>String(c.id)===String(id));
  if(!u) return;
  editandoUsuarioId = id;
  document.getElementById('us_tituloForm').textContent = `Editando: ${u.nome}`;
  document.getElementById('us_cliente').value = u.clienteId;
  document.getElementById('us_nome').value = u.nome;
  document.getElementById('us_login').value = u.login;
  document.getElementById('us_senha').value = '';
  document.getElementById('us_senha_hint').style.display = '';
  document.getElementById('us_email').value = u.email || '';
  document.getElementById('us_telefone').value = u.telefone || '';
  document.getElementById('us_admin_cliente').checked = !!u.adminCliente;
  renderPerfisAcessoCheckboxes('us_perfis_acesso', u.perfisAcessoIds||[]);
  renderPaineisVinculoCheckboxes('us_paineis', u.painelIds||[]);
  document.getElementById('btnAddUsuario').textContent = 'Salvar alterações';
  document.getElementById('btnCancelarEdicaoUsuario').style.display = '';

  const historico = atendimentos.filter(a=>a.usuario === u.nome).slice().sort((a,b)=>String(b.data).localeCompare(String(a.data)));
  const cardHist = document.getElementById('historicoUsuarioCard');
  const contHist = document.getElementById('historicoUsuario');
  if(historico.length === 0){
    contHist.innerHTML = `<div class="empty">Nenhum atendimento registrado ainda.</div>`;
  }else{
    contHist.innerHTML = historico.map(r=>{
      const [y,m,d] = String(r.data).split('-');
      return `<div class="cad-item" style="cursor:default;">
        <div class="info"><b>${d}/${m}/${y} · ${labelTipo(r.tipo)}</b><span>${r.atendente} · ${r.qtd ? Number(r.qtd).toFixed(2).replace('.',',')+'h' : ''}</span></div>
        <span class="tag status-${statusSlug(r.status)}">${r.status}</span>
      </div>`;
    }).join('');
  }
  cardHist.style.display = '';
  document.getElementById('us_nome').scrollIntoView({behavior:'smooth', block:'start'});
}

function cancelarEdicaoUsuario(){
  editandoUsuarioId = null;
  document.getElementById('us_tituloForm').textContent = 'Novo usuário solicitante (login)';
  document.getElementById('us_nome').value = '';
  document.getElementById('us_login').value = '';
  document.getElementById('us_senha').value = '';
  document.getElementById('us_senha_hint').style.display = 'none';
  document.getElementById('us_email').value = '';
  document.getElementById('us_telefone').value = '';
  document.getElementById('us_admin_cliente').checked = false;
  renderPerfisAcessoCheckboxes('us_perfis_acesso', []);
  renderPaineisVinculoCheckboxes('us_paineis', []);
  document.getElementById('btnAddUsuario').textContent = 'Adicionar usuário';
  document.getElementById('btnCancelarEdicaoUsuario').style.display = 'none';
  document.getElementById('historicoUsuarioCard').style.display = 'none';
}

function linkWhatsapp(telefone){
  if(!telefone) return '';
  let digitos = String(telefone).replace(/\D/g,'');
  if(!digitos) return '';
  if(digitos.length <= 11) digitos = '55' + digitos; // assume Brasil quando não vem com DDI
  return `https://wa.me/${digitos}`;
}

// texto de aviso do prazo de validação automática (some quando falta o
// dado de quando entrou em validação, ex: registro antigo)
function textoPrazoValidacao(r){
  if(!r.emValidacaoDesde || !empresaAtual) return '';
  const horas = Number(empresaAtual.horasValidacaoAutomatica) || 48;
  const prazo = new Date(r.emValidacaoDesde);
  prazo.setHours(prazo.getHours() + horas);
  const dd = String(prazo.getDate()).padStart(2,'0'), mm = String(prazo.getMonth()+1).padStart(2,'0');
  const hh = String(prazo.getHours()).padStart(2,'0'), mi = String(prazo.getMinutes()).padStart(2,'0');
  return `<br><span style="color:var(--muted);">Se ninguém aprovar até ${dd}/${mm} às ${hh}:${mi}, ele é validado automaticamente.</span>`;
}

async function aprovarValidacaoUi(id){
  const conta = contaAtual();
  const r = await api('aprovarValidacao', { contaId: conta.id, id });
  if(!r.ok){ toast(r.erro || 'Não foi possível aprovar a validação.'); return; }
  toast('Validação aprovada — chamado encerrado');
  await carregarTudo();
  renderLista();
  fecharChat();
}

async function rejeitarValidacaoUi(id){
  const motivo = document.getElementById('chatMotivoRejeicao').value.trim();
  const conta = contaAtual();
  const r = await api('rejeitarValidacao', { contaId: conta.id, id, motivo });
  if(!r.ok){ toast(r.erro || 'Não foi possível rejeitar a validação.'); return; }
  toast('Validação rejeitada — o atendente vai revisar');
  await carregarTudo();
  renderLista();
  fecharChat();
}

/* ---------- bate-papo por atendimento ---------- */
let chatAtendimentoId = null;
let chatPodeRemoverVinculo = false;
let movimentacoesCache = [];

async function abrirDetalhe(atendimentoId){
  const r = atendimentos.find(x=>String(x.id)===String(atendimentoId));
  if(!r || !podeUsarChat(r)) return;
  chatAtendimentoId = atendimentoId;
  const [y,m,d] = String(r.data).split('-');
  const modSub = [r.modulo, r.submodulo].filter(Boolean).join(' · ');
  const conta = contaAtual();
  const isUsuario = conta && conta.perfil === 'USUARIO';

  document.getElementById('chatTitulo').textContent = `${r.cliente} · ${r.usuario}`;
  document.getElementById('chatSub').textContent = `#${r.id} · Atendente: ${r.atendente || '(a definir)'}${r.atendente2 ? ' + '+r.atendente2+' (2º)' : ''} · ${d}/${m}/${y} · ${r.status}`;
  const horario = `${r.hi}–${r.hf}${r.inter && r.inter!=='00:00' ? ' (intervalo '+r.inter+')' : ''}`;
  const totalApurado = `${Number(r.qtd||0).toFixed(2).replace('.',',')}h`;
  let dataPrevistaTexto = '';
  if(r.dataPrevista){
    const [py,pm,pd] = String(r.dataPrevista).split('-');
    dataPrevistaTexto = `${pd}/${pm}/${py}`;
  }
  document.getElementById('chatResumo').innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px 14px;font-size:12.5px;margin-bottom:10px;">
      <div><span style="color:var(--muted);">Tipo</span><br>${labelTipo(r.tipo)}</div>
      <div><span style="color:var(--muted);">Total apurado nas movimentações</span><br>${totalApurado}<span style="color:var(--muted);font-size:10.5px;"> (cadastro: ${horario})</span></div>
      ${dataPrevistaTexto ? `<div><span style="color:var(--muted);">Previsão de conclusão</span><br>${dataPrevistaTexto} ${flagPrazo(r)}</div>` : ''}
    </div>
    ${modSub ? `<div style="color:var(--accent);font-weight:600;font-size:12.5px;margin-bottom:4px;">${modSub}</div>` : ''}
    ${r.assunto ? `<div style="font-weight:600;font-size:13px;margin-bottom:4px;">${escaparHtml(r.assunto)}</div>` : ''}
    ${r.detalhe ? `<div class="rt-content" style="font-size:12.5px;color:var(--muted);margin-top:2px;">${sanitizarHtml(r.detalhe)}</div>` : ''}
    ${r.solucao ? `<div style="font-size:12.5px;margin-top:8px;padding:8px 10px;background:var(--panel-2);border-radius:8px;"><b style="color:var(--ok);display:block;margin-bottom:4px;">Solução:</b><div class="rt-content">${sanitizarHtml(r.solucao)}</div></div>` : ''}
    ${(isUsuario && r.status === 'EM VALIDAÇÃO') ? `
      <div style="font-size:12.5px;margin-top:8px;padding:10px;background:var(--panel-2);border-radius:8px;">
        <b>Esse chamado está em validação.</b> Confirma que ficou tudo certo?
        ${textoPrazoValidacao(r)}
        <textarea id="chatMotivoRejeicao" placeholder="Se for rejeitar, explique o motivo (opcional)" style="width:100%;margin-top:8px;min-height:50px;font-size:12.5px;padding:8px;border-radius:8px;border:1px solid var(--line);background:var(--bg);color:inherit;box-sizing:border-box;"></textarea>
        <div style="display:flex;gap:8px;margin-top:8px;">
          <button class="primary" style="flex:1;margin-top:0;" onclick="aprovarValidacaoUi('${r.id}')">✓ Aprovar</button>
          <button class="danger" style="flex:1;" onclick="rejeitarValidacaoUi('${r.id}')">✗ Rejeitar</button>
        </div>
      </div>` : ''}
  `;
  document.getElementById('chatVinculosWrap').style.display = 'none';
  document.getElementById('chatVideosWrap').style.display = 'none';
  document.getElementById('chatAnexosLista').innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Carregando…</div>`;
  document.getElementById('chatHistorico').innerHTML = `<div class="chat-empty">Carregando…</div>`;
  document.getElementById('movLista').innerHTML = `<div class="chat-empty">Carregando…</div>`;
  movLimparComposer('');
  document.getElementById('chatModal').classList.add('show');
  if(!isUsuario) carregarVideosCacheParaVinculo();
  await Promise.all([
    carregarHistorico(),
    carregarMovimentacoes(atendimentoId, ''),
    carregarAnexosDetalhe(atendimentoId, !isUsuario),
    carregarVinculosDetalhe(atendimentoId, !isUsuario),
    carregarVideosDetalhe(atendimentoId, !isUsuario),
  ]);
}

async function carregarAnexosDetalhe(atendimentoId, podeRemover){
  try{
    const r = await api('listarAnexos', { atendimentoId });
    if(!r.ok){ document.getElementById('chatAnexosLista').innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">${r.erro||'Não foi possível carregar os anexos.'}</div>`; return; }
    renderAnexosGenerico('chatAnexosLista', r.anexos, atendimentoId, podeRemover);
  }catch(e){
    document.getElementById('chatAnexosLista').innerHTML = `<div class="empty" style="padding:8px 0;font-size:12.5px;">Não foi possível carregar os anexos.</div>`;
  }
}

async function carregarVinculosDetalhe(atendimentoId, podeGerenciar){
  const wrap = document.getElementById('chatVinculosWrap');
  document.getElementById('chatVinculoAdd').style.display = podeGerenciar ? '' : 'none';
  chatPodeRemoverVinculo = podeGerenciar;
  try{
    const r = await recarregarVinculos(atendimentoId, 'chatVinculos', podeGerenciar);
    if(!r) { wrap.style.display = podeGerenciar ? '' : 'none'; return; }
    const temVinculos = r.vinculados && r.vinculados.length > 0;
    // sem gerência (usuário) e sem nenhum vínculo, não mostra a seção — pra quem gerencia, mostra sempre (pra poder adicionar)
    wrap.style.display = (podeGerenciar || temVinculos) ? '' : 'none';
    if(temVinculos){
      const totalEl = document.createElement('div');
      totalEl.style.cssText = 'text-align:right;font-size:12.5px;margin-top:6px;color:var(--accent);font-weight:600;';
      totalEl.textContent = `Total de horas (com vinculados): ${r.horasTotais.toFixed(2).replace('.',',')}h`;
      document.getElementById('chatVinculos').appendChild(totalEl);
    }
  }catch(e){ /* silencioso — vínculo é informação complementar */ }
}

async function carregarVideosDetalhe(atendimentoId, podeGerenciar){
  const wrap = document.getElementById('chatVideosWrap');
  document.getElementById('chatVideoVinculoAdd').style.display = podeGerenciar ? '' : 'none';
  try{
    const r = await recarregarVideosVinculados(atendimentoId, 'chatVideosVinculo', podeGerenciar);
    if(!r) { wrap.style.display = podeGerenciar ? '' : 'none'; return; }
    const temVideos = r.videos && r.videos.length > 0;
    // sem gerência (usuário) e sem nenhum vídeo, não mostra a seção — pra quem gerencia, mostra sempre (pra poder adicionar)
    wrap.style.display = (podeGerenciar || temVideos) ? '' : 'none';
  }catch(e){ /* silencioso — vídeo vinculado é informação complementar */ }
}

function fecharChat(){
  chatAtendimentoId = null;
  document.getElementById('chatModal').classList.remove('show');
}

async function carregarHistorico(){
  if(!chatAtendimentoId) return;
  const cont = document.getElementById('chatHistorico');
  let r;
  try{
    r = await api('listarHistorico', { atendimentoId: chatAtendimentoId });
  }catch(e){
    cont.innerHTML = `<div class="chat-empty">Não foi possível carregar o histórico.</div>`;
    return;
  }
  if(!r.ok){
    cont.innerHTML = `<div class="chat-empty">${r.erro || 'Não foi possível carregar o histórico.'}</div>`;
    return;
  }
  if(r.historico.length === 0){
    cont.innerHTML = `<div class="chat-empty">Sem ocorrências ainda.</div>`;
    return;
  }
  cont.innerHTML = r.historico.map(h=>`
    <div style="font-size:11.5px;color:var(--muted);padding:4px 0;border-bottom:1px dashed var(--line);">
      ${escaparHtml(h.descricao)} <span style="opacity:.6;">· ${String(h.dataHora||'').slice(0,16)}</span>
    </div>`).join('');
}

let movEstado = {
  '': { atendimentoId: null, cache: [], respondendoId: null, editandoId: null, anexoArquivo: null },
  '_ed': { atendimentoId: null, cache: [], respondendoId: null, editandoId: null, anexoArquivo: null },
};
// os dois lugares onde as movimentações aparecem (modal de detalhes e a
// tela de editar atendimento) usam nomes de campo ligeiramente
// diferentes — esse mapa resolve pra cada sufixo
function movIds(sufixo){
  return sufixo === '_ed' ? {
    lista:'movLista_ed', composer:'movComposerWrap_ed', respWrap:'movRespondendoWrap_ed', respTexto:'movRespondendoTexto_ed',
    respCancelar:'movCancelarResposta_ed', texto:'mov_texto_ed', anexo:'mov_anexo_ed', anexoNome:'mov_anexo_ed_nome',
    btnEnviar:'btnEnviarMovimentacao_ed', btnFinalizar:'btnFinalizarAtendimento_ed', bloqueado:'movBloqueadoAviso_ed',
    camposTempo:'movCamposTempo_ed', datasWrap:'movCamposTempoDatas_ed', ehResposta:'mov_e_resposta_ed',
    dataIni:'mov_data_ini_ed', horaIni:'mov_hora_ini_ed',
    dataFim:'mov_data_fim_ed', horaFim:'mov_hora_fim_ed', intervalo:'mov_intervalo_ed',
  } : {
    lista:'movLista', composer:'movComposerWrap', respWrap:'movRespondendoWrap', respTexto:'movRespondendoTexto',
    respCancelar:'movCancelarResposta', texto:'mov_texto', anexo:'mov_anexo', anexoNome:'mov_anexo_nome',
    btnEnviar:'btnEnviarMovimentacao', btnFinalizar:'btnFinalizarAtendimento', bloqueado:'movBloqueadoAviso',
    camposTempo:'movCamposTempo', datasWrap:'movCamposTempoDatas', ehResposta:'mov_e_resposta',
    dataIni:'mov_data_ini', horaIni:'mov_hora_ini',
    dataFim:'mov_data_fim', horaFim:'mov_hora_fim', intervalo:'mov_intervalo',
  };
}

function movLabelPerfil(perfil){
  return perfil === 'USUARIO' ? 'Cliente' : perfil === 'ATENDENTE' ? 'Atendente' : 'Admin';
}
function movIniciais(nome){
  const partes = String(nome||'').trim().split(/\s+/);
  return ((partes[0]?.[0]||'') + (partes[1]?.[0]||'')).toUpperCase();
}
function movFmtDataHora(iso){
  if(!iso) return '';
  const d = new Date(iso);
  // fixa o fuso de Fortaleza em vez de confiar no fuso do aparelho —
  // um dispositivo com fuso mal configurado mostrava o horário em UTC (3h adiantado)
  return d.toLocaleDateString('pt-BR', {timeZone:'America/Fortaleza'}) + ' ' + d.toLocaleTimeString('pt-BR', {hour:'2-digit',minute:'2-digit',timeZone:'America/Fortaleza'});
}
// apuração de tempo da movimentação: só quem atende registra (pro Usuário o
// campo de movimentação continua só texto/anexo, como sempre foi)
function movPodeUsarTempo(){
  const conta = contaAtual();
  return !!conta && conta.perfil !== 'USUARIO';
}
function movTemTempo(m){
  return !!(m.dataInicial && m.horaInicial && m.dataFinal && m.horaFinal);
}
// duração em horas (decimal) de uma movimentação com apuração de tempo —
// só pra exibir na tela; quem manda de verdade no total é o "qtd" do
// atendimento, recalculado no servidor
function movDuracaoHoras(m){
  if(!movTemTempo(m)) return 0;
  const ini = new Date(`${m.dataInicial}T${m.horaInicial}:00`).getTime();
  const fim = new Date(`${m.dataFinal}T${m.horaFinal}:00`).getTime();
  return Math.max(0, (fim-ini)/60000 - (Number(m.intervaloMin)||0)) / 60;
}
function movFmtDataBr(iso){
  const p = String(iso||'').split('-');
  return p.length === 3 ? `${p[2]}/${p[1]}` : '';
}
function movFmtPeriodo(m){
  const mesmaData = m.dataInicial === m.dataFinal;
  return `${movFmtDataBr(m.dataInicial)} ${m.horaInicial} → ${mesmaData ? '' : movFmtDataBr(m.dataFinal)+' '}${m.horaFinal}`;
}
// o campo de Intervalo é um <input type="time"> (mesma cara de Hora
// Inicial/Final, ex: "00:15") — guardado/enviado sempre em minutos
function movIntervaloParaMin(hhmm){
  const [h,m] = String(hhmm||'00:00').split(':').map(Number);
  return (h||0)*60 + (m||0);
}
function movMinParaIntervalo(min){
  min = Math.max(0, Number(min)||0);
  return `${String(Math.floor(min/60)).padStart(2,'0')}:${String(Math.round(min%60)).padStart(2,'0')}`;
}
// mostra/esconde os campos de Data/Horário Inicial e Final no composer,
// conforme o perfil de quem está logado — chamada sempre que o composer é
// preparado (limpo ou entrando em modo de edição de uma movimentação)
function movAtualizarVisibilidadeTempo(sufixo){
  const ids = movIds(sufixo);
  document.getElementById(ids.camposTempo).style.display = movPodeUsarTempo() ? '' : 'none';
}
// marcado como "é uma resposta", esconde Data/Horário Inicial e Final —
// não faz sentido perguntar horário de uma resposta, o cálculo já é 0h
function movAtualizarVisibilidadeDatas(sufixo){
  const ids = movIds(sufixo);
  const marcado = document.getElementById(ids.ehResposta).checked;
  document.getElementById(ids.datasWrap).style.display = marcado ? 'none' : '';
}
// botão "Finalizar atendimento" só aparece pra quem atende (não Usuário),
// escrevendo uma movimentação nova (não editando uma já existente) e com o
// chamado ainda não em validação/concluído — senão seria redundante
function movAtualizarVisibilidadeFinalizar(sufixo){
  const ids = movIds(sufixo);
  const estado = movEstado[sufixo];
  const btn = document.getElementById(ids.btnFinalizar);
  if(!btn) return;
  const r = atendimentos.find(x=>String(x.id)===String(estado.atendimentoId));
  const podeFinalizar = movPodeUsarTempo() && !estado.editandoId && r && r.status !== 'CONCLUÍDO' && r.status !== 'EM VALIDAÇÃO';
  btn.style.display = podeFinalizar ? '' : 'none';
}
async function carregarMovimentacoes(atendimentoId, sufixo){
  sufixo = sufixo || '';
  const ids = movIds(sufixo);
  const estado = movEstado[sufixo];
  estado.atendimentoId = atendimentoId;
  if(!atendimentoId) return;
  const cont = document.getElementById(ids.lista);
  const r = atendimentos.find(x=>String(x.id)===String(atendimentoId));
  const bloqueado = r && r.status === 'CONCLUÍDO';
  document.getElementById(ids.composer).style.display = bloqueado ? 'none' : '';
  document.getElementById(ids.bloqueado).style.display = bloqueado ? '' : 'none';
  movAtualizarVisibilidadeFinalizar(sufixo);

  let resp;
  try{
    const conta = contaAtual();
    resp = await api('listarMovimentacoes', { atendimentoId, contaId: conta ? conta.id : '' });
  }catch(e){
    cont.innerHTML = `<div class="chat-empty">Não foi possível carregar as movimentações.</div>`;
    return;
  }
  if(!resp.ok){ cont.innerHTML = `<div class="chat-empty">${resp.erro || 'Não foi possível carregar as movimentações.'}</div>`; return; }
  // abrir a lista já marca como "vista" no servidor — reflete isso na hora
  // na tela também (bolinha do card e do menu), sem esperar o próximo
  // carregarTudo() apagar tudo
  if(r && r.naoLidas){
    r.naoLidas = false;
    atualizarBadgeAtendimentos();
    if(document.getElementById('view-lista').classList.contains('active')) renderLista();
  }

  estado.cache = resp.movimentacoes || [];
  if(estado.cache.length === 0){
    cont.innerHTML = `<div class="chat-empty">Nenhuma movimentação ainda.</div>`;
    return;
  }
  const conta = contaAtual();
  cont.innerHTML = estado.cache.map(m=>{
    const citada = m.respondendoA ? estado.cache.find(x=>x.id===m.respondendoA) : null;
    const podeGerenciar = !bloqueado && conta && (ehAdminEfetivo(conta) || conta.nome === m.autorNome);
    return `<div class="mov-item">
      ${citada ? `<div class="mov-respondendo-item">Em resposta a <b>${escaparHtml(citada.autorNome)}</b>: "${escaparHtml(stripHtml(citada.texto).slice(0,60))}"</div>` : ''}
      <div class="mov-topo">
        <div class="mov-autor">
          <div class="mov-avatar">${movIniciais(m.autorNome)}</div>
          <div><span class="mov-nome">${escaparHtml(m.autorNome)}</span><span class="mov-perfil ${m.autorPerfil}">${movLabelPerfil(m.autorPerfil)}</span>${m.ehResposta ? `<span class="mov-perfil mov-resposta-tag">↩ Resposta</span>` : ''}</div>
        </div>
        <div class="mov-data">${movFmtDataHora(m.criadoEm)}</div>
      </div>
      ${movTemTempo(m) ? `<div class="mov-tempo">🕐 ${movFmtPeriodo(m)}${m.intervaloMin ? ' · intervalo '+m.intervaloMin+'min' : ''}<span class="mov-tempo-dur">${movDuracaoHoras(m).toFixed(2).replace('.',',')}h</span></div>` : ''}
      <div class="mov-conteudo rt-content">${sanitizarHtml(m.texto)}</div>
      ${(m.anexos && m.anexos.length>0) ? m.anexos.map(a=>`<div class="mov-anexo-item">📎 <a href="${a.url}" target="_blank">${escaparHtml(a.nome)}</a> · <a href="${urlDownloadAnexo(a.url, a.nome)}" title="Baixar arquivo original">⬇ Baixar</a></div>`).join('') : ''}
      <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:2px;">
        ${!bloqueado ? `<button type="button" class="mov-btn-responder" onclick="responderMovimentacao('${m.id}','${sufixo}')">↩ Responder</button>` : ''}
        ${podeGerenciar ? `<button type="button" class="mov-btn-responder" onclick="editarMovimentacaoUi('${m.id}','${sufixo}')">✎ Editar</button>` : ''}
        ${podeGerenciar ? `<button type="button" class="mov-btn-responder" onclick="excluirMovimentacaoUi('${m.id}','${sufixo}')">🗑 Excluir</button>` : ''}
      </div>
    </div>`;
  }).join('');
}

function movLimparComposer(sufixo){
  const ids = movIds(sufixo);
  const estado = movEstado[sufixo];
  document.getElementById(ids.texto).innerHTML = '';
  document.getElementById(ids.anexo).value = '';
  document.getElementById(ids.anexoNome).textContent = '';
  document.getElementById(ids.respWrap).style.display = 'none';
  estado.respondendoId = null;
  estado.editandoId = null;
  estado.anexoArquivo = null;
  document.getElementById(ids.btnEnviar).textContent = 'Enviar';
  document.getElementById(ids.dataIni).value = hojeLocalISO();
  document.getElementById(ids.dataFim).value = hojeLocalISO();
  document.getElementById(ids.horaIni).value = '';
  document.getElementById(ids.horaFim).value = '';
  document.getElementById(ids.intervalo).value = '00:00';
  document.getElementById(ids.ehResposta).checked = false;
  movAtualizarVisibilidadeTempo(sufixo);
  movAtualizarVisibilidadeDatas(sufixo);
  movAtualizarVisibilidadeFinalizar(sufixo);
}

function responderMovimentacao(id, sufixo){
  sufixo = sufixo || '';
  const ids = movIds(sufixo);
  const estado = movEstado[sufixo];
  const m = estado.cache.find(x=>x.id===id);
  if(!m) return;
  estado.editandoId = null;
  estado.respondendoId = id;
  document.getElementById(ids.respTexto).textContent = `Respondendo a ${m.autorNome}: "${stripHtml(m.texto).slice(0,60)}"`;
  document.getElementById(ids.respWrap).style.display = 'flex';
  document.getElementById(ids.btnEnviar).textContent = 'Enviar';
  document.getElementById(ids.texto).focus();
}

function editarMovimentacaoUi(id, sufixo){
  sufixo = sufixo || '';
  const ids = movIds(sufixo);
  const estado = movEstado[sufixo];
  const m = estado.cache.find(x=>x.id===id);
  if(!m) return;
  estado.respondendoId = null;
  estado.editandoId = id;
  document.getElementById(ids.texto).innerHTML = sanitizarHtml(m.texto || '');
  document.getElementById(ids.respTexto).textContent = `Editando a movimentação de ${m.autorNome}`;
  document.getElementById(ids.respWrap).style.display = 'flex';
  document.getElementById(ids.btnEnviar).textContent = 'Salvar edição';
  movAtualizarVisibilidadeTempo(sufixo);
  document.getElementById(ids.dataIni).value = m.dataInicial || hojeLocalISO();
  document.getElementById(ids.horaIni).value = m.horaInicial || '';
  document.getElementById(ids.dataFim).value = m.dataFinal || hojeLocalISO();
  document.getElementById(ids.horaFim).value = m.horaFinal || '';
  document.getElementById(ids.intervalo).value = movMinParaIntervalo(m.intervaloMin);
  document.getElementById(ids.ehResposta).checked = !!m.ehResposta;
  movAtualizarVisibilidadeDatas(sufixo);
  movAtualizarVisibilidadeFinalizar(sufixo);
  document.getElementById(ids.texto).focus();
}

function cancelarRespostaMovimentacao(sufixo){
  sufixo = sufixo || '';
  const ids = movIds(sufixo);
  const estado = movEstado[sufixo];
  estado.respondendoId = null;
  estado.editandoId = null;
  document.getElementById(ids.respWrap).style.display = 'none';
  document.getElementById(ids.btnEnviar).textContent = 'Enviar';
  movAtualizarVisibilidadeFinalizar(sufixo);
}

async function excluirMovimentacaoUi(id, sufixo){
  sufixo = sufixo || '';
  const estado = movEstado[sufixo];
  pedirConfirmacao('Excluir movimentação?', 'Essa ação não pode ser desfeita.', async ()=>{
    const conta = contaAtual();
    const r = await api('removerMovimentacao', { contaId: conta.id, id });
    if(!r.ok){ toast(r.erro || 'Não foi possível excluir.'); return; }
    await carregarMovimentacoes(estado.atendimentoId, sufixo);
    atualizarPreview();
    toast('Movimentação excluída');
  });
}

// pedido de confirmação antes de finalizar — muda o status do chamado pra
// "EM VALIDAÇÃO" (aguardando o usuário aprovar/rejeitar), então merece um
// passo a mais antes de disparar
function finalizarAtendimentoUi(sufixo){
  sufixo = sufixo || '';
  pedirConfirmacao(
    'Finalizar atendimento?',
    'O chamado vai para "Em Validação", aguardando o usuário confirmar que ficou tudo certo.',
    ()=>enviarMovimentacao(sufixo, true),
    'Finalizar'
  );
}

async function enviarMovimentacao(sufixo, finalizar){
  sufixo = sufixo || '';
  finalizar = !!finalizar;
  const ids = movIds(sufixo);
  const estado = movEstado[sufixo];
  if(!estado.atendimentoId) return;
  const conta = contaAtual();
  const textoHtml = sanitizarHtml(document.getElementById(ids.texto).innerHTML.trim());
  const textoLimpo = stripHtml(textoHtml).trim();
  // finalizar sem escrever nada: usa um texto padrão em vez de travar o
  // clique — é comum querer só apertar o botão sem digitar comentário
  const textoParaEnviar = (!textoLimpo && !estado.anexoArquivo && finalizar)
    ? 'Atendimento finalizado — aguardando validação do usuário.'
    : textoHtml;
  if(!textoLimpo && !estado.anexoArquivo && !finalizar){ toast('Escreva algo ou anexe um arquivo'); return; }

  // apuração de tempo é opcional: os 4 campos (data/horário inicial e
  // final) precisam vir todos preenchidos ou todos vazios — só quem atende
  // vê esses campos (pro Usuário nem aparecem, então nunca preenchidos).
  // Marcado como "é uma resposta", nem olha esses campos — vale 0h direto
  const ehResposta = movPodeUsarTempo() && document.getElementById(ids.ehResposta).checked;
  let camposTempo = { ehResposta };
  if(movPodeUsarTempo() && !ehResposta){
    const dataIni = document.getElementById(ids.dataIni).value, horaIni = document.getElementById(ids.horaIni).value;
    const dataFim = document.getElementById(ids.dataFim).value, horaFim = document.getElementById(ids.horaFim).value;
    const preenchidos = [dataIni, horaIni, dataFim, horaFim].filter(Boolean).length;
    if(preenchidos > 0 && preenchidos < 4){
      toast('Preencha Data e Horário Inicial e Final, ou deixe os quatro em branco.');
      return;
    }
    if(preenchidos === 4){
      const intervaloMin = movIntervaloParaMin(document.getElementById(ids.intervalo).value);
      if(new Date(`${dataFim}T${horaFim}:00`) <= new Date(`${dataIni}T${horaIni}:00`)){
        toast('O horário final precisa ser depois do horário inicial.');
        return;
      }
      camposTempo = { ehResposta, dataInicial: dataIni, horaInicial: horaIni, dataFinal: dataFim, horaFinal: horaFim, intervaloMin };
    }
  }

  const btn = document.getElementById(ids.btnEnviar);
  const btnFinalizar = document.getElementById(ids.btnFinalizar);
  const editando = !!estado.editandoId;
  btn.disabled = true;
  if(btnFinalizar) btnFinalizar.disabled = true;
  btn.textContent = editando ? 'Salvando…' : 'Enviando…';
  if(finalizar && btnFinalizar) btnFinalizar.textContent = 'Finalizando…';
  try{
    let r;
    if(editando){
      r = await api('atualizarMovimentacao', { contaId: conta.id, id: estado.editandoId, texto: textoHtml, ...camposTempo });
    }else{
      const payload = {
        atendimentoId: estado.atendimentoId, texto: textoParaEnviar, autorNome: conta.nome, autorPerfil: conta.perfil,
        respondendoA: estado.respondendoId, contaId: conta.id, finalizar, ...camposTempo,
      };
      if(estado.anexoArquivo){
        payload.anexoBase64 = await lerArquivoBase64(estado.anexoArquivo);
        payload.anexoTipo = estado.anexoArquivo.type;
        payload.anexoNome = estado.anexoArquivo.name;
      }
      r = await api('criarMovimentacao', payload);
    }
    if(!r.ok){ toast(r.erro || 'Não foi possível salvar.'); return; }
    if(finalizar){
      toast('Atendimento finalizado — aguardando validação do usuário');
      // o status virou "EM VALIDAÇÃO" e a Solução foi preenchida com o texto
      // dessa movimentação no servidor — recarrega tudo pra refletir em
      // todas as telas (lista, kanban, etc); no formulário de edição,
      // também atualiza Status e Solução na tela, senão um "Salvar" logo em
      // seguida reenviaria os valores antigos e desfaria a mudança
      if(sufixo === '_ed'){
        const fStatus = document.getElementById('f_status');
        if(fStatus) fStatus.value = 'EM VALIDAÇÃO';
        const fSolucao = document.getElementById('f_solucao');
        if(fSolucao) fSolucao.innerHTML = sanitizarHtml(textoParaEnviar);
      }
      await carregarTudo();
      renderLista();
      if(sufixo === ''){ fecharChat(); return; }
      movLimparComposer(sufixo);
      await carregarMovimentacoes(estado.atendimentoId, sufixo);
      atualizarPreview();
      return;
    }
    movLimparComposer(sufixo);
    await carregarMovimentacoes(estado.atendimentoId, sufixo);
    atualizarPreview();
    if(editando) toast('Movimentação atualizada');
  }catch(e){
    toast(e && e.message ? e.message : 'Não foi possível salvar.');
  } finally {
    btn.disabled = false;
    btn.textContent = 'Enviar';
    if(btnFinalizar){ btnFinalizar.disabled = false; btnFinalizar.textContent = '✅ Finalizar atendimento'; }
  }
}

function escaparHtml(s){
  const d = document.createElement('div');
  d.textContent = s;
  return d.innerHTML;
}

/* ---------- texto rico (Solução) ---------- */
// remove o que pode ser perigoso (script, iframe, atributos on*, links javascript:)
// mantendo formatação (negrito, listas, imagens) — é um filtro simples, suficiente
// pra um app interno onde só admin/atendente escrevem nesse campo
function sanitizarHtml(html){
  const div = document.createElement('div');
  div.innerHTML = html || '';
  div.querySelectorAll('script,style,iframe,object,embed,link,meta').forEach(el=>el.remove());
  div.querySelectorAll('*').forEach(el=>{
    [...el.attributes].forEach(attr=>{
      const nome = attr.name.toLowerCase();
      if(nome.startsWith('on')) el.removeAttribute(attr.name);
      if((nome==='href' || nome==='src') && /^\s*javascript:/i.test(attr.value)) el.removeAttribute(attr.name);
    });
  });
  return div.innerHTML;
}
function stripHtml(html){
  const d = document.createElement('div');
  d.innerHTML = html || '';
  return (d.textContent || d.innerText || '').replace(/\s+/g,' ').trim();
}

// redimensionar imagem dentro dos editores de texto rico — via um "puxador" fixo
// que segue a imagem selecionada, funciona tanto no mouse quanto no toque (app Android),
// diferente do resize nativo do CSS que não responde a toque
let rtImgSelecionada = null;
let rtImgHandle = null;
function rtImgHandleEl(){
  if(!rtImgHandle){
    rtImgHandle = document.createElement('div');
    rtImgHandle.className = 'rt-img-handle';
    document.body.appendChild(rtImgHandle);
    rtImgHandle.addEventListener('pointerdown', rtIniciarRedimensionamento);
  }
  return rtImgHandle;
}
function rtPosicionarHandle(){
  if(!rtImgSelecionada) return;
  const r = rtImgSelecionada.getBoundingClientRect();
  const h = rtImgHandleEl();
  h.style.left = (r.right - 10) + 'px';
  h.style.top = (r.bottom - 10) + 'px';
}
function rtSelecionarImagem(img){
  if(rtImgSelecionada && rtImgSelecionada !== img) rtImgSelecionada.classList.remove('rt-img-sel');
  rtImgSelecionada = img;
  img.classList.add('rt-img-sel');
  rtImgHandleEl().style.display = 'block';
  rtPosicionarHandle();
}
function rtDeselecionarImagem(){
  if(rtImgSelecionada) rtImgSelecionada.classList.remove('rt-img-sel');
  rtImgSelecionada = null;
  if(rtImgHandle) rtImgHandle.style.display = 'none';
}
function rtIniciarRedimensionamento(e){
  if(!rtImgSelecionada) return;
  e.preventDefault();
  const handle = e.currentTarget;
  const img = rtImgSelecionada;
  const editor = img.closest('.rt-editor');
  const larguraMax = editor ? editor.clientWidth - 20 : 2000;
  const startX = e.clientX;
  const startWidth = img.getBoundingClientRect().width;
  if(handle.setPointerCapture) handle.setPointerCapture(e.pointerId);
  function mover(ev){
    const delta = ev.clientX - startX;
    let nova = Math.round(startWidth + delta);
    nova = Math.max(40, Math.min(nova, larguraMax));
    img.style.width = nova + 'px';
    img.style.height = 'auto';
    rtPosicionarHandle();
  }
  function soltar(ev){
    handle.removeEventListener('pointermove', mover);
    handle.removeEventListener('pointerup', soltar);
    handle.removeEventListener('pointercancel', soltar);
    if(handle.releasePointerCapture) handle.releasePointerCapture(ev.pointerId);
  }
  handle.addEventListener('pointermove', mover);
  handle.addEventListener('pointerup', soltar);
  handle.addEventListener('pointercancel', soltar);
}
document.addEventListener('click', (e)=>{
  if(rtImgSelecionada && e.target !== rtImgSelecionada && e.target !== rtImgHandle) rtDeselecionarImagem();
});
window.addEventListener('resize', rtPosicionarHandle);

// canvas livre do Painel genérico — arrastar/redimensionar (ver
// pnlCanvasIniciarArraste/Redimensionar, chamados no mousedown da alça,
// delegado dentro de #pnlGradeWidgets). Globais e sempre ligados: são
// no-op sempre que nada está sendo arrastado/redimensionado.
window.addEventListener('mousemove', e=>{
  if(pnlCanvasArrastando) pnlCanvasMoverArraste(e);
  else if(pnlCanvasRedimensionando) pnlCanvasMoverRedimensionar(e);
});
window.addEventListener('mouseup', ()=>{
  pnlCanvasArrastando = null;
  pnlCanvasRedimensionando = null;
});
// troca de grade pra canvas (ou o contrário) ao cruzar o breakpoint de tela
// larga — só fora do modo de edição do canvas, pra não brigar com o admin
// enquanto ele está arrastando algo
let pnlCanvasResizeTimer = null;
window.addEventListener('resize', ()=>{
  clearTimeout(pnlCanvasResizeTimer);
  pnlCanvasResizeTimer = setTimeout(()=>{
    if(pnlModoCanvas || !pnlPainelAtual || !pnlConsultasCarregadas.length) return;
    pnlRenderEsqueleto();
    pnlRenderConteudo();
  }, 200);
});

// funciona pra qualquer editor de texto rico da tela (Detalhe, Solução...) —
// cada toolbar sabe qual editor controla via data-editor no próprio toolbar
function configurarEditorRico(){
  document.querySelectorAll('.rt-toolbar').forEach(toolbar=>{
    const editorId = toolbar.dataset.editor;
    toolbar.querySelectorAll('button[data-cmd]').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        document.getElementById(editorId).focus();
        document.execCommand(btn.dataset.cmd, false);
      });
    });
    const btnImagem = toolbar.querySelector('button[data-cmd-imagem]');
    if(btnImagem){
      const inputImagem = toolbar.querySelector('input[type=file]');
      btnImagem.addEventListener('click', ()=> inputImagem.click());
      inputImagem.addEventListener('change', async (e)=>{
        const arquivo = e.target.files[0];
        e.target.value = '';
        if(!arquivo) return;
        if(arquivo.size > 5 * 1024 * 1024){ toast('Imagem muito grande (máx. 5MB)'); return; }
        toast('Enviando imagem…');
        try{
          const base64 = await lerArquivoBase64(arquivo);
          const r = await api('uploadImagem', { base64, tipo: arquivo.type, nome: arquivo.name });
          if(!r.ok){ toast(r.erro || 'Não foi possível enviar a imagem.'); return; }
          document.getElementById(editorId).focus();
          document.execCommand('insertHTML', false, `<img src="${r.url}" alt="${escaparHtml(r.nome||'')}" title="Toque na imagem e arraste o puxador para redimensionar. Duplo toque para restaurar o tamanho original.">`);
        }catch(err){
          toast(err && err.message ? err.message : 'Não foi possível enviar a imagem.');
        }
      });
    }
    const editorEl = document.getElementById(editorId);
    if(editorEl){
      editorEl.addEventListener('click', (e)=>{
        if(e.target.tagName === 'IMG') rtSelecionarImagem(e.target);
      });
      editorEl.addEventListener('dblclick', (e)=>{
        if(e.target.tagName === 'IMG'){
          e.preventDefault();
          e.target.removeAttribute('style');
          if(rtImgSelecionada === e.target) rtPosicionarHandle();
        }
      });
      editorEl.addEventListener('scroll', rtPosicionarHandle);
    }
  });
}

/* ---------- anexos múltiplos (só disponível ao editar um atendimento já existente) ---------- */
async function carregarAnexosMultiplos(atendimentoId){
  const cont = document.getElementById('listaAnexos');
  cont.innerHTML = `<div class="empty" style="padding:14px;">Carregando…</div>`;
  try{
    const r = await api('listarAnexos', { atendimentoId });
    if(!r.ok){ cont.innerHTML = `<div class="empty" style="padding:14px;">${r.erro||'Não foi possível carregar os anexos.'}</div>`; return; }
    renderAnexosGenerico('listaAnexos', r.anexos, atendimentoId, true);
  }catch(e){
    cont.innerHTML = `<div class="empty" style="padding:14px;">Não foi possível carregar os anexos.</div>`;
  }
}
// usado tanto pela lista de anexos do formulário de edição (admin/atendente)
// quanto pela tela de visualização do chamado (usuário/atendente/admin)
function renderAnexosGenerico(containerId, lista, atendimentoId, podeRemover){
  const cont = document.getElementById(containerId);
  if(!lista || lista.length === 0){ cont.innerHTML = `<div class="empty" style="padding:10px 0;font-size:12.5px;">Nenhum anexo ainda.</div>`; return; }
  cont.innerHTML = lista.map(a=>`
    <div class="anexo-item">
      <a href="${a.url}" target="_blank">📎 ${escaparHtml(a.nome||'anexo')}</a>
      <a href="${urlDownloadAnexo(a.url, a.nome)}" title="Baixar arquivo original">⬇ Baixar</a>
      ${podeRemover ? `<button type="button" onclick="removerAnexoGenerico('${a.id}','${containerId}','${atendimentoId}',${podeRemover})">remover</button>` : ''}
    </div>`).join('');
}
async function adicionarAnexoGenerico(atendimentoId, arquivo, containerId, podeRemover){
  if(!atendimentoId){ toast('Salve o atendimento antes de anexar arquivos.'); return; }
  if(arquivo.size > 8 * 1024 * 1024){ toast('Anexo muito grande (máx. 8MB)'); return; }
  toast('Enviando anexo…');
  try{
    const base64 = await lerArquivoBase64(arquivo);
    const r = await api('adicionarAnexo', { atendimentoId, base64, tipo: arquivo.type, nome: arquivo.name });
    if(!r.ok){ toast(r.erro || 'Não foi possível enviar o anexo.'); return; }
    const rl = await api('listarAnexos', { atendimentoId });
    if(rl.ok) renderAnexosGenerico(containerId, rl.anexos, atendimentoId, podeRemover);
    toast('Anexo adicionado');
  }catch(e){
    toast(e && e.message ? e.message : 'Não foi possível enviar o anexo.');
  }
}
async function removerAnexoGenerico(id, containerId, atendimentoId, podeRemover){
  const r = await api('removerAnexo', { id });
  if(!r.ok){ toast(r.erro || 'Não foi possível remover.'); return; }
  const rl = await api('listarAnexos', { atendimentoId });
  if(rl.ok) renderAnexosGenerico(containerId, rl.anexos, atendimentoId, podeRemover);
  toast('Anexo removido');
}

/* ---------- navegação ---------- */
function goView(name){
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
  document.getElementById('view-'+name).classList.add('active');
  document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active', t.dataset.view===name));
  document.querySelectorAll('.navbtn').forEach(t=>t.classList.toggle('active', t.dataset.view===name));
  if(name==='lista') renderLista();
  if(name==='resumo') renderResumo();
  if(name==='dashboard') renderDashboard();
  if(name==='gantt'){ renderFiltrosGantt(); renderGantt(); }
  if(name==='relatorio'){
    renderRelatorioFiltros(); renderRelatorioColunas(); atualizarRelatorioComMovimentacoes();
    carregarRelatoriosSalvos().then(renderListaRelatoriosSalvos);
  }
  if(name==='relatoriospub'){
    document.getElementById('cardPreviewRelatoriosPub').style.display = 'none';
    carregarRelatoriosPublicados();
  }
  if(name==='cubo'){ renderTodosSeletoresCubo(); renderCuboPerfilSelect(); renderCubo(); }
  if(name==='relatoriosgerenciaisrm'){ goRgrmSub(primeiraSubAbaVisivel('relatoriosgerenciaisrm', rgrmAba)); }
  if(name==='financeiro'){
    goFinSub(primeiraSubAbaVisivel('financeiro', finAba));
    selecionarTipoLancamento('RECEITA');
    popularClientesFinanceiro();
    popularFornecedoresFinanceiro();
    popularMesesFinanceiro();
    renderFinAtendimentosLista();
    carregarLancamentos().then(()=>{ renderListaLancamentos(); renderFinAtendimentosLista(); });
    carregarNotasImportadas().then(renderListaNotasImportadas);
    document.getElementById('fin_xml_preview').style.display = 'none';
    document.getElementById('fin_xml_arquivo').value = '';
  }
  if(name==='agenda'){
    goAgSub(primeiraSubAbaVisivel('agenda', agAba));
    popularSelectsAgenda();
    renderSeletorCores('ag_cores', document.getElementById('ag_cor_selecionada').value);
    Promise.all([carregarAgendamentos(), carregarAtividadesCacheParaAgenda()]).then(renderAgenda);
  }
  if(name==='atividades'){
    ativFiltroStatus = 'TODOS';
    ativFiltroResponsavel = 'TODOS';
    limparFormAtividade();
    carregarAtividades();
  }
  if(name==='orcamentos'){
    // criar/editar orçamento é coisa de quem gerencia (ADMIN/ATENDENTE) —
    // igual o backend já exige em podeGerenciarOrcamento; administrador do
    // cliente só acompanha os orçamentos feitos pro próprio cliente (visto
    // em renderListaOrcamentos), sem ver o formulário de criação/edição
    const contaOrc = contaAtual();
    const podeGerenciarOrc = contaOrc && (contaOrc.perfil === 'ADMIN' || contaOrc.perfil === 'ATENDENTE');
    document.getElementById('cardFormOrcamento').style.display = podeGerenciarOrc ? '' : 'none';
    if(podeGerenciarOrc) limparFormOrcamento();
    carregarOrcamentos();
  }
  if(name==='projetos'){
    fecharProjetoDetalhe();
    popularSelectsProjeto();
    limparFormProjeto();
    carregarProjetos();
  }
  if(name==='videos'){
    const contaVid = contaAtual();
    const permVid = permissaoMenu(contaVid, 'videos');
    const podeInserirVidPadrao = permVid ? permVid.inserir : ehAdminEfetivo(contaVid);
    const podeInserirVid = menuVisivel(contaVid, 'videos.novo', podeInserirVidPadrao);
    if(podeInserirVid){ popularSelectsVideo(); limparFormVideo(); }
    goVidSub(primeiraSubAbaVisivel('videos', vidAba));
    vidFiltroModulo = 'TODOS';
    vidSelecionadoId = null;
    carregarVideos();
  }
  if(name==='cadastros') goCadSub(primeiraSubAbaVisivel('cadastros', cadAba));
  if(name==='utilitarios') resetUtilitarios();
}
function goCadSub(sub){
  cadAba = sub;
  document.querySelectorAll('.subtab').forEach(t=>t.classList.toggle('active', t.dataset.sub===sub));
  document.querySelectorAll('.cad-view').forEach(v=>{ v.style.display = (v.id === 'cad-'+sub) ? '' : 'none'; });
  if(sub === 'tabelasrm') carregarECadTabelasRM();
  if(sub === 'camposrm') carregarECadCamposRM();
  if(sub === 'relacionamentosrm') carregarECadRelacionamentosRM();
  if(sub === 'tabelasauxrm') carregarECadTabelasAuxRM();
}

/* ---------- relógio ---------- */
function tickClock(){ document.getElementById('clock').textContent = new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}); }

/* ---------- puxar do topo pra atualizar (tipo o F5 do navegador) — o app
   Android roda numa WebView que não tem esse gesto nativo ---------- */
function configurarPullParaAtualizar(){
  const indicador = document.getElementById('pullRefreshIndicator');
  const texto = document.getElementById('pullRefreshTexto');
  const spinner = document.getElementById('pullRefreshSpinner');
  const LIMITE = 70;
  let inicioY = 0, puxando = false, distancia = 0, disparado = false;

  function podeComecar(alvo){
    if(disparado) return false;
    if(document.getElementById('app').style.display === 'none') return false; // ainda na tela de login
    if(document.querySelector('.modal-bg.show')) return false; // não atrapalha quem está usando um modal
    if(alvo && alvo.closest('.rt-editor, .lookup-dropdown, table')) return false; // tem rolagem própria — não brigar com ela
    return window.scrollY <= 0;
  }
  function atualizarVisual(d){
    indicador.style.height = Math.min(d, LIMITE + 20) + 'px';
    indicador.classList.toggle('com-borda', d > 4);
    spinner.style.display = 'none';
    texto.style.display = '';
    texto.textContent = d >= LIMITE ? '↑ Solte para atualizar' : '↓ Puxe para atualizar';
  }

  document.addEventListener('touchstart', e=>{
    if(!podeComecar(e.target)){ puxando = false; return; }
    inicioY = e.touches[0].clientY;
    puxando = true;
    distancia = 0;
  }, {passive:true});

  document.addEventListener('touchmove', e=>{
    if(!puxando || disparado) return;
    const dy = e.touches[0].clientY - inicioY;
    if(dy <= 0 || window.scrollY > 0){ puxando = false; atualizarVisual(0); return; }
    distancia = Math.min(dy * 0.5, LIMITE + 20); // resistência, igual apps nativos
    atualizarVisual(distancia);
    e.preventDefault(); // evita o overscroll/pull-to-refresh nativo do navegador brigando com o nosso
  }, {passive:false});

  document.addEventListener('touchend', ()=>{
    if(puxando && distancia >= LIMITE){
      disparado = true;
      indicador.style.height = LIMITE + 'px';
      indicador.classList.add('com-borda');
      spinner.style.display = '';
      texto.textContent = 'Atualizando…';
      setTimeout(()=>location.reload(), 200);
    } else if(puxando){
      atualizarVisual(0);
    }
    puxando = false;
  });
}

