    cancelarEdicaoCliente();
    await carregarTudo({ comAtendimentos: false }); renderListClientes(); popularSelects(); renderValoresForm(); renderFiltros();
    toast(editando ? 'Cliente atualizado' : 'Cliente adicionado');
